-- El día de hoy en la zona horaria de una Prestadora. Es el único lugar de la base que lo cuenta,
-- y da lo mismo que la cuenta del backend. Sin zona o sin Prestadora no hay día: falla cerrado.
CREATE OR REPLACE FUNCTION "interno"."hoy_en_la_zona"("p_zona" "text") RETURNS "date"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  SELECT (now() AT TIME ZONE p_zona)::date
$$;


ALTER FUNCTION "interno"."hoy_en_la_zona"("p_zona" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."hoy_de_la_prestadora"("p_prestadora" "uuid") RETURNS "date"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT interno.hoy_en_la_zona(p.zona_horaria) FROM prestadoras p WHERE p.id = p_prestadora
$$;


ALTER FUNCTION "interno"."hoy_de_la_prestadora"("p_prestadora" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."hoy_de_la_sesion"() RETURNS "date"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  SELECT interno.hoy_de_la_prestadora(interno.prestadora_actual())
$$;


ALTER FUNCTION "interno"."hoy_de_la_sesion"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "interno"."accesos_fuera_de_lo_normal_de"("p_prestadora" "uuid", "p_desde" "date", "p_hasta" "date") RETURNS TABLE("consulta_id" "uuid", "usuario_id" "uuid", "persona" "text", "paciente_id" "uuid", "paciente" "text", "categorias" "text"[], "momento" timestamp with time zone, "origen" "text", "motivos" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  WITH configuracion AS (
    SELECT p.zona_horaria AS zona,
           p.registro_de_accesos_hora_de_inicio AS inicio,
           p.registro_de_accesos_hora_de_fin AS fin,
           p.registro_de_accesos_pacientes_por_dia AS tope,
           make_interval(hours => p.registro_de_accesos_horas_alrededor_del_turno_guardia) AS margen,
           p.registro_de_accesos_horas_alrededor_del_turno_guardia / 24 + 2 AS dias_de_margen
      FROM prestadoras p
     WHERE p.id = p_prestadora
  ),
  -- Las lecturas de personas en el período, con la hora del lugar.
  lecturas AS (
    SELECT c.id, c.usuario_id, c.paciente_id, c.categorias, c.momento, c.origen,
           (c.momento AT TIME ZONE k.zona) AS hora_local,
           k.inicio, k.fin, k.tope, k.margen
      FROM consultas_a_hce c
      CROSS JOIN configuracion k
     WHERE c.prestadora_id = p_prestadora
       AND c.usuario_id IS NOT NULL
       AND c.momento >= (p_desde::timestamp AT TIME ZONE k.zona)
       AND c.momento <  ((p_hasta + 1)::timestamp AT TIME ZONE k.zona)
  ),
  -- Las guardias que rodean el período, con su comienzo y su fin en hora del lugar. El fin sale
  -- de los días que dura cada una, sin tope.
  turnos_guardia_del_periodo AS (
    SELECT g.paciente_id, g.coordinador_id, a.usuario_id AS asistente_usuario_id,
           (g.fecha + g.hora_inicio) AS empieza,
           (interno.dia_en_que_termina_turno_guardia(g.fecha, g.hora_inicio, g.hora_fin, g.dias_hasta_el_fin) + g.hora_fin) AS termina
      FROM turnos_guardia g
      CROSS JOIN configuracion k
      LEFT JOIN asistentes a ON a.id = g.asistente_id AND a.prestadora_id = g.prestadora_id
     WHERE g.prestadora_id = p_prestadora
       AND g.estado <> 'cancelada'
       AND g.fecha + g.dias_hasta_el_fin >= p_desde - k.dias_de_margen AND g.fecha <= p_hasta + k.dias_de_margen
  ),
  -- Las personas que ese día leyeron más Pacientes distintos que el tope.
  volumen AS (
    SELECT l.usuario_id, l.hora_local::date AS dia
      FROM lecturas l
     GROUP BY l.usuario_id, l.hora_local::date
    HAVING count(DISTINCT l.paciente_id) > max(l.tope)
  ),
  marcadas AS (
    SELECT l.*,
           array_remove(ARRAY[
             CASE WHEN NOT (CASE WHEN l.inicio < l.fin
                                 THEN l.hora_local::time >= l.inicio AND l.hora_local::time < l.fin
                                 ELSE l.hora_local::time >= l.inicio OR l.hora_local::time < l.fin END)
                   AND NOT EXISTS (
                     SELECT 1 FROM turnos_guardia_del_periodo g
                      WHERE g.asistente_usuario_id = l.usuario_id
                        AND l.hora_local >= g.empieza AND l.hora_local < g.termina)
                  THEN 'fuera_del_horario' END,
             CASE WHEN NOT EXISTS (
                     SELECT 1 FROM turnos_guardia_del_periodo g
                      WHERE g.paciente_id = l.paciente_id
                        AND (g.asistente_usuario_id = l.usuario_id OR g.coordinador_id = l.usuario_id)
                        AND l.hora_local >= g.empieza - l.margen
                        AND l.hora_local <  g.termina + l.margen)
                   AND NOT EXISTS (
                     SELECT 1 FROM pacientes pa
                       JOIN servicios s ON s.prestadora_id = pa.prestadora_id
                                       AND s.cliente_id = pa.cliente_id
                      WHERE pa.id = l.paciente_id
                        AND pa.prestadora_id = p_prestadora
                        AND s.estado = 'vigente'
                        AND s.coordinador_id = l.usuario_id)
                  THEN 'sin_relacion_con_el_paciente' END,
             CASE WHEN EXISTS (
                     SELECT 1 FROM volumen v
                      WHERE v.usuario_id = l.usuario_id AND v.dia = l.hora_local::date)
                  THEN 'volumen_inusual' END
           ], NULL) AS motivos
      FROM lecturas l
  )
  SELECT m.id, m.usuario_id, u.nombre, m.paciente_id, pe.nombre_visible,
         m.categorias, m.momento, m.origen, m.motivos
    FROM marcadas m
    LEFT JOIN usuarios u ON u.id = m.usuario_id
    LEFT JOIN pacientes pa ON pa.id = m.paciente_id AND pa.prestadora_id = p_prestadora
    LEFT JOIN personas pe ON pe.id = pa.persona_id
   WHERE cardinality(m.motivos) > 0
   ORDER BY m.momento DESC;
$$;


ALTER FUNCTION "interno"."accesos_fuera_de_lo_normal_de"("p_prestadora" "uuid", "p_desde" "date", "p_hasta" "date") OWNER TO "postgres";



CREATE OR REPLACE FUNCTION "interno"."alarmas_a_la_vista_del_coordinador"("p_tipo" "text") RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
  v_llegaron uuid[];
  v_abiertas uuid[];
BEGIN
  IF v_prestadora IS NULL OR NOT interno.es_coordinador() THEN
    RETURN '{}';
  END IF;

  SELECT coalesce(array_agg(e.referencia_id), '{}') INTO v_llegaron
    FROM escalones_de_alarma_avisados e
   WHERE e.prestadora_id = v_prestadora
     AND e.tipo = p_tipo
     AND e.escalon = 'todos_los_coordinadores';

  IF p_tipo = 'alerta_temprana_turno_guardia' THEN
    SELECT coalesce(array_agg(x.id), '{}') INTO v_abiertas FROM alertas_tempranas_turno_guardia x
     WHERE x.id = ANY (v_llegaron) AND x.resuelto_at IS NULL;
  ELSIF p_tipo = 'incidente_relevo' THEN
    SELECT coalesce(array_agg(x.id), '{}') INTO v_abiertas FROM incidentes_relevo x
     WHERE x.id = ANY (v_llegaron) AND x.resuelto_at IS NULL;
  ELSIF p_tipo = 'incidente_turno_guardia_sin_cubrir' THEN
    SELECT coalesce(array_agg(x.id), '{}') INTO v_abiertas FROM incidentes_turno_guardia_sin_cubrir x
     WHERE x.id = ANY (v_llegaron) AND x.resuelto_at IS NULL;
  ELSIF p_tipo = 'emergencia_turno_guardia' THEN
    SELECT coalesce(array_agg(x.id), '{}') INTO v_abiertas FROM emergencias_turno_guardia x
     WHERE x.id = ANY (v_llegaron) AND x.atendida_at IS NULL;
  ELSIF p_tipo = 'turno_guardia_sin_cerrar' THEN
    SELECT coalesce(array_agg(x.id), '{}') INTO v_abiertas FROM turnos_guardia x
     WHERE x.id = ANY (v_llegaron) AND x.estado = 'activa';
  ELSE
    v_abiertas := '{}';
  END IF;

  RETURN v_abiertas || interno.alarmas_que_tengo_tomadas(p_tipo);
END;
$$;


ALTER FUNCTION "interno"."alarmas_a_la_vista_del_coordinador"("p_tipo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."alarmas_que_tengo_tomadas"("p_tipo" "text") RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT coalesce(array_agg(a.referencia_id), '{}')
    FROM alarmas_tomadas a
   WHERE a.prestadora_id = interno.prestadora_actual()
     AND a.tipo = p_tipo
     AND a.tomada_por = auth.uid()
     AND a.soltada_at IS NULL
     AND a.vence_at > now();
$$;


ALTER FUNCTION "interno"."alarmas_que_tengo_tomadas"("p_tipo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."alcanza_el_archivo_del_paciente"("p_ruta" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT interno.es_superadmin()
      OR interno.es_admin_prestadora()
      OR coalesce(interno.coordinador_ve_al_paciente(interno.paciente_de_la_ruta(p_ruta)), false);
$$;


ALTER FUNCTION "interno"."alcanza_el_archivo_del_paciente"("p_ruta" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."alcanza_la_informacion_de_salud"("p_paciente" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT p_paciente IS NOT NULL
     AND (NOT interno.rige_la_restriccion_de_hce(interno.prestadora_actual())
          OR interno.atiende_al_paciente(p_paciente)
          OR (interno.es_admin_prestadora()
              AND EXISTS (SELECT 1 FROM pacientes p
                           WHERE p.id = p_paciente
                             AND p.prestadora_id = interno.prestadora_actual()))
          OR interno.tiene_acceso_de_emergencia(p_paciente))
$$;


ALTER FUNCTION "interno"."alcanza_la_informacion_de_salud"("p_paciente" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."anotar_cambio_de_fecha_de_ausencia"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF NEW.fecha_fin IS DISTINCT FROM OLD.fecha_fin THEN
    INSERT INTO public.ausencias_cambios_de_fecha (prestadora_id, ausencia_id, fecha_anterior, fecha_nueva)
    VALUES (NEW.prestadora_id, NEW.id, OLD.fecha_fin, NEW.fecha_fin);
    NEW.pregunta_vuelta_at := NULL;
    NEW.pregunta_vuelta_veces := 0;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."anotar_cambio_de_fecha_de_ausencia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."anotar_cambio_de_la_restriccion_de_hce"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_antes boolean := CASE WHEN TG_OP = 'UPDATE' THEN OLD.restriccion_de_hce ELSE true END;
BEGIN
  IF v_antes IS NOT DISTINCT FROM NEW.restriccion_de_hce OR auth.uid() IS NULL THEN
    RETURN NULL;
  END IF;

  INSERT INTO registro_actividad
    (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, campos_cambiados, detalle)
  VALUES
    (NEW.prestadora_id, auth.uid(), 'cambio_de_permisos_de_la_prestadora',
     TG_TABLE_NAME, NEW.prestadora_id, ARRAY['restriccion_de_hce'],
     jsonb_build_object('alcance_anterior', v_antes, 'alcance_nuevo', NEW.restriccion_de_hce));

  RETURN NULL;
END;
$$;


ALTER FUNCTION "interno"."anotar_cambio_de_la_restriccion_de_hce"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."anotar_descuento_del_servicio"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_usuario uuid := interno.usuario_de_la_sesion();
BEGIN
  IF v_usuario IS NULL THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.registro_actividad
      (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, campos_cambiados)
    VALUES
      (NEW.prestadora_id, v_usuario, 'alta_de_descuento', TG_TABLE_NAME, NEW.id,
       ARRAY['clase', 'valor', 'moneda', 'vigente_desde', 'cantidad_de_periodos', 'vigente_hasta', 'motivo']);
  ELSIF OLD.terminado_en IS NULL AND NEW.terminado_en IS NOT NULL THEN
    INSERT INTO public.registro_actividad
      (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, campos_cambiados)
    VALUES
      (NEW.prestadora_id, v_usuario, 'terminacion_de_descuento', TG_TABLE_NAME, NEW.id,
       ARRAY['terminado_en']);
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "interno"."anotar_descuento_del_servicio"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."anotar_precio_de_item_adicional"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_usuario uuid := interno.usuario_de_la_sesion();
BEGIN
  IF v_usuario IS NULL THEN
