CREATE OR REPLACE FUNCTION "interno"."calcular_prorroga_de_gracia"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_gracia date;
BEGIN
  v_gracia := interno.gracia_hasta(NEW.asistente_id, NEW.tipo_documento_id, interno.hoy_de_la_prestadora(NEW.prestadora_id));
  IF v_gracia IS NULL THEN
    RAISE EXCEPTION 'documento_sin_gracia' USING ERRCODE = '23514';
  END IF;
  NEW.hasta := GREATEST(v_gracia, interno.hoy_de_la_prestadora(NEW.prestadora_id)) + NEW.dias;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."calcular_prorroga_de_gracia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."cerrar_la_prestacion_anterior"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  anterior record;
  cerradas integer;
BEGIN
  IF NEW.prestacion_anterior_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT id, prestadora_id, paciente_id, servicio_id, estado, vigente_desde, vigente_hasta
    INTO anterior
    FROM prestaciones
   WHERE id = NEW.prestacion_anterior_id
   FOR UPDATE;

  IF NOT FOUND
     OR anterior.prestadora_id <> NEW.prestadora_id
     OR anterior.paciente_id <> NEW.paciente_id
     OR anterior.servicio_id IS DISTINCT FROM NEW.servicio_id
     OR anterior.estado <> 'vigente' THEN
    RAISE EXCEPTION 'prestacion_anterior_no_corresponde' USING ERRCODE = '23514';
  END IF;

  IF NEW.vigente_desde <= anterior.vigente_desde
     OR (anterior.vigente_hasta IS NOT NULL AND NEW.vigente_desde > anterior.vigente_hasta) THEN
    RAISE EXCEPTION 'cambio_de_precio_fuera_del_periodo' USING ERRCODE = '23514';
  END IF;

  UPDATE prestaciones
     SET vigente_hasta = NEW.vigente_desde - 1,
         updated_at = now()
   WHERE id = anterior.id;

  GET DIAGNOSTICS cerradas = ROW_COUNT;
  IF cerradas <> 1 THEN
    RAISE EXCEPTION 'prestacion_anterior_no_corresponde' USING ERRCODE = '23514';
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "interno"."cerrar_la_prestacion_anterior"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."cerrar_vigencia_de_la_prestacion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  recien_se_da_de_baja boolean;
  la_trae_escrita boolean;
BEGIN
  IF NEW.estado <> 'de_baja' THEN
    RETURN NEW;
  END IF;

  recien_se_da_de_baja := TG_OP = 'INSERT' OR OLD.estado <> 'de_baja';
  la_trae_escrita := CASE
    WHEN TG_OP = 'INSERT' THEN NEW.vigente_hasta IS NOT NULL
    ELSE NEW.vigente_hasta IS DISTINCT FROM OLD.vigente_hasta
  END;

  IF recien_se_da_de_baja AND NOT la_trae_escrita THEN
    -- `GREATEST` cubre la prestacion que se da de baja antes de arrancar: no
    -- puede terminar antes de empezar, y la restriccion de mas arriba lo exige.
    NEW.vigente_hasta := GREATEST(NEW.vigente_desde, interno.hoy_de_la_prestadora(NEW.prestadora_id));
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."cerrar_vigencia_de_la_prestacion"() OWNER TO "postgres";


