    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT array_agg(a.attname::text ORDER BY a.attnum)
    FROM pg_catalog.pg_attribute a
   WHERE a.attrelid = p_tabla
     AND a.attnum > 0
     AND NOT a.attisdropped
     AND a.attgenerated = ''
     AND a.attname NOT IN ('id', 'created_at', 'updated_at')
$$;


ALTER FUNCTION "interno"."columnas_que_se_copian"("p_tabla" "regclass") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."completar_documento_asistente"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_tipo public.tipos_documento_asistente;
BEGIN
  SELECT * INTO v_tipo
    FROM tipos_documento_asistente
   WHERE id = NEW.tipo_documento_id;

  IF v_tipo.vencimiento = 'no_vence' THEN
    NEW.fecha_vencimiento := NULL;
  ELSIF v_tipo.vencimiento = 'plazo_desde_emision' THEN
    NEW.fecha_vencimiento := CASE
      WHEN NEW.fecha_emision IS NULL THEN NULL
      ELSE (NEW.fecha_emision + CASE v_tipo.periodo_unidad
              WHEN 'dia'    THEN make_interval(days => v_tipo.periodo_cantidad)
              WHEN 'semana' THEN make_interval(weeks => v_tipo.periodo_cantidad)
              WHEN 'mes'    THEN make_interval(months => v_tipo.periodo_cantidad)
              WHEN 'anio'   THEN make_interval(years => v_tipo.periodo_cantidad)
            END)::date
    END;
  END IF;

  IF NEW.organismo_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM organismos_por_tipo_documento o
        WHERE o.tipo_documento_id = NEW.tipo_documento_id
          AND o.organismo_id = NEW.organismo_id) THEN
    RAISE EXCEPTION 'organismo_no_otorga_ese_documento' USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."completar_documento_asistente"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."condicion_del_pedido"("p_tabla" "text", "p_alias" "text", "p_filtros" "jsonb", "p_union" "text" DEFAULT 'AND'::"text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  e        jsonb;
  v_partes text[] := '{}';
  v_col    text;
  v_op     text;
  v_valor  text;
BEGIN
  IF p_union NOT IN ('AND', 'OR') OR p_alias NOT IN ('t', 'g') THEN
    RAISE EXCEPTION 'pedido_invalido' USING ERRCODE = '22023';
  END IF;
  IF p_filtros IS NULL OR p_filtros = 'null'::jsonb THEN
    RETURN 'true';
  END IF;
  IF jsonb_typeof(p_filtros) <> 'array' THEN
    RAISE EXCEPTION 'pedido_invalido' USING ERRCODE = '22023';
  END IF;

  FOR e IN SELECT x FROM jsonb_array_elements(p_filtros) x LOOP
    IF jsonb_typeof(e) <> 'object' THEN
      RAISE EXCEPTION 'pedido_invalido' USING ERRCODE = '22023';
    END IF;

    IF e ? 'o' THEN
      v_partes := v_partes || ('(' || interno.condicion_del_pedido(p_tabla, p_alias, e -> 'o', 'OR') || ')');
    ELSIF e ? 'y' THEN
      v_partes := v_partes || ('(' || interno.condicion_del_pedido(p_tabla, p_alias, e -> 'y', 'AND') || ')');
    ELSIF e ? 'turno_guardia' THEN
      -- Una condición sobre la guardia de la fila. La guardia se lee con los permisos de quien
      -- pide, como cualquier otra lectura suya.
      IF p_alias <> 't' THEN
        RAISE EXCEPTION 'pedido_invalido' USING ERRCODE = '22023';
      END IF;
      PERFORM interno.columna_del_pedido(p_tabla, 'turno_guardia_id');
      v_partes := v_partes || format(
        'EXISTS (SELECT 1 FROM public.turnos_guardia g WHERE g.id = t.turno_guardia_id AND %s)',
        interno.condicion_del_pedido('turnos_guardia', 'g', e -> 'turno_guardia', 'AND'));
    ELSE
      v_col := interno.columna_del_pedido(p_tabla, e ->> 'columna');
      v_op := e ->> 'op';
      v_valor := format('(jsonb_populate_record(NULL::public.%I, %L::jsonb)).%I',
                        p_tabla, jsonb_build_object(v_col, e -> 'valor'), v_col);
      v_partes := v_partes || CASE v_op
        WHEN 'eq'       THEN format('%I.%I = %s',  p_alias, v_col, v_valor)
        WHEN 'neq'      THEN format('%I.%I <> %s', p_alias, v_col, v_valor)
        WHEN 'gt'       THEN format('%I.%I > %s',  p_alias, v_col, v_valor)
        WHEN 'gte'      THEN format('%I.%I >= %s', p_alias, v_col, v_valor)
        WHEN 'lt'       THEN format('%I.%I < %s',  p_alias, v_col, v_valor)
        WHEN 'lte'      THEN format('%I.%I <= %s', p_alias, v_col, v_valor)
        WHEN 'is_null'  THEN format('%I.%I IS NULL', p_alias, v_col)
        WHEN 'not_null' THEN format('%I.%I IS NOT NULL', p_alias, v_col)
        WHEN 'in'       THEN format(
          '%I.%I = ANY (ARRAY(SELECT (jsonb_populate_record(NULL::public.%I, jsonb_build_object(%L, x))).%I FROM jsonb_array_elements(%L::jsonb) x))',
          p_alias, v_col, p_tabla, v_col, v_col,
          CASE WHEN jsonb_typeof(e -> 'valor') = 'array' THEN e -> 'valor' END)
      END;
      IF v_partes[cardinality(v_partes)] IS NULL THEN
        RAISE EXCEPTION 'pedido_invalido' USING ERRCODE = '22023';
      END IF;
    END IF;
  END LOOP;

  IF cardinality(v_partes) = 0 THEN
    RETURN CASE WHEN p_union = 'OR' THEN 'false' ELSE 'true' END;
  END IF;
  RETURN array_to_string(v_partes, ' ' || p_union || ' ');
END;
$$;


ALTER FUNCTION "interno"."condicion_del_pedido"("p_tabla" "text", "p_alias" "text", "p_filtros" "jsonb", "p_union" "text") OWNER TO "postgres";


