CREATE OR REPLACE FUNCTION "interno"."coordinador_ve_la_indicacion"("p_indicacion" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM indicaciones_medicacion i
     WHERE i.id = p_indicacion
       AND i.prestadora_id = interno.prestadora_actual()
       AND interno.coordinador_ve_al_paciente(i.paciente_id)
  );
$$;


ALTER FUNCTION "interno"."coordinador_ve_la_indicacion"("p_indicacion" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."coordinador_ve_la_serie"("p_serie" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT p_serie IS NOT NULL
     AND interno.es_coordinador()
     AND EXISTS (
       SELECT 1 FROM series_turnos_guardia sg
        WHERE sg.id = p_serie
          AND sg.prestadora_id = interno.prestadora_actual()
          AND interno.coordinador_alcanza_la_serie_de(sg.servicio_id, sg.paciente_id, sg.id)
     );
$$;


ALTER FUNCTION "interno"."coordinador_ve_la_serie"("p_serie" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."coordinadores_que_represento"() RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT CASE WHEN auth.uid() IS NULL THEN '{}'::uuid[]
              ELSE ARRAY(
                SELECT auth.uid()
                UNION
                SELECT a.usuario_id
                  FROM ausencias a
                 WHERE a.coordinador_que_cubre_id = auth.uid()
                   AND a.prestadora_id = interno.prestadora_actual()
                   AND a.usuario_id IS NOT NULL
                   AND a.fecha_inicio <= interno.hoy_de_la_prestadora(a.prestadora_id)
                   AND (a.fecha_vuelta_real IS NULL OR a.fecha_vuelta_real > interno.hoy_de_la_prestadora(a.prestadora_id))
              ) END;
$$;


ALTER FUNCTION "interno"."coordinadores_que_represento"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."copiar_renglon"("p_tabla" "regclass", "p_id" bigint, "p_cambios" "jsonb") RETURNS bigint
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_columnas text[] := interno.columnas_que_se_copian(p_tabla);
  v_lista    text;
  v_valores  text;
  v_nuevo    bigint;
BEGIN
  SELECT string_agg(format('%I', c), ', '),
         string_agg(
           CASE WHEN p_cambios ? c
             THEN format('(jsonb_populate_record(NULL::%s, $2)).%I', p_tabla, c)
             ELSE format('t.%I', c)
           END, ', ')
    INTO v_lista, v_valores
    FROM unnest(v_columnas) AS c;

  EXECUTE format('INSERT INTO %s (%s) SELECT %s FROM %s t WHERE t.id = $1 RETURNING id',
                 p_tabla, v_lista, v_valores, p_tabla)
     INTO v_nuevo
    USING p_id, p_cambios;

  IF v_nuevo IS NULL THEN
    RAISE EXCEPTION 'no_encontrado' USING ERRCODE = 'P0002';
  END IF;
  RETURN v_nuevo;
END;
$$;


ALTER FUNCTION "interno"."copiar_renglon"("p_tabla" "regclass", "p_id" bigint, "p_cambios" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."crear_y_cerrar_servicios_lo_hace_quien_puede"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_cambia_estado boolean := TG_OP = 'UPDATE' AND NEW.estado IS DISTINCT FROM OLD.estado;
BEGIN
  IF COALESCE(auth.jwt() ->> 'role', '') <> 'authenticated' THEN
    RETURN NEW;
  END IF;

  IF (TG_OP = 'INSERT' OR v_cambia_estado)
     AND NOT (interno.es_admin_prestadora()
              OR interno.es_superadmin()
              OR interno.tiene_permiso('gestionar_servicios')) THEN
    RAISE EXCEPTION 'crear_y_cerrar_servicios_lo_hace_quien_puede';
  END IF;

  -- Una persona cambia el estado sólo por las dos funciones, que dejan el registro.
  IF v_cambia_estado
     AND COALESCE(current_setting('careonys.cambio_de_estado_del_servicio', true), '') <> NEW.id::text THEN
    RAISE EXCEPTION 'el_estado_del_servicio_cambia_por_la_baja_o_la_reactivacion';
  END IF;

  IF v_cambia_estado AND NEW.estado = 'de_baja'
     AND interno.turnos_guardia_asignados_del_servicio(NEW.id) > 0 THEN
    RAISE EXCEPTION 'el_servicio_tiene_turnos_guardia_asignados';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."crear_y_cerrar_servicios_lo_hace_quien_puede"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."cumple_modulo_11"("p_numero" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case
    when p_numero !~ '^[0-9]{11}$' then false
    else (
      with suma as (
        select sum(substr(p_numero, i, 1)::int * (array[5,4,3,2,7,6,5,4,3,2])[i]) as s
          from generate_series(1, 10) as i
      )
      select case 11 - (s % 11)
               when 11 then 0
               when 10 then null
               else 11 - (s % 11)
             end is not distinct from substr(p_numero, 11, 1)::int
        from suma
    )
  end
$_$;


ALTER FUNCTION "interno"."cumple_modulo_11"("p_numero" "text") OWNER TO "postgres";



CREATE OR REPLACE FUNCTION "interno"."dar_de_baja_las_prestaciones_del_servicio"("p_servicio" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  -- Sólo para un Servicio de la Prestadora de la sesión que ya tiene su baja anotada.
  IF NOT EXISTS (SELECT 1 FROM bajas_de_servicio b
                  WHERE b.servicio_id = p_servicio
                    AND b.prestadora_id = interno.prestadora_actual()) THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;

  -- La fecha de fin de cada prestación la pone la base al ver la baja.
  UPDATE prestaciones SET estado = 'de_baja'
   WHERE servicio_id = p_servicio
     AND prestadora_id = interno.prestadora_actual()
     AND estado = 'vigente';
END;
$$;


ALTER FUNCTION "interno"."dar_de_baja_las_prestaciones_del_servicio"("p_servicio" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "interno"."dar_de_baja_las_prestaciones_del_servicio"("p_servicio" "uuid") IS 'Da de baja las prestaciones vigentes de un Servicio que se está dando de baja. La llama la baja del Servicio.';



CREATE OR REPLACE FUNCTION "interno"."derechos_por_vencer"("p_prestadora" "uuid") RETURNS TABLE("solicitud_id" "uuid", "tipo" "text", "recibida_en" timestamp with time zone, "vence_en" timestamp with time zone, "recibida_el" "date", "vence_el" "date")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT s.id, s.tipo, s.recibida_en, s.vence_en,
         (s.recibida_en AT TIME ZONE interno.zona_horaria_de_la_prestadora(p_prestadora))::date,
         (s.vence_en AT TIME ZONE interno.zona_horaria_de_la_prestadora(p_prestadora))::date
    FROM solicitudes_de_derechos s
    JOIN plazos_de_respuesta_de_derechos pz ON pz.id = s.plazo_id
   WHERE s.prestadora_id = p_prestadora
     AND s.estado = 'pendiente'
     AND s.vence_en IS NOT NULL
     AND s.aviso_enviado_en IS NULL
     AND now() >= s.vence_en - make_interval(days => pz.dias_de_aviso)
   ORDER BY s.vence_en, s.id
$$;


ALTER FUNCTION "interno"."derechos_por_vencer"("p_prestadora" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."descuento_lo_escribe_la_base"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.cargado_por   := interno.usuario_de_la_sesion();
    NEW.cargado_en    := now();
    NEW.terminado_por := NULL;
    NEW.terminado_en  := NULL;
    RETURN NEW;
  END IF;

  IF OLD.terminado_en IS NOT NULL THEN
    RAISE EXCEPTION 'ya_terminado' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.terminado_en IS NULL THEN
    RAISE EXCEPTION 'dato_invalido' USING ERRCODE = 'P0001';
  END IF;
  IF (NEW.prestadora_id, NEW.servicio_id, NEW.clase, NEW.valor, NEW.moneda, NEW.vigente_desde,
      NEW.cantidad_de_periodos, NEW.vigente_hasta, NEW.motivo, NEW.cargado_por, NEW.cargado_en)
     IS DISTINCT FROM
     (OLD.prestadora_id, OLD.servicio_id, OLD.clase, OLD.valor, OLD.moneda, OLD.vigente_desde,
      OLD.cantidad_de_periodos, OLD.vigente_hasta, OLD.motivo, OLD.cargado_por, OLD.cargado_en) THEN
    RAISE EXCEPTION 'no_se_edita' USING ERRCODE = 'P0001';
  END IF;

  NEW.terminado_en  := now();
  NEW.terminado_por := interno.usuario_de_la_sesion();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."descuento_lo_escribe_la_base"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."dia_en_que_termina_turno_guardia"("p_fecha" "date", "p_hora_inicio" time without time zone, "p_hora_fin" time without time zone, "p_dias_hasta_el_fin" smallint DEFAULT NULL::smallint) RETURNS "date"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
           -- Duración escrita: manda, y es el caso de toda guardia cargada de acá en adelante.
           WHEN p_dias_hasta_el_fin IS NOT NULL THEN p_fecha + p_dias_hasta_el_fin
           WHEN p_hora_fin IS NULL OR p_hora_inicio IS NULL THEN p_fecha
           -- Sin duración escrita se cae en la regla vieja, que sólo sabe de la guardia de noche.
           WHEN p_hora_fin <= p_hora_inicio THEN p_fecha + 1
           ELSE p_fecha
         END;
$$;


ALTER FUNCTION "interno"."dia_en_que_termina_turno_guardia"("p_fecha" "date", "p_hora_inicio" time without time zone, "p_hora_fin" time without time zone, "p_dias_hasta_el_fin" smallint) OWNER TO "postgres";



CREATE OR REPLACE FUNCTION "interno"."distancias_de_asistentes_a_pacientes"("p_asistentes" "uuid"[], "p_pacientes" "uuid"[], "p_fecha" "date") RETURNS TABLE("asistente_id" "uuid", "metros" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  WITH prestadora AS (
    SELECT interno.prestadora_actual() AS id
  ),
  casas AS (
    SELECT d.lat, d.lng
      FROM public.domicilios_de_pacientes_en(p_pacientes, p_fecha) d
      JOIN pacientes p ON p.id = d.paciente_id
     WHERE p.prestadora_id = (SELECT id FROM prestadora)
       AND d.lat IS NOT NULL AND d.lng IS NOT NULL
  )
  SELECT da.asistente_id,
         (round(min(interno.metros_en_linea_recta(da.lat, da.lng, c.lat, c.lng)) / 100.0) * 100)::integer
    FROM domicilio_asistente da
    CROSS JOIN casas c
   WHERE (SELECT id FROM prestadora) IS NOT NULL
     AND da.prestadora_id = (SELECT id FROM prestadora)
     AND da.asistente_id = ANY (p_asistentes)
     AND da.lat IS NOT NULL AND da.lng IS NOT NULL
   GROUP BY da.asistente_id;
$$;



ALTER FUNCTION "interno"."distancias_de_asistentes_a_pacientes"("p_asistentes" "uuid"[], "p_pacientes" "uuid"[], "p_fecha" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."documento_autorizacion_signos_vitales"("p_paciente" "uuid", "p_idioma" "text") RETURNS TABLE("titulo" "text", "texto" "text", "verificador" "text", "idioma" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  WITH datos AS (
    SELECT pa.prestadora_id, pr.pais, pr.nombre_fantasia,
           btrim(coalesce(pe.nombre, '') || ' ' || coalesce(pe.apellido, '')) AS paciente
      FROM pacientes pa
      JOIN prestadoras pr ON pr.id = pa.prestadora_id
      JOIN personas pe ON pe.id = pa.persona_id
     WHERE pa.id = p_paciente
  ),
  fabrica AS (
    SELECT t.titulo, t.cuerpo
      FROM textos_consentimiento t, datos d
     WHERE t.clave = 'autorizacion_signos_vitales'
       AND t.jurisdiccion = d.pais
       AND t.idioma = p_idioma
       AND NOT t.es_borrador
       AND t.vigente_hasta IS NULL
     ORDER BY t.version DESC
     LIMIT 1
  ),
  armado AS (
    SELECT f.titulo,
           replace(replace(coalesce(o.cuerpo, f.cuerpo), '{{prestadora}}', d.nombre_fantasia), '{{paciente}}', d.paciente) AS texto
      FROM datos d
      JOIN fabrica f ON true
      LEFT JOIN textos_autorizacion_signos_vitales o ON o.prestadora_id = d.prestadora_id AND o.idioma = p_idioma
  )
  SELECT a.titulo, a.texto, encode(sha256(convert_to(a.texto, 'UTF8')), 'hex'), p_idioma
    FROM armado a;
$$;


ALTER FUNCTION "interno"."documento_autorizacion_signos_vitales"("p_paciente" "uuid", "p_idioma" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."documentos_que_bloquean"("p_asistente_id" "uuid", "p_dia" "date", "p_paciente_id" "uuid" DEFAULT NULL::"uuid", "p_servicio_id" "uuid" DEFAULT NULL::"uuid") RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_prestadora_id uuid;
  v_tipo_id       uuid;
  v_tipo          record;
  v_hasta         date;
  v_vencio        date;
  v_bloquean      text[] := ARRAY[]::text[];
BEGIN
  IF p_asistente_id IS NULL THEN
    RETURN v_bloquean;
  END IF;

  SELECT a.prestadora_id, a.tipo_asistente_id INTO v_prestadora_id, v_tipo_id
    FROM public.asistentes a
   WHERE a.id = p_asistente_id;

  IF COALESCE(auth.jwt() ->> 'role', '') NOT IN ('', 'service_role')
     AND v_prestadora_id IS DISTINCT FROM interno.prestadora_actual() THEN
    RAISE EXCEPTION 'El Asistente no pertenece a la Prestadora de quien pregunta'
      USING ERRCODE = '42501';
  END IF;

  IF v_tipo_id IS NULL THEN
    RETURN v_bloquean;
  END IF;

  FOR v_tipo IN
    SELECT t.id, t.nombre
      FROM public.tipos_documento_asistente t
      JOIN public.tipos_documento_por_tipo_asistente r ON r.tipo_documento_id = t.id
     WHERE t.prestadora_id = v_prestadora_id
       AND t.activo
       AND t.impide_trabajar
       AND r.tipo_asistente_id = v_tipo_id
     ORDER BY t.nombre
  LOOP
    CONTINUE WHEN EXISTS (
      SELECT 1 FROM public.documentos_asistente d
       WHERE d.asistente_id = p_asistente_id
         AND d.tipo_documento_id = v_tipo.id
         AND d.estado = 'aprobado'
         AND (d.fecha_vencimiento IS NULL OR d.fecha_vencimiento >= p_dia));

    v_hasta := interno.gracia_hasta(p_asistente_id, v_tipo.id, p_dia);

    IF v_hasta IS NOT NULL AND v_hasta >= p_dia THEN
      SELECT max(d.fecha_vencimiento) INTO v_vencio
        FROM public.documentos_asistente d
       WHERE d.asistente_id = p_asistente_id
         AND d.tipo_documento_id = v_tipo.id
         AND d.estado = 'aprobado'
         AND d.fecha_vencimiento < p_dia;

      CONTINUE WHEN EXISTS (
        SELECT 1 FROM public.turnos_guardia g
         WHERE g.asistente_id = p_asistente_id
           AND g.fecha <= v_vencio
           AND g.estado <> 'cancelada'
           AND (g.paciente_id = p_paciente_id OR g.servicio_id = p_servicio_id))
      OR EXISTS (
        SELECT 1 FROM public.series_turnos_guardia s
         WHERE s.asistente_id = p_asistente_id
           AND s.estado = 'activa'
           AND s.paciente_id = p_paciente_id);
    END IF;

    v_bloquean := v_bloquean || v_tipo.nombre;
  END LOOP;

  RETURN v_bloquean;
END;
$$;


ALTER FUNCTION "interno"."documentos_que_bloquean"("p_asistente_id" "uuid", "p_dia" "date", "p_paciente_id" "uuid", "p_servicio_id" "uuid") OWNER TO "postgres";



CREATE OR REPLACE FUNCTION "interno"."el_acceso_abre_contactos"("p_prestadora" "uuid", "p_estado" "text", "p_suspension_desde" "date", "p_vigente_hasta" "date") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT COALESCE(CASE p_estado
    WHEN 'vigente' THEN true
    -- En gracia abre hasta el día anterior a la suspensión. Sin fecha de suspensión no hay
    -- fecha conocida y se niega: falla cerrado.
    WHEN 'en_gracia' THEN p_suspension_desde IS NOT NULL AND p_suspension_desde > interno.hoy_de_la_prestadora(p_prestadora)
    -- Dado de baja, abre hasta el último día del período pagado, ese día incluido.
    WHEN 'cancelada' THEN p_vigente_hasta IS NOT NULL AND p_vigente_hasta >= interno.hoy_de_la_prestadora(p_prestadora)
    ELSE false
  END, false);
$$;



ALTER FUNCTION "interno"."el_acceso_abre_contactos"("p_prestadora" "uuid", "p_estado" "text", "p_suspension_desde" "date", "p_vigente_hasta" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."el_asistente_marca_solo_su_turno_guardia"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_suyas constant text[] := ARRAY[
    'salida_checkin_at', 'salida_lat', 'salida_lng', 'medio_transporte',
    'checkin_at', 'checkin_lat', 'checkin_lng',
    'estado',
    'ubicacion_actual_lat', 'ubicacion_actual_lng', 'ubicacion_actual_at',
    'push_llegada_enviado_at', 'push_reporte_enviado_at'
  ];
BEGIN
  IF current_user <> 'authenticated' THEN
    RETURN NEW;
  END IF;
  IF interno.es_personal_de_la_prestadora() THEN
    RETURN NEW;
  END IF;

  IF (to_jsonb(NEW) - v_suyas) IS DISTINCT FROM (to_jsonb(OLD) - v_suyas) THEN
    RAISE EXCEPTION 'la_persona_cambia_solo_lo_suyo' USING ERRCODE = '42501';
  END IF;

  -- La salida hacia la casa y la llegada: se marcan una vez, con todo lo suyo, y no se reescriben.
  IF (NEW.salida_checkin_at, NEW.salida_lat, NEW.salida_lng, NEW.medio_transporte)
       IS DISTINCT FROM (OLD.salida_checkin_at, OLD.salida_lat, OLD.salida_lng, OLD.medio_transporte)
     AND (OLD.salida_checkin_at IS NOT NULL OR NEW.salida_checkin_at IS NULL) THEN
    RAISE EXCEPTION 'la_persona_cambia_solo_lo_suyo' USING ERRCODE = '42501';
  END IF;
  IF (NEW.checkin_at, NEW.checkin_lat, NEW.checkin_lng)
       IS DISTINCT FROM (OLD.checkin_at, OLD.checkin_lat, OLD.checkin_lng)
     AND (OLD.checkin_at IS NOT NULL OR NEW.checkin_at IS NULL OR NEW.estado IS DISTINCT FROM 'activa') THEN
    RAISE EXCEPTION 'la_persona_cambia_solo_lo_suyo' USING ERRCODE = '42501';
  END IF;

  -- El estado: a empezada al llegar, desde una guardia que todavía no empezó y no se canceló.
  -- Ningún otro cambio es del Asistente.
  IF NEW.estado IS DISTINCT FROM OLD.estado
     AND NOT (NEW.estado = 'activa' AND OLD.estado IN ('programada', 'ausente', 'pausada')
              AND OLD.checkin_at IS NULL AND NEW.checkin_at IS NOT NULL) THEN
    RAISE EXCEPTION 'la_persona_cambia_solo_lo_suyo' USING ERRCODE = '42501';
  END IF;

  -- Los avisos ya mandados no se desmarcan: desmarcarlos los volvería a mandar.
  IF (OLD.push_llegada_enviado_at IS NOT NULL AND NEW.push_llegada_enviado_at IS DISTINCT FROM OLD.push_llegada_enviado_at)
     OR (OLD.push_reporte_enviado_at IS NOT NULL AND NEW.push_reporte_enviado_at IS DISTINCT FROM OLD.push_reporte_enviado_at) THEN
    RAISE EXCEPTION 'la_persona_cambia_solo_lo_suyo' USING ERRCODE = '42501';
  END IF;

  -- La hora de cada marca es la de la base, no la que mande el teléfono.
  IF NEW.salida_checkin_at IS DISTINCT FROM OLD.salida_checkin_at THEN NEW.salida_checkin_at := now(); END IF;
  IF NEW.checkin_at IS DISTINCT FROM OLD.checkin_at THEN NEW.checkin_at := now(); END IF;
  IF NEW.ubicacion_actual_at IS NOT NULL AND NEW.ubicacion_actual_at IS DISTINCT FROM OLD.ubicacion_actual_at THEN
    NEW.ubicacion_actual_at := now();
  END IF;
  IF NEW.push_llegada_enviado_at IS DISTINCT FROM OLD.push_llegada_enviado_at THEN NEW.push_llegada_enviado_at := now(); END IF;
  IF NEW.push_reporte_enviado_at IS DISTINCT FROM OLD.push_reporte_enviado_at THEN NEW.push_reporte_enviado_at := now(); END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."el_asistente_marca_solo_su_turno_guardia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION interno.cerrar_el_turno_guardia(
  p_turno_guardia uuid,
  p_hora timestamp with time zone,
  p_reporte_atrasado boolean,
  p_motivo uuid,
  p_detalle text,
  p_cerrada_por uuid,
  p_lat double precision,
  p_lng double precision,
  p_motivo_del_sistema boolean
)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public', 'interno'
AS $$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
  v_persona boolean := current_user = 'authenticated';
  v_quien uuid;
  v_turno turnos_guardia%ROWTYPE;
  v_motivo motivos_cierre_turno_guardia%ROWTYPE;
  v_detalle text := NULLIF(btrim(COALESCE(p_detalle, '')), '');
  v_texto text;
  v_hora timestamp with time zone;
  v_atrasado boolean := COALESCE(p_reporte_atrasado, false);
  v_estado text;
  v_relevo timestamp with time zone;
BEGIN
  IF v_prestadora IS NULL THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;

  -- Quién cierra. Una persona con sesión cierra desde el Panel, siempre con motivo, y queda
  -- anotada ella. El backend, con el trabajo de la Prestadora, cierra lo que hizo el Asistente
  -- —sin motivo— o lo que autorizó alguien del Panel, en nombre de esa persona.
  IF v_persona THEN
    v_quien := interno.usuario_de_la_sesion();
    IF v_quien IS NULL
       OR NOT interno.es_personal_de_la_prestadora()
       OR NOT (interno.es_superadmin()
               OR interno.es_admin_prestadora()
               OR interno.coordinador_ve_el_turno_guardia(p_turno_guardia)) THEN
      RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
    END IF;
    IF p_motivo IS NULL THEN
      RAISE EXCEPTION 'falta_el_motivo' USING ERRCODE = 'P0001';
    END IF;
  ELSIF p_motivo IS NOT NULL THEN
    IF NOT interno.es_del_panel_de_la_prestadora(p_cerrada_por) THEN
      RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
    END IF;
    v_quien := p_cerrada_por;
  END IF;

  SELECT * INTO v_turno
    FROM turnos_guardia
   WHERE id = p_turno_guardia
     AND prestadora_id = v_prestadora
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no_encontrado' USING ERRCODE = 'P0001';
  END IF;
  IF v_turno.estado IS DISTINCT FROM 'activa' OR v_turno.checkout_at IS NOT NULL THEN
    RAISE EXCEPTION 'turno_guardia_ya_cerrado' USING ERRCODE = 'P0001';
  END IF;

  IF p_motivo IS NOT NULL THEN
    SELECT * INTO v_motivo
      FROM motivos_cierre_turno_guardia
     WHERE id = p_motivo
       AND prestadora_id = v_prestadora
       AND activo;
    IF NOT FOUND
       OR (v_motivo.lo_escribe_el_sistema AND NOT COALESCE(p_motivo_del_sistema, false)) THEN
      RAISE EXCEPTION 'motivo_de_salida_inexistente' USING ERRCODE = 'P0001';
    END IF;
    IF v_motivo.pide_detalle AND v_detalle IS NULL THEN
      RAISE EXCEPTION 'motivo_de_salida_pide_detalle' USING ERRCODE = 'P0001';
    END IF;
    v_texto := COALESCE(v_motivo.nombre, v_motivo.clave)
               || CASE WHEN v_detalle IS NULL THEN '' ELSE ' — ' || v_detalle END;
  END IF;

  -- La hora de salida: obligatoria, no en el futuro y no antes de la llegada. Un minuto de
  -- tolerancia en cada punta, porque el Panel la elige sin segundos.
  IF p_hora IS NULL THEN
    RAISE EXCEPTION 'hora_de_salida_obligatoria' USING ERRCODE = 'P0001';
  END IF;
  IF p_hora > now() + interval '1 minute' THEN
    RAISE EXCEPTION 'hora_de_salida_futura' USING ERRCODE = 'P0001';
  END IF;
  v_hora := LEAST(p_hora, now());
  IF v_turno.checkin_at IS NOT NULL AND v_hora < v_turno.checkin_at THEN
    IF v_hora >= date_trunc('minute', v_turno.checkin_at) THEN
      v_hora := v_turno.checkin_at;
    ELSE
      RAISE EXCEPTION 'hora_de_salida_anterior_a_la_llegada' USING ERRCODE = 'P0001';
    END IF;
  END IF;

  -- Quien cierra desde el Panel, o autoriza la salida, tampoco puede poner una hora posterior a la
  -- llegada ya registrada del Asistente que tomó el turno siguiente del mismo Paciente.
  IF p_motivo IS NOT NULL THEN
    v_relevo := interno.llegada_del_turno_siguiente(p_turno_guardia);
    IF v_relevo IS NOT NULL AND v_hora > v_relevo THEN
      RAISE EXCEPTION 'hora_de_salida_posterior_al_relevo' USING ERRCODE = 'P0001';
    END IF;
  END IF;

  -- El Reporte pendiente lo decide el backend. Lo que la base no acepta es un cierre que diga que
  -- están todos cuando a algún Paciente todavía le queda el suyo.
  IF NOT v_atrasado AND interno.el_reporte_esta_atrasado(p_turno_guardia) THEN
    RAISE EXCEPTION 'reporte_no_coincide' USING ERRCODE = 'P0001';
  END IF;

  v_estado := CASE WHEN v_atrasado THEN 'salida_sin_reporte' ELSE 'completada' END;

  PERFORM set_config('careonys.cierre_por_la_funcion', 'si', true);

  UPDATE turnos_guardia SET
    checkout_at  = v_hora,
    checkout_lat = CASE WHEN v_persona THEN NULL ELSE p_lat END,
    checkout_lng = CASE WHEN v_persona THEN NULL ELSE p_lng END,
    estado       = v_estado,
    salio_sin_reporte = salio_sin_reporte OR v_atrasado,
    factura_espera_el_reporte = CASE WHEN v_atrasado
                                     THEN NOT interno.factura_los_turnos_sin_reporte()
                                     ELSE factura_espera_el_reporte END,
    push_reporte_pendiente_enviado_at = CASE WHEN v_atrasado
                                             THEN now()
                                             ELSE push_reporte_pendiente_enviado_at END,
    cerrada_at        = CASE WHEN p_motivo IS NULL THEN cerrada_at ELSE now() END,
    cerrada_origen    = CASE WHEN p_motivo IS NULL THEN cerrada_origen ELSE 'panel' END,
    cerrada_por       = CASE WHEN p_motivo IS NULL THEN cerrada_por ELSE v_quien END,
    cerrada_motivo    = CASE WHEN p_motivo IS NULL THEN cerrada_motivo ELSE v_texto END,
    cerrada_motivo_id = CASE WHEN p_motivo IS NULL THEN cerrada_motivo_id ELSE p_motivo END
  WHERE id = p_turno_guardia
    AND prestadora_id = v_prestadora;

  PERFORM set_config('careonys.cierre_por_la_funcion', '', true);

  RETURN v_estado;
END;
$$;

ALTER FUNCTION interno.cerrar_el_turno_guardia(uuid, timestamp with time zone, boolean, uuid, text, uuid, double precision, double precision, boolean) OWNER TO postgres;
REVOKE ALL ON FUNCTION interno.cerrar_el_turno_guardia(uuid, timestamp with time zone, boolean, uuid, text, uuid, double precision, double precision, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION interno.cerrar_el_turno_guardia(uuid, timestamp with time zone, boolean, uuid, text, uuid, double precision, double precision, boolean) TO authenticated, trabajo_sin_persona, service_role;

COMMENT ON FUNCTION interno.cerrar_el_turno_guardia(uuid, timestamp with time zone, boolean, uuid, text, uuid, double precision, double precision, boolean) IS 'Único camino por el que un turno de guardia empezado se cierra: valida quién cierra, el motivo y la hora —no antes de la llegada, no después de este momento ni de la llegada del turno siguiente del mismo Paciente—, y lo deja completado o en Salida sin Reporte con la elección de la Prestadora sobre la factura.';


CREATE OR REPLACE FUNCTION interno.coordina_el_servicio_del_turno_guardia(p_turno_guardia uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'interno'
AS $$
  SELECT EXISTS (
    SELECT 1 FROM turnos_guardia g
     WHERE g.id = p_turno_guardia
       AND g.prestadora_id = interno.prestadora_actual()
       AND interno.coordina_el_servicio(g.servicio_id)
  );
$$;

ALTER FUNCTION interno.coordina_el_servicio_del_turno_guardia(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION interno.coordina_el_servicio_del_turno_guardia(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION interno.coordina_el_servicio_del_turno_guardia(uuid) TO authenticated, service_role;


CREATE OR REPLACE FUNCTION interno.el_cierre_pasa_por_la_funcion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $$
BEGIN
  IF current_user <> 'authenticated'
     OR COALESCE(current_setting('careonys.cierre_por_la_funcion', true), '') = 'si' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.checkout_at IS NOT NULL OR NEW.checkout_lat IS NOT NULL OR NEW.checkout_lng IS NOT NULL
       OR NEW.estado IN ('completada', 'salida_sin_reporte')
       OR NEW.cerrada_at IS NOT NULL OR NEW.cerrada_origen IS NOT NULL
       OR NEW.cerrada_por IS NOT NULL OR NEW.cerrada_motivo IS NOT NULL
       OR NEW.cerrada_motivo_id IS NOT NULL
       OR NEW.salio_sin_reporte OR NEW.factura_espera_el_reporte
       OR NEW.reporte_llego_at IS NOT NULL THEN
      RAISE EXCEPTION 'el_cierre_pasa_por_la_funcion' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;

  IF (NEW.checkout_at, NEW.checkout_lat, NEW.checkout_lng,
      NEW.cerrada_at, NEW.cerrada_origen, NEW.cerrada_por, NEW.cerrada_motivo, NEW.cerrada_motivo_id,
      NEW.salio_sin_reporte, NEW.factura_espera_el_reporte, NEW.reporte_llego_at)
     IS DISTINCT FROM
     (OLD.checkout_at, OLD.checkout_lat, OLD.checkout_lng,
      OLD.cerrada_at, OLD.cerrada_origen, OLD.cerrada_por, OLD.cerrada_motivo, OLD.cerrada_motivo_id,
      OLD.salio_sin_reporte, OLD.factura_espera_el_reporte, OLD.reporte_llego_at)
     OR (NEW.estado IN ('completada', 'salida_sin_reporte') AND NEW.estado IS DISTINCT FROM OLD.estado) THEN
    RAISE EXCEPTION 'el_cierre_pasa_por_la_funcion' USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;

ALTER FUNCTION interno.el_cierre_pasa_por_la_funcion() OWNER TO postgres;
REVOKE ALL ON FUNCTION interno.el_cierre_pasa_por_la_funcion() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION interno.el_cierre_pasa_por_la_funcion() TO authenticated, trabajo_sin_persona, service_role;

COMMENT ON FUNCTION interno.el_cierre_pasa_por_la_funcion() IS 'Una persona con sesión no escribe la salida, el cierre ni la marca del Reporte pendiente de un turno de guardia: eso lo hace sólo interno.cerrar_el_turno_guardia.';


CREATE OR REPLACE FUNCTION interno.el_reporte_esta_atrasado(p_turno_guardia uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'interno'
AS $$
  SELECT EXISTS (
    SELECT 1
      FROM turno_guardia_pacientes tp
     WHERE tp.turno_guardia_id = p_turno_guardia
       AND tp.prestadora_id = interno.prestadora_actual()
       AND NOT EXISTS (
         SELECT 1 FROM reportes r
          WHERE r.prestadora_id = tp.prestadora_id
            AND r.turno_guardia_id = p_turno_guardia
            AND r.paciente_id = tp.paciente_id
       )
  );
$$;

ALTER FUNCTION interno.el_reporte_esta_atrasado(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION interno.el_reporte_esta_atrasado(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION interno.el_reporte_esta_atrasado(uuid) TO authenticated, trabajo_sin_persona, service_role;


CREATE OR REPLACE FUNCTION interno.es_del_panel_de_la_prestadora(p_usuario uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'interno'
AS $$
  SELECT p_usuario IS NOT NULL AND EXISTS (
    SELECT 1 FROM usuarios u
     WHERE u.id = p_usuario
       AND (u.rol = 'superadmin'
            OR (u.rol IN ('admin_prestadora', 'coordinador')
                AND u.prestadora_id = interno.prestadora_actual()))
  );
$$;

ALTER FUNCTION interno.es_del_panel_de_la_prestadora(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION interno.es_del_panel_de_la_prestadora(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION interno.es_del_panel_de_la_prestadora(uuid) TO authenticated, trabajo_sin_persona, service_role;


CREATE OR REPLACE FUNCTION interno.factura_los_turnos_sin_reporte()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'interno'
AS $$
  SELECT COALESCE(
    (SELECT p.factura_turnos_sin_reporte FROM prestadoras p WHERE p.id = interno.prestadora_actual()),
    true
  );
$$;

ALTER FUNCTION interno.factura_los_turnos_sin_reporte() OWNER TO postgres;
REVOKE ALL ON FUNCTION interno.factura_los_turnos_sin_reporte() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION interno.factura_los_turnos_sin_reporte() TO authenticated, trabajo_sin_persona, service_role;


CREATE OR REPLACE FUNCTION interno.llegada_del_turno_siguiente(p_turno_guardia uuid)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE
 SECURITY DEFINER
 SET search_path TO 'public', 'interno'
AS $$
  WITH este AS (
    SELECT g.id, g.prestadora_id, g.checkin_at
      FROM turnos_guardia g
     WHERE g.id = p_turno_guardia
       AND g.prestadora_id = interno.prestadora_actual()
  ),
  sus_pacientes AS (
    SELECT tp.paciente_id
      FROM turno_guardia_pacientes tp
      JOIN este ON tp.turno_guardia_id = este.id AND tp.prestadora_id = este.prestadora_id
    UNION
    SELECT g.paciente_id
      FROM turnos_guardia g
      JOIN este ON g.id = este.id
     WHERE g.paciente_id IS NOT NULL
  ),
  otros AS (
    SELECT tp.turno_guardia_id AS id
      FROM turno_guardia_pacientes tp
      JOIN este ON tp.prestadora_id = este.prestadora_id
     WHERE tp.paciente_id IN (SELECT paciente_id FROM sus_pacientes)
    UNION
    SELECT g.id
      FROM turnos_guardia g
      JOIN este ON g.prestadora_id = este.prestadora_id
     WHERE g.paciente_id IN (SELECT paciente_id FROM sus_pacientes)
  )
  SELECT min(g.checkin_at)
    FROM turnos_guardia g
    JOIN este ON g.prestadora_id = este.prestadora_id
   WHERE g.id IN (SELECT id FROM otros)
     AND g.id <> este.id
     AND g.checkin_at IS NOT NULL
     AND (este.checkin_at IS NULL OR g.checkin_at > este.checkin_at);
$$;

ALTER FUNCTION interno.llegada_del_turno_siguiente(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION interno.llegada_del_turno_siguiente(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION interno.llegada_del_turno_siguiente(uuid) TO authenticated, trabajo_sin_persona, service_role;

COMMENT ON FUNCTION interno.llegada_del_turno_siguiente(uuid) IS 'Llegada registrada del primer turno de guardia posterior que comparte un Paciente con éste, en la Prestadora de la sesión. Límite de la hora de salida que se pone desde el Panel.';




CREATE OR REPLACE FUNCTION "interno"."el_contratante_lo_fija_la_administracion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF NEW.cliente_id IS DISTINCT FROM OLD.cliente_id
     AND COALESCE(auth.jwt() ->> 'role', '') = 'authenticated'
     AND NOT (interno.es_admin_prestadora() OR interno.es_superadmin()) THEN
    RAISE EXCEPTION 'el_contratante_lo_fija_la_administracion';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."el_contratante_lo_fija_la_administracion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."el_coordinador_del_servicio_lo_asigna_la_administracion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.coordinador_id IS NOT DISTINCT FROM OLD.coordinador_id THEN
    NEW.coordinador_asignado_por := OLD.coordinador_asignado_por;
    NEW.coordinador_asignado_en := OLD.coordinador_asignado_en;
    RETURN NEW;
  END IF;

  IF NEW.coordinador_id IS NULL THEN
    IF TG_OP = 'UPDATE' THEN
      RAISE EXCEPTION 'el_servicio_no_se_queda_sin_coordinador';
    END IF;
    NEW.coordinador_asignado_por := NULL;
    NEW.coordinador_asignado_en := NULL;
    RETURN NEW;
  END IF;

  -- Una persona con sesión sólo asigna si administra la Prestadora. Lo que corre sin persona —el
  -- trabajo de la Prestadora, la carga de datos inventados— no pasa por esta pregunta.
  IF COALESCE(auth.jwt() ->> 'role', '') = 'authenticated'
     AND NOT (interno.es_admin_prestadora() OR interno.es_superadmin()) THEN
    RAISE EXCEPTION 'el_coordinador_lo_asigna_la_administracion';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM usuarios u
     WHERE u.id = NEW.coordinador_id
       AND u.prestadora_id = NEW.prestadora_id
       AND u.rol = 'coordinador'
       AND u.desactivada_en IS NULL
  ) THEN
    RAISE EXCEPTION 'el_asignado_no_coordina_en_la_prestadora';
  END IF;

  NEW.coordinador_asignado_por := CASE WHEN auth.uid() IS NULL THEN NEW.coordinador_asignado_por
                                       ELSE auth.uid() END;
  NEW.coordinador_asignado_en := now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."el_coordinador_del_servicio_lo_asigna_la_administracion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."el_documento_del_asistente_es_valido"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
declare
  v record;
begin
  if new.genero is null or btrim(new.genero) = '' then
    raise exception 'falta_el_genero';
  end if;
  select * into v
    from interno.identidad_validada(new.prestadora_id, 'fisica', new.documento_tipo,
                                    new.documento_numero, new.documento_pais, new.dni, new.genero);
  new.documento_numero := v.numero;
  new.documento_pais := v.pais;
  new.dni := v.dni;
  new.genero := v.genero;
  return new;
end;
$$;


ALTER FUNCTION "interno"."el_documento_del_asistente_es_valido"() OWNER TO "postgres";


