    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  PERFORM interno.el_email_pasa_a_la_cuenta(NEW.usuario_id, NEW.email);
  RETURN NULL;
END;
$$;


ALTER FUNCTION "interno"."el_email_del_legajo_pasa_a_la_cuenta"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."el_email_pasa_a_la_cuenta"("p_cuenta" "uuid", "p_email" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_email text := lower(btrim(coalesce(p_email, ''), E' \t\r\n'));
BEGIN
  IF p_cuenta IS NULL OR v_email = '' THEN RETURN; END IF;
  UPDATE usuarios SET email = v_email
   WHERE id = p_cuenta AND email IS DISTINCT FROM v_email;
EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION 'correo_de_esta_prestadora';
END;
$$;


ALTER FUNCTION "interno"."el_email_pasa_a_la_cuenta"("p_cuenta" "uuid", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."el_estado_se_resuelve_no_se_pisa"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_estado_resuelto text;
BEGIN
  -- La última resolución de esta misma fila. `created_at` no alcanza para desempatar dentro de una
  -- transacción, así que desempata la secuencia, igual que en `resoluciones_vigentes`.
  SELECT r.estado
    INTO v_estado_resuelto
    FROM public.resoluciones r
   WHERE r.prestadora_id = NEW.prestadora_id
     AND r.tabla = TG_TABLE_NAME
     AND r.fila_id = NEW.id::text
   ORDER BY r.created_at DESC, r.secuencia DESC
   LIMIT 1;

  IF v_estado_resuelto IS NULL OR v_estado_resuelto IS DISTINCT FROM NEW.estado THEN
    RAISE EXCEPTION 'el_estado_se_resuelve_no_se_pisa';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."el_estado_se_resuelve_no_se_pisa"() OWNER TO "postgres";


COMMENT ON FUNCTION "interno"."el_estado_se_resuelve_no_se_pisa"() IS 'Impide escribir el estado a mano: solo queda el que diga la ultima resolucion de esa fila, que escribe public.resolver con el motivo y la firma de quien decidio.';



