CREATE OR REPLACE FUNCTION "interno"."el_registro_de_actividad_solo_lleva_lo_permitido"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_clave text;
BEGIN
  IF NEW.usuario_id IS NULL AND NOT EXISTS (
       SELECT 1 FROM public.catalogo_acciones_registradas
        WHERE accion = NEW.accion AND la_hace_el_sistema) THEN
    RAISE EXCEPTION 'Esa accion la hace una persona y tiene que decir quien' USING ERRCODE = '23502';
  END IF;

  IF NEW.detalle IS NULL THEN
    RETURN NEW;
  END IF;

  IF jsonb_typeof(NEW.detalle) <> 'object' THEN
    RAISE EXCEPTION 'El detalle del registro de actividad tiene que ser un objeto';
  END IF;

  FOR v_clave IN SELECT jsonb_object_keys(NEW.detalle) LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.catalogo_datos_del_registro WHERE clave = v_clave
    ) THEN
      RAISE EXCEPTION 'El registro de actividad no admite el dato %', v_clave;
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."el_registro_de_actividad_solo_lleva_lo_permitido"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."el_relevo_se_resuelve_como_paso"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_asistente_del_turno_guardia uuid;
  v_llego_tarde boolean;
BEGIN
  -- Ya resuelto: queda como quedó.
  IF OLD.resuelto_at IS NOT NULL THEN
    NEW.resuelto_at := OLD.resuelto_at;
    NEW.resuelto_por_tipo := OLD.resuelto_por_tipo;
    NEW.resuelto_por_id := OLD.resuelto_por_id;
    NEW.resuelto_por_usuario := OLD.resuelto_por_usuario;
    RETURN NEW;
  END IF;

  IF NEW.resuelto_at IS NULL THEN
    NEW.resuelto_por_tipo := NULL;
    NEW.resuelto_por_id := NULL;
    NEW.resuelto_por_usuario := NULL;
    RETURN NEW;
  END IF;

  NEW.resuelto_por_usuario := interno.usuario_de_la_sesion();

  IF NEW.resuelto_por_id IS NOT NULL THEN
    SELECT g.asistente_id, g.llegada_tarde INTO v_asistente_del_turno_guardia, v_llego_tarde
      FROM turnos_guardia g
     WHERE g.id = NEW.turno_guardia_entrante_id
       AND g.prestadora_id = NEW.prestadora_id;
    IF v_asistente_del_turno_guardia IS DISTINCT FROM NEW.resuelto_por_id THEN
      RAISE EXCEPTION 'relevo_con_otro_asistente' USING ERRCODE = '23514';
    END IF;

    -- Es el titular sólo si marcó la llegada sobre la guardia ausente: quien la cubre entra sobre
    -- una guardia que la reasignación ya volvió a programada, así que nunca llega tarde por esto.
    IF NEW.resuelto_por_tipo = 'titular' THEN
      IF NOT coalesce(v_llego_tarde, false) THEN
        RAISE EXCEPTION 'relevo_con_otro_asistente' USING ERRCODE = '23514';
      END IF;
      RETURN NEW;
    END IF;

    NEW.resuelto_por_tipo := coalesce(
      (SELECT pe.tipo
         FROM personal_emergencia pe
        WHERE pe.asistente_id = NEW.resuelto_por_id
          AND pe.prestadora_id = NEW.prestadora_id
          AND pe.activo
        ORDER BY (pe.tipo = 'franquero') DESC
        LIMIT 1),
      'suplente');
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."el_relevo_se_resuelve_como_paso"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."el_servicio_nace_con_sus_condiciones_comerciales"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  INSERT INTO condiciones_comerciales_servicio (servicio_id, prestadora_id, contratante_persona_id)
  SELECT NEW.id, NEW.prestadora_id, c.contratante_persona_id
    FROM clientes c
   WHERE c.id = NEW.cliente_id AND c.prestadora_id = NEW.prestadora_id
  ON CONFLICT (servicio_id) DO NOTHING;
  RETURN NEW;
END;
$$;


