    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT interno.es_personal_de_la_prestadora() AND interno.tiene_permiso('ver_facturacion_cliente');
$$;


