CREATE OR REPLACE FUNCTION "interno"."hay_excepcion_por_documentos"("p_turno_guardia_id" "uuid", "p_asistente_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
