    SELECT 1 FROM public.excepciones_por_documentos e
      JOIN public.turnos_guardia g ON g.id = e.turno_guardia_id AND g.prestadora_id = e.prestadora_id
     WHERE e.turno_guardia_id = p_turno_guardia_id
