CREATE OR REPLACE FUNCTION "interno"."la_restriccion_de_hce_se_apaga_donde_se_puede"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.prestadora_id IS DISTINCT FROM OLD.prestadora_id THEN
    RAISE EXCEPTION 'La restricción de HCE no cambia de Prestadora';
  END IF;

  IF NOT NEW.restriccion_de_hce THEN
    IF interno.el_pais_exige_la_restriccion_de_hce(NEW.prestadora_id) THEN
      RAISE EXCEPTION 'En el país de esta Prestadora la ley no permite apagarla'
        USING ERRCODE = 'check_violation';
    END IF;
    IF interno.usuario_de_la_sesion() IS NULL THEN
      RAISE EXCEPTION 'Apagarla exige una persona con sesión, para que quede registrado quién lo hizo'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."la_restriccion_de_hce_se_apaga_donde_se_puede"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."la_tarea_acordada_no_esta_prohibida"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
declare
  la_tarea public.tareas_tipo_asistente%rowtype;
  el_tipo public.tipos_asistente%rowtype;
  el_pais text;
begin
  select pais into el_pais from public.prestadoras where id = new.prestadora_id;

  select * into el_tipo from public.tipos_asistente where id = new.tipo_asistente_id;
  if not found
     or (el_tipo.prestadora_id is not null and el_tipo.prestadora_id <> new.prestadora_id) then
    raise exception 'El tipo de Asistente no existe o no es de esta Prestadora.' using errcode = 'P0001';
  end if;

  select * into la_tarea from public.tareas_tipo_asistente where id = new.tarea_id;
  if not found
     or (la_tarea.prestadora_id is null and la_tarea.pais is distinct from el_pais)
     or (la_tarea.prestadora_id is not null and la_tarea.prestadora_id <> new.prestadora_id) then
    raise exception 'La tarea no existe o no es de esta Prestadora.' using errcode = 'P0001';
  end if;

  if la_tarea.clase = 'prohibida' then
    raise exception 'Una prohibición no es una tarea que se acuerde.' using errcode = 'P0001';
  end if;

  if el_tipo.recibe_solo_sus_tareas and la_tarea.tipo_asistente_id <> el_tipo.id then
    raise exception 'Ese tipo de Asistente sólo recibe sus propias tareas.' using errcode = 'P0001';
  end if;

  if exists (
    select 1
      from public.tareas_que_alcanza_la_prohibicion a
      join public.tareas_tipo_asistente p on p.id = a.prohibicion_id
     where a.tarea_id = new.tarea_id
       and p.tipo_asistente_id = new.tipo_asistente_id
       and p.clase = 'prohibida'
       and (p.prestadora_id = new.prestadora_id
            or (p.prestadora_id is null and p.pais = el_pais))
  ) then
    raise exception 'Esa tarea está prohibida para ese tipo de Asistente.' using errcode = 'P0001';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "interno"."la_tarea_acordada_no_esta_prohibida"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."la_toma_la_suelta_quien_la_tomo"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF interno.usuario_de_la_sesion() IS NOT NULL AND interno.usuario_de_la_sesion() IS DISTINCT FROM OLD.tomada_por THEN
    RAISE EXCEPTION 'alarma_tomada_por_otra_persona' USING ERRCODE = '42501';
  END IF;
  IF OLD.soltada_at IS NOT NULL THEN
    RAISE EXCEPTION 'toma_ya_soltada' USING ERRCODE = '23514';
  END IF;

  NEW.id := OLD.id;
  NEW.prestadora_id := OLD.prestadora_id;
  NEW.tipo := OLD.tipo;
  NEW.referencia_id := OLD.referencia_id;
  NEW.tomada_por := OLD.tomada_por;
  NEW.tomada_at := OLD.tomada_at;
  NEW.vence_at := OLD.vence_at;
  IF NEW.soltada_at IS NOT NULL THEN
    NEW.soltada_at := now();
  END IF;
  RETURN NEW;
END;
$$;


