CREATE OR REPLACE FUNCTION "interno"."se_habilita_hacia_abajo_y_nunca_a_uno_mismo"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_destinatario record;
  v_quien record;
  v_quien_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'cambios_de_clave_habilitados' THEN
    v_quien_id := NEW.habilitado_por;
  ELSE
    v_quien_id := NEW.confirmado_por;
  END IF;

  SELECT rol, prestadora_id INTO v_destinatario FROM public.usuarios WHERE id = NEW.usuario_id;
  SELECT rol, prestadora_id INTO v_quien FROM public.usuarios WHERE id = v_quien_id;

  -- Falla cerrado ante cualquier cosa que no se pudo resolver.
  IF v_destinatario IS NULL OR v_quien IS NULL THEN
    RAISE EXCEPTION 'No se pudo resolver quién habilita a quién';
  END IF;

  -- Las dos cuentas son de la Prestadora de la fila, y de ninguna otra. El rol técnico de la
  -- empresa no tiene Prestadora propia, y por eso queda exceptuado del lado de quien habilita.
  IF v_destinatario.prestadora_id IS DISTINCT FROM NEW.prestadora_id THEN
    RAISE EXCEPTION 'La cuenta no es de esa Prestadora';
  END IF;
  IF v_quien.rol <> 'superadmin' AND v_quien.prestadora_id IS DISTINCT FROM NEW.prestadora_id THEN
    RAISE EXCEPTION 'Quien habilita no es de esa Prestadora';
  END IF;

  IF NOT interno.puede_habilitar(v_quien.rol, v_destinatario.rol) THEN
    RAISE EXCEPTION 'Nadie habilita a su propio escalón ni a uno de más arriba';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."se_habilita_hacia_abajo_y_nunca_a_uno_mismo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."servicio_a_revisar_al_programar"("p_nuevo" "jsonb", "p_viejo" "jsonb", "p_operacion" "text") RETURNS "uuid"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT CASE
    -- Una guardia que genera una serie: la serie ya se revisó al crearse.
    WHEN p_nuevo ->> 'serie_id' IS NOT NULL THEN NULL
    WHEN p_nuevo ->> 'servicio_id' IS NULL THEN NULL
    -- Un cambio que no la pasa a otro Servicio.
    WHEN p_operacion = 'UPDATE'
         AND (p_nuevo ->> 'servicio_id') IS NOT DISTINCT FROM (p_viejo ->> 'servicio_id') THEN NULL
    ELSE (p_nuevo ->> 'servicio_id')::uuid
  END;
$$;


ALTER FUNCTION "interno"."servicio_a_revisar_al_programar"("p_nuevo" "jsonb", "p_viejo" "jsonb", "p_operacion" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."sin_coordinador_no_hay_turnos_guardia"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_servicio uuid := interno.servicio_a_revisar_al_programar(
    to_jsonb(NEW), CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) END, TG_OP);
BEGIN
  IF v_servicio IS NULL THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM servicios s
     WHERE s.id = v_servicio
       AND s.prestadora_id = NEW.prestadora_id
       AND s.coordinador_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'servicio_sin_coordinador:%', v_servicio;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "interno"."sin_coordinador_no_hay_turnos_guardia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."sin_firma_del_pagador_no_hay_turnos_guardia"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_servicio uuid := interno.servicio_a_revisar_al_programar(
    to_jsonb(NEW), CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) END, TG_OP);
BEGIN
  IF v_servicio IS NULL THEN
    RETURN NEW;
