  IF interno.falta_la_firma_del_pagador(v_servicio) THEN
    RAISE EXCEPTION 'servicio_sin_firma_del_pagador' USING DETAIL = v_servicio::text;
  END IF;
  RETURN NEW;
END;
$$;


