CREATE OR REPLACE FUNCTION "interno"."valor_del_indice_de_la_prestadora"("p_prestadora" "uuid", "p_indice" "text", "p_periodo" "date") RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
