CREATE OR REPLACE FUNCTION "interno"."vencimiento_de_la_solicitud"("p_prestadora" "uuid", "p_tipo" "text", "p_recibida" timestamp with time zone) RETURNS TABLE("plazo_id" "uuid", "vence_en" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  WITH lugar AS (
    SELECT pr.pais, interno.zona_horaria_de_la_prestadora(pr.id) AS zona
      FROM prestadoras pr
     WHERE pr.id = p_prestadora
  )
  SELECT pz.id,
         CASE pz.unidad
           WHEN 'horas' THEN p_recibida + make_interval(hours => pz.cantidad)
           WHEN 'dias_corridos' THEN p_recibida + make_interval(days => pz.cantidad)
           ELSE interno.sumar_dias_habiles(l.pais, p_recibida, pz.cantidad)
         END
    FROM lugar l
    JOIN plazos_de_respuesta_de_derechos pz
      ON pz.pais = l.pais
     AND pz.tipo = p_tipo
     AND pz.vigente_desde <= (p_recibida AT TIME ZONE l.zona)::date
     AND (pz.vigente_hasta IS NULL OR pz.vigente_hasta >= (p_recibida AT TIME ZONE l.zona)::date)
   ORDER BY pz.vigente_desde DESC
   LIMIT 1
$$;


ALTER FUNCTION "interno"."vencimiento_de_la_solicitud"("p_prestadora" "uuid", "p_tipo" "text", "p_recibida" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."verificar_cadena_de_consultas"("p_prestadora" "uuid") RETURNS TABLE("intacta" boolean, "renglones" bigint, "rota_en_numero" bigint, "rota_en_id" "uuid", "motivo" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  r           consultas_a_hce;
  v_corte     record;
  v_esperado  bigint;
  v_anterior  bytea;
  v_cuantos   bigint := 0;
BEGIN
  SELECT c.hasta_numero, c.ultimo_resumen INTO v_corte
    FROM cortes_de_consultas_a_hce c
   WHERE c.prestadora_id = p_prestadora
   ORDER BY c.hasta_numero DESC
   LIMIT 1;
  v_esperado := COALESCE(v_corte.hasta_numero, 0) + 1;
  v_anterior := v_corte.ultimo_resumen;

  FOR r IN
    SELECT * FROM consultas_a_hce a
     WHERE a.prestadora_id = p_prestadora
     ORDER BY a.numero
  LOOP
    IF r.numero <> v_esperado THEN
      RETURN QUERY SELECT false, v_cuantos, r.numero, r.id, 'falta_un_renglon'::text;
      RETURN;
    END IF;
    IF r.resumen_anterior IS DISTINCT FROM v_anterior THEN
      RETURN QUERY SELECT false, v_cuantos, r.numero, r.id, 'no_sigue_al_anterior'::text;
      RETURN;
    END IF;
    IF r.resumen IS DISTINCT FROM interno.resumen_de_la_consulta(r) THEN
      RETURN QUERY SELECT false, v_cuantos, r.numero, r.id, 'el_renglon_fue_alterado'::text;
      RETURN;
    END IF;
    v_anterior := r.resumen;
    v_esperado := v_esperado + 1;
    v_cuantos := v_cuantos + 1;
  END LOOP;

  RETURN QUERY SELECT true, v_cuantos, NULL::bigint, NULL::uuid, NULL::text;
END;
$$;


ALTER FUNCTION "interno"."verificar_cadena_de_consultas"("p_prestadora" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "interno"."versionar_tabla_clinica"("p_tabla" "regclass") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $_$
DECLARE
  v_nombre text;
BEGIN
  SELECT c.relname INTO v_nombre
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
   WHERE c.oid = p_tabla AND n.nspname = 'public';
  IF v_nombre IS NULL THEN
    RAISE EXCEPTION 'Sólo se versionan tablas del esquema public: %', p_tabla;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                  WHERE table_schema = 'public' AND table_name = v_nombre
                    AND column_name = 'id' AND data_type = 'uuid')
     OR NOT EXISTS (SELECT 1 FROM information_schema.columns
                  WHERE table_schema = 'public' AND table_name = v_nombre
                    AND column_name = 'prestadora_id' AND data_type = 'uuid') THEN
    RAISE EXCEPTION 'La tabla % necesita id uuid y prestadora_id uuid para versionarse', v_nombre;
  END IF;

  EXECUTE format('ALTER TABLE %s ADD COLUMN IF NOT EXISTS nota_aclaratoria text', p_tabla);

  -- Lo que ya estaba escrito entra como primera versión. Lo que se pisó antes de hoy no se
  -- recupera: el momento es el de la última escritura conocida y el autor queda sin saberse.
  EXECUTE format($f$
    INSERT INTO versiones_registro_clinico
      (prestadora_id, paciente_id, tabla, registro_id, version, operacion, datos,
       nota_aclaratoria, autor_id, credencial_rol, momento)
    SELECT (to_jsonb(t) ->> 'prestadora_id')::uuid, (to_jsonb(t) ->> 'paciente_id')::uuid,
           %L, t.id, 1, 'anterior_al_historial', to_jsonb(t), NULL, NULL, session_user::text,
           COALESCE((to_jsonb(t) ->> 'updated_at')::timestamptz,
                    (to_jsonb(t) ->> 'created_at')::timestamptz, now())
      FROM %s t
     WHERE NOT EXISTS (SELECT 1 FROM versiones_registro_clinico v
                        WHERE v.tabla = %L AND v.registro_id = t.id)
  $f$, v_nombre, p_tabla, v_nombre);

  EXECUTE format('DROP TRIGGER IF EXISTS trg_la_nota_es_de_una_version ON %s', p_tabla);
  EXECUTE format('CREATE TRIGGER trg_la_nota_es_de_una_version BEFORE UPDATE ON %s
                  FOR EACH ROW EXECUTE FUNCTION interno.la_nota_aclaratoria_es_de_una_version()', p_tabla);

  EXECUTE format('DROP TRIGGER IF EXISTS trg_versiones_del_registro_clinico ON %s', p_tabla);
  EXECUTE format('CREATE TRIGGER trg_versiones_del_registro_clinico AFTER INSERT OR UPDATE OR DELETE ON %s
                  FOR EACH ROW EXECUTE FUNCTION interno.anotar_version_clinica()', p_tabla);
END;
$_$;


ALTER FUNCTION "interno"."versionar_tabla_clinica"("p_tabla" "regclass") OWNER TO "postgres";



CREATE OR REPLACE FUNCTION "interno"."zona_horaria_de_la_prestadora"("p_prestadora" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT COALESCE((SELECT p.zona_horaria FROM prestadoras p WHERE p.id = p_prestadora), 'UTC')
$$;


ALTER FUNCTION "interno"."zona_horaria_de_la_prestadora"("p_prestadora" "uuid") OWNER TO "postgres";



CREATE OR REPLACE FUNCTION "public"."abrir_acceso_de_emergencia"("p_paciente" "uuid", "p_motivo" "text") RETURNS TABLE("id" "uuid", "hasta" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_usuario    uuid := auth.uid();
  v_prestadora uuid := interno.prestadora_actual();
  v_minutos    integer;
  v_id         uuid;
  v_hasta      timestamp with time zone;
BEGIN
  IF v_usuario IS NULL OR v_prestadora IS NULL OR NOT interno.es_personal_de_la_prestadora() THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;

  IF p_motivo IS NULL OR btrim(p_motivo) = '' THEN
    RAISE EXCEPTION 'faltan_datos' USING ERRCODE = '22023';
  END IF;

  IF p_paciente IS NULL OR NOT EXISTS (SELECT 1 FROM pacientes p
                                        WHERE p.id = p_paciente
                                          AND p.prestadora_id = v_prestadora) THEN
    RAISE EXCEPTION 'no_encontrado' USING ERRCODE = 'P0002';
  END IF;

  -- Quien ya alcanza esa información no necesita un acceso de emergencia.
  IF interno.alcanza_la_informacion_de_salud(p_paciente) THEN
    RAISE EXCEPTION 'ya_alcanza' USING ERRCODE = 'P0001';
  END IF;

  -- La configuración de la Prestadora, con sus valores de arranque si todavía no tenía.
  INSERT INTO configuracion_de_hce (prestadora_id) VALUES (v_prestadora)
  ON CONFLICT (prestadora_id) DO NOTHING;

  SELECT c.minutos_de_acceso_de_emergencia INTO v_minutos
    FROM configuracion_de_hce c
   WHERE c.prestadora_id = v_prestadora;

  INSERT INTO accesos_de_emergencia AS a (prestadora_id, usuario_id, paciente_id, motivo, desde, hasta)
  VALUES (v_prestadora, v_usuario, p_paciente, btrim(p_motivo), now(),
          now() + make_interval(mins => v_minutos))
  RETURNING a.id, a.hasta INTO v_id, v_hasta;

  INSERT INTO registro_actividad (prestadora_id, usuario_id, accion, tabla_afectada, registro_id)
  VALUES (v_prestadora, v_usuario, 'acceso_de_emergencia', 'accesos_de_emergencia', v_id);

  RETURN QUERY SELECT v_id, v_hasta;
END;
$$;


ALTER FUNCTION "public"."abrir_acceso_de_emergencia"("p_paciente" "uuid", "p_motivo" "text") OWNER TO "postgres";



CREATE OR REPLACE FUNCTION "public"."accesos_a_la_informacion_de_salud_del_paciente"("p_paciente" "uuid", "p_limite" integer DEFAULT 500) RETURNS TABLE("momento" timestamp with time zone, "quien" "text", "rol" "text", "origen" "text", "categorias" "text"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_usuario uuid := interno.usuario_de_la_sesion();
  v_prest   uuid := interno.prestadora_actual();
BEGIN
  IF v_usuario IS NULL OR v_prest IS NULL THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF p_limite IS NULL OR p_limite < 1 OR p_limite > 5000 THEN
    RAISE EXCEPTION 'dato_invalido' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM pacientes pa
     WHERE pa.id = p_paciente
       AND pa.prestadora_id = v_prest
       AND pa.deleted_at IS NULL
       AND pa.cliente_id = interno.cliente_id_de_usuario(v_usuario)
       AND interno.persona_autorizada_puede(v_usuario, 'persona_autorizada_ficha_del_paciente')
  ) THEN
    RAISE EXCEPTION 'paciente_no_encontrado' USING ERRCODE = 'P0001';
  END IF;

  RETURN QUERY
    SELECT c.momento, u.nombre, u.rol, c.origen, c.categorias
      FROM consultas_a_hce c
      LEFT JOIN usuarios u ON u.id = c.usuario_id
     WHERE c.prestadora_id = v_prest
       AND c.paciente_id = p_paciente
     ORDER BY c.momento DESC
     LIMIT p_limite;
END;
$$;


ALTER FUNCTION "public"."accesos_a_la_informacion_de_salud_del_paciente"("p_paciente" "uuid", "p_limite" integer) OWNER TO "postgres";



CREATE OR REPLACE FUNCTION "public"."accesos_fuera_de_lo_normal"("p_desde" "date", "p_hasta" "date") RETURNS TABLE("consulta_id" "uuid", "usuario_id" "uuid", "persona" "text", "paciente_id" "uuid", "paciente" "text", "categorias" "text"[], "momento" timestamp with time zone, "origen" "text", "motivos" "text"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
BEGIN
  IF v_prestadora IS NULL OR NOT interno.es_la_administracion_de_la_prestadora(v_prestadora) THEN
    RAISE EXCEPTION 'Sin permiso para revisar el registro de accesos' USING ERRCODE = '42501';
  END IF;
  IF p_desde IS NULL OR p_hasta IS NULL OR p_hasta < p_desde THEN
    RAISE EXCEPTION 'El período no es válido' USING ERRCODE = '22023';
  END IF;
  RETURN QUERY SELECT * FROM interno.accesos_fuera_de_lo_normal_de(v_prestadora, p_desde, p_hasta);
END;
$$;


ALTER FUNCTION "public"."accesos_fuera_de_lo_normal"("p_desde" "date", "p_hasta" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aceptar_asignacion"("p_asignacion_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
  v_asistente  uuid := interno.asistente_de_la_sesion();
  v_asignacion public.asignaciones_de_turno_guardia;
  v_tomadas    integer;
BEGIN
  IF v_prestadora IS NULL OR v_asistente IS NULL THEN
    RAISE EXCEPTION 'asignacion_no_encontrada';
  END IF;

  SELECT * INTO v_asignacion
    FROM asignaciones_de_turno_guardia
   WHERE id = p_asignacion_id
     AND prestadora_id = v_prestadora
     AND asistente_id = v_asistente
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'asignacion_no_encontrada';
  END IF;

  IF v_asignacion.estado <> 'sin_responder' THEN
    RAISE EXCEPTION 'asignacion_ya_respondida';
  END IF;

  IF v_asignacion.turno_guardia_id IS NOT NULL THEN
    UPDATE turnos_guardia
       SET asistente_id = v_asistente
     WHERE id = v_asignacion.turno_guardia_id
       AND prestadora_id = v_prestadora
       AND estado = 'programada'
       AND asistente_id IS NULL;

    GET DIAGNOSTICS v_tomadas = ROW_COUNT;
    IF v_tomadas = 0 THEN
      RAISE EXCEPTION 'turno_guardia_ya_cubierto';
    END IF;

  ELSIF v_asignacion.serie_id IS NOT NULL THEN
    UPDATE series_turnos_guardia
       SET asistente_id = v_asistente
     WHERE id = v_asignacion.serie_id
       AND prestadora_id = v_prestadora
       AND estado = 'activa'
       AND asistente_id IS NULL;

    GET DIAGNOSTICS v_tomadas = ROW_COUNT;
    IF v_tomadas = 0 THEN
      RAISE EXCEPTION 'turno_guardia_ya_cubierto';
    END IF;

    -- Los turnos que vienen pasan a ser suyos: los que no tienen a nadie y los que seguía haciendo
    -- quien tenía el turno fijo antes. Los que esperan la respuesta de otro por ese día quedan como
    -- están. Ya contestó que sí: no le llega un aviso por cada día.
    UPDATE turnos_guardia g
       SET asistente_id = v_asistente,
           push_asignacion_enviado_at = now()
     WHERE g.serie_id = v_asignacion.serie_id
       AND g.prestadora_id = v_prestadora
       AND g.estado = 'programada'
       AND (g.asistente_id IS NULL OR g.asistente_id = v_asignacion.asistente_anterior_id)
       AND g.fecha >= interno.hoy_de_la_prestadora(v_prestadora)
       AND NOT EXISTS (
         SELECT 1 FROM asignaciones_de_turno_guardia o
          WHERE o.turno_guardia_id = g.id
            AND o.estado = 'sin_responder'
       );

  ELSE
    UPDATE coberturas_de_ausencia
       SET aceptada_at = now()
     WHERE ausencia_id = v_asignacion.ausencia_id
       AND prestadora_id = v_prestadora
       AND asistente_sustituto_id = v_asistente
       AND aceptada_at IS NULL
       AND objetada_at IS NULL;
  END IF;

  UPDATE asignaciones_de_turno_guardia
     SET estado = 'aceptada'
   WHERE id = v_asignacion.id;

  RETURN v_asignacion.turno_guardia_id;
END;
$$;


ALTER FUNCTION "public"."aceptar_asignacion"("p_asignacion_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."activar_la_cuenta"("p_codigo" "text", "p_clave" "text", "p_usuario" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid;
  v_usuario uuid;
  v_rol text;
  v_nombre text;
BEGIN
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'trabajo_sin_persona' THEN RETURN NULL; END IF;
  v_prestadora := interno.prestadora_actual();
  IF v_prestadora IS NULL OR coalesce(p_codigo, '') = '' OR coalesce(p_clave, '') = '' THEN
    RETURN NULL;
  END IF;

  UPDATE tokens_activacion_cuenta t SET usado_en = now()
    FROM usuarios u
   WHERE t.token = encode(extensions.digest(p_codigo, 'sha256'), 'hex')
     AND t.usado_en IS NULL AND t.expira_en > now()
     AND u.id = t.usuario_id AND u.prestadora_id = v_prestadora
     AND u.rol IN ('coordinador', 'asistente', 'cliente')
  RETURNING t.usuario_id, u.rol INTO v_usuario, v_rol;

  IF v_usuario IS NULL THEN RETURN NULL; END IF;

  -- La coordinación ya tiene el suyo. Asistentes y Clientes lo eligen ahora.
  IF v_rol IN ('asistente', 'cliente') THEN
    v_nombre := lower(btrim(coalesce(p_usuario, ''), E' \t\r\n'));
    IF v_nombre = '' THEN RAISE EXCEPTION 'faltan_datos'; END IF;
    IF NOT interno.usuario_elegido_bien_escrito(v_nombre) THEN RAISE EXCEPTION 'usuario_mal_escrito'; END IF;
    IF EXISTS (SELECT 1 FROM usuarios WHERE lower(nombre_de_usuario) = v_nombre AND id <> v_usuario
                  AND desactivada_en IS NULL) THEN
      RAISE EXCEPTION 'usuario_en_uso';
    END IF;
    BEGIN
      UPDATE usuarios SET nombre_de_usuario = v_nombre WHERE id = v_usuario;
    EXCEPTION WHEN unique_violation THEN
      RAISE EXCEPTION 'usuario_en_uso';
    END;
  END IF;

  UPDATE auth.users
     SET encrypted_password = extensions.crypt(p_clave, extensions.gen_salt('bf', 10)),
         updated_at = now()
   WHERE id = v_usuario;
  IF NOT FOUND THEN RAISE EXCEPTION 'activar_la_cuenta: la cuenta no tiene ingreso'; END IF;

  RETURN v_usuario;
END;
$$;


ALTER FUNCTION "public"."activar_la_cuenta"("p_codigo" "text", "p_clave" "text", "p_usuario" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."actualizar_precios_por_indice"("p_desde" "date", "p_periodo_base" "date", "p_periodo_nuevo" "date", "p_aplicar" boolean) RETURNS TABLE("clase" "text", "renglon_id" bigint, "renglon_nuevo_id" bigint, "servicio_id" "uuid", "descripcion" "text", "indice" "text", "precio_actual" numeric, "precio_nuevo" numeric, "moneda" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_prestadora  uuid := interno.prestadora_actual();
  v_regla       jsonb;
  v_indice_p    text;
  v_factor      numeric;
  v_lista       public.lista_precios;
  v_prestacion  record;
  v_pendientes  jsonb;
  v_elemento    jsonb;
  v_reemplazo   bigint;
BEGIN
  IF v_prestadora IS NULL OR NOT interno.es_la_administracion_de_la_prestadora(v_prestadora) THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF p_desde IS NULL OR p_periodo_base IS NULL OR p_periodo_nuevo IS NULL
     OR p_desde <> date_trunc('month', p_desde)::date
     OR date_trunc('month', p_periodo_nuevo) <= date_trunc('month', p_periodo_base) THEN
    RAISE EXCEPTION 'dato_invalido' USING ERRCODE = 'P0001';
  END IF;

  SELECT c.regla INTO v_regla FROM public.configuracion_facturacion_clientes c
   WHERE c.prestadora_id = v_prestadora;
  -- Igual que `condicionDe` de `panel/src/lib/condicionesDelCliente.js`: 'ninguno' es «sin índice».
  v_indice_p := NULLIF(NULLIF(btrim(coalesce(v_regla ->> 'indice_de_actualizacion', '')), ''), 'ninguno');

  -- Las prestaciones se eligen antes de tocar la lista, con su marca de revisión de ese momento:
  -- reemplazar un renglón de la lista marca a revisar las que apuntan a él, y la que se versiona
  -- acá no tiene nada que revisar. Las que todavía no tienen precio no se actualizan.
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'id', p.id, 'servicio_id', p.servicio_id, 'tipo_servicio', p.tipo_servicio,
           'precio_final', p.precio_final, 'precio_lista_snapshot', p.precio_lista_snapshot,
           'precio_lista_id', p.precio_lista_id, 'requiere_revision', p.requiere_revision,
           'precio_turno_guardia_adicional', p.precio_turno_guardia_adicional,
           'precio_hora_adicional', p.precio_hora_adicional,
           'moneda', p.moneda, 'indice', x.indice)), '[]'::jsonb)
    INTO v_pendientes
    FROM public.prestaciones p
    LEFT JOIN public.condiciones_comerciales_servicio c ON c.servicio_id = p.servicio_id
    CROSS JOIN LATERAL (SELECT
        CASE WHEN c.indice_de_actualizacion = 'ninguno' THEN NULL
             ELSE coalesce(NULLIF(btrim(coalesce(c.indice_de_actualizacion, '')), ''), v_indice_p) END AS indice) x
   WHERE p.prestadora_id = v_prestadora
     AND p.estado = 'vigente'
     AND p.vigente_hasta IS NULL
     AND p.vigente_desde < p_desde
     AND p.servicio_id IS NOT NULL
     AND p.forma_de_precio IS NOT NULL
     AND x.indice IS NOT NULL;

  -- La lista de precios de la Prestadora.
  IF v_indice_p IS NOT NULL THEN
    v_factor := public.valor_del_indice(v_indice_p, p_periodo_nuevo)
              / NULLIF(public.valor_del_indice(v_indice_p, p_periodo_base), 0);
    FOR v_lista IN
      SELECT * FROM public.lista_precios l
       WHERE l.prestadora_id = v_prestadora AND l.vigente_hasta IS NULL AND l.activo
         AND l.vigente_desde < p_desde
       ORDER BY l.tipo_servicio, l.modalidad, l.id
    LOOP
      clase := 'lista';
      renglon_id := v_lista.id;
      renglon_nuevo_id := NULL;
      servicio_id := NULL;
      descripcion := v_lista.tipo_servicio || ' — ' || v_lista.modalidad;
      indice := v_indice_p;
      precio_actual := v_lista.precio;
      precio_nuevo := round(v_lista.precio * v_factor, 2);
      moneda := v_lista.moneda;
      IF p_aplicar AND precio_nuevo IS NOT NULL THEN
        renglon_nuevo_id := public.reemplazar_precio_de_lista(v_lista.id, precio_nuevo, p_desde);
      END IF;
      RETURN NEXT;
    END LOOP;
  END IF;

  -- Las prestaciones de los Servicios que se actualizan por índice.
  FOR v_elemento IN SELECT * FROM jsonb_array_elements(v_pendientes) LOOP
    v_factor := public.valor_del_indice(v_elemento ->> 'indice', p_periodo_nuevo)
              / NULLIF(public.valor_del_indice(v_elemento ->> 'indice', p_periodo_base), 0);
    clase := 'prestacion';
    renglon_id := (v_elemento ->> 'id')::bigint;
    renglon_nuevo_id := NULL;
    servicio_id := (v_elemento ->> 'servicio_id')::uuid;
    descripcion := v_elemento ->> 'tipo_servicio';
    indice := v_elemento ->> 'indice';
    precio_actual := (v_elemento ->> 'precio_final')::numeric;
    precio_nuevo := round(precio_actual * v_factor, 2);
    moneda := v_elemento ->> 'moneda';

    IF p_aplicar AND precio_nuevo IS NOT NULL AND precio_nuevo <> precio_actual THEN
      -- Si el renglón de la lista del que salió fue reemplazado recién, la nueva apunta al nuevo.
      SELECT l.id INTO v_reemplazo FROM public.lista_precios l
       WHERE l.reemplaza_a = NULLIF(v_elemento ->> 'precio_lista_id', '')::bigint
         AND l.vigente_desde = p_desde
       ORDER BY l.id DESC LIMIT 1;

      renglon_nuevo_id := interno.copiar_renglon('public.prestaciones', renglon_id, jsonb_build_object(
        'precio_final', precio_nuevo,
        'precio_lista_snapshot', CASE WHEN v_elemento ->> 'precio_lista_snapshot' IS NULL THEN NULL
                                      ELSE round((v_elemento ->> 'precio_lista_snapshot')::numeric * v_factor, 2) END,
        'precio_turno_guardia_adicional', CASE WHEN v_elemento ->> 'precio_turno_guardia_adicional' IS NULL THEN NULL
                                         ELSE round((v_elemento ->> 'precio_turno_guardia_adicional')::numeric * v_factor, 2) END,
        'precio_hora_adicional', CASE WHEN v_elemento ->> 'precio_hora_adicional' IS NULL THEN NULL
                                      ELSE round((v_elemento ->> 'precio_hora_adicional')::numeric * v_factor, 2) END,
        'precio_lista_id', coalesce(v_reemplazo, NULLIF(v_elemento ->> 'precio_lista_id', '')::bigint),
        'vigente_desde', p_desde,
        'vigente_hasta', NULL,
        'requiere_revision', false,
        'prestacion_anterior_id', renglon_id
      ));

      UPDATE public.prestaciones
         SET vigente_hasta = p_desde - 1,
             requiere_revision = (v_elemento ->> 'requiere_revision')::boolean
       WHERE id = renglon_id;
    END IF;
    RETURN NEXT;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."actualizar_precios_por_indice"("p_desde" "date", "p_periodo_base" "date", "p_periodo_nuevo" "date", "p_aplicar" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agregar_informacion_de_salud"("p_tabla" "text", "p_origen" "text", "p_fila" "jsonb", "p_columnas_devueltas" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $_$
DECLARE
  v_antes     text := coalesce(current_setting('careonys.lectura_de_salud', true), '');
  v_cols      text[];
  v_lista     text;
  v_sql       text;
  v_resultado jsonb;
  v_pacientes uuid[];
BEGIN
  PERFORM interno.pedido_de_salud_valido(p_tabla, p_origen);
  IF p_fila IS NULL OR jsonb_typeof(p_fila) <> 'object' THEN
    RAISE EXCEPTION 'pedido_invalido' USING ERRCODE = '22023';
  END IF;
  v_cols := ARRAY(SELECT interno.columna_del_pedido(p_tabla, k) FROM jsonb_object_keys(p_fila) k);
  IF cardinality(v_cols) = 0 THEN
    RAISE EXCEPTION 'pedido_invalido' USING ERRCODE = '22023';
  END IF;
  SELECT string_agg(format('%I', c), ', ') INTO v_lista FROM unnest(v_cols) c;

  -- Sólo las columnas que llegaron: las demás toman su valor de fábrica.
  v_sql := format(
    'WITH i AS (
       INSERT INTO public.%I (%s) SELECT %s FROM jsonb_populate_record(NULL::public.%I, $1)
       RETURNING *),
     f AS (SELECT %s AS fila, %s AS pacientes FROM i t)
     SELECT coalesce(jsonb_agg(f.fila), ''[]''::jsonb),
            (SELECT array_agg(DISTINCT p) FROM f, unnest(f.pacientes) p WHERE p IS NOT NULL)
       FROM f',
    p_tabla, v_lista, v_lista, p_tabla,
    CASE WHEN p_columnas_devueltas IS NULL THEN 'jsonb_build_object(''id'', t.id)'
         ELSE interno.fila_del_pedido(p_tabla, p_columnas_devueltas) END,
    interno.pacientes_de_la_fila(p_tabla));

  PERFORM set_config('careonys.lectura_de_salud', 'anotada', true);
  EXECUTE v_sql INTO v_resultado, v_pacientes USING p_fila;
  PERFORM set_config('careonys.lectura_de_salud', v_antes, true);

  PERFORM interno.anotar_lo_que_se_leyo(p_tabla, v_pacientes, p_origen);
  RETURN v_resultado;
END;
$_$;


ALTER FUNCTION "public"."agregar_informacion_de_salud"("p_tabla" "text", "p_origen" "text", "p_fila" "jsonb", "p_columnas_devueltas" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ajustar_precios_por_indice"() RETURNS TABLE("aplicados" integer, "propuestos" integer, "sin_efecto" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_prest      uuid := interno.prestadora_actual();
  v_regla      jsonb;
  v            record;
  v_ancla      date;
  v_rige       date;
  v_base       date;
  v_nuevo      date;
  v_factor     numeric;
  v_precio     numeric;
  v_propuesta  uuid;
  v_nueva      bigint;
BEGIN
  IF v_prest IS NULL OR coalesce(auth.jwt() ->> 'role', '') <> 'trabajo_sin_persona' THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;

  -- Dos corridas a la vez para la misma Prestadora harían el mismo ajuste dos veces.
  PERFORM pg_advisory_xact_lock(hashtextextended('ajuste_por_indice:' || v_prest::text, 0));

  aplicados := 0;
  propuestos := 0;
  sin_efecto := 0;

  SELECT c.regla INTO v_regla FROM public.configuracion_facturacion_clientes c
   WHERE c.prestadora_id = v_prest;

  -- Las pendientes que ya no corresponden: la prestación dejó de ser la vigente, cambió su
  -- precio, o el Servicio cambió de índice o lo sacó.
  WITH vencidas AS (
    UPDATE public.propuestas_de_ajuste_por_indice pr
       SET estado = 'sin_efecto'
      FROM public.prestaciones p
      LEFT JOIN public.condiciones_comerciales_servicio c ON c.servicio_id = p.servicio_id
     WHERE pr.prestadora_id = v_prest
       AND pr.estado = 'pendiente'
       AND p.id = pr.prestacion_id
       AND (p.estado <> 'vigente'
            OR p.vigente_hasta IS NOT NULL
            OR p.precio_final <> pr.precio_actual
            OR (SELECT x.indice FROM interno.condiciones_del_ajuste_por_indice(
                  v_regla, c.indice_de_actualizacion, c.meses_entre_actualizaciones, c.ajuste_por_indice) x)
               IS DISTINCT FROM pr.indice)
    RETURNING pr.id
  )
  SELECT count(*) INTO sin_efecto FROM vencidas;

  -- Las que todavía no tienen precio no se ajustan.
  FOR v IN
    SELECT p.id, p.servicio_id, p.vigente_desde, p.precio_final, p.precio_lista_snapshot, p.moneda,
           p.precio_turno_guardia_adicional, p.precio_hora_adicional,
           x.indice, x.meses, x.ajuste
      FROM public.prestaciones p
      LEFT JOIN public.condiciones_comerciales_servicio c ON c.servicio_id = p.servicio_id
     CROSS JOIN LATERAL interno.condiciones_del_ajuste_por_indice(
           v_regla, c.indice_de_actualizacion, c.meses_entre_actualizaciones, c.ajuste_por_indice) x
     WHERE p.prestadora_id = v_prest
       AND p.estado = 'vigente'
       AND p.vigente_hasta IS NULL
       AND p.servicio_id IS NOT NULL
       AND p.vigente_desde <= interno.hoy_de_la_prestadora(v_prest)
       AND p.forma_de_precio IS NOT NULL
       AND p.precio_final > 0
       AND x.indice IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.propuestas_de_ajuste_por_indice pr
                        WHERE pr.prestacion_id = p.id AND pr.estado = 'pendiente')
     ORDER BY p.id
  LOOP
    SELECT greatest(date_trunc('month', v.vigente_desde)::date, max(pr.rige_desde))
      INTO v_ancla
      FROM public.propuestas_de_ajuste_por_indice pr
     WHERE pr.prestacion_id = v.id AND pr.estado = 'rechazada';

    v_rige := (v_ancla + make_interval(months => v.meses))::date;
    CONTINUE WHEN interno.hoy_de_la_prestadora(v_prest) < v_rige;

    v_base := (date_trunc('month', v.vigente_desde) - interval '1 month')::date;
    v_nuevo := (v_rige - interval '1 month')::date;

    v_factor := interno.valor_del_indice_de_la_prestadora(v_prest, v.indice, v_nuevo)
              / NULLIF(interno.valor_del_indice_de_la_prestadora(v_prest, v.indice, v_base), 0);
    CONTINUE WHEN v_factor IS NULL;

    v_precio := round(v.precio_final * v_factor, 2);
    CONTINUE WHEN v_precio = v.precio_final;

    -- Ya hubo un ajuste para ese mes (rechazado, por ejemplo): no se vuelve a proponer.
    CONTINUE WHEN EXISTS (SELECT 1 FROM public.propuestas_de_ajuste_por_indice pr
                           WHERE pr.prestacion_id = v.id AND pr.rige_desde = v_rige
                             AND pr.estado <> 'sin_efecto');

    IF v.ajuste = 'automatico' THEN
      v_nueva := interno.copiar_renglon('public.prestaciones', v.id, jsonb_build_object(
        'precio_final', v_precio,
        'precio_lista_snapshot', CASE WHEN v.precio_lista_snapshot IS NULL THEN NULL
                                      ELSE round(v.precio_lista_snapshot * v_factor, 2) END,
        'precio_turno_guardia_adicional', CASE WHEN v.precio_turno_guardia_adicional IS NULL THEN NULL
                                         ELSE round(v.precio_turno_guardia_adicional * v_factor, 2) END,
        'precio_hora_adicional', CASE WHEN v.precio_hora_adicional IS NULL THEN NULL
                                      ELSE round(v.precio_hora_adicional * v_factor, 2) END,
        'vigente_desde', v_rige,
        'vigente_hasta', NULL,
        'requiere_revision', false,
        'prestacion_anterior_id', v.id
      ));

      INSERT INTO public.propuestas_de_ajuste_por_indice (
        prestadora_id, prestacion_id, servicio_id, indice, periodo_base, periodo_nuevo,
        precio_actual, precio_propuesto, moneda, rige_desde, estado, prestacion_nueva_id)
      VALUES (v_prest, v.id, v.servicio_id, v.indice, v_base, v_nuevo,
              v.precio_final, v_precio, v.moneda, v_rige, 'aplicada', v_nueva)
      RETURNING id INTO v_propuesta;

      INSERT INTO public.registro_actividad (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, detalle)
      VALUES (v_prest, NULL, 'ajuste_por_indice_aplicado', 'propuestas_de_ajuste_por_indice', v_propuesta,
              jsonb_build_object('prestacion_id', v.id, 'prestacion_nueva_id', v_nueva,
                                 'servicio_id', v.servicio_id, 'indice', v.indice,
                                 'precio_anterior', v.precio_final, 'precio_nuevo', v_precio,
                                 'moneda', v.moneda, 'rige_desde', v_rige));
      aplicados := aplicados + 1;
    ELSE
      INSERT INTO public.propuestas_de_ajuste_por_indice (
        prestadora_id, prestacion_id, servicio_id, indice, periodo_base, periodo_nuevo,
        precio_actual, precio_propuesto, moneda, rige_desde)
      VALUES (v_prest, v.id, v.servicio_id, v.indice, v_base, v_nuevo,
              v.precio_final, v_precio, v.moneda, v_rige);
      propuestos := propuestos + 1;
    END IF;
  END LOOP;

  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."ajustar_precios_por_indice"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."alcanza_al_asistente_la_sesion"("p_asistente" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM asistentes a
    WHERE a.id = p_asistente
      AND a.prestadora_id = interno.prestadora_actual()
      AND (interno.es_admin_prestadora() OR interno.coordinador_alcanza_asistente(a.id))
  );
$$;


ALTER FUNCTION "public"."alcanza_al_asistente_la_sesion"("p_asistente" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."alcanza_la_informacion_de_salud_la_sesion"("p_paciente" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT COALESCE(
    interno.usuario_de_la_sesion() IS NOT NULL
    AND EXISTS (SELECT 1 FROM pacientes p
                 WHERE p.id = p_paciente
                   AND p.prestadora_id = interno.prestadora_actual())
    AND interno.alcanza_la_informacion_de_salud(p_paciente),
    false);
$$;


ALTER FUNCTION "public"."alcanza_la_informacion_de_salud_la_sesion"("p_paciente" "uuid") OWNER TO "postgres";



CREATE OR REPLACE FUNCTION "public"."anotar_aviso_de_acceso_de_match"("p_acceso_id" "uuid", "p_estado" "text", "p_periodo" "date", "p_monto" numeric, "p_moneda" "text", "p_numero_del_aviso" "text", "p_fecha_cobro" "date" DEFAULT NULL::"date", "p_suspende_el" "date" DEFAULT NULL::"date", "p_vigente_hasta" "date" DEFAULT NULL::"date", "p_medio" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
  v_acceso public.accesos_intermediacion%ROWTYPE;
  v_renueva_sola boolean;
  v_contactos integer;
  v_hay_uno_posterior boolean;
  v_estado_nuevo text;
  v_campos text[];
BEGIN
  -- Falla cerrado: sin Prestadora del trabajo no se anota nada.
  IF v_prestadora IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'acceso_inexistente');
  END IF;

  IF p_estado IS NULL OR p_estado NOT IN ('pagado', 'gracia', 'suspendido', 'baja') THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'aviso_incompleto', 'dato', 'estado');
  END IF;
  IF p_periodo IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'aviso_incompleto', 'dato', 'periodo');
  END IF;
  IF p_monto IS NULL OR p_monto < 0 THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'aviso_incompleto', 'dato', 'monto');
  END IF;
  IF p_moneda IS NULL OR p_moneda !~ '^[A-Z]{3}$' THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'aviso_incompleto', 'dato', 'moneda');
  END IF;
  IF p_numero_del_aviso IS NULL OR btrim(p_numero_del_aviso) = '' THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'aviso_incompleto', 'dato', 'numero_del_aviso');
  END IF;
  IF p_estado = 'gracia' AND p_suspende_el IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'aviso_incompleto', 'dato', 'suspende_el');
  END IF;
  IF p_estado = 'baja' AND p_vigente_hasta IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'aviso_incompleto', 'dato', 'vigente_hasta');
  END IF;

  -- La fila del acceso tomada: dos avisos del mismo acceso que llegan juntos se anotan de a uno.
  -- El filtro por la Prestadora está escrito además de la política de fila: un acceso de otra
  -- Prestadora contesta igual que uno que no existe.
  SELECT * INTO v_acceso
    FROM public.accesos_intermediacion
   WHERE id = p_acceso_id AND prestadora_id = v_prestadora
     FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'acceso_inexistente');
  END IF;

  SELECT f.renueva_sola, f.contactos_incluidos
    INTO v_renueva_sola, v_contactos
    FROM public.formas_de_cobro_intermediacion f
   WHERE f.id = v_acceso.forma_de_cobro_id AND f.prestadora_id = v_prestadora;

  -- Sólo se da de baja lo que se renueva solo. Lo que no se renueva termina por sí mismo.
  IF p_estado = 'baja' AND v_renueva_sola IS NOT TRUE THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'no_se_renueva');
  END IF;

  -- Un aviso de un período anterior al último cobro anotado llegó tarde: se anota el cobro, pero
  -- no cambia el estado, que ya lo fijó un aviso más nuevo.
  SELECT EXISTS (
    SELECT 1 FROM public.cobros_intermediacion
     WHERE acceso_id = p_acceso_id AND periodo > p_periodo
  ) INTO v_hay_uno_posterior;

  IF p_estado = 'baja' THEN
    -- La baja no es un cobro, así que no deja fila en los cobros. Repetida es la que encuentra el
    -- acceso ya dado de baja con la misma fecha.
    IF v_acceso.estado = 'cancelada' AND v_acceso.vigente_hasta = p_vigente_hasta THEN
      RETURN jsonb_build_object('ok', true, 'repetido', true,
        'estado', v_acceso.estado, 'saldo_contactos', v_acceso.saldo_contactos);
    END IF;
  ELSE
    -- El cobro se anota con el número del aviso como referencia. El índice único de la
    -- referencia es lo que hace que el mismo aviso mandado dos veces se anote una sola.
    BEGIN
      INSERT INTO public.cobros_intermediacion
        (acceso_id, prestadora_id, medio, monto, moneda, periodo, estado_cobro,
         referencia_externa, fecha_cobro)
      VALUES
        (p_acceso_id, v_prestadora,
         COALESCE(NULLIF(btrim(p_medio), ''), 'otro'),
         round(p_monto, 2), p_moneda, p_periodo,
         CASE WHEN p_estado = 'pagado' THEN 'exitoso' ELSE 'fallido' END,
         btrim(p_numero_del_aviso),
         COALESCE(p_fecha_cobro, interno.hoy_de_la_prestadora(v_prestadora)));
    EXCEPTION WHEN unique_violation THEN
      RETURN jsonb_build_object('ok', true, 'repetido', true,
        'estado', v_acceso.estado, 'saldo_contactos', v_acceso.saldo_contactos);
    END;

    -- El paquete pagado suma sus contactos en la misma operación que anota el cobro. Si algo
    -- falla después, no queda un cobro anotado sin sus contactos ni contactos sin su cobro.
    IF p_estado = 'pagado' AND COALESCE(v_contactos, 0) > 0 THEN
      PERFORM public.sumar_contactos_al_saldo(p_acceso_id, v_contactos);
    END IF;
  END IF;

  v_estado_nuevo := v_acceso.estado;

  IF NOT v_hay_uno_posterior THEN
    IF p_estado = 'pagado' THEN
      -- El pago levanta la gracia, la suspensión y la baja, sin que nadie intervenga.
      UPDATE public.accesos_intermediacion
         SET estado = 'vigente', suspension_desde = NULL, cancelada_en = NULL,
             vigente_hasta = NULL, updated_at = now()
       WHERE id = p_acceso_id;
      v_estado_nuevo := 'vigente';
      v_campos := ARRAY['estado', 'suspension_desde', 'cancelada_en', 'vigente_hasta'];
    ELSIF p_estado = 'gracia' THEN
      UPDATE public.accesos_intermediacion
         SET estado = 'en_gracia', suspension_desde = p_suspende_el, updated_at = now()
       WHERE id = p_acceso_id;
      v_estado_nuevo := 'en_gracia';
      v_campos := ARRAY['estado', 'suspension_desde'];
    ELSIF p_estado = 'suspendido' THEN
      UPDATE public.accesos_intermediacion
         SET estado = 'suspendida',
             suspension_desde = COALESCE(p_suspende_el, v_acceso.suspension_desde, interno.hoy_de_la_prestadora(v_prestadora)),
             updated_at = now()
       WHERE id = p_acceso_id;
      v_estado_nuevo := 'suspendida';
      v_campos := ARRAY['estado', 'suspension_desde'];
    ELSE
      UPDATE public.accesos_intermediacion
         SET estado = 'cancelada', cancelada_en = now(), vigente_hasta = p_vigente_hasta,
             updated_at = now()
       WHERE id = p_acceso_id;
      v_estado_nuevo := 'cancelada';
      v_campos := ARRAY['estado', 'cancelada_en', 'vigente_hasta'];
    END IF;
  END IF;

  IF p_estado = 'pagado' AND COALESCE(v_contactos, 0) > 0 THEN
    v_campos := array_append(COALESCE(v_campos, ARRAY[]::text[]), 'saldo_contactos'::text);
  END IF;

  -- La constancia: quién (el sistema), cuándo, sobre qué acceso y qué cambió. Sin importes.
  INSERT INTO public.registro_actividad
    (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, campos_cambiados, detalle)
  VALUES
    (v_prestadora, NULL, 'aviso_de_acceso_de_match', 'accesos_intermediacion', p_acceso_id,
     v_campos,
     jsonb_build_object('estado_anterior', v_acceso.estado, 'estado_nuevo', v_estado_nuevo));

  RETURN jsonb_build_object('ok', true, 'estado', v_estado_nuevo,
    'saldo_contactos', (SELECT saldo_contactos FROM public.accesos_intermediacion WHERE id = p_acceso_id));
END;
$_$;



ALTER FUNCTION "public"."anotar_aviso_de_acceso_de_match"("p_acceso_id" "uuid", "p_estado" "text", "p_periodo" "date", "p_monto" numeric, "p_moneda" "text", "p_numero_del_aviso" "text", "p_fecha_cobro" "date", "p_suspende_el" "date", "p_vigente_hasta" "date", "p_medio" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."anotar_aviso_de_borrado_de_consultas_a_hce"("p_anio" integer, "p_aviso" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prest uuid := interno.prestadora_actual();
BEGIN
  IF v_prest IS NULL OR COALESCE(auth.jwt() ->> 'role', '') <> 'trabajo_sin_persona' THEN
    RAISE EXCEPTION 'sin_permiso_para_avisar_el_borrado_de_las_consultas_a_hce' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('aviso_de_borrado:' || v_prest::text, 0));

  IF NOT EXISTS (
    SELECT 1 FROM interno.aviso_de_borrado_de_consultas_a_hce_pendiente(v_prest) p
     WHERE p.anio = p_anio AND p.aviso = p_aviso) THEN
    RETURN false;
  END IF;

  INSERT INTO registro_actividad (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, detalle)
  VALUES (v_prest, NULL, p_aviso || '_de_borrado', 'consultas_a_hce', NULL, jsonb_build_object('anio', p_anio));
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."anotar_aviso_de_borrado_de_consultas_a_hce"("p_anio" integer, "p_aviso" "text") OWNER TO "postgres";



CREATE OR REPLACE FUNCTION "public"."anotar_aviso_de_derecho_por_vencer"("p_solicitud" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prest uuid := interno.prestadora_actual();
BEGIN
  IF v_prest IS NULL OR COALESCE(auth.jwt() ->> 'role', '') <> 'trabajo_sin_persona' THEN
    RAISE EXCEPTION 'sin_permiso_para_avisar_los_derechos_por_vencer' USING ERRCODE = '42501';
  END IF;

  UPDATE solicitudes_de_derechos s
     SET aviso_enviado_en = now()
   WHERE s.id = p_solicitud
     AND s.prestadora_id = v_prest
     AND s.id IN (SELECT p.solicitud_id FROM interno.derechos_por_vencer(v_prest) p);
  RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."anotar_aviso_de_derecho_por_vencer"("p_solicitud" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."anotar_valor_de_indice_publico"("p_indice" "text", "p_periodo" "date", "p_valor" numeric) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_indice uuid;
  v_filas  integer;
BEGIN
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'trabajo_sin_persona'
     OR auth.jwt() ->> 'prestadora_id' IS NOT NULL THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF p_periodo IS NULL OR p_valor IS NULL OR p_valor <= 0 THEN
    RAISE EXCEPTION 'dato_invalido' USING ERRCODE = 'P0001';
  END IF;

  SELECT id INTO v_indice FROM public.indices_de_actualizacion WHERE codigo = p_indice;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no_encontrado' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.valores_de_indice (indice_id, periodo, valor, origen, prestadora_id, cargado_por)
  VALUES (v_indice, date_trunc('month', p_periodo)::date, p_valor, 'automatico', NULL, NULL)
  ON CONFLICT (indice_id, periodo) WHERE prestadora_id IS NULL
  DO UPDATE SET valor = EXCLUDED.valor, updated_at = now()
   WHERE public.valores_de_indice.valor IS DISTINCT FROM EXCLUDED.valor;
  GET DIAGNOSTICS v_filas = ROW_COUNT;
  RETURN v_filas > 0;
END;
$$;


ALTER FUNCTION "public"."anotar_valor_de_indice_publico"("p_indice" "text", "p_periodo" "date", "p_valor" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."asignar_serie"("p_serie_id" "uuid", "p_asistente_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
  v_serie      public.series_turnos_guardia;
  v_pendiente  public.asignaciones_de_turno_guardia;
  v_anterior   uuid;
  v_nueva      uuid;
  v_bloquean   text[];
BEGIN
  IF v_prestadora IS NULL THEN
    RAISE EXCEPTION 'serie_no_encontrada';
  END IF;

  SELECT * INTO v_pendiente
    FROM asignaciones_de_turno_guardia
   WHERE serie_id = p_serie_id
     AND prestadora_id = v_prestadora
     AND estado = 'sin_responder'
   FOR UPDATE;

  SELECT * INTO v_serie
    FROM series_turnos_guardia
   WHERE id = p_serie_id
     AND prestadora_id = v_prestadora
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'serie_no_encontrada';
  END IF;

  IF v_serie.estado <> 'activa' THEN
    RAISE EXCEPTION 'serie_no_se_asigna' USING ERRCODE = '23514';
  END IF;

  IF p_asistente_id IS NOT NULL AND v_pendiente.asistente_id = p_asistente_id THEN
    RETURN jsonb_build_object('sin_cambios', true);
  END IF;
  IF p_asistente_id IS NOT NULL AND v_pendiente.id IS NULL AND v_serie.asistente_id = p_asistente_id THEN
    RETURN jsonb_build_object('sin_cambios', true);
  END IF;
  IF p_asistente_id IS NULL AND v_pendiente.id IS NULL AND v_serie.asistente_id IS NULL THEN
    RETURN jsonb_build_object('sin_cambios', true);
  END IF;

  v_anterior := COALESCE(v_serie.asistente_id, v_pendiente.asistente_anterior_id);

  IF p_asistente_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM asistentes a WHERE a.id = p_asistente_id AND a.prestadora_id = v_prestadora) THEN
      RAISE EXCEPTION 'asistente_no_encontrado';
    END IF;

    IF EXISTS (SELECT 1 FROM usuarios u WHERE u.id = interno.usuario_de_la_sesion() AND u.rol = 'coordinador')
       AND NOT interno.coordinador_alcanza_asistente(p_asistente_id) THEN
      RAISE EXCEPTION 'asistente_no_encontrado';
    END IF;

    v_bloquean := interno.documentos_que_bloquean(
      p_asistente_id, GREATEST(v_serie.vigente_desde, interno.hoy_de_la_prestadora(v_prestadora)), v_serie.paciente_id, v_serie.servicio_id);
    IF cardinality(v_bloquean) > 0 THEN
      RAISE EXCEPTION 'documentos_bloquean:%:', array_to_string(v_bloquean, ', ') USING ERRCODE = '23514';
    END IF;

    IF v_serie.canal_modalidad IS NOT NULL
       AND NOT interno.asistente_trabaja_en_modalidad(p_asistente_id, v_serie.canal_modalidad) THEN
      RAISE EXCEPTION 'modalidad_bloquea:%:', v_serie.canal_modalidad USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_pendiente.id IS NOT NULL THEN
    UPDATE asignaciones_de_turno_guardia SET estado = 'retirada' WHERE id = v_pendiente.id;
  END IF;

  IF v_serie.asistente_id IS NOT NULL THEN
    UPDATE series_turnos_guardia SET asistente_id = NULL WHERE id = v_serie.id;
  END IF;

  IF p_asistente_id IS NOT NULL THEN
    INSERT INTO asignaciones_de_turno_guardia (prestadora_id, serie_id, asistente_id, asistente_anterior_id)
    VALUES (v_prestadora, v_serie.id, p_asistente_id, v_anterior)
    RETURNING id INTO v_nueva;
  END IF;

  RETURN jsonb_build_object(
    'sin_cambios', false,
    'asignacion_id', v_nueva,
    'titular_retirado', v_serie.asistente_id,
    'pendiente_retirado', v_pendiente.asistente_id,
    'asistente_anterior_id', v_anterior
  );
END;
$$;


ALTER FUNCTION "public"."asignar_serie"("p_serie_id" "uuid", "p_asistente_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."asignar_turno_guardia"("p_turno_guardia_id" "uuid", "p_asistente_id" "uuid", "p_motivo_excepcion" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
  v_turno_guardia    public.turnos_guardia;
  v_pendiente  public.asignaciones_de_turno_guardia;
  v_anterior   uuid;
  v_nueva      uuid;
BEGIN
  IF v_prestadora IS NULL THEN
    RAISE EXCEPTION 'turno_guardia_no_encontrado';
  END IF;

  -- Primero la asignación pendiente y después el turno: es el mismo orden en que los toma
  -- `aceptar_asignacion`, así las dos nunca se esperan una a la otra.
  SELECT * INTO v_pendiente
    FROM asignaciones_de_turno_guardia
   WHERE turno_guardia_id = p_turno_guardia_id
     AND prestadora_id = v_prestadora
     AND estado = 'sin_responder'
   FOR UPDATE;

  SELECT * INTO v_turno_guardia
    FROM turnos_guardia
   WHERE id = p_turno_guardia_id
     AND prestadora_id = v_prestadora
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'turno_guardia_no_encontrado';
  END IF;

  IF v_turno_guardia.estado <> 'programada' THEN
    RAISE EXCEPTION 'turno_guardia_no_se_asigna' USING ERRCODE = '23514';
  END IF;

  -- Lo que ya está como se pide no se toca: ni se retira ni se vuelve a avisar.
  IF p_asistente_id IS NOT NULL AND v_pendiente.asistente_id = p_asistente_id THEN
    RETURN jsonb_build_object('sin_cambios', true);
  END IF;
  IF p_asistente_id IS NULL AND v_pendiente.id IS NULL AND v_turno_guardia.asistente_id IS NULL THEN
    RETURN jsonb_build_object('sin_cambios', true);
  END IF;

  v_anterior := COALESCE(v_turno_guardia.asistente_id, v_pendiente.asistente_anterior_id);

  -- Las mismas paredes que pone la base cuando el turno pasa a ser de alguien, puestas ahora,
  -- para que el Coordinador se entere al asignar y no el Asistente al aceptar.
  IF p_asistente_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM asistentes a WHERE a.id = p_asistente_id AND a.prestadora_id = v_prestadora) THEN
      RAISE EXCEPTION 'asistente_no_encontrado';
    END IF;

    -- El Coordinador asigna sólo a los Asistentes de su zona. Lo frenaría igual la política de
    -- la asignación, pero con un error que no dice qué pasó.
    IF EXISTS (SELECT 1 FROM usuarios u WHERE u.id = interno.usuario_de_la_sesion() AND u.rol = 'coordinador')
       AND NOT interno.coordinador_alcanza_asistente(p_asistente_id) THEN
      RAISE EXCEPTION 'asistente_no_encontrado';
    END IF;

    PERFORM interno.excepcion_por_documentos(
      v_prestadora,
      v_turno_guardia.id,
      p_asistente_id,
      interno.documentos_que_bloquean(
        p_asistente_id,
        interno.dia_en_que_termina_turno_guardia(v_turno_guardia.fecha, v_turno_guardia.hora_inicio, v_turno_guardia.hora_fin, v_turno_guardia.dias_hasta_el_fin),
        v_turno_guardia.paciente_id,
        v_turno_guardia.servicio_id
      ),
      p_motivo_excepcion
    );

    IF v_turno_guardia.canal_modalidad IS NOT NULL
       AND NOT interno.asistente_trabaja_en_modalidad(p_asistente_id, v_turno_guardia.canal_modalidad) THEN
      RAISE EXCEPTION 'modalidad_bloquea:%:', v_turno_guardia.canal_modalidad USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_pendiente.id IS NOT NULL THEN
    UPDATE asignaciones_de_turno_guardia SET estado = 'retirada' WHERE id = v_pendiente.id;
  END IF;

  IF v_turno_guardia.asistente_id IS NOT NULL THEN
    UPDATE turnos_guardia SET asistente_id = NULL WHERE id = v_turno_guardia.id;
  END IF;

  IF p_asistente_id IS NOT NULL THEN
    INSERT INTO asignaciones_de_turno_guardia (prestadora_id, turno_guardia_id, asistente_id, asistente_anterior_id)
    VALUES (v_prestadora, v_turno_guardia.id, p_asistente_id, v_anterior)
    RETURNING id INTO v_nueva;
  END IF;

  -- Alguien perdió el turno: la alarma se abre ya. Si había una abierta, sigue la misma.
  IF v_turno_guardia.asistente_id IS NOT NULL OR v_pendiente.id IS NOT NULL THEN
    INSERT INTO incidentes_turno_guardia_sin_cubrir (prestadora_id, turno_guardia_id)
    VALUES (v_prestadora, v_turno_guardia.id)
    ON CONFLICT (turno_guardia_id) WHERE resuelto_at IS NULL DO NOTHING;
  END IF;

  RETURN jsonb_build_object(
    'sin_cambios', false,
    'asignacion_id', v_nueva,
    'titular_retirado', v_turno_guardia.asistente_id,
    'pendiente_retirado', v_pendiente.asistente_id,
    'asistente_anterior_id', v_anterior
  );
END;
$$;


ALTER FUNCTION "public"."asignar_turno_guardia"("p_turno_guardia_id" "uuid", "p_asistente_id" "uuid", "p_motivo_excepcion" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."asistente_asignado_a_cliente"("p_asistente_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM turnos_guardia g
    JOIN pacientes p ON p.id = g.paciente_id
    WHERE g.asistente_id = p_asistente_id
      AND p.cliente_id = cliente_id_de_usuario(auth.uid())
  );
$$;


ALTER FUNCTION "public"."asistente_asignado_a_cliente"("p_asistente_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."asistente_asignado_a_cliente"("p_asistente_id" "uuid") IS 'Única fuente de verdad para saber si un Asistente atiende a un Paciente del Cliente de la sesión. Va por función y no dentro de la política para no armar una referencia circular entre asistentes y turnos de guardia.';



CREATE OR REPLACE FUNCTION "public"."asistentes_asignados_al_paciente"("p_paciente" "uuid") RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT DISTINCT g.asistente_id
    FROM turno_guardia_pacientes gp
    JOIN turnos_guardia g ON g.id = gp.turno_guardia_id AND g.prestadora_id = gp.prestadora_id
   WHERE gp.paciente_id = p_paciente
     AND gp.prestadora_id = interno.prestadora_actual()
     AND interno.es_personal_de_la_prestadora()
     AND g.asistente_id IS NOT NULL
     AND g.fecha >= interno.hoy_de_la_prestadora(gp.prestadora_id);
$$;


ALTER FUNCTION "public"."asistentes_asignados_al_paciente"("p_paciente" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ausencias_que_tapan"("p_desde" "date", "p_hasta" "date", "p_hoy" "date" DEFAULT "interno"."hoy_de_la_sesion"()) RETURNS TABLE("asistente_id" "uuid", "fecha_inicio" "date", "fecha_fin" "date")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  WITH efectivas AS (
    SELECT a.asistente_id, a.fecha_inicio,
           CASE WHEN a.fecha_vuelta_real IS NULL AND a.fecha_fin < p_hoy THEN NULL
                ELSE a.fecha_fin END AS fecha_fin
    FROM public.ausencias a
    JOIN public.asistentes s ON s.id = a.asistente_id
    WHERE
      -- El aislamiento, primero y adentro: la licencia y la persona, las dos de esta Prestadora.
      a.prestadora_id = prestadora_actual()
      AND s.prestadora_id = prestadora_actual()
      -- Quién tiene derecho a preguntar: los tres roles de Panel y nadie más.
      AND (
        es_superadmin()
        OR es_admin_prestadora()
        OR EXISTS (SELECT 1 FROM public.usuarios u WHERE u.id = auth.uid() AND u.rol = 'coordinador')
      )
  )
  SELECT e.asistente_id, e.fecha_inicio, e.fecha_fin
  FROM efectivas e
  WHERE e.fecha_inicio <= p_hasta
    AND (e.fecha_fin IS NULL OR e.fecha_fin >= p_desde);
$$;


ALTER FUNCTION "public"."ausencias_que_tapan"("p_desde" "date", "p_hasta" "date", "p_hoy" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aviso_de_borrado_de_consultas_a_hce_pendiente"() RETURNS TABLE("anio" integer, "se_borra_el" "date", "aviso" "text", "dias" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prest uuid := interno.prestadora_actual();
BEGIN
  IF v_prest IS NULL OR COALESCE(auth.jwt() ->> 'role', '') <> 'trabajo_sin_persona' THEN
    RAISE EXCEPTION 'sin_permiso_para_avisar_el_borrado_de_las_consultas_a_hce' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM interno.aviso_de_borrado_de_consultas_a_hce_pendiente(v_prest);
END;
$$;


ALTER FUNCTION "public"."aviso_de_borrado_de_consultas_a_hce_pendiente"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bloquear_edicion_laboral_coordinador"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  rol_actual TEXT;
BEGIN
  SELECT rol INTO rol_actual FROM usuarios WHERE id = interno.usuario_de_la_sesion();

  IF rol_actual = 'coordinador' THEN
    IF NEW.horas_semanales IS DISTINCT FROM OLD.horas_semanales
      OR NEW.fecha_baja IS DISTINCT FROM OLD.fecha_baja
    THEN
      RAISE EXCEPTION 'Coordinador no puede modificar datos laborales internos del Asistente';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."bloquear_edicion_laboral_coordinador"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."borrar_consultas_a_hce_vencidas"() RETURNS TABLE("anio" integer, "renglones" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prest    uuid := interno.prestadora_actual();
  v          record;
  v_hasta    record;
  v_cuantos  bigint;
  v_corte    uuid;
BEGIN
  IF v_prest IS NULL OR COALESCE(auth.jwt() ->> 'role', '') <> 'trabajo_sin_persona' THEN
    RAISE EXCEPTION 'sin_permiso_para_borrar_las_consultas_a_hce' USING ERRCODE = '42501';
  END IF;

  -- El mismo candado que la anotación: mientras se borra, nadie se cuelga de un renglón que se va.
  PERFORM pg_advisory_xact_lock(hashtextextended('consultas_a_hce:' || v_prest::text, 0));

  LOOP
    SELECT * INTO v FROM interno.consultas_a_hce_por_vencer(v_prest);
    EXIT WHEN v.anio IS NULL OR v.se_borra_el > interno.hoy_de_la_prestadora(v_prest);

    SELECT a.numero, a.resumen INTO v_hasta
      FROM consultas_a_hce a
     WHERE a.prestadora_id = v_prest AND a.momento < v.hasta
     ORDER BY a.numero DESC
     LIMIT 1;

    SELECT count(*) INTO v_cuantos
      FROM consultas_a_hce a
     WHERE a.prestadora_id = v_prest AND a.numero <= v_hasta.numero;

    INSERT INTO cortes_de_consultas_a_hce (prestadora_id, anio, hasta_numero, ultimo_resumen, renglones)
    VALUES (v_prest, v.anio, v_hasta.numero, v_hasta.resumen, v_cuantos)
    RETURNING id INTO v_corte;

    DELETE FROM consultas_a_hce a
     WHERE a.prestadora_id = v_prest AND a.numero <= v_hasta.numero;

    INSERT INTO registro_actividad (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, detalle)
    VALUES (v_prest, NULL, 'borrado_por_vencimiento', 'consultas_a_hce', v_corte,
            jsonb_build_object('anio', v.anio, 'renglones', v_cuantos, 'hasta_numero', v_hasta.numero));

    anio := v.anio;
    renglones := v_cuantos;
    RETURN NEXT;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."borrar_consultas_a_hce_vencidas"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cargar_promocion_de_lista"("p_precio_id" bigint, "p_precio" numeric, "p_desde" "date", "p_hasta" "date") RETURNS bigint
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_base  public.lista_precios;
  v_nuevo bigint;
BEGIN
  IF p_precio IS NULL OR p_precio <= 0 OR p_desde IS NULL OR p_hasta IS NULL THEN
    RAISE EXCEPTION 'dato_invalido' USING ERRCODE = 'P0001';
  END IF;
  IF p_hasta < p_desde THEN
    RAISE EXCEPTION 'fechas_al_reves' USING ERRCODE = 'P0001';
  END IF;

  -- El renglón de siempre se bloquea: dos promociones cargadas al mismo tiempo sobre el mismo
  -- precio no pueden pasar las dos el control de superposición.
  SELECT * INTO v_base FROM public.lista_precios WHERE id = p_precio_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no_encontrado' USING ERRCODE = 'P0002';
  END IF;
  -- Sólo sobre un precio de siempre, abierto y activo.
  IF v_base.promocion_de IS NOT NULL OR v_base.vigente_hasta IS NOT NULL OR NOT v_base.activo THEN
    RAISE EXCEPTION 'no_es_precio_vigente' USING ERRCODE = 'P0001';
  END IF;
  IF p_desde < v_base.vigente_desde THEN
    RAISE EXCEPTION 'fecha_anterior' USING ERRCODE = 'P0001';
  END IF;

  -- Dos promociones del mismo tipo, modalidad y moneda no se superponen: el precio de un día
  -- tiene que ser uno solo.
  IF EXISTS (
    SELECT 1 FROM public.lista_precios l
     WHERE l.prestadora_id = v_base.prestadora_id
       AND l.tipo_servicio = v_base.tipo_servicio
       AND l.modalidad = v_base.modalidad
       AND l.moneda = v_base.moneda
       AND l.promocion_de IS NOT NULL
       AND l.activo
       AND l.vigente_desde <= p_hasta
       AND l.vigente_hasta >= p_desde
  ) THEN
    RAISE EXCEPTION 'promocion_superpuesta' USING ERRCODE = 'P0001';
  END IF;

  v_nuevo := interno.copiar_renglon('public.lista_precios', v_base.id, jsonb_build_object(
    'precio', p_precio,
    'vigente_desde', p_desde,
    'vigente_hasta', p_hasta,
    'activo', true,
    'reemplaza_a', NULL,
    'promocion_de', v_base.id
  ));

  RETURN v_nuevo;
END;
$$;


ALTER FUNCTION "public"."cargar_promocion_de_lista"("p_precio_id" bigint, "p_precio" numeric, "p_desde" "date", "p_hasta" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cerrar_autorizacion_signos_vitales_con_documento_firmado"("p_paciente" "uuid", "p_archivo" "text", "p_idioma" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_quien uuid := auth.uid();
  v_prestadora uuid := interno.prestadora_actual();
  v_doc record;
  v_id uuid;
BEGIN
  IF v_quien IS NULL OR NOT interno.es_personal_de_la_prestadora() THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pacientes WHERE id = p_paciente AND prestadora_id = v_prestadora)
     OR NOT interno.alcanza_la_informacion_de_salud(p_paciente) THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF p_archivo NOT LIKE v_prestadora::text || '/' || p_paciente::text || '/autorizacion-%' THEN
    RAISE EXCEPTION 'archivo_invalido' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM autorizaciones_monitoreo_paciente
              WHERE paciente_id = p_paciente AND estado IN ('aceptada', 'pendiente')) THEN
    RAISE EXCEPTION 'ya_hay_una_autorizacion' USING ERRCODE = '23505';
  END IF;

  SELECT * INTO v_doc FROM interno.documento_autorizacion_signos_vitales(p_paciente, p_idioma);
  IF v_doc.texto IS NULL THEN
    RAISE EXCEPTION 'sin_texto' USING ERRCODE = '22023';
  END IF;

  INSERT INTO autorizaciones_monitoreo_paciente
    (prestadora_id, paciente_id, metodo, estado, documento_texto, documento_verificador, documento_idioma,
     firmante_persona_id, archivo_url, cargado_por, revisado_por, revisado_en)
  VALUES
    (v_prestadora, p_paciente, 'documento_firmado_panel', 'aceptada', v_doc.texto, v_doc.verificador, p_idioma,
     interno.firmante_autorizacion_signos_vitales(p_paciente), p_archivo, v_quien, v_quien, now())
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."cerrar_autorizacion_signos_vitales_con_documento_firmado"("p_paciente" "uuid", "p_archivo" "text", "p_idioma" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cerrar_firma_medicacion_con_documento_firmado"("p_firma" "uuid", "p_archivo" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT interno.es_personal_de_la_prestadora() THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;

  UPDATE consentimientos_medicacion c
     SET estado = 'cerrado',
         cerrado_como = 'documento_firmado',
         cerrado_en = now(),
         cerrado_desde = 'panel',
         archivo_firmado_url = p_archivo
    FROM indicaciones_medicacion i
   WHERE c.id = p_firma
     AND c.prestadora_id = interno.prestadora_actual()
     AND c.estado = 'pendiente_firma'
     AND i.id = c.indicacion_id
     AND i.prestadora_id = c.prestadora_id
     AND interno.alcanza_la_informacion_de_salud(i.paciente_id)
     AND p_archivo LIKE c.prestadora_id::text || '/firmas-medicacion/' || i.paciente_id::text || '/firma-' || c.id::text || '.%';
  RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."cerrar_firma_medicacion_con_documento_firmado"("p_firma" "uuid", "p_archivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cerrar_hospitalizacion"("p_hospitalizacion" "uuid", "p_fecha" "date") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_antes    text := coalesce(current_setting('careonys.lectura_de_salud', true), '');
  v_paciente uuid;
  v_inicio   date;
  v_fin      date;
  v_forma    text;
  v_hoy      date;
BEGIN
  PERFORM set_config('careonys.lectura_de_salud', 'anotada', true);
  UPDATE hospitalizaciones_paciente h
     SET fecha_fin = greatest(p_fecha, h.fecha_inicio)
   WHERE h.id = p_hospitalizacion
     AND h.prestadora_id = interno.prestadora_actual()
     AND h.fecha_fin IS NULL
  RETURNING h.paciente_id, h.fecha_inicio, h.fecha_fin, h.forma INTO v_paciente, v_inicio, v_fin, v_forma;
  PERFORM set_config('careonys.lectura_de_salud', v_antes, true);
  IF v_paciente IS NULL THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  PERFORM interno.anotar_lo_que_se_leyo('hospitalizaciones_paciente', ARRAY[v_paciente], 'cerrar_hospitalizacion');

  IF v_forma = 'muda' THEN
    UPDATE domicilios_temporales_paciente d
       SET fecha_fin = greatest(p_fecha, d.fecha_inicio)
     WHERE d.hospitalizacion_id = p_hospitalizacion
       AND (d.fecha_fin IS NULL OR d.fecha_fin > greatest(p_fecha, d.fecha_inicio));
  ELSIF v_forma = 'suspende' THEN
    -- Vuelve sólo lo que esta internación suspendió, desde el día siguiente al alta y nunca antes
    -- de hoy: lo pasado queda como quedó.
    v_hoy := interno.hoy_de_la_sesion();
    PERFORM interno.levantar_lo_de_la_internacion(p_hospitalizacion, greatest(v_hoy, v_fin + 1));
  END IF;

  PERFORM interno.anotar_turnos_sin_cubrir();
END;
$$;


ALTER FUNCTION "public"."cerrar_hospitalizacion"("p_hospitalizacion" "uuid", "p_fecha" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."completar_genero_de_la_persona"("p_persona" "uuid", "p_genero" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
BEGIN
  IF interno.prestadora_actual() IS NULL
     OR NOT (auth.jwt() ->> 'role' = 'trabajo_sin_persona' OR interno.es_personal_de_la_prestadora()) THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  UPDATE public.personas
     SET genero = p_genero
   WHERE id = p_persona
     AND prestadora_id = interno.prestadora_actual()
     AND genero IS NULL;
END;
$$;


ALTER FUNCTION "public"."completar_genero_de_la_persona"("p_persona" "uuid", "p_genero" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consentimiento_seguimiento_vigente"("p_asistente_id" "uuid", "p_clave" "text" DEFAULT 'seguimiento_ubicacion'::"text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM consentimientos_asistente c
    JOIN textos_consentimiento tx ON tx.id = c.texto_consentimiento_id
    WHERE c.asistente_id = p_asistente_id
      AND c.clave = p_clave
      AND c.retirado_at IS NULL
      AND c.decision = 'otorgado'
      AND tx.es_borrador = FALSE
      AND tx.vigente_hasta IS NULL
      AND interno.le_corresponde(c.prestadora_id)
  );
$$;


ALTER FUNCTION "public"."consentimiento_seguimiento_vigente"("p_asistente_id" "uuid", "p_clave" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."consentimiento_seguimiento_vigente"("p_asistente_id" "uuid", "p_clave" "text") IS 'Pendiente #102. Única fuente de verdad para saber si se puede registrar la ubicación de un Asistente. Devuelve FALSE si no consintió, si lo retiró, si el texto que firmó quedó desactualizado, o si firmó sobre un texto de relleno.';



CREATE OR REPLACE FUNCTION "public"."consultas_a_hce_por_vencer"() RETURNS TABLE("anio" integer, "desde" timestamp with time zone, "hasta" timestamp with time zone, "se_borra_el" "date", "preaviso_el" "date", "notificacion_el" "date")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prest uuid := interno.prestadora_actual();
BEGIN
  IF v_prest IS NULL
     OR NOT (interno.es_superadmin()
             OR interno.es_admin_prestadora()
             OR COALESCE(auth.jwt() ->> 'role', '') = 'trabajo_sin_persona') THEN
    RAISE EXCEPTION 'sin_permiso_para_ver_el_vencimiento_de_las_consultas_a_hce' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM interno.consultas_a_hce_por_vencer(v_prest);
END;
$$;


ALTER FUNCTION "public"."consultas_a_hce_por_vencer"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consumir_contacto_intermediacion"("p_acceso_id" "uuid", "p_asistente_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_acceso public.accesos_intermediacion%ROWTYPE;
  v_ya_estaba boolean;
  v_saldo integer;
BEGIN
  -- Tomada la fila del acceso, el que llegue segundo espera acá. Sin esto, dos pedidos leen el
  -- mismo saldo y los dos descuentan sobre ese número: de dos contactos se cobra uno.
  SELECT * INTO v_acceso
    FROM public.accesos_intermediacion
   WHERE id = p_acceso_id
     FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'acceso_inexistente');
  END IF;

  -- Falla cerrado: un acceso suspendido, vencido o dado de baja con el período pagado ya
  -- terminado no abre nada, aunque le haya quedado saldo.
  IF NOT interno.el_acceso_abre_contactos(v_acceso.prestadora_id, v_acceso.estado, v_acceso.suspension_desde, v_acceso.vigente_hasta) THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'acceso_no_vigente');
  END IF;

  -- El Asistente tiene que ser de la misma Prestadora que el acceso. Uno de otra, o uno que no
  -- existe, contesta igual: no se distingue cuál de los dos fue.
  IF NOT EXISTS (
    SELECT 1 FROM public.asistentes
     WHERE id = p_asistente_id AND prestadora_id = v_acceso.prestadora_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'no_encontrado');
  END IF;

  -- Ya abierto antes: se contesta que sí y no se cobra de nuevo. El contacto de un Asistente se
  -- paga una sola vez por Cliente, y mirarlo otra vez no es un contacto nuevo.
  SELECT EXISTS (
    SELECT 1 FROM public.contactos_vistos_intermediacion
     WHERE cliente_id = v_acceso.cliente_id AND asistente_id = p_asistente_id
  ) INTO v_ya_estaba;

  IF v_ya_estaba THEN
    RETURN jsonb_build_object(
      'ok', true, 'ya_estaba', true, 'saldo_contactos', v_acceso.saldo_contactos
    );
  END IF;

  IF v_acceso.saldo_contactos IS NOT NULL AND v_acceso.saldo_contactos <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'saldo_agotado', 'saldo_contactos', 0);
  END IF;

  -- Se anota primero y se descuenta después, en ese orden y no al revés: así el candado de la
  -- tabla es el que decide, y no queda ninguna forma de descontar sin haber anotado. La misma
  -- Cliente con dos paquetes abriendo el mismo Asistente a la vez llega hasta acá por dos filas
  -- de acceso distintas, que el candado de más arriba no cruza; el segundo choca contra éste.
  BEGIN
    INSERT INTO public.contactos_vistos_intermediacion
      (prestadora_id, cliente_id, asistente_id, acceso_id)
    VALUES
      (v_acceso.prestadora_id, v_acceso.cliente_id, p_asistente_id, p_acceso_id);
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'ok', true, 'ya_estaba', true, 'saldo_contactos', v_acceso.saldo_contactos
    );
  END;

  -- El que se sostiene por fecha no tiene qué descontar: queda anotado y el saldo sigue vacío.
  IF v_acceso.saldo_contactos IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'ya_estaba', false, 'saldo_contactos', NULL);
  END IF;

  UPDATE public.accesos_intermediacion
     SET saldo_contactos = saldo_contactos - 1,
         updated_at = now()
   WHERE id = p_acceso_id
  RETURNING saldo_contactos INTO v_saldo;

  RETURN jsonb_build_object('ok', true, 'ya_estaba', false, 'saldo_contactos', v_saldo);
END;
$$;


ALTER FUNCTION "public"."consumir_contacto_intermediacion"("p_acceso_id" "uuid", "p_asistente_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."consumir_contacto_intermediacion"("p_acceso_id" "uuid", "p_asistente_id" "uuid") IS 'Anota a qué Asistente se le abrió el contacto y, si el acceso se sostiene por saldo, le descuenta uno, en la misma transacción. Sólo acepta un Asistente de la misma Prestadora que el acceso. Un Asistente ya abierto no vuelve a descontar. El acceso que se sostiene por fecha se anota sin descontar nada. Devuelve ok y el saldo que queda, o el motivo por el que no se pudo.';



CREATE OR REPLACE FUNCTION "public"."correcciones_de_factura"("p_factura_id" "uuid") RETURNS TABLE("neto" numeric, "correcciones_contadas" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    COALESCE(SUM(CASE WHEN c.sentido = 'resta' THEN -c.monto ELSE c.monto END), 0)::numeric(12, 2),
    COUNT(*)::integer
  FROM public.correcciones_factura_cliente c
  WHERE c.factura_id = p_factura_id;
$$;


ALTER FUNCTION "public"."correcciones_de_factura"("p_factura_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."correcciones_de_factura"("p_factura_id" "uuid") IS 'Cuanto movieron en total las correcciones de una factura, y cuantas fueron. Negativo es que se facturo de mas.';



CREATE OR REPLACE FUNCTION "public"."cuenta_del_usuario"("p_usuario" "text") RETURNS TABLE("id" "uuid", "prestadora_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT u.id, u.prestadora_id
    FROM usuarios u
   WHERE auth.jwt() ->> 'role' = 'trabajo_sin_persona'
     AND u.rol IN ('coordinador', 'asistente', 'cliente')
     AND u.desactivada_en IS NULL
     AND u.nombre_de_usuario IS NOT NULL
     AND lower(u.nombre_de_usuario) = lower(btrim(coalesce(p_usuario, ''), E' \t\r\n'));
$$;


ALTER FUNCTION "public"."cuenta_del_usuario"("p_usuario" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."asistentes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "nombre" "text" NOT NULL,
    "telefono" "text",
    "email" "text",
    "foto_url" "text",
    "disponibilidad" "jsonb",
    "estado" "text" DEFAULT 'activo'::"text" NOT NULL,
    "qr_token" "text" DEFAULT ("gen_random_uuid"())::"text",
    "fecha_alta" "date" NOT NULL,
    "fecha_baja" "date",
    "horas_semanales" numeric(5,2),
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "deleted_at" timestamp with time zone,
    "dni" "text",
    "prestadora_id" "uuid" NOT NULL,
    "canales" "text"[] DEFAULT ARRAY['directa'::"text", 'intermediacion'::"text"] NOT NULL,
    "importacion_id" "uuid",
    "pendiente_conformidad" boolean DEFAULT false NOT NULL,
    "tipo_asistente_id" "uuid",
    "disponible" boolean DEFAULT true NOT NULL,
    "disponibilidad_cambiada_en" timestamp with time zone,
    "usuario_id" "uuid" NOT NULL,
    "numero_legajo" integer NOT NULL,
    "documento_tipo" "text",
    "documento_numero" "text",
    "documento_pais" "text",
    "genero" "text",
    CONSTRAINT "asistentes_canales_valido" CHECK ((("canales" <@ ARRAY['directa'::"text", 'intermediacion'::"text"]) AND ("array_length"("canales", 1) > 0))),
    CONSTRAINT "asistentes_estado_check" CHECK (("estado" = ANY (ARRAY['activo'::"text", 'inactivo'::"text", 'cesado'::"text"]))),
    CONSTRAINT "la_disponibilidad_es_una_lista_de_opciones" CHECK ((("disponibilidad" IS NULL) OR (("jsonb_typeof"("disponibilidad") = 'array'::"text") AND (NOT "jsonb_path_exists"("disponibilidad", '$[*]?(@.type() != "string")'::"jsonpath")))))
);


ALTER TABLE "public"."asistentes" OWNER TO "postgres";


COMMENT ON COLUMN "public"."asistentes"."canales" IS 'En qué modalidades de trabajo está este Asistente: directa, match, o las dos. Tiene que estar dentro de lo que la Prestadora tenga habilitado. El nombre de la columna quedó de antes y no se renombra; la palabra del producto es modalidad de trabajo.';



COMMENT ON COLUMN "public"."asistentes"."tipo_asistente_id" IS 'Que ES este Asistente: cuidador/a, enfermero/a, kinesiologo/a, medico/a o el tipo que haya creado su Prestadora. Decide sus Tareas y si se le exige Matricula vigente para atender.';



COMMENT ON COLUMN "public"."asistentes"."disponible" IS 'Lo decide el Asistente desde su aplicacion, no la Prestadora. En false, el aviso automatico de relevo no le escribe y en la lista de candidatos queda con su motivo. No cambia ningun turno de guardia ya asignado. Distinto de asistentes.estado, que es la decision administrativa de la Prestadora.';



COMMENT ON COLUMN "public"."asistentes"."disponibilidad" IS 'En qué horarios suele estar disponible: las claves de las opciones elegidas de la lista de opciones disponibilidad. Nula o vacía, no está cargada.';



COMMENT ON COLUMN "public"."asistentes"."disponibilidad_cambiada_en" IS 'Cuando lo cambio por ultima vez. Sirve para que quien coordina sepa si el "no disponible" es de hoy o de hace tres meses.';



COMMENT ON COLUMN "public"."asistentes"."usuario_id" IS 'De qué cuenta cuelga esta ficha. Una cuenta puede tener una ficha por Prestadora; la ficha es el legajo de trabajo en esa Prestadora y la cuenta es la persona.';



CREATE OR REPLACE FUNCTION "public"."cuenta_desactivada"("a" "public"."asistentes") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT CASE
    WHEN interno.prestadora_actual() IS NOT NULL
         AND interno.prestadora_actual() IS DISTINCT FROM a.prestadora_id THEN false
    ELSE interno.asistente_desactivado(a.id)
  END;
$$;


ALTER FUNCTION "public"."cuenta_desactivada"("a" "public"."asistentes") OWNER TO "postgres";



CREATE OR REPLACE FUNCTION "public"."cuenta_regresiva_del_incidente"("p_incidente" "uuid") RETURNS TABLE("destinatario" "text", "organismo" "text", "cantidad" integer, "unidad" "text", "cuenta_desde" "text", "desde_at" timestamp with time zone, "vence_at" timestamp with time zone, "notificado_at" timestamp with time zone, "vencido" boolean, "manda" boolean, "fuente" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
#variable_conflict use_column
DECLARE
  v_incidente public.incidentes_de_seguridad%ROWTYPE;
  v_pais      text;
BEGIN
  IF NOT (interno.es_superadmin() OR interno.es_admin_prestadora()) THEN
    RETURN;
  END IF;

  SELECT i.* INTO v_incidente
    FROM public.incidentes_de_seguridad i
   WHERE i.id = p_incidente
     AND i.prestadora_id = interno.prestadora_actual();
  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT p.pais INTO v_pais FROM public.prestadoras p WHERE p.id = v_incidente.prestadora_id;
  IF v_pais IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH plazos AS (
    SELECT pl.destinatario, pl.organismo, pl.cantidad, pl.unidad, pl.cuenta_desde, pl.fuente,
           CASE pl.cuenta_desde
             WHEN 'ocurrido' THEN v_incidente.ocurrido_at
             ELSE v_incidente.conocido_at
           END AS desde_at,
           CASE pl.destinatario
             WHEN 'autoridad' THEN v_incidente.autoridad_notificada_at
             WHEN 'titular' THEN v_incidente.titulares_notificados_at
             ELSE v_incidente.responsable_notificado_at
           END AS notificado_at
      FROM public.plazos_de_notificacion_de_brechas pl
     WHERE pl.jurisdiccion = v_pais
       AND pl.vigencia_desde <= v_incidente.ocurrido_at::date
       AND (pl.vigencia_hasta IS NULL OR pl.vigencia_hasta >= v_incidente.ocurrido_at::date)
  ),
  con_vencimiento AS (
    SELECT pz.*,
           CASE pz.unidad
             WHEN 'horas' THEN pz.desde_at + make_interval(hours => pz.cantidad)
             WHEN 'dias_corridos' THEN pz.desde_at + make_interval(days => pz.cantidad)
             ELSE interno.sumar_dias_habiles(v_pais, pz.desde_at, pz.cantidad)
           END AS vence_at
      FROM plazos pz
  ),
  el_que_manda AS (
    SELECT cv.destinatario
      FROM con_vencimiento cv
     ORDER BY (cv.notificado_at IS NOT NULL), cv.vence_at, cv.destinatario
     LIMIT 1
  )
  SELECT cv.destinatario, cv.organismo, cv.cantidad, cv.unidad, cv.cuenta_desde,
         cv.desde_at, cv.vence_at, cv.notificado_at,
         (cv.notificado_at IS NULL AND cv.vence_at < now()) AS vencido,
         (cv.destinatario = (SELECT m.destinatario FROM el_que_manda m)) AS manda,
         cv.fuente
    FROM con_vencimiento cv
   ORDER BY cv.vence_at, cv.destinatario;
END;
$$;


ALTER FUNCTION "public"."cuenta_regresiva_del_incidente"("p_incidente" "uuid") OWNER TO "postgres";



COMMENT ON FUNCTION "public"."cuenta_regresiva_del_incidente"("p_incidente" "uuid") IS 'Para un incidente de seguridad, cada plazo legal de aviso del país de la Prestadora, cuándo vence y cuál manda. Sólo para la administración de la Prestadora dueña del incidente.';


CREATE OR REPLACE FUNCTION "public"."cuentas_nunca_activadas"("p_usuarios" "uuid"[]) RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT u.id
  FROM public.usuarios u
  JOIN auth.users a ON a.id = u.id
  WHERE auth.jwt() ->> 'role' = 'trabajo_sin_persona'
    AND u.prestadora_id = interno.prestadora_actual()
    AND u.id = ANY (p_usuarios)
    AND a.last_sign_in_at IS NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.tokens_activacion_cuenta t
      WHERE t.usuario_id = u.id
        AND t.usado_en IS NOT NULL
    );
$$;


ALTER FUNCTION "public"."cuentas_nunca_activadas"("p_usuarios" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dar_de_alta_la_cuenta"("p_email" "text", "p_clave" "text", "p_rol" "text", "p_nombre" "text", "p_telefono" "text", "p_nombre_de_usuario" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $_$
DECLARE
  v_prestadora uuid;
  v_correo text;
  v_usuario uuid := gen_random_uuid();
  v_ingreso text;
  v_parte text;
  v_dominio text;
  v_nombre_de_usuario text;
BEGIN
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'trabajo_sin_persona' THEN
    RAISE EXCEPTION 'sin_permiso';
  END IF;
  v_prestadora := interno.prestadora_actual();
  IF v_prestadora IS NULL THEN RAISE EXCEPTION 'sin_permiso'; END IF;
  IF p_rol IS NULL OR p_rol NOT IN ('coordinador', 'asistente', 'cliente') THEN
    RAISE EXCEPTION 'sin_permiso';
  END IF;
  v_correo := lower(btrim(coalesce(p_email, ''), E' \t\r\n'));
  IF v_correo = '' OR coalesce(p_clave, '') = '' THEN RAISE EXCEPTION 'faltan_datos'; END IF;

  IF EXISTS (SELECT 1 FROM usuarios WHERE prestadora_id = v_prestadora AND lower(email) = v_correo
                AND desactivada_en IS NULL) THEN
    RAISE EXCEPTION 'correo_de_esta_prestadora';
  END IF;

  -- La coordinación nace con su nombre: la parte que escribe el Administrador y el código de la
  -- Prestadora. Asistentes y Clientes eligen el suyo al activar la cuenta.
  IF p_rol = 'coordinador' THEN
    v_parte := nullif(lower(btrim(coalesce(p_nombre_de_usuario, ''), E' \t\r\n')), '');
    IF v_parte IS NULL THEN RAISE EXCEPTION 'faltan_datos'; END IF;
    IF v_parte !~ '^[a-z0-9]([a-z0-9._-]{0,38}[a-z0-9])?$' THEN
      RAISE EXCEPTION 'usuario_mal_escrito';
    END IF;
    SELECT dominio INTO v_dominio FROM configuracion_prestadora WHERE prestadora_id = v_prestadora;
    IF v_dominio IS NULL THEN RAISE EXCEPTION 'faltan_datos'; END IF;
    v_nombre_de_usuario := v_parte || '_' || lower(v_dominio);
    IF EXISTS (SELECT 1 FROM usuarios WHERE lower(nombre_de_usuario) = v_nombre_de_usuario
                  AND desactivada_en IS NULL) THEN
      RAISE EXCEPTION 'usuario_en_uso';
    END IF;
  END IF;

  v_ingreso := v_usuario::text || '@acceso.careonys.invalid';

  INSERT INTO auth.users (
    instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
    confirmation_token, recovery_token, email_change_token_new, email_change,
    email_change_token_current, phone_change, phone_change_token, reauthentication_token)
  VALUES (
    '00000000-0000-0000-0000-000000000000', v_usuario, 'authenticated', 'authenticated',
    v_ingreso, extensions.crypt(p_clave, extensions.gen_salt('bf', 10)), now(),
    '{"provider":"email","providers":["email"]}'::jsonb, '{}'::jsonb, now(), now(),
    '', '', '', '', '', '', '', '');
  INSERT INTO auth.identities (
    provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
  VALUES (
    v_usuario::text, v_usuario,
    jsonb_build_object('sub', v_usuario::text, 'email', v_ingreso, 'email_verified', true),
    'email', NULL, now(), now());
  BEGIN
    INSERT INTO usuarios (id, rol, nombre, telefono, email, prestadora_id, nombre_de_usuario)
    VALUES (v_usuario, p_rol, p_nombre, nullif(btrim(coalesce(p_telefono, '')), ''), v_correo, v_prestadora,
            v_nombre_de_usuario);
  EXCEPTION WHEN unique_violation THEN
    -- Dos altas al mismo tiempo pasaron las dos comprobaciones de arriba: el índice decide.
    IF v_nombre_de_usuario IS NOT NULL
       AND EXISTS (SELECT 1 FROM usuarios WHERE lower(nombre_de_usuario) = v_nombre_de_usuario
                      AND desactivada_en IS NULL) THEN
      RAISE EXCEPTION 'usuario_en_uso';
    END IF;
    RAISE EXCEPTION 'correo_de_esta_prestadora';
  END;
  RETURN v_usuario;
END;
$_$;


ALTER FUNCTION "public"."dar_de_alta_la_cuenta"("p_email" "text", "p_clave" "text", "p_rol" "text", "p_nombre" "text", "p_telefono" "text", "p_nombre_de_usuario" "text") OWNER TO "postgres";



CREATE OR REPLACE FUNCTION "public"."dar_de_alta_la_prestadora"("p_referencia" "text", "p_razon_social" "text", "p_identificacion_fiscal" "text", "p_pais" "text", "p_nombre_fantasia" "text", "p_codigo" "text", "p_casilla_envio" "text", "p_email_respuestas" "text", "p_regla_reenvio" "text", "p_admin_nombre" "text", "p_admin_email" "text", "p_admin_telefono" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_pase         jsonb := COALESCE(auth.jwt(), '{}'::jsonb);
  v_pase_crudo   text  := current_setting('request.jwt.claims', true);
  v_id           uuid;
  v_admin        uuid;
  v_email        text  := lower(btrim(COALESCE(p_admin_email, '')));
  v_restriccion  text;
  v_mensaje      text;
BEGIN
  -- Sólo la cuenta automática sin Prestadora. Una cuenta de una Prestadora, aunque sea del
  -- trabajo sin persona, no da de alta otra.
  IF v_pase ->> 'role' IS DISTINCT FROM 'trabajo_sin_persona'
     OR COALESCE(v_pase ->> 'prestadora_id', '') <> ''
     OR v_pase ->> 'trabajo' IS NOT NULL THEN
    RAISE EXCEPTION 'sin_permiso';
  END IF;

  IF NULLIF(btrim(COALESCE(p_referencia, '')), '') IS NULL
     OR NULLIF(btrim(COALESCE(p_razon_social, '')), '') IS NULL
     OR NULLIF(btrim(COALESCE(p_pais, '')), '') IS NULL
     OR NULLIF(btrim(COALESCE(p_nombre_fantasia, '')), '') IS NULL
     OR NULLIF(btrim(COALESCE(p_codigo, '')), '') IS NULL
     OR NULLIF(btrim(COALESCE(p_admin_nombre, '')), '') IS NULL
     OR v_email = '' THEN
    RAISE EXCEPTION 'faltan_datos';
  END IF;

  -- El alta repetida devuelve la misma Prestadora.
  SELECT id INTO v_id FROM prestadoras WHERE referencia_celtatech = p_referencia;
  IF FOUND THEN
    RETURN jsonb_build_object('prestadora_id', v_id, 'creada', false);
  END IF;

  v_id := gen_random_uuid();

  BEGIN
    -- La sesión apunta a la Prestadora nueva, y a ninguna otra, mientras dura esta operación.
    -- Es lo que piden los disparadores que siembran su configuración.
    PERFORM set_config('request.jwt.claims',
                       (v_pase || jsonb_build_object('prestadora_id', v_id))::text, true);

    INSERT INTO prestadoras (id, razon_social, identificacion_fiscal, pais, nombre_fantasia,
                             casilla_envio, regla_reenvio, referencia_celtatech)
    VALUES (v_id, btrim(p_razon_social), NULLIF(btrim(COALESCE(p_identificacion_fiscal, '')), ''),
            upper(btrim(p_pais)), btrim(p_nombre_fantasia), NULLIF(btrim(COALESCE(p_casilla_envio, '')), ''),
            NULLIF(btrim(COALESCE(p_regla_reenvio, '')), ''), p_referencia);

    -- El código y el correo que recibe las respuestas viven en la configuración, que el
    -- disparador de la Prestadora ya sembró.
    UPDATE configuracion_prestadora
       SET dominio = p_codigo,
           email   = NULLIF(lower(btrim(COALESCE(p_email_respuestas, ''))), ''),
           updated_at = now()
     WHERE prestadora_id = v_id;

    -- La cuenta del Administrador. Entra con su correo. La contraseña nace al azar y nadie la
    -- conoce: la que va a usar se la da CeltaTech.
    v_admin := gen_random_uuid();

    INSERT INTO auth.users (
      instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      confirmation_token, recovery_token, email_change_token_new, email_change,
      email_change_token_current, phone_change, phone_change_token, reauthentication_token
    ) VALUES (
      '00000000-0000-0000-0000-000000000000', v_admin, 'authenticated', 'authenticated', v_email,
      extensions.crypt(encode(extensions.gen_random_bytes(32), 'hex'), extensions.gen_salt('bf', 10)),
      now(), '{"provider":"email","providers":["email"]}'::jsonb, '{}'::jsonb, now(), now(),
      '', '', '', '', '', '', '', ''
    );

    INSERT INTO auth.identities (provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
    VALUES (v_admin::text, v_admin,
            jsonb_build_object('sub', v_admin::text, 'email', v_email, 'email_verified', true),
            'email', NULL, now(), now());

    INSERT INTO usuarios (id, rol, nombre, telefono, email, prestadora_id, nombre_de_usuario)
    VALUES (v_admin, 'admin_prestadora', btrim(p_admin_nombre),
            NULLIF(btrim(COALESCE(p_admin_telefono, '')), ''), v_email, v_id, NULL);

    INSERT INTO registro_actividad (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, detalle)
    VALUES (v_id, NULL, 'alta_de_la_prestadora', 'prestadoras', v_id,
            jsonb_build_object('rol_nuevo', 'admin_prestadora'));

    PERFORM set_config('request.jwt.claims', COALESCE(v_pase_crudo, ''), true);

  EXCEPTION
    WHEN unique_violation THEN
      GET STACKED DIAGNOSTICS v_restriccion = CONSTRAINT_NAME;
      PERFORM set_config('request.jwt.claims', COALESCE(v_pase_crudo, ''), true);

      -- Dos altas iguales a la vez: la otra ganó, y se devuelve la suya.
      IF v_restriccion = 'prestadoras_referencia_celtatech_unica' THEN
        SELECT id INTO v_id FROM prestadoras WHERE referencia_celtatech = p_referencia;
        RETURN jsonb_build_object('prestadora_id', v_id, 'creada', false);
      END IF;

      RAISE EXCEPTION '%', CASE
        WHEN v_restriccion IN ('configuracion_prestadora_dominio_key', 'configuracion_prestadora_dominio_unico') THEN 'codigo_en_uso'
        WHEN v_restriccion = 'prestadoras_casilla_envio_unica' THEN 'casilla_en_uso'
        WHEN v_restriccion = 'prestadoras_nombre_fantasia_unico' THEN 'nombre_en_uso'
        WHEN v_restriccion LIKE 'users_%' OR v_restriccion LIKE 'identities_%' THEN 'correo_de_administracion_en_uso'
        ELSE 'dato_en_uso'
      END;

    WHEN raise_exception THEN
      GET STACKED DIAGNOSTICS v_mensaje = MESSAGE_TEXT;
      PERFORM set_config('request.jwt.claims', COALESCE(v_pase_crudo, ''), true);

      RAISE EXCEPTION '%', CASE
        WHEN v_mensaje = 'la_direccion_de_la_prestadora_no_tiene_forma' THEN 'codigo_mal_escrito'
        WHEN v_mensaje LIKE 'No se sabe en qué moneda trabaja%' THEN 'pais_sin_moneda'
        ELSE 'alta_rechazada'
      END;
  END;

  RETURN jsonb_build_object('prestadora_id', v_id, 'creada', true);
END;
$$;



ALTER FUNCTION "public"."dar_de_alta_la_prestadora"("p_referencia" "text", "p_razon_social" "text", "p_identificacion_fiscal" "text", "p_pais" "text", "p_nombre_fantasia" "text", "p_codigo" "text", "p_casilla_envio" "text", "p_email_respuestas" "text", "p_regla_reenvio" "text", "p_admin_nombre" "text", "p_admin_email" "text", "p_admin_telefono" "text") OWNER TO "postgres";



COMMENT ON FUNCTION "public"."dar_de_alta_la_prestadora"("p_referencia" "text", "p_razon_social" "text", "p_identificacion_fiscal" "text", "p_pais" "text", "p_nombre_fantasia" "text", "p_codigo" "text", "p_casilla_envio" "text", "p_email_respuestas" "text", "p_regla_reenvio" "text", "p_admin_nombre" "text", "p_admin_email" "text", "p_admin_telefono" "text") IS 'El alta de una Prestadora que hace CeltaTech, entera o nada. Sólo la llama la cuenta automática sin Prestadora. No lee ni cambia ninguna Prestadora existente.';


CREATE OR REPLACE FUNCTION "public"."dar_de_baja_el_servicio"("p_servicio" "uuid", "p_motivo" "text", "p_motivo_detalle" "text", "p_comprobaciones" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_servicio servicios%ROWTYPE;
  v_pide_detalle boolean;
  v_comprobaciones text[];
  v_faltan integer;
  v_baja uuid;
BEGIN
  SELECT * INTO v_servicio FROM servicios
   WHERE id = p_servicio AND prestadora_id = interno.prestadora_actual();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'servicio_inexistente';
  END IF;
  IF v_servicio.estado <> 'vigente' THEN
    RAISE EXCEPTION 'el_servicio_ya_esta_de_baja';
  END IF;

  IF interno.turnos_guardia_asignados_del_servicio(p_servicio) > 0 THEN
    RAISE EXCEPTION 'el_servicio_tiene_turnos_guardia_asignados';
  END IF;

  SELECT m.pide_detalle INTO v_pide_detalle
    FROM motivos_cierre_servicio m
   WHERE m.prestadora_id = v_servicio.prestadora_id
     AND m.activo
     AND coalesce(m.clave, m.nombre) = p_motivo
   LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'motivo_de_cierre_inexistente:%', p_motivo;
  END IF;
  IF v_pide_detalle AND coalesce(btrim(p_motivo_detalle), '') = '' THEN
    RAISE EXCEPTION 'motivo_de_cierre_pide_detalle:%', p_motivo;
  END IF;

  SELECT count(*) INTO v_faltan
    FROM lista_de_comprobacion_baja_servicio l
   WHERE l.prestadora_id = v_servicio.prestadora_id
     AND l.activo
     AND NOT (l.id = ANY (coalesce(p_comprobaciones, '{}')));
  IF v_faltan > 0 THEN
    RAISE EXCEPTION 'faltan_comprobaciones_de_la_baja';
  END IF;

  SELECT coalesce(array_agg(l.nombre ORDER BY l.orden, l.created_at), '{}') INTO v_comprobaciones
    FROM lista_de_comprobacion_baja_servicio l
   WHERE l.prestadora_id = v_servicio.prestadora_id
     AND l.activo
     AND l.id = ANY (coalesce(p_comprobaciones, '{}'));

  INSERT INTO bajas_de_servicio (prestadora_id, servicio_id, motivo, motivo_detalle, comprobaciones, dada_por)
  VALUES (v_servicio.prestadora_id, p_servicio, p_motivo,
          CASE WHEN v_pide_detalle THEN btrim(p_motivo_detalle) END,
          v_comprobaciones, interno.usuario_de_la_sesion())
  RETURNING id INTO v_baja;

  -- Todas las prestaciones del Servicio, también las que quien da la baja no lee por el precio.
  PERFORM interno.dar_de_baja_las_prestaciones_del_servicio(p_servicio);
  UPDATE series_turnos_guardia
     SET estado = 'cancelada', cancelacion_origen = 'prestadora', cancelado_at = now()
   WHERE servicio_id = p_servicio AND estado = 'activa';
  -- Lo pausado y lo suspendido también se cancela: la baja no deja nada esperando volver.
  UPDATE turnos_guardia
     SET estado = 'cancelada', cancelacion_origen = 'prestadora', cancelacion_alcance = 'servicio',
         interrupcion_id = NULL
   WHERE servicio_id = p_servicio
     AND ((estado = 'programada' AND asistente_id IS NULL) OR estado IN ('pausada', 'suspendida'));

  -- Las pausas y las suspensiones abiertas del Servicio terminan con la baja.
  UPDATE interrupciones_de_cobertura
     SET levantada_desde = greatest(desde, interno.hoy_de_la_prestadora(prestadora_id)),
         levantada_at = now(), levantada_por = interno.usuario_de_la_sesion()
   WHERE servicio_id = p_servicio AND tipo IN ('pausa', 'suspension') AND levantada_at IS NULL;

  PERFORM set_config('careonys.cambio_de_estado_del_servicio', p_servicio::text, true);
  UPDATE servicios
     SET estado = 'de_baja',
         vigente_hasta = greatest(vigente_desde,
                                  interno.hoy_de_la_prestadora(prestadora_id))
   WHERE id = p_servicio;
  PERFORM set_config('careonys.cambio_de_estado_del_servicio', '', true);

  PERFORM interno.anotar_deuda_de_la_baja(v_baja);

  PERFORM interno.anotar_turnos_sin_cubrir();

  RETURN v_baja;
END;
$$;


ALTER FUNCTION "public"."dar_de_baja_el_servicio"("p_servicio" "uuid", "p_motivo" "text", "p_motivo_detalle" "text", "p_comprobaciones" "uuid"[]) OWNER TO "postgres";



CREATE OR REPLACE FUNCTION "public"."derechos_por_vencer"() RETURNS TABLE("solicitud_id" "uuid", "tipo" "text", "recibida_en" timestamp with time zone, "vence_en" timestamp with time zone, "recibida_el" "date", "vence_el" "date")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prest uuid := interno.prestadora_actual();
BEGIN
  IF v_prest IS NULL OR COALESCE(auth.jwt() ->> 'role', '') <> 'trabajo_sin_persona' THEN
    RAISE EXCEPTION 'sin_permiso_para_avisar_los_derechos_por_vencer' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM interno.derechos_por_vencer(v_prest);
END;
$$;


ALTER FUNCTION "public"."derechos_por_vencer"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desactivar_la_cuenta"("p_usuario" "uuid", "p_motivo" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid;
  v_motivo text := btrim(coalesce(p_motivo, ''), E' \t\r\n');
BEGIN
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'trabajo_sin_persona' THEN RETURN false; END IF;
  v_prestadora := interno.prestadora_actual();
  IF v_prestadora IS NULL OR p_usuario IS NULL OR v_motivo = '' THEN RETURN false; END IF;

  -- Turnos sin terminar: se reasignan o se cierran antes, y la cuenta queda como estaba.
  IF EXISTS (SELECT 1 FROM interno.turnos_guardia_que_traban_la_desactivacion(p_usuario, v_prestadora)) THEN
    RAISE EXCEPTION 'desactivacion_con_turnos_guardia_por_delante';
  END IF;

  UPDATE usuarios
     SET desactivada_en = now(),
         motivo_de_la_desactivacion = v_motivo
   WHERE id = p_usuario
     AND prestadora_id = v_prestadora
     AND rol IN ('coordinador', 'asistente', 'cliente')
     AND desactivada_en IS NULL;
  IF NOT FOUND THEN RETURN false; END IF;

  -- La cuenta de ingreso queda bloqueada: no entra con la clave, no renueva la sesión y no canjea
  -- ningún enlace. El bloqueo no lo levanta un cambio de clave.
  UPDATE auth.users
     SET banned_until = now() + interval '100 years',
         updated_at = now()
   WHERE id = p_usuario;

  -- Las sesiones abiertas se cierran ahora y no cuando venzan.
  DELETE FROM auth.refresh_tokens WHERE user_id = p_usuario::text;
  DELETE FROM auth.sessions WHERE user_id = p_usuario;

  -- Lo que tenía pendiente para entrar o cambiar la clave deja de servir.
  UPDATE tokens_activacion_cuenta SET usado_en = now()
   WHERE usuario_id = p_usuario AND usado_en IS NULL;
  UPDATE tokens_recuperacion_clave SET usado_en = now()
   WHERE usuario_id = p_usuario AND usado_en IS NULL;
  UPDATE cambios_de_clave_habilitados SET anulado_en = now()
   WHERE usuario_id = p_usuario AND usado_en IS NULL AND anulado_en IS NULL;
  UPDATE codigos_al_telefono SET anulado_en = now()
   WHERE usuario_id = p_usuario AND verificado_en IS NULL AND anulado_en IS NULL;
  UPDATE equipos_conocidos SET revocado_en = now()
   WHERE usuario_id = p_usuario AND revocado_en IS NULL;

  -- La responsabilidad del reclutamiento queda libre, como quedaba al borrar la cuenta.
  UPDATE configuracion_reclutamiento SET responsable_id = NULL
   WHERE responsable_id = p_usuario AND prestadora_id = v_prestadora;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."desactivar_la_cuenta"("p_usuario" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deshacer_el_alta_de_la_cuenta"("p_usuario" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid;
BEGIN
  -- Único borrado de una cuenta: deshace un alta que se cortó, y sólo si la cuenta nunca entró.
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'trabajo_sin_persona' THEN RETURN false; END IF;
  v_prestadora := interno.prestadora_actual();
  IF v_prestadora IS NULL OR p_usuario IS NULL THEN RETURN false; END IF;

  IF EXISTS (SELECT 1 FROM auth.users WHERE id = p_usuario AND last_sign_in_at IS NOT NULL) THEN
    RETURN false;
  END IF;

  DELETE FROM usuarios
   WHERE id = p_usuario
     AND prestadora_id = v_prestadora
     AND rol IN ('coordinador', 'asistente', 'cliente')
     AND desactivada_en IS NULL;
  IF NOT FOUND THEN RETURN false; END IF;

  DELETE FROM auth.users WHERE id = p_usuario;
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."deshacer_el_alta_de_la_cuenta"("p_usuario" "uuid") OWNER TO "postgres";



CREATE OR REPLACE FUNCTION "public"."distancias_de_asistentes_a_pacientes"("p_asistentes" "uuid"[], "p_pacientes" "uuid"[], "p_fecha" "date") RETURNS TABLE("asistente_id" "uuid", "metros" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT x.asistente_id, x.metros
    FROM interno.distancias_de_asistentes_a_pacientes(
           ARRAY(SELECT a.id FROM public.asistentes a
                  WHERE a.id = ANY (p_asistentes)
                    AND a.prestadora_id = interno.prestadora_actual()),
           ARRAY(SELECT d.paciente_id FROM public.domicilios_de_pacientes_en(p_pacientes, p_fecha) d),
           p_fecha
         ) x
   WHERE interno.es_personal_de_la_prestadora();
$$;



ALTER FUNCTION "public"."distancias_de_asistentes_a_pacientes"("p_asistentes" "uuid"[], "p_pacientes" "uuid"[], "p_fecha" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."documento_autorizacion_signos_vitales"("p_paciente" "uuid", "p_idioma" "text") RETURNS TABLE("titulo" "text", "texto" "text", "verificador" "text", "idioma" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid;
BEGIN
  SELECT pa.prestadora_id INTO v_prestadora FROM pacientes pa WHERE pa.id = p_paciente;
  IF v_prestadora IS NULL OR v_prestadora <> interno.prestadora_actual() THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'trabajo_sin_persona'
     AND NOT (interno.es_personal_de_la_prestadora() AND interno.alcanza_la_informacion_de_salud(p_paciente))
     AND NOT (p_paciente IN (SELECT interno.pacientes_del_cliente())
              AND interno.persona_autorizada_puede(auth.uid(), 'persona_autorizada_ficha_del_paciente')) THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM interno.documento_autorizacion_signos_vitales(p_paciente, p_idioma);
END;
$$;


ALTER FUNCTION "public"."documento_autorizacion_signos_vitales"("p_paciente" "uuid", "p_idioma" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."domicilio_del_paciente_en"("p_paciente_id" "uuid", "p_fecha" "date") RETURNS TABLE("paciente_id" "uuid", "domicilio_temporal_id" "uuid", "calle" "text", "numero" "text", "piso" "text", "unidad" "text", "lugar" "text", "lat" double precision, "lng" double precision, "es_temporal" boolean, "motivo" "text", "desde" "date", "hasta" "date", "lugar_id" "uuid")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select * from public.domicilios_de_pacientes_en(array[p_paciente_id], p_fecha);
$$;


ALTER FUNCTION "public"."domicilio_del_paciente_en"("p_paciente_id" "uuid", "p_fecha" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."domicilios_de_pacientes_en"("p_pacientes" "uuid"[], "p_fecha" "date") RETURNS TABLE("paciente_id" "uuid", "domicilio_temporal_id" "uuid", "calle" "text", "numero" "text", "piso" "text", "unidad" "text", "lugar" "text", "lat" double precision, "lng" double precision, "es_temporal" boolean, "motivo" "text", "desde" "date", "hasta" "date", "lugar_id" "uuid")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select
    p.id as paciente_id,
    d.id as domicilio_temporal_id,
    case when d.id is null then f.calle else d.calle end as calle,
    case when d.id is null then f.numero else d.numero end as numero,
    case when d.id is null then f.piso else d.piso end as piso,
    case when d.id is null then f.unidad else d.unidad end as unidad,
    l.nombre as lugar,
    case when d.id is null then f.lat else d.lat end as lat,
    case when d.id is null then f.lng else d.lng end as lng,
    d.id is not null as es_temporal,
    d.motivo,
    d.fecha_inicio as desde,
    d.fecha_fin as hasta,
    case when d.id is null then f.lugar_id else d.lugar_id end as lugar_id
  from public.pacientes p
  join public.personas f on f.id = p.persona_id and f.prestadora_id = p.prestadora_id
  left join lateral (
    select t.id, t.calle, t.numero, t.piso, t.unidad, t.lugar_id, t.lat, t.lng, t.motivo,
           t.fecha_inicio, t.fecha_fin
      from public.domicilios_temporales_paciente t
     where t.paciente_id = p.id
       and t.fecha_inicio <= p_fecha
       and (t.fecha_fin is null or t.fecha_fin >= p_fecha)
     -- La restricción de la tabla garantiza que haya una sola; el orden y el tope son la red por
     -- si alguna vez se afloja.
     order by t.fecha_inicio desc
     limit 1
  ) d on true
  left join public.lugares l
    on l.id = case when d.id is null then f.lugar_id else d.lugar_id end
   and l.prestadora_id = p.prestadora_id
  where p.id = any (p_pacientes);
$$;


ALTER FUNCTION "public"."domicilios_de_pacientes_en"("p_pacientes" "uuid"[], "p_fecha" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."el_mensaje_se_guarda_ya_tapado"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  lo_tapado record;
BEGIN
  -- Un mensaje automático no lo escribió nadie: su cuerpo es una clave de traducción. Buscarle
  -- un teléfono a una clave no encuentra nada y podría romperla.
  IF NEW.automatico THEN
    NEW.regla_tapada := NULL;
    RETURN NEW;
  END IF;

  SELECT t.texto, t.regla
    INTO lo_tapado
    FROM interno.tapar_lo_que_no_viaja_en_un_mensaje(NEW.cuerpo, NEW.prestadora_id) t;

  NEW.cuerpo       := lo_tapado.texto;
  NEW.regla_tapada := lo_tapado.regla;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."el_mensaje_se_guarda_ya_tapado"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."el_mensaje_se_guarda_ya_tapado"() IS 'Sobre mensajes_match: tapa el texto antes de escribirlo y anota que regla lo tapo. El texto tapado no se guarda, no se registra y no sale en ningun error.';



CREATE OR REPLACE FUNCTION "public"."estado_de_factura"("p_prestadora" "uuid", "p_monto_total" numeric, "p_cobrado" numeric, "p_fecha_vencimiento" "date") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    -- Nada por cobrar, nada que reclamar. Vale también para una factura de cero.
    WHEN COALESCE(p_cobrado, 0) >= COALESCE(p_monto_total, 0) THEN 'pagada'
    WHEN p_fecha_vencimiento IS NOT NULL AND p_fecha_vencimiento < interno.hoy_de_la_prestadora(p_prestadora) THEN 'vencida'
    ELSE 'pendiente'
  END;
$$;


ALTER FUNCTION "public"."estado_de_factura"("p_prestadora" "uuid", "p_monto_total" numeric, "p_cobrado" numeric, "p_fecha_vencimiento" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."estado_de_factura"("p_prestadora" "uuid", "p_monto_total" numeric, "p_cobrado" numeric, "p_fecha_vencimiento" "date") IS 'Único lugar donde se decide si una factura está pagada, vencida o pendiente. Cobro parcial: sigue pendiente (o vencida), y el cuánto falta lo dice el saldo.';



