CREATE OR REPLACE FUNCTION "public"."fn_rastro_del_cierre_por_el_asistente"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Que la hora de salida sea nueva. Un UPDATE cualquiera sobre una guardia ya cerrada no
  -- vuelve a marcar nada.
  IF NEW.checkout_at IS NULL OR OLD.checkout_at IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Que la guardia efectivamente quede cerrada: completada, o con la salida hecha y el Reporte
  -- Diario pendiente. Marcar la salida sin dar por terminada la guardia no es un cierre.
  IF NEW.estado IS NULL OR NEW.estado NOT IN ('completada', 'salida_sin_reporte') THEN
    RETURN NEW;
  END IF;

  -- Que nadie haya escrito ya el rastro en esta misma operación. Si vino escrito, manda quien
  -- lo escribió.
  IF NEW.cerrada_at IS NOT NULL OR NEW.cerrada_origen IS NOT NULL THEN
    RETURN NEW;
  END IF;

  NEW.cerrada_at     := NEW.checkout_at;
  NEW.cerrada_origen := 'asistente';
  NEW.cerrada_por    := NEW.asistente_id;
  NEW.cerrada_motivo := NULL;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_rastro_del_cierre_por_el_asistente"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_rastro_del_cierre_por_el_asistente"() IS 'Le pone la etiqueta al cierre que hace el Asistente cuando marca su salida. No cierra turnos de guardia: solo escribe quién, cuándo y desde dónde, sobre un cierre que ya está ocurriendo en esa misma operación.';



CREATE OR REPLACE FUNCTION "public"."fn_refrescar_factura_de_un_cobro"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    UPDATE public.facturas_cliente SET updated_at = now() WHERE id = OLD.factura_id;
  END IF;

  IF TG_OP <> 'DELETE' AND (TG_OP = 'INSERT' OR NEW.factura_id IS DISTINCT FROM OLD.factura_id) THEN
    UPDATE public.facturas_cliente SET updated_at = now() WHERE id = NEW.factura_id;
  END IF;

  RETURN NULL;
END;
$$;


