CREATE OR REPLACE FUNCTION "public"."poner_clave_con_codigo"("p_uso" "text", "p_codigo" "text", "p_clave" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid;
  v_usuario uuid;
  v_verificador text;
BEGIN
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'trabajo_sin_persona' THEN RETURN NULL; END IF;
  v_prestadora := interno.prestadora_actual();
  IF v_prestadora IS NULL OR coalesce(p_codigo, '') = '' OR coalesce(p_clave, '') = '' THEN
    RETURN NULL;
  END IF;

  -- Llega el enlace tal como vino en el correo; lo guardado es su identificador de verificación.
  v_verificador := encode(extensions.digest(p_codigo, 'sha256'), 'hex');

  IF p_uso = 'activacion' THEN
    UPDATE tokens_activacion_cuenta t SET usado_en = now()
      FROM usuarios u
     WHERE t.token = v_verificador AND t.usado_en IS NULL AND t.expira_en > now()
       AND u.id = t.usuario_id AND u.prestadora_id = v_prestadora
       AND u.rol IN ('coordinador', 'asistente', 'cliente')
       AND u.desactivada_en IS NULL
    RETURNING t.usuario_id INTO v_usuario;
  ELSIF p_uso = 'recuperacion' THEN
    UPDATE tokens_recuperacion_clave t SET usado_en = now()
      FROM usuarios u
     WHERE t.token = v_verificador AND t.usado_en IS NULL AND t.expira_en > now()
       AND u.id = t.usuario_id AND u.prestadora_id = v_prestadora
       AND u.rol IN ('coordinador', 'asistente', 'cliente')
       AND u.desactivada_en IS NULL
    RETURNING t.usuario_id INTO v_usuario;
  ELSE
    RETURN NULL;
  END IF;

  IF v_usuario IS NULL THEN RETURN NULL; END IF;

  UPDATE auth.users
     SET encrypted_password = extensions.crypt(p_clave, extensions.gen_salt('bf', 10)),
         updated_at = now()
   WHERE id = v_usuario;
  -- Sin cuenta de ingreso no queda ninguna clave puesta, y el código tampoco se gasta.
  IF NOT FOUND THEN RAISE EXCEPTION 'poner_clave_con_codigo: la cuenta no tiene ingreso'; END IF;

  RETURN v_usuario;
END;
$$;


ALTER FUNCTION "public"."poner_clave_con_codigo"("p_uso" "text", "p_codigo" "text", "p_clave" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."lista_precios" (
    "id" bigint NOT NULL,
    "tipo_servicio" "text" NOT NULL,
    "modalidad" "text" NOT NULL,
    "precio" numeric(12,2) NOT NULL,
    "vigente_desde" "date" NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "prestadora_id" "uuid" NOT NULL,
    "moneda" "public"."moneda_iso" NOT NULL,
    "vigente_hasta" "date",
    "reemplaza_a" bigint,
    "promocion_de" bigint,
    CONSTRAINT "lista_precios_promocion_con_fin" CHECK ((("promocion_de" IS NULL) OR ("vigente_hasta" IS NOT NULL))),
    CONSTRAINT "lista_precios_promocion_no_es_reemplazo" CHECK ((("promocion_de" IS NULL) OR ("reemplaza_a" IS NULL))),
    CONSTRAINT "lista_precios_vigencia_coherente" CHECK ((("vigente_hasta" IS NULL) OR ("vigente_hasta" >= "vigente_desde")))
);


ALTER TABLE "public"."lista_precios" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."precios_de_lista_que_rigen"("p_fecha" "date" DEFAULT "interno"."hoy_de_la_sesion"()) RETURNS SETOF "public"."lista_precios"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT DISTINCT ON (l.tipo_servicio, l.modalidad, l.moneda) l.*
    FROM public.lista_precios l
   WHERE l.prestadora_id = interno.prestadora_actual()
     AND l.activo
     AND l.vigente_desde <= p_fecha
     AND (l.vigente_hasta IS NULL OR l.vigente_hasta >= p_fecha)
   ORDER BY l.tipo_servicio, l.modalidad, l.moneda,
            (l.promocion_de IS NOT NULL) DESC,
            l.vigente_desde DESC,
            l.id DESC
$$;


ALTER FUNCTION "public"."precios_de_lista_que_rigen"("p_fecha" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prestaciones_con_promocion_vencida"("p_fecha" "date" DEFAULT "interno"."hoy_de_la_sesion"()) RETURNS TABLE("prestacion_id" bigint, "promocion_id" bigint, "promocion_hasta" "date", "precio_de_siempre_id" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT p.id, l.id, l.vigente_hasta, l.promocion_de
    FROM public.prestaciones p
    JOIN public.lista_precios l ON l.id = p.precio_lista_id
   WHERE p.prestadora_id = interno.prestadora_actual()
     AND l.promocion_de IS NOT NULL
     AND l.vigente_hasta < p_fecha
     AND p.estado = 'vigente'
     AND (p.vigente_hasta IS NULL OR p.vigente_hasta > l.vigente_hasta)
$$;


