CREATE OR REPLACE FUNCTION "public"."quitar_apoderado"("p_cliente" "uuid", "p_funcion" "text", "p_usuario" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_quien uuid := interno.quien_gestiona_al_apoderado(p_cliente, p_usuario);
BEGIN
  UPDATE apoderados
     SET quitado_en = now(), quitado_por = v_quien
   WHERE cliente_id = p_cliente AND funcion = p_funcion AND quitado_en IS NULL;
  RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."quitar_apoderado"("p_cliente" "uuid", "p_funcion" "text", "p_usuario" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reactivar_el_servicio"("p_servicio" "uuid", "p_motivo" "uuid", "p_motivo_detalle" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_servicio servicios%ROWTYPE;
  v_motivo motivos_reactivacion_servicio%ROWTYPE;
  v_reactivacion uuid;
BEGIN
  SELECT * INTO v_servicio FROM servicios
   WHERE id = p_servicio AND prestadora_id = interno.prestadora_actual();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'servicio_inexistente';
  END IF;
  IF v_servicio.estado <> 'de_baja' THEN
    RAISE EXCEPTION 'el_servicio_esta_vigente';
  END IF;

  SELECT * INTO v_motivo FROM motivos_reactivacion_servicio m
   WHERE m.id = p_motivo AND m.prestadora_id = v_servicio.prestadora_id AND m.activo;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'motivo_de_reactivacion_inexistente';
  END IF;
  IF v_motivo.pide_detalle AND coalesce(btrim(p_motivo_detalle), '') = '' THEN
    RAISE EXCEPTION 'motivo_de_reactivacion_pide_detalle';
  END IF;

  INSERT INTO reactivaciones_de_servicio (prestadora_id, servicio_id, motivo, motivo_detalle, reactivada_por)
  VALUES (v_servicio.prestadora_id, p_servicio, v_motivo.nombre,
          CASE WHEN v_motivo.pide_detalle THEN btrim(p_motivo_detalle) END,
          interno.usuario_de_la_sesion())
  RETURNING id INTO v_reactivacion;

  PERFORM set_config('careonys.cambio_de_estado_del_servicio', p_servicio::text, true);
  -- Reactivado, el Servicio vuelve a tener duración indeterminada hasta que se le ponga otro fin.
  UPDATE servicios SET estado = 'vigente', vigente_hasta = NULL WHERE id = p_servicio;
  PERFORM set_config('careonys.cambio_de_estado_del_servicio', '', true);

  RETURN v_reactivacion;
END;
$$;


ALTER FUNCTION "public"."reactivar_el_servicio"("p_servicio" "uuid", "p_motivo" "uuid", "p_motivo_detalle" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reactivar_la_cuenta"("p_usuario" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid;
  v_quien uuid := auth.uid();
  v_rol text;
  v_email text;
  v_nombre_de_usuario text;
BEGIN
  IF v_quien IS NULL OR p_usuario IS NULL THEN RETURN false; END IF;
  IF NOT coalesce(interno.es_admin_prestadora(), false) THEN RETURN false; END IF;
  v_prestadora := interno.prestadora_actual();
  IF v_prestadora IS NULL THEN RETURN false; END IF;

  SELECT rol, lower(email), lower(nombre_de_usuario)
    INTO v_rol, v_email, v_nombre_de_usuario
    FROM usuarios
   WHERE id = p_usuario
     AND prestadora_id = v_prestadora
     AND rol IN ('coordinador', 'asistente')
     AND desactivada_en IS NOT NULL
   FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;

  IF v_nombre_de_usuario IS NOT NULL AND EXISTS (
    SELECT 1 FROM usuarios
     WHERE lower(nombre_de_usuario) = v_nombre_de_usuario
       AND desactivada_en IS NULL AND id <> p_usuario) THEN
    RAISE EXCEPTION 'reactivacion_usuario_en_uso';
  END IF;
  IF v_email IS NOT NULL AND EXISTS (
    SELECT 1 FROM usuarios
     WHERE prestadora_id = v_prestadora AND lower(email) = v_email
       AND desactivada_en IS NULL AND id <> p_usuario) THEN
    RAISE EXCEPTION 'reactivacion_correo_en_uso';
  END IF;

  BEGIN
    UPDATE usuarios
       SET desactivada_en = NULL,
           motivo_de_la_desactivacion = NULL
     WHERE id = p_usuario;
  EXCEPTION WHEN unique_violation THEN
    -- Otra cuenta tomó el nombre o el email entre la comprobación y la escritura: el índice decide.
    IF v_nombre_de_usuario IS NOT NULL AND EXISTS (
      SELECT 1 FROM usuarios
       WHERE lower(nombre_de_usuario) = v_nombre_de_usuario
         AND desactivada_en IS NULL AND id <> p_usuario) THEN
      RAISE EXCEPTION 'reactivacion_usuario_en_uso';
    END IF;
    RAISE EXCEPTION 'reactivacion_correo_en_uso';
  END;

  -- La cuenta de ingreso vuelve a entrar con la clave que tenía.
  UPDATE auth.users
     SET banned_until = NULL,
         updated_at = now()
   WHERE id = p_usuario;

  INSERT INTO registro_actividad (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, detalle)
  VALUES (v_prestadora, v_quien, 'reactivacion_de_cuenta', 'usuarios', p_usuario,
          jsonb_build_object('rol_nuevo', v_rol));

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."reactivar_la_cuenta"("p_usuario" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reasignar_turno_guardia_por_emergencia"("p_turno_guardia_id" "uuid", "p_asistente_id" "uuid", "p_motivo" "text", "p_motivo_excepcion" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid;
  v_usuario    uuid;
  v_motivo     text := btrim(COALESCE(p_motivo, ''));
  v_turno_guardia    record;
  v_tocadas    integer;
BEGIN
  -- La Prestadora y la persona salen de la sesión, nunca del pedido. Sin persona no hay a quién
  -- atribuirle el cambio, y no se hace.
  v_prestadora := interno.prestadora_actual();
  v_usuario := interno.usuario_de_la_sesion();
  IF v_prestadora IS NULL OR v_usuario IS NULL THEN
    RAISE EXCEPTION 'reasignacion_sin_sesion' USING ERRCODE = '42501';
  END IF;

  IF p_turno_guardia_id IS NULL OR p_asistente_id IS NULL OR v_motivo = '' THEN
    RAISE EXCEPTION 'reasignacion_incompleta' USING ERRCODE = '23514';
  END IF;

  -- La lectura pasa por la RLS de quien pide.
  SELECT g.id, g.asistente_id, g.estado, g.checkin_at, g.fecha, g.hora_inicio, g.hora_fin,
         g.dias_hasta_el_fin, g.paciente_id, g.servicio_id
    INTO v_turno_guardia
    FROM public.turnos_guardia g
   WHERE g.id = p_turno_guardia_id
     AND g.prestadora_id = v_prestadora
     FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'reasignacion_sin_turno_guardia' USING ERRCODE = '42501';
  END IF;

  IF v_turno_guardia.estado <> 'ausente' OR v_turno_guardia.checkin_at IS NOT NULL
     OR v_turno_guardia.asistente_id IS NOT DISTINCT FROM p_asistente_id THEN
    RAISE EXCEPTION 'turno_guardia_empezado_no_cambia_de_asistente' USING ERRCODE = '23514';
  END IF;

  IF interno.asistente_ocupado_entre(
       p_asistente_id,
       p_turno_guardia_id,
       v_turno_guardia.fecha + v_turno_guardia.hora_inicio,
       interno.dia_en_que_termina_turno_guardia(v_turno_guardia.fecha, v_turno_guardia.hora_inicio, v_turno_guardia.hora_fin, v_turno_guardia.dias_hasta_el_fin) + v_turno_guardia.hora_fin
     ) THEN
    RAISE EXCEPTION 'asistente_en_otro_turno_guardia' USING ERRCODE = '23514';
  END IF;

  PERFORM interno.excepcion_por_documentos(
    v_prestadora,
    p_turno_guardia_id,
    p_asistente_id,
    interno.documentos_que_bloquean(
      p_asistente_id,
      interno.dia_en_que_termina_turno_guardia(v_turno_guardia.fecha, v_turno_guardia.hora_inicio, v_turno_guardia.hora_fin, v_turno_guardia.dias_hasta_el_fin),
      v_turno_guardia.paciente_id,
      v_turno_guardia.servicio_id
    ),
    p_motivo_excepcion
  );

  PERFORM set_config('careonys.reasignacion_por_emergencia', p_turno_guardia_id::text, true);

  INSERT INTO public.auditoria_reasignaciones_por_emergencia
    (prestadora_id, turno_guardia_id, usuario_id, asistente_anterior_id, asistente_nuevo_id, motivo)
  VALUES
    (v_prestadora, p_turno_guardia_id, v_usuario, v_turno_guardia.asistente_id, p_asistente_id, v_motivo);

  -- Quien la cubre entra ahora: el turno vuelve a esperar su check-in.
  UPDATE public.turnos_guardia
     SET asistente_id = p_asistente_id,
         estado = 'programada'
   WHERE id = p_turno_guardia_id
     AND prestadora_id = v_prestadora;
  GET DIAGNOSTICS v_tocadas = ROW_COUNT;

  PERFORM set_config('careonys.reasignacion_por_emergencia', '', true);

  IF v_tocadas = 0 THEN
    RAISE EXCEPTION 'reasignacion_sin_turno_guardia' USING ERRCODE = '42501';
  END IF;
END;
$$;


ALTER FUNCTION "public"."reasignar_turno_guardia_por_emergencia"("p_turno_guardia_id" "uuid", "p_asistente_id" "uuid", "p_motivo" "text", "p_motivo_excepcion" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reemplazar_poder_del_apoderado"("p_cliente" "uuid", "p_funcion" "text", "p_archivo" "text", "p_usuario" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_quien uuid := interno.quien_gestiona_al_apoderado(p_cliente, p_usuario);
  v_prestadora uuid := interno.prestadora_actual();
  v_id uuid;
BEGIN
  IF p_archivo IS NULL
     OR p_archivo NOT LIKE v_prestadora::text || '/' || p_cliente::text || '/' || p_funcion || '/%' THEN
    RAISE EXCEPTION 'archivo_invalido' USING ERRCODE = '22023';
  END IF;

  UPDATE apoderados
     SET archivo_url = p_archivo, estado = 'en_revision', motivo_observacion = NULL,
         revisado_por = NULL, revisado_at = NULL, cargado_por = v_quien
   WHERE cliente_id = p_cliente AND funcion = p_funcion AND quitado_en IS NULL
   RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    RAISE EXCEPTION 'no_encontrado' USING ERRCODE = 'P0002';
  END IF;
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."reemplazar_poder_del_apoderado"("p_cliente" "uuid", "p_funcion" "text", "p_archivo" "text", "p_usuario" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reemplazar_precio_de_lista"("p_precio_id" bigint, "p_precio" numeric, "p_desde" "date") RETURNS bigint
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_viejo public.lista_precios;
  v_nuevo bigint;
BEGIN
  IF p_precio IS NULL OR p_precio <= 0 OR p_desde IS NULL THEN
    RAISE EXCEPTION 'dato_invalido' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_viejo FROM public.lista_precios WHERE id = p_precio_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no_encontrado' USING ERRCODE = 'P0002';
  END IF;
  -- Un renglón ya cerrado no se vuelve a reemplazar: se reemplaza el que lo sucedió.
  IF v_viejo.vigente_hasta IS NOT NULL THEN
    RAISE EXCEPTION 'ya_reemplazado' USING ERRCODE = 'P0001';
  END IF;

  IF v_viejo.precio = p_precio THEN
    RETURN v_viejo.id;
  END IF;

  IF p_desde <= v_viejo.vigente_desde THEN
    RAISE EXCEPTION 'fecha_anterior' USING ERRCODE = 'P0001';
  END IF;

  v_nuevo := interno.copiar_renglon('public.lista_precios', v_viejo.id, jsonb_build_object(
    'precio', p_precio,
    'vigente_desde', p_desde,
    'vigente_hasta', NULL,
    'activo', true,
    'reemplaza_a', v_viejo.id
  ));

  UPDATE public.lista_precios
     SET vigente_hasta = p_desde - 1, activo = false
   WHERE id = v_viejo.id;

  UPDATE public.prestaciones
     SET requiere_revision = true
   WHERE precio_lista_id = v_viejo.id
     AND estado = 'vigente'
     AND (vigente_hasta IS NULL OR vigente_hasta >= p_desde);

  RETURN v_nuevo;
END;
$$;


ALTER FUNCTION "public"."reemplazar_precio_de_lista"("p_precio_id" bigint, "p_precio" numeric, "p_desde" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."registrar_autorizacion_signos_vitales_del_titular"("p_usuario" "uuid", "p_paciente" "uuid", "p_idioma" "text", "p_verificador" "text", "p_archivo" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
  v_doc record;
  v_id uuid;
BEGIN
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'trabajo_sin_persona' OR v_prestadora IS NULL THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pacientes pa JOIN clientes c ON c.id = pa.cliente_id
     WHERE pa.id = p_paciente AND pa.prestadora_id = v_prestadora AND c.usuario_id = p_usuario
  ) THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF EXISTS (SELECT 1 FROM autorizaciones_monitoreo_paciente
              WHERE paciente_id = p_paciente AND estado IN ('aceptada', 'pendiente')) THEN
    RAISE EXCEPTION 'ya_hay_una_autorizacion' USING ERRCODE = '23505';
  END IF;

  SELECT * INTO v_doc FROM interno.documento_autorizacion_signos_vitales(p_paciente, p_idioma);
  IF v_doc.texto IS NULL THEN
    RAISE EXCEPTION 'sin_texto' USING ERRCODE = '22023';
  END IF;

  IF p_archivo IS NULL THEN
    IF p_verificador IS DISTINCT FROM v_doc.verificador THEN
      RAISE EXCEPTION 'el_texto_cambio' USING ERRCODE = '22023';
    END IF;
    INSERT INTO autorizaciones_monitoreo_paciente
      (prestadora_id, paciente_id, metodo, estado, documento_texto, documento_verificador, documento_idioma,
       firmante_persona_id, cargado_por, revisado_en)
    VALUES
      (v_prestadora, p_paciente, 'aplicacion', 'aceptada', v_doc.texto, v_doc.verificador, p_idioma,
       interno.firmante_autorizacion_signos_vitales(p_paciente), p_usuario, now())
    RETURNING id INTO v_id;
  ELSE
    IF p_archivo NOT LIKE v_prestadora::text || '/' || p_paciente::text || '/autorizacion-%' THEN
      RAISE EXCEPTION 'archivo_invalido' USING ERRCODE = '22023';
    END IF;
    INSERT INTO autorizaciones_monitoreo_paciente
      (prestadora_id, paciente_id, metodo, estado, documento_texto, documento_verificador, documento_idioma,
       firmante_persona_id, archivo_url, cargado_por)
    VALUES
      (v_prestadora, p_paciente, 'documento_firmado_cliente', 'pendiente', v_doc.texto, v_doc.verificador, p_idioma,
       interno.firmante_autorizacion_signos_vitales(p_paciente), p_archivo, p_usuario)
    RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."registrar_autorizacion_signos_vitales_del_titular"("p_usuario" "uuid", "p_paciente" "uuid", "p_idioma" "text", "p_verificador" "text", "p_archivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."registrar_hospitalizacion"("p_paciente" "uuid", "p_institucion" "text", "p_motivo" "text", "p_fecha_inicio" "date", "p_domicilio" "jsonb", "p_forma" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_antes      text := coalesce(current_setting('careonys.lectura_de_salud', true), '');
  v_prestadora uuid;
  v_id         uuid := gen_random_uuid();
  v_d          domicilios_temporales_paciente;
  v_forma      text := coalesce(p_forma, CASE WHEN p_domicilio IS NULL THEN 'suspende' ELSE 'muda' END);
BEGIN
  SELECT p.prestadora_id INTO v_prestadora
    FROM pacientes p
   WHERE p.id = p_paciente
     AND p.prestadora_id = interno.prestadora_actual();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF nullif(btrim(coalesce(p_institucion, '')), '') IS NULL OR p_fecha_inicio IS NULL
     OR (v_forma = 'muda' AND p_domicilio IS NULL) THEN
    RAISE EXCEPTION 'falta_un_dato' USING ERRCODE = '23502';
  END IF;
  -- Tres formas: el Servicio se suspende, se muda al domicilio temporal, o sigue en el domicilio
  -- habitual porque ahí atiende a otro Paciente.
  IF v_forma NOT IN ('suspende', 'muda', 'sigue') OR (v_forma <> 'muda' AND p_domicilio IS NOT NULL) THEN
    RAISE EXCEPTION 'dato_invalido' USING ERRCODE = 'P0001';
  END IF;

  -- El identificador se arma acá y no se lee de vuelta: quien no alcanza la información de salud
  -- del Paciente puede registrar la internación, pero no leerla.
  PERFORM set_config('careonys.lectura_de_salud', 'anotada', true);
  INSERT INTO hospitalizaciones_paciente
    (id, prestadora_id, paciente_id, institucion, motivo, fecha_inicio, registrado_por, forma)
  VALUES
    (v_id, v_prestadora, p_paciente, btrim(p_institucion), nullif(btrim(coalesce(p_motivo, '')), ''),
     p_fecha_inicio, interno.usuario_de_la_sesion(), v_forma);
  PERFORM set_config('careonys.lectura_de_salud', v_antes, true);
  PERFORM interno.anotar_lo_que_se_leyo('hospitalizaciones_paciente', ARRAY[p_paciente], 'registrar_hospitalizacion');

  IF v_forma = 'muda' THEN
    v_d := jsonb_populate_record(NULL::domicilios_temporales_paciente, p_domicilio);
    INSERT INTO domicilios_temporales_paciente
      (prestadora_id, paciente_id, hospitalizacion_id, domicilio, calle, numero, piso, unidad,
       lugar_id, codigo_postal, lat, lng, motivo, fecha_inicio)
    VALUES
      (v_prestadora, p_paciente, v_id, v_d.domicilio, v_d.calle, v_d.numero, v_d.piso, v_d.unidad,
       v_d.lugar_id, v_d.codigo_postal, v_d.lat, v_d.lng, v_d.motivo, p_fecha_inicio);
  ELSIF v_forma = 'suspende' THEN
    -- Se suspende cada Servicio vigente que atiende a este Paciente.
    PERFORM interno.suspender_por_la_internacion(v_id);
  END IF;

  PERFORM interno.anotar_turnos_sin_cubrir();
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."registrar_hospitalizacion"("p_paciente" "uuid", "p_institucion" "text", "p_motivo" "text", "p_fecha_inicio" "date", "p_domicilio" "jsonb", "p_forma" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."resoluciones" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" DEFAULT "interno"."prestadora_actual"() NOT NULL,
    "tabla" "text" NOT NULL,
    "fila_id" "text" NOT NULL,
    "estado" "text" NOT NULL,
    "motivo_id" "uuid" NOT NULL,
    "detalle" "text",
    "resuelto_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "secuencia" bigint NOT NULL,
    CONSTRAINT "resoluciones_detalle_no_vacio" CHECK ((("detalle" IS NULL) OR ("length"("btrim"("detalle")) > 0))),
    CONSTRAINT "resoluciones_fila_no_vacia" CHECK (("length"("btrim"("fila_id")) > 0)),
    CONSTRAINT "resoluciones_tabla_no_vacia" CHECK (("length"("btrim"("tabla")) > 0))
);


ALTER TABLE "public"."resoluciones" OWNER TO "postgres";


COMMENT ON TABLE "public"."resoluciones" IS 'Cada decision que cambia el estado de algo, con su motivo y con quien la firmo. Es una fila nueva por decision y no se modifica ni se borra: el estado que se ve sale de la ultima.';



COMMENT ON COLUMN "public"."resoluciones"."tabla" IS 'Nombre guardado de la tabla cuya fila se resolvio.';



COMMENT ON COLUMN "public"."resoluciones"."fila_id" IS 'La llave de la fila resuelta, escrita como texto porque unas tablas la tienen uuid y otras bigint.';



COMMENT ON COLUMN "public"."resoluciones"."estado" IS 'En que estado quedo la fila resuelta. Sale del motivo elegido.';



COMMENT ON COLUMN "public"."resoluciones"."detalle" IS 'Que paso, cuando el motivo elegido lo exige. Nunca datos de salud ni de la persona atendida.';



COMMENT ON COLUMN "public"."resoluciones"."resuelto_por" IS 'Quien resolvio. Lo pone un disparador con la sesion de quien escribe, pisando lo que venga en el pedido.';



COMMENT ON COLUMN "public"."resoluciones"."secuencia" IS 'El orden de llegada, para saber cual es la ultima cuando dos resoluciones caen en la misma transaccion y comparten la hora.';



CREATE OR REPLACE FUNCTION "public"."resolver"("p_tabla" "text", "p_fila_id" "text", "p_motivo_id" "uuid", "p_detalle" "text" DEFAULT NULL::"text") RETURNS "public"."resoluciones"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'interno'
    AS $_$
DECLARE
  v_prestadora uuid;
  v_motivo     public.motivos_resolucion;
  v_fila       public.resoluciones;
  v_tocadas    integer;
BEGIN
  -- La Prestadora sale de la membresía verificada de quien inició sesión, nunca de un valor que
  -- venga en el pedido. Con la llave de servicio no hay a quién atribuirle la firma, así que no
  -- se resuelve: fallar cerrado es la respuesta.
  v_prestadora := interno.prestadora_actual();
  IF v_prestadora IS NULL THEN
    RAISE EXCEPTION 'resolucion_sin_sesion';
  END IF;

  IF coalesce(btrim(p_tabla), '') = '' OR coalesce(btrim(p_fila_id), '') = '' THEN
    RAISE EXCEPTION 'resolucion_sin_fila';
  END IF;

  -- La lectura pasa por la protección por fila del catálogo, así que un motivo de otra Prestadora
  -- no aparece y el pedido termina acá.
  SELECT m.* INTO v_motivo
    FROM public.motivos_resolucion m
   WHERE m.id = p_motivo_id
     AND m.activo
   LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'resolucion_motivo_inexistente';
  END IF;

  IF v_motivo.tabla <> btrim(p_tabla) THEN
    RAISE EXCEPTION 'resolucion_motivo_de_otra_cosa';
  END IF;

  -- Que el motivo pida detalle lo comprueba el disparador de la tabla, que es el punto único: vale
  -- igual si la fila se escribe por otra vía.

  INSERT INTO public.resoluciones
    (prestadora_id, tabla, fila_id, estado, motivo_id, detalle)
  VALUES
    (v_prestadora, v_motivo.tabla, btrim(p_fila_id), v_motivo.estado, v_motivo.id, p_detalle)
  RETURNING * INTO v_fila;

  -- Y el estado queda igual en la tabla resuelta, en esta misma transacción, para que lo que ya
  -- lee esa columna siga funcionando. El UPDATE corre con el pase de quien resuelve: si no le
  -- alcanza, no toca ninguna fila y la función se planta. Una resolución bloqueada no se informa
  -- como hecha.
  EXECUTE format(
    'UPDATE public.%I SET estado = $1 WHERE id::text = $2 AND prestadora_id = $3',
    v_motivo.tabla
  ) USING v_motivo.estado, btrim(p_fila_id), v_prestadora;

  GET DIAGNOSTICS v_tocadas = ROW_COUNT;
  IF v_tocadas = 0 THEN
    RAISE EXCEPTION 'resolucion_sin_fila';
  END IF;

  RETURN v_fila;
END;
$_$;


ALTER FUNCTION "public"."resolver"("p_tabla" "text", "p_fila_id" "text", "p_motivo_id" "uuid", "p_detalle" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolver"("p_tabla" "text", "p_fila_id" "text", "p_motivo_id" "uuid", "p_detalle" "text") IS 'Resuelve una fila: escribe la resolucion y deja el estado igual en la tabla resuelta. Es la unica puerta; escribir estado a mano no deja quien ni por que.';



CREATE OR REPLACE FUNCTION "public"."resumen_cobros_de_factura"("p_factura_id" "uuid") RETURNS TABLE("cobrado" numeric, "cobros_contados" integer, "ultimo_cobro_fecha" "date", "origenes" "text"[])
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    COALESCE(SUM(c.monto), 0)::numeric(12, 2),
    COUNT(*)::integer,
    MAX(c.fecha_cobro),
    COALESCE(ARRAY_AGG(DISTINCT c.origen ORDER BY c.origen), ARRAY[]::text[])
  FROM public.cobros_cliente c
  WHERE c.factura_id = p_factura_id
    AND c.estado = 'registrado';
$$;


ALTER FUNCTION "public"."resumen_cobros_de_factura"("p_factura_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resumen_cobros_de_factura"("p_factura_id" "uuid") IS 'Lo que entró contra una factura: cuánto, cuántas veces, cuándo fue lo último y por qué orígenes. Los cobros anulados no cuentan.';



CREATE OR REPLACE FUNCTION "public"."resumen_del_registro_de_accesos_por_persona"("p_desde" "date", "p_hasta" "date") RETURNS TABLE("usuario_id" "uuid", "persona" "text", "pacientes_distintos" integer, "accesos" integer, "accesos_de_emergencia" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
BEGIN
  IF v_prestadora IS NULL OR NOT interno.es_la_administracion_de_la_prestadora(v_prestadora) THEN
    RAISE EXCEPTION 'Sin permiso para revisar el registro de accesos' USING ERRCODE = '42501';
  END IF;
  IF p_desde IS NULL OR p_hasta IS NULL OR p_hasta < p_desde THEN
    RAISE EXCEPTION 'El período no es válido' USING ERRCODE = '22023';
  END IF;
  RETURN QUERY SELECT * FROM interno.resumen_del_registro_de_accesos_de(v_prestadora, p_desde, p_hasta);
END;
$$;


ALTER FUNCTION "public"."resumen_del_registro_de_accesos_por_persona"("p_desde" "date", "p_hasta" "date") OWNER TO "postgres";



CREATE OR REPLACE FUNCTION "public"."revisar_propuesta_de_ajuste"("p_propuesta" "uuid", "p_precio" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_prest   uuid := interno.prestadora_actual();
  v_quien   uuid := interno.usuario_de_la_sesion();
  pr        public.propuestas_de_ajuste_por_indice;
  p         public.prestaciones;
  v_precio  numeric := round(p_precio, 2);
  v_nueva   bigint;
BEGIN
  IF v_prest IS NULL OR v_quien IS NULL
     OR NOT interno.es_la_administracion_de_la_prestadora(v_prest) THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF v_precio IS NULL OR v_precio <= 0 THEN
    RAISE EXCEPTION 'dato_invalido' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO pr FROM public.propuestas_de_ajuste_por_indice
   WHERE id = p_propuesta AND prestadora_id = v_prest
   FOR UPDATE;
  IF NOT FOUND OR pr.estado <> 'pendiente' THEN
    RAISE EXCEPTION 'no_encontrado' USING ERRCODE = 'P0002';
  END IF;

  -- El mismo precio actual: no cambia nada.
  IF v_precio = pr.precio_actual THEN
    UPDATE public.propuestas_de_ajuste_por_indice
       SET estado = 'rechazada', revisada_por = v_quien, revisada_en = now()
     WHERE id = pr.id;

    INSERT INTO public.registro_actividad (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, detalle)
    VALUES (v_prest, v_quien, 'ajuste_por_indice_rechazado', 'propuestas_de_ajuste_por_indice', pr.id,
            jsonb_build_object('prestacion_id', pr.prestacion_id, 'servicio_id', pr.servicio_id,
                               'indice', pr.indice, 'precio_actual', pr.precio_actual,
                               'precio_propuesto', pr.precio_propuesto, 'moneda', pr.moneda,
                               'rige_desde', pr.rige_desde));
    RETURN;
  END IF;

  SELECT * INTO p FROM public.prestaciones
   WHERE id = pr.prestacion_id AND prestadora_id = v_prest
   FOR UPDATE;
  IF NOT FOUND OR p.estado <> 'vigente' OR p.vigente_hasta IS NOT NULL
     OR p.precio_final <> pr.precio_actual THEN
    RAISE EXCEPTION 'ya_reemplazado' USING ERRCODE = 'P0001';
  END IF;

  -- Rige desde el mes que correspondía, aunque ya haya pasado.
  v_nueva := interno.copiar_renglon('public.prestaciones', p.id, jsonb_build_object(
    'precio_final', v_precio,
    'precio_lista_snapshot', CASE WHEN p.precio_lista_snapshot IS NULL THEN NULL
                                  ELSE round(p.precio_lista_snapshot * v_precio / pr.precio_actual, 2) END,
    'precio_turno_guardia_adicional', CASE WHEN p.precio_turno_guardia_adicional IS NULL THEN NULL
                                     ELSE round(p.precio_turno_guardia_adicional * v_precio / pr.precio_actual, 2) END,
    'precio_hora_adicional', CASE WHEN p.precio_hora_adicional IS NULL THEN NULL
                                  ELSE round(p.precio_hora_adicional * v_precio / pr.precio_actual, 2) END,
    'vigente_desde', pr.rige_desde,
    'vigente_hasta', NULL,
    'requiere_revision', false,
    'prestacion_anterior_id', p.id
  ));

  UPDATE public.propuestas_de_ajuste_por_indice
     SET estado = 'aceptada', revisada_por = v_quien, revisada_en = now(), prestacion_nueva_id = v_nueva
   WHERE id = pr.id;

  INSERT INTO public.registro_actividad (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, detalle)
  VALUES (v_prest, v_quien, 'ajuste_por_indice_aceptado', 'propuestas_de_ajuste_por_indice', pr.id,
          jsonb_build_object('prestacion_id', p.id, 'prestacion_nueva_id', v_nueva,
                             'servicio_id', pr.servicio_id, 'indice', pr.indice,
                             'precio_anterior', pr.precio_actual, 'precio_propuesto', pr.precio_propuesto,
                             'precio_nuevo', v_precio, 'moneda', pr.moneda, 'rige_desde', pr.rige_desde));
END;
$$;


ALTER FUNCTION "public"."revisar_propuesta_de_ajuste"("p_propuesta" "uuid", "p_precio" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revisar_apoderado"("p_id" "uuid", "p_aprobar" boolean, "p_motivo" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
BEGIN
  IF v_prestadora IS NULL OR NOT interno.es_la_administracion_de_la_prestadora(v_prestadora) THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF NOT COALESCE(p_aprobar, false) AND btrim(COALESCE(p_motivo, '')) = '' THEN
    RAISE EXCEPTION 'falta_el_motivo' USING ERRCODE = '22023';
  END IF;

  UPDATE apoderados
     SET estado = CASE WHEN p_aprobar THEN 'aprobado' ELSE 'observado' END,
         motivo_observacion = CASE WHEN p_aprobar THEN NULL ELSE btrim(p_motivo) END,
         revisado_por = auth.uid(),
         revisado_at = now()
   WHERE id = p_id
     AND prestadora_id = v_prestadora
     AND quitado_en IS NULL
     AND estado = 'en_revision';
  RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."revisar_apoderado"("p_id" "uuid", "p_aprobar" boolean, "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revisar_autorizacion_signos_vitales"("p_autorizacion" "uuid", "p_estado" "text", "p_motivo" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_quien uuid := auth.uid();
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
BEGIN
  IF v_quien IS NULL OR NOT interno.es_personal_de_la_prestadora() THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF p_estado NOT IN ('aceptada', 'rechazada') THEN
    RAISE EXCEPTION 'estado_invalido' USING ERRCODE = '22023';
  END IF;
  IF p_estado = 'rechazada' AND v_motivo IS NULL THEN
    RAISE EXCEPTION 'falta_el_motivo' USING ERRCODE = '22023';
  END IF;

  UPDATE autorizaciones_monitoreo_paciente a
     SET estado = p_estado,
         motivo_rechazo = CASE WHEN p_estado = 'rechazada' THEN v_motivo END,
         revisado_por = v_quien,
         revisado_en = now()
   WHERE a.id = p_autorizacion
     AND a.prestadora_id = interno.prestadora_actual()
     AND a.estado = 'pendiente'
     AND interno.alcanza_la_informacion_de_salud(a.paciente_id);
  RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."revisar_autorizacion_signos_vitales"("p_autorizacion" "uuid", "p_estado" "text", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revisar_carga"("p_carga" "uuid", "p_acepta" boolean, "p_motivo" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_quien  uuid := auth.uid();
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_carga  cargas_sujetas_a_aprobacion;
  v_admin  boolean := interno.es_superadmin() OR interno.es_admin_prestadora();
BEGIN
  IF v_quien IS NULL OR p_acepta IS NULL THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_carga
    FROM cargas_sujetas_a_aprobacion c
   WHERE c.id = p_carga
     AND c.prestadora_id = interno.prestadora_actual()
     AND c.estado = 'pendiente'
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN false;
  END IF;

  IF NOT (v_admin OR interno.coordina_al_paciente(v_carga.paciente_id)) THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF v_carga.tabla = 'informacion_de_salud_del_paciente'
     AND (NOT interno.alcanza_la_informacion_de_salud(v_carga.paciente_id)
          OR NOT (v_admin OR interno.tiene_permiso('editar_datos_paciente'))) THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;

  IF NOT p_acepta THEN
    IF v_motivo IS NULL THEN
      RAISE EXCEPTION 'falta_el_motivo' USING ERRCODE = 'P0001';
    END IF;
    UPDATE cargas_sujetas_a_aprobacion
       SET estado = 'rechazada', motivo_rechazo = v_motivo, revisado_por = v_quien, revisado_en = now()
     WHERE id = v_carga.id;
    RETURN true;
  END IF;

  IF v_carga.tabla = 'informacion_de_salud_del_paciente' THEN
    IF EXISTS (SELECT 1 FROM informacion_de_salud_del_paciente s WHERE s.paciente_id = v_carga.paciente_id) THEN
      UPDATE informacion_de_salud_del_paciente t
         SET (patologias, nivel_complejidad, nota_aclaratoria, updated_at) =
             (SELECT r.patologias, r.nivel_complejidad, r.nota_aclaratoria, now()
                FROM jsonb_populate_record(t, v_carga.datos) r)
       WHERE t.paciente_id = v_carga.paciente_id;
    ELSE
      INSERT INTO informacion_de_salud_del_paciente (prestadora_id, paciente_id, patologias, nivel_complejidad, nota_aclaratoria)
      SELECT v_carga.prestadora_id, v_carga.paciente_id, coalesce(r.patologias, '{}'), r.nivel_complejidad, r.nota_aclaratoria
        FROM jsonb_populate_record(NULL::informacion_de_salud_del_paciente, v_carga.datos) r;
    END IF;
  ELSIF v_carga.operacion = 'alta' THEN
    INSERT INTO domicilios_temporales_paciente
      (prestadora_id, paciente_id, domicilio, lat, lng, motivo, fecha_inicio, fecha_fin,
       calle, numero, piso, unidad, lugar_id, codigo_postal)
    SELECT v_carga.prestadora_id, v_carga.paciente_id, r.domicilio, r.lat, r.lng, r.motivo, r.fecha_inicio,
           r.fecha_fin, r.calle, r.numero, r.piso, r.unidad, r.lugar_id, r.codigo_postal
      FROM jsonb_populate_record(NULL::domicilios_temporales_paciente, v_carga.datos) r;
  ELSE
    UPDATE domicilios_temporales_paciente t
       SET (domicilio, lat, lng, motivo, fecha_inicio, fecha_fin, calle, numero, piso, unidad, lugar_id, codigo_postal) =
           (SELECT r.domicilio, r.lat, r.lng, r.motivo, r.fecha_inicio, r.fecha_fin, r.calle, r.numero,
                   r.piso, r.unidad, r.lugar_id, r.codigo_postal
              FROM jsonb_populate_record(t, v_carga.datos) r)
     WHERE t.id = v_carga.registro_id
       AND t.paciente_id = v_carga.paciente_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'la_fila_ya_no_existe' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  UPDATE cargas_sujetas_a_aprobacion
     SET estado = 'aceptada', revisado_por = v_quien, revisado_en = now()
   WHERE id = v_carga.id;
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."revisar_carga"("p_carga" "uuid", "p_acepta" boolean, "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revisar_indicacion_medicacion"("p_indicacion" "uuid", "p_estado" "text", "p_motivo" "text", "p_motivo_clave" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'interno'
    AS $$
DECLARE
  v_quien uuid := auth.uid();
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
BEGIN
  IF v_quien IS NULL OR NOT interno.es_personal_de_la_prestadora() THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF p_estado NOT IN ('aceptada', 'rechazada') THEN
    RAISE EXCEPTION 'estado_invalido' USING ERRCODE = '22023';
  END IF;
  IF p_estado = 'rechazada' AND v_motivo IS NULL AND p_motivo_clave IS NULL THEN
    RAISE EXCEPTION 'falta_el_motivo' USING ERRCODE = '22023';
  END IF;

  UPDATE indicaciones_medicacion i
     SET estado = p_estado,
         motivo_rechazo = CASE WHEN p_estado = 'rechazada' AND p_motivo_clave IS NULL THEN v_motivo END,
         motivo_rechazo_clave = CASE WHEN p_estado = 'rechazada' THEN p_motivo_clave END,
         revisado_por = v_quien,
         revisado_en = now()
   WHERE i.id = p_indicacion
     AND i.prestadora_id = interno.prestadora_actual()
     AND i.estado = 'pendiente'
     AND interno.alcanza_la_informacion_de_salud(i.paciente_id);
  RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."revisar_indicacion_medicacion"("p_indicacion" "uuid", "p_estado" "text", "p_motivo" "text", "p_motivo_clave" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION public.cerrar_turno_guardia(
  p_turno_guardia uuid,
  p_hora timestamp with time zone,
  p_reporte_atrasado boolean,
  p_motivo uuid DEFAULT NULL,
  p_detalle text DEFAULT NULL,
  p_cerrada_por uuid DEFAULT NULL,
  p_lat double precision DEFAULT NULL,
  p_lng double precision DEFAULT NULL
)
 RETURNS text
 LANGUAGE sql
 SECURITY INVOKER
 SET search_path TO 'public', 'interno'
AS $$
  SELECT interno.cerrar_el_turno_guardia(
    p_turno_guardia, p_hora, p_reporte_atrasado, p_motivo, p_detalle, p_cerrada_por, p_lat, p_lng, false
  );
$$;

ALTER FUNCTION public.cerrar_turno_guardia(uuid, timestamp with time zone, boolean, uuid, text, uuid, double precision, double precision) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.cerrar_turno_guardia(uuid, timestamp with time zone, boolean, uuid, text, uuid, double precision, double precision) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.cerrar_turno_guardia(uuid, timestamp with time zone, boolean, uuid, text, uuid, double precision, double precision) TO authenticated, trabajo_sin_persona, service_role;

COMMENT ON FUNCTION public.cerrar_turno_guardia(uuid, timestamp with time zone, boolean, uuid, text, uuid, double precision, double precision) IS 'Cierra un turno de guardia empezado. Resuelve la Prestadora adentro, corre con los permisos de quien llama y devuelve el estado en que quedó.';


CREATE OR REPLACE FUNCTION public.permitir_que_el_paciente_quede_solo(
  p_turno_guardia uuid,
  p_paciente uuid,
  p_quien text,
  p_medio text,
  p_desde timestamp with time zone,
  p_hasta timestamp with time zone,
  p_nota text,
  p_reporte_atrasado boolean
)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY INVOKER
 SET search_path TO 'public', 'interno'
AS $$
DECLARE
  v_prestadora uuid := interno.prestadora_actual();
  v_yo uuid := interno.usuario_de_la_sesion();
  v_motivo uuid;
  v_checkin timestamp with time zone;
  v_id uuid;
BEGIN
  IF v_prestadora IS NULL OR v_yo IS NULL
     OR NOT interno.es_personal_de_la_prestadora()
     OR NOT (interno.es_superadmin()
             OR interno.es_admin_prestadora()
             OR interno.coordina_el_servicio_del_turno_guardia(p_turno_guardia)) THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;

  SELECT m.id INTO v_motivo
    FROM motivos_cierre_turno_guardia m
   WHERE m.prestadora_id = v_prestadora
     AND m.clave = 'paciente_solo_con_permiso'
     AND m.activo;
  IF v_motivo IS NULL THEN
    RAISE EXCEPTION 'motivo_de_salida_inexistente' USING ERRCODE = 'P0001';
  END IF;

  SELECT g.checkin_at INTO v_checkin
    FROM turnos_guardia g
   WHERE g.id = p_turno_guardia
     AND g.prestadora_id = v_prestadora;

  PERFORM set_config('careonys.cierre_por_la_funcion', 'si', true);
  INSERT INTO consentimientos_paciente_solo
    (prestadora_id, turno_guardia_id, paciente_id, quien_consintio, medio, desde_at, hasta_at, registrado_por, nota)
  VALUES
    (v_prestadora, p_turno_guardia, p_paciente, btrim(COALESCE(p_quien, '')), p_medio, p_desde, p_hasta, v_yo,
     NULLIF(btrim(COALESCE(p_nota, '')), ''))
  RETURNING id INTO v_id;

  -- El turno de guardia se cierra a la hora desde la que el Paciente quedó solo, que no puede
  -- ser antes de la llegada del Asistente ni después de este momento.
  PERFORM interno.cerrar_el_turno_guardia(
    p_turno_guardia,
    GREATEST(COALESCE(v_checkin, '-infinity'::timestamptz), LEAST(p_desde, now())),
    p_reporte_atrasado, v_motivo, NULL, NULL, NULL, NULL, true
  );

  RETURN v_id;
END;
$$;

ALTER FUNCTION public.permitir_que_el_paciente_quede_solo(uuid, uuid, text, text, timestamp with time zone, timestamp with time zone, text, boolean) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.permitir_que_el_paciente_quede_solo(uuid, uuid, text, text, timestamp with time zone, timestamp with time zone, text, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.permitir_que_el_paciente_quede_solo(uuid, uuid, text, text, timestamp with time zone, timestamp with time zone, text, boolean) TO authenticated, service_role;

COMMENT ON FUNCTION public.permitir_que_el_paciente_quede_solo(uuid, uuid, text, text, timestamp with time zone, timestamp with time zone, text, boolean) IS 'Guarda el permiso del Cliente para que el Paciente quede solo y cierra, en la misma operación, el turno de guardia del Asistente que se fue. Sólo el Administrador o el Coordinador de ese Servicio.';


CREATE OR REPLACE FUNCTION "public"."sembrar_configuracion_prestadora"("p_prestadora_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_tabla TEXT;
BEGIN
  IF NOT interno.le_corresponde(p_prestadora_id) THEN
    RAISE EXCEPTION 'sembrar_configuracion_prestadora: esa Prestadora no es la de quien llama';
  END IF;

  -- La fila de los datos de contacto, que ya no lleva el nombre: el de la Prestadora vive en
  -- `prestadoras.nombre_fantasia`, y uno solo.
  INSERT INTO configuracion_prestadora (prestadora_id)
  VALUES (p_prestadora_id)
  ON CONFLICT (prestadora_id) DO NOTHING;

  FOR v_tabla IN
    SELECT c.relname
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    JOIN pg_constraint pk ON pk.conrelid = c.oid AND pk.contype = 'p'
    JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum = pk.conkey[1]
    WHERE n.nspname = 'public'
      AND c.relkind = 'r'
      AND c.relname LIKE 'configuracion\_%'
      AND c.relname <> 'configuracion_prestadora'
      AND array_length(pk.conkey, 1) = 1
      AND a.attname = 'prestadora_id'
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format(
        'INSERT INTO public.%I (prestadora_id) VALUES ($1) ON CONFLICT DO NOTHING',
        v_tabla
      ) USING p_prestadora_id;
    EXCEPTION WHEN not_null_violation THEN
      RAISE EXCEPTION
        'No se puede sembrar la configuración de la Prestadora: la tabla % tiene una columna obligatoria sin valor de arranque. Póngale un DEFAULT a esa columna, o sáquele la forma de una fila por Prestadora.',
        v_tabla;
    END;
  END LOOP;

  -- Los motivos de cierre con los que arranca. De acá en adelante la lista es de ella: los
  -- puede sacar, apagar, y agregar los suyos.
  INSERT INTO motivos_cierre_servicio (prestadora_id, clave, pide_detalle, orden)
  VALUES
    (p_prestadora_id, 'fin_demanda',           false, 10),
    (p_prestadora_id, 'fallecimiento',         false, 20),
    (p_prestadora_id, 'internacion',           false, 30),
    (p_prestadora_id, 'baja_del_cliente',    false, 40),
    (p_prestadora_id, 'corte_de_pago',         false, 50),
    (p_prestadora_id, 'mudanza_fuera_de_zona', false, 60),
    (p_prestadora_id, 'otro',                  true,  99)
  ON CONFLICT DO NOTHING;

  -- Y las causas de sustitución, con el mismo criterio.
  INSERT INTO motivos_sustitucion_turno_guardia (prestadora_id, clave, pide_detalle, orden)
  VALUES
    (p_prestadora_id, 'emergencia', false, 10),
    (p_prestadora_id, 'otro',       true,  99)
  ON CONFLICT DO NOTHING;

  -- Y cómo puede terminar un turno que quedó sin nadie. Los dos primeros los escribe el motor
  -- cuando la base ya lo dice; los demás los elige quien coordina.
  INSERT INTO finales_turno_guardia_sin_cubrir
    (prestadora_id, clave, es_defecto_grave, pide_detalle, lo_escribe_el_sistema, orden)
  VALUES
    (p_prestadora_id, 'llego_un_relevo',               false, false, true,  10),
    (p_prestadora_id, 'ya_no_hacia_falta',             false, false, true,  20),
    (p_prestadora_id, 'lo_cubrio_la_coordinadora',     false, false, false, 30),
    (p_prestadora_id, 'se_extendio_el_turno_guardia',          false, false, false, 40),
    (p_prestadora_id, 'quedo_solo_con_consentimiento', true,  false, false, 50),
    (p_prestadora_id, 'no_fue_nadie',                  true,  false, false, 60),
    (p_prestadora_id, 'se_resolvio_de_otra_manera',    false, true,  false, 99)
  ON CONFLICT DO NOTHING;

  -- Y por qué se cierra un turno de guardia desde el Panel. El del Paciente solo lo escribe la
  -- base cuando se da ese permiso; los demás los elige quien cierra.
  INSERT INTO motivos_cierre_turno_guardia
    (prestadora_id, clave, pide_detalle, lo_escribe_el_sistema, orden)
  VALUES
    (p_prestadora_id, 'fallo_el_telefono_del_asistente',  false, false, 10),
    (p_prestadora_id, 'fallo_la_ubicacion_del_asistente', false, false, 20),
    (p_prestadora_id, 'lo_cubrio_el_coordinador',         false, false, 30),
    (p_prestadora_id, 'se_olvido_de_marcar_la_salida',    false, false, 40),
    (p_prestadora_id, 'paciente_solo_con_permiso',        false, true,  50),
    (p_prestadora_id, 'otro',                             true,  false, 99)
  ON CONFLICT DO NOTHING;

  -- Y los motivos con los que se resuelve una postulación o una Guardia. La lista la arma
  -- `sembrar_motivos_resolucion`, que sigue siendo el punto único: acá se la llama, no se la copia.
  PERFORM sembrar_motivos_resolucion(p_prestadora_id);
END;
$_$;


ALTER FUNCTION "public"."sembrar_configuracion_prestadora"("p_prestadora_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sembrar_motivos_resolucion"("p_prestadora_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into motivos_resolucion
    (prestadora_id, tabla, estado, nombre_es_ar, nombre_en, nombre_pt_br, pide_detalle, orden)
  values
    -- Postulaciones.
    (p_prestadora_id, 'postulaciones', 'en_revision',
     'Pasa a revisión', 'Moves to review', 'Passa para análise', false, 10),
    (p_prestadora_id, 'postulaciones', 'aprobado',
     'Reúne lo que el puesto pide', 'Meets what the role requires', 'Atende ao que a vaga exige', false, 20),
    (p_prestadora_id, 'postulaciones', 'rechazado',
     'No reúne la experiencia pedida', 'Does not have the required experience', 'Não tem a experiência exigida', false, 30),
    (p_prestadora_id, 'postulaciones', 'rechazado',
     'Queda fuera de las zonas cubiertas', 'Outside the areas covered', 'Fora das áreas atendidas', false, 40),
    (p_prestadora_id, 'postulaciones', 'rechazado',
     'No se presentó a la entrevista', 'Did not attend the interview', 'Não compareceu à entrevista', false, 50),
    (p_prestadora_id, 'postulaciones', 'rechazado',
     'Pidió retirar su postulación', 'Asked to withdraw the application', 'Pediu para retirar a candidatura', false, 60),
    (p_prestadora_id, 'postulaciones', 'rechazado',
     'Otro motivo', 'Other reason', 'Outro motivo', true, 99),
    -- Guardias. Por ahora sólo las canceladas: es la decisión que se toma mirando la Guardia y que
    -- hasta hoy no dejaba rastro. La llegada y la salida las escribe el motor cuando pasan, y no
    -- se resuelven con un motivo porque no son una decisión sino un hecho.
    (p_prestadora_id, 'turnos_guardia', 'cancelada',
     'El Cliente la dio de baja', 'The Client cancelled it', 'O Cliente cancelou', false, 10),
    (p_prestadora_id, 'turnos_guardia', 'cancelada',
     'El Paciente quedó internado', 'The Patient was admitted to hospital', 'O Paciente ficou internado', false, 20),
    (p_prestadora_id, 'turnos_guardia', 'cancelada',
     'No se consiguió quién la cubriera', 'Nobody could be found to cover it', 'Não foi possível encontrar quem cobrisse', false, 30),
    (p_prestadora_id, 'turnos_guardia', 'cancelada',
     'Terminó el Servicio', 'The Service ended', 'O Serviço terminou', false, 40),
    (p_prestadora_id, 'turnos_guardia', 'cancelada',
     'Se había cargado por error', 'It had been entered by mistake', 'Tinha sido cadastrado por engano', false, 50),
    (p_prestadora_id, 'turnos_guardia', 'cancelada',
     'Otro motivo', 'Other reason', 'Outro motivo', true, 99),
    -- Por qué un Asistente rechaza el turno que se le asignó.
    (p_prestadora_id, 'asignaciones_de_turno_guardia', 'rechazada',
     'Problema de salud', 'Health problem', 'Problema de saúde', false, 10),
    (p_prestadora_id, 'asignaciones_de_turno_guardia', 'rechazada',
     'Compromiso personal o familiar', 'Personal or family commitment', 'Compromisso pessoal ou familiar', false, 20),
    (p_prestadora_id, 'asignaciones_de_turno_guardia', 'rechazada',
     'Viaje o ausencia', 'Travel or absence', 'Viagem ou ausência', false, 30),
    (p_prestadora_id, 'asignaciones_de_turno_guardia', 'rechazada',
     'Distancia al domicilio', 'Distance to the home', 'Distância até o domicílio', false, 40),
    (p_prestadora_id, 'asignaciones_de_turno_guardia', 'rechazada',
     'Otro', 'Other', 'Outro', true, 99),
    -- Por qué se pausa la cobertura: una interrupción breve, con día de vuelta.
    (p_prestadora_id, 'interrupciones_de_cobertura', 'pausa',
     'Vacaciones o viaje del Paciente', 'Patient holiday or trip', 'Férias ou viagem do Paciente', false, 10),
    (p_prestadora_id, 'interrupciones_de_cobertura', 'pausa',
     'Un familiar se ocupa del Paciente', 'A relative is looking after the Patient', 'Um familiar cuida do Paciente', false, 20),
    (p_prestadora_id, 'interrupciones_de_cobertura', 'pausa',
     'Pedido del Cliente', 'Client request', 'Pedido do Cliente', false, 30),
    (p_prestadora_id, 'interrupciones_de_cobertura', 'pausa',
     'Otro motivo', 'Other reason', 'Outro motivo', true, 99),
    -- Por qué se suspende la cobertura: una interrupción larga o sin día de vuelta.
    (p_prestadora_id, 'interrupciones_de_cobertura', 'suspension',
     'Pedido del Cliente', 'Client request', 'Pedido do Cliente', false, 10),
    (p_prestadora_id, 'interrupciones_de_cobertura', 'suspension',
     'Cambio de planes del Cliente', 'Change of plans by the Client', 'Mudança de planos do Cliente', false, 20),
    (p_prestadora_id, 'interrupciones_de_cobertura', 'suspension',
     'Atraso en los pagos', 'Late payments', 'Atraso nos pagamentos', false, 30),
    (p_prestadora_id, 'interrupciones_de_cobertura', 'suspension',
     'A la espera de una decisión', 'Awaiting a decision', 'Aguardando uma decisão', false, 40),
    (p_prestadora_id, 'interrupciones_de_cobertura', 'suspension',
     'Otro motivo', 'Other reason', 'Outro motivo', true, 99),
    -- Por qué se cancela, desde una fecha, un turno de guardia recurrente o una Prestación.
    (p_prestadora_id, 'interrupciones_de_cobertura', 'cancelacion',
     'El Cliente lo dio de baja', 'The Client cancelled it', 'O Cliente cancelou', false, 10),
    (p_prestadora_id, 'interrupciones_de_cobertura', 'cancelacion',
     'Cambió el cronograma del Paciente', 'The Patient schedule changed', 'O cronograma do Paciente mudou', false, 20),
    (p_prestadora_id, 'interrupciones_de_cobertura', 'cancelacion',
     'Terminó la atención', 'The care ended', 'O atendimento terminou', false, 30),
    (p_prestadora_id, 'interrupciones_de_cobertura', 'cancelacion',
     'Se había cargado por error', 'It had been entered by mistake', 'Tinha sido cadastrado por engano', false, 40),
    (p_prestadora_id, 'interrupciones_de_cobertura', 'cancelacion',
     'Otro motivo', 'Other reason', 'Outro motivo', true, 99)
  on conflict do nothing;
end;
$$;


ALTER FUNCTION "public"."sembrar_motivos_resolucion"("p_prestadora_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sembrar_motivos_resolucion"("p_prestadora_id" "uuid") IS 'Carga los motivos de resolucion que trae el producto para una Prestadora. No pisa ninguno: lo que ella ya edito queda como esta.';



CREATE OR REPLACE FUNCTION "public"."servicios_que_coordino"() RETURNS "uuid"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'interno'
    AS $$
  SELECT coalesce(array_agg(s.id), '{}'::uuid[])
    FROM servicios s
   WHERE s.prestadora_id = interno.prestadora_actual()
     AND s.coordinador_id = ANY (interno.coordinadores_que_represento());
$$;


ALTER FUNCTION "public"."servicios_que_coordino"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sincronizar_paciente_principal_de_turno_guardia"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.paciente_id IS DISTINCT FROM NEW.paciente_id THEN
    DELETE FROM turno_guardia_pacientes
    WHERE turno_guardia_id = NEW.id AND paciente_id = OLD.paciente_id;
  END IF;

  IF NEW.paciente_id IS NOT NULL THEN
    INSERT INTO turno_guardia_pacientes (turno_guardia_id, paciente_id, prestadora_id)
    VALUES (NEW.id, NEW.paciente_id, NEW.prestadora_id)
    ON CONFLICT (turno_guardia_id, paciente_id) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sincronizar_paciente_principal_de_turno_guardia"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sincronizar_paciente_principal_de_turno_guardia"() IS 'Puente temporal: mantiene en turno_guardia_pacientes al Paciente escrito en la columna vieja turnos_guardia.paciente_id. Se borra junto con esa columna.';



CREATE OR REPLACE FUNCTION "public"."sincronizar_paciente_principal_de_serie"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.paciente_id IS DISTINCT FROM NEW.paciente_id THEN
    DELETE FROM series_turnos_guardia_pacientes
    WHERE serie_id = NEW.id AND paciente_id = OLD.paciente_id;
  END IF;

  IF NEW.paciente_id IS NOT NULL THEN
    INSERT INTO series_turnos_guardia_pacientes (serie_id, paciente_id, prestadora_id)
    VALUES (NEW.id, NEW.paciente_id, NEW.prestadora_id)
    ON CONFLICT (serie_id, paciente_id) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sincronizar_paciente_principal_de_serie"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sincronizar_paciente_principal_de_serie"() IS 'Puente temporal: mantiene en series_turnos_guardia_pacientes al Paciente escrito en la columna vieja series_turnos_guardia.paciente_id. Se borra junto con esa columna.';



CREATE OR REPLACE FUNCTION "public"."sumar_contactos_al_saldo"("p_acceso_id" "uuid", "p_cuantos" integer) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_saldo integer;
BEGIN
  IF p_cuantos IS NULL OR p_cuantos <= 0 THEN
    RAISE EXCEPTION 'sumar_contactos_al_saldo: se suman contactos, no cero ni menos';
  END IF;

  -- En una sola sentencia. Un saldo vacío es un acceso que todavía no se sostenía por saldo: la
  -- primera carga lo estrena, y de ahí en más se le suma lo de cada compra.
  UPDATE public.accesos_intermediacion
     SET saldo_contactos = COALESCE(saldo_contactos, 0) + p_cuantos,
         updated_at = now()
   WHERE id = p_acceso_id
  RETURNING saldo_contactos INTO v_saldo;

  -- Sin fila, queda nulo. Se devuelve así: quien llama tiene que poder distinguir «no había qué
  -- cargar» de «quedó en cero», que no son lo mismo.
  RETURN v_saldo;
END;
$$;


ALTER FUNCTION "public"."sumar_contactos_al_saldo"("p_acceso_id" "uuid", "p_cuantos" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sumar_contactos_al_saldo"("p_acceso_id" "uuid", "p_cuantos" integer) IS 'Le suma contactos al saldo de un acceso y devuelve con cuántos queda. Se llama cuando entra la plata de un paquete. Suma y no pisa: el paquete no vence por calendario, así que lo que quedó sin usar sigue estando.';



CREATE OR REPLACE FUNCTION "public"."sumar_intento_de_codigo"("p_tabla" "text", "p_id" "uuid", "p_prestadora_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_intentos integer;
BEGIN
  -- Falla cerrado: sin Prestadora no se cuenta nada.
  IF p_prestadora_id IS NULL THEN
    RAISE EXCEPTION 'sumar_intento_de_codigo: falta la Prestadora';
  END IF;

  IF p_tabla = 'instrucciones_acceso_personas_autorizadas' THEN
    UPDATE public.instrucciones_acceso_personas_autorizadas
       SET codigo_intentos = codigo_intentos + 1
     WHERE id = p_id
       AND prestadora_id = p_prestadora_id
    RETURNING codigo_intentos INTO v_intentos;

  ELSIF p_tabla = 'codigos_al_telefono' THEN
    UPDATE public.codigos_al_telefono
       SET codigo_intentos = codigo_intentos + 1
     WHERE id = p_id
       AND prestadora_id = p_prestadora_id
    RETURNING codigo_intentos INTO v_intentos;

  ELSE
    RAISE EXCEPTION 'sumar_intento_de_codigo: esa tabla no lleva cuenta de intentos';
  END IF;

  -- Si no se actualizó ninguna fila, `v_intentos` queda nulo. Se devuelve así a propósito: quien
  -- llama trata el nulo como "se agotaron", que es lo que corresponde cuando no se pudo contar.
  RETURN v_intentos;
END;
$$;


ALTER FUNCTION "public"."sumar_intento_de_codigo"("p_tabla" "text", "p_id" "uuid", "p_prestadora_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tiene_permiso_de"("p_usuario" "uuid", "p_accion" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rol           TEXT;
  v_prestadora_id UUID;
  v_cfg           permisos_prestadora;
  v_solo_admin    BOOLEAN;
BEGIN
  SELECT rol, prestadora_id INTO v_rol, v_prestadora_id FROM usuarios WHERE id = p_usuario;

  IF v_rol IN ('admin_prestadora', 'superadmin') THEN
    RETURN TRUE;
  END IF;
  IF v_rol IS DISTINCT FROM 'coordinador' THEN
    RETURN FALSE;
  END IF;

  SELECT * INTO v_cfg FROM permisos_prestadora
    WHERE prestadora_id = v_prestadora_id AND accion = p_accion;

  -- La Prestadora no configuró nada para esta acción: manda el valor por defecto del
  -- catálogo. Si la acción ni siquiera está en el catálogo, la respuesta es que no: un
  -- nombre mal escrito no puede terminar abriendo un permiso.
  IF NOT FOUND THEN
    SELECT default_solo_admin INTO v_solo_admin
      FROM catalogo_acciones_permisos WHERE accion = p_accion;
    RETURN NOT COALESCE(v_solo_admin, TRUE);
  END IF;

  IF p_usuario = ANY(v_cfg.excepciones_denegar)  THEN RETURN FALSE; END IF;
  IF p_usuario = ANY(v_cfg.excepciones_permitir) THEN RETURN TRUE;  END IF;
  RETURN v_cfg.alcance = 'admin_y_coordinador';
END;
$$;


ALTER FUNCTION "public"."tiene_permiso_de"("p_usuario" "uuid", "p_accion" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."tiene_permiso_de"("p_usuario" "uuid", "p_accion" "text") IS 'Si un usuario tiene permitida una acción. Único lugar donde está programada esa decisión: la usan las reglas de acceso de la base y también el motor (pendiente #127).';



