CREATE TABLE IF NOT EXISTS "public"."alarmas_tomadas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "tipo" "text" NOT NULL,
    "referencia_id" "uuid" NOT NULL,
    "tomada_por" "uuid" NOT NULL,
    "tomada_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "vence_at" timestamp with time zone NOT NULL,
    "soltada_at" timestamp with time zone,
    "nota" "text",
    CONSTRAINT "alarmas_tomadas_tipo_conocido" CHECK (("tipo" = ANY (ARRAY['alerta_temprana_turno_guardia'::"text", 'incidente_relevo'::"text", 'turno_guardia_sin_cerrar'::"text", 'incidente_turno_guardia_sin_cubrir'::"text", 'emergencia_turno_guardia'::"text"]))),
    CONSTRAINT "alarmas_tomadas_vence_despues_de_tomarse" CHECK (("vence_at" > "tomada_at"))
);


ALTER TABLE "public"."alarmas_tomadas" OWNER TO "postgres";


COMMENT ON TABLE "public"."alarmas_tomadas" IS 'Quien se hizo cargo de una alarma y hasta cuando. Mientras la toma esta en pie el proceso de fondo no insiste con esa alarma. Tomarla no la resuelve.';



COMMENT ON COLUMN "public"."alarmas_tomadas"."referencia_id" IS 'La fila alarmada. La tabla a la que apunta depende del tipo: no hay clave foranea posible.';



COMMENT ON COLUMN "public"."alarmas_tomadas"."vence_at" IS 'Cuando vuelve la alarma si el problema sigue abierto. Cuanto dura la toma lo decide cada Prestadora; el valor de fabrica vive en panel/src/lib/alarmasTomadas.js.';



COMMENT ON COLUMN "public"."alarmas_tomadas"."nota" IS 'Lo que quien la tomo dejo escrito. Nunca datos de salud ni de la persona atendida.';



CREATE OR REPLACE VIEW "public"."alarmas_tomadas_quien_la_tomo" WITH ("security_invoker"='true') AS
 SELECT "id",
    "prestadora_id",
    "tipo",
    "referencia_id",
    "tomada_por",
    "tomada_at",
    "vence_at",
    "soltada_at",
    "nota",
    "interno"."nombre_de_usuario"("tomada_por") AS "tomada_por_nombre"
   FROM "public"."alarmas_tomadas" "a";


ALTER VIEW "public"."alarmas_tomadas_quien_la_tomo" OWNER TO "postgres";


COMMENT ON VIEW "public"."alarmas_tomadas_quien_la_tomo" IS 'Las tomas de alarma con el nombre de quien la tomo ya resuelto. Muestra exactamente las mismas filas que alarmas_tomadas: lo unico que agrega es el nombre. Para escribir se usa la tabla.';



CREATE TABLE IF NOT EXISTS "public"."alertas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "paciente_id" "uuid" NOT NULL,
    "nivel" "text" NOT NULL,
    "descripcion" "text",
    "detalle_coordinador" "text",
    "campos_preocupantes" "text"[],
    "resuelta" boolean DEFAULT false NOT NULL,
    "resuelta_por" "uuid",
    "resuelta_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "reportes_relacionados" "uuid"[],
    CONSTRAINT "alertas_nivel_check" CHECK (("nivel" = ANY (ARRAY['verde'::"text", 'amarilla'::"text", 'roja'::"text"])))
);


ALTER TABLE "public"."alertas" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."alertas_tempranas_turno_guardia" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "turno_guardia_id" "uuid" NOT NULL,
    "fuente" "text" NOT NULL,
    "motivo" "text",
    "reportado_por" "uuid",
    "detectado_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resuelto_at" timestamp with time zone,
    "resuelto_nota" "text",
    "ultima_notificacion_at" timestamp with time zone,
    "veces_notificado" integer DEFAULT 0 NOT NULL,
    "backup_notificado_at" timestamp with time zone
);


ALTER TABLE "public"."alertas_tempranas_turno_guardia" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."apoderados" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "cliente_id" "uuid" NOT NULL,
    "funcion" "text" NOT NULL,
    "persona_id" "uuid" NOT NULL,
    "archivo_url" "text",
    "estado" "text" DEFAULT 'en_revision'::"text" NOT NULL,
    "motivo_observacion" "text",
    "revisado_por" "uuid",
    "revisado_at" timestamp with time zone,
    "cargado_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "quitado_en" timestamp with time zone,
    "quitado_por" "uuid",
    CONSTRAINT "apoderados_estado_check" CHECK (("estado" = ANY (ARRAY['falta'::"text", 'en_revision'::"text", 'aprobado'::"text", 'observado'::"text"]))),
    CONSTRAINT "apoderados_funcion_check" CHECK (("funcion" = ANY (ARRAY['pagos'::"text", 'signos_vitales'::"text"]))),
    CONSTRAINT "apoderados_observado_con_motivo" CHECK ((("estado" <> 'observado'::"text") OR ("btrim"(COALESCE("motivo_observacion", ''::"text")) <> ''::"text"))),
    CONSTRAINT "apoderados_sin_poder_solo_si_falta" CHECK ((("estado" = 'falta'::"text") OR ("archivo_url" IS NOT NULL)))
);


ALTER TABLE "public"."apoderados" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."asignaciones_de_turno_guardia" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "turno_guardia_id" "uuid",
    "asistente_id" "uuid" NOT NULL,
    "asignado_por" "uuid",
    "asignado_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "estado" "text" DEFAULT 'sin_responder'::"text" NOT NULL,
    "respondida_at" timestamp with time zone,
    "retirada_at" timestamp with time zone,
    "retirada_por" "uuid",
    "asistente_anterior_id" "uuid",
    "serie_id" "uuid",
    "ausencia_id" "uuid",
    CONSTRAINT "asignaciones_de_turno_guardia_apunta_a_una_sola_cosa" CHECK (("num_nonnulls"("turno_guardia_id", "serie_id", "ausencia_id") = 1)),
    CONSTRAINT "asignaciones_de_turno_guardia_estado_check" CHECK (("estado" = ANY (ARRAY['sin_responder'::"text", 'aceptada'::"text", 'rechazada'::"text", 'retirada'::"text"]))),
    CONSTRAINT "asignaciones_de_turno_guardia_respondida_check" CHECK ((("respondida_at" IS NOT NULL) = ("estado" = ANY (ARRAY['aceptada'::"text", 'rechazada'::"text"])))),
    CONSTRAINT "asignaciones_de_turno_guardia_retirada_check" CHECK ((("retirada_at" IS NOT NULL) = ("estado" = 'retirada'::"text")))
);


ALTER TABLE "public"."asignaciones_de_turno_guardia" OWNER TO "postgres";


COMMENT ON TABLE "public"."asignaciones_de_turno_guardia" IS 'Cada vez que un turno de guardia se le asigna a un Asistente, y lo que paso despues: si lo acepto, lo rechazo o se le retiro. El motivo de un rechazo vive en resoluciones.';



COMMENT ON COLUMN "public"."asignaciones_de_turno_guardia"."estado" IS 'sin_responder al asignarse; de ahi pasa una sola vez a aceptada, rechazada o retirada.';



COMMENT ON COLUMN "public"."asignaciones_de_turno_guardia"."serie_id" IS 'El turno de guardia fijo asignado entero. Se acepta o se rechaza una vez por todos sus días.';



COMMENT ON COLUMN "public"."asignaciones_de_turno_guardia"."ausencia_id" IS 'La ausencia que el Asistente cubre. Se acepta o se rechaza una vez por todas sus coberturas pendientes.';



CREATE TABLE IF NOT EXISTS "public"."asistente_lugares" (
    "asistente_id" "uuid" NOT NULL,
    "lugar_id" "uuid" NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."asistente_lugares" OWNER TO "postgres";


COMMENT ON TABLE "public"."asistente_lugares" IS 'Los lugares donde cada Asistente acepta trabajar. Se guardan lugares y no zonas: su disponibilidad no tiene por que coincidir con el agrupamiento de la Prestadora.';



CREATE OR REPLACE VIEW "public"."asistentes_coordinador" WITH ("security_invoker"='true') AS
 SELECT "id",
    "nombre",
    "telefono",
    "email",
    "foto_url",
    "disponibilidad",
    "estado",
    "qr_token",
    "fecha_alta",
    "created_at",
    "updated_at",
    "deleted_at",
    "dni",
    "tipo_asistente_id",
    "numero_legajo",
    "documento_tipo",
    "documento_numero",
    "documento_pais",
    "genero"
   FROM "public"."asistentes"
  WHERE (NOT "public"."cuenta_desactivada"("asistentes".*));


ALTER VIEW "public"."asistentes_coordinador" OWNER TO "postgres";


COMMENT ON VIEW "public"."asistentes_coordinador" IS 'Lo que quien coordina ve de una Asistente: sin vinculo laboral y sin remuneraciones.';



CREATE TABLE IF NOT EXISTS "public"."auditoria_advertencias_legales" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "usuario_id" "uuid" NOT NULL,
    "funcion_clave" "text" NOT NULL,
    "jurisdiccion" "text" NOT NULL,
    "texto_mostrado" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"()
);


ALTER TABLE "public"."auditoria_advertencias_legales" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."auditoria_asignaciones_con_aviso" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "usuario_id" "uuid" NOT NULL,
    "turno_guardia_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "avisos" "jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "auditoria_asignaciones_con_aviso_hay_algo" CHECK ((("jsonb_typeof"("avisos") = 'array'::"text") AND ("jsonb_array_length"("avisos") > 0)))
);


ALTER TABLE "public"."auditoria_asignaciones_con_aviso" OWNER TO "postgres";


COMMENT ON TABLE "public"."auditoria_asignaciones_con_aviso" IS 'Quien asigno un turno de guardia teniendo avisos delante, y cuales eran. Registra la decision, no el resultado: se escribe antes de asignar.';



COMMENT ON COLUMN "public"."auditoria_asignaciones_con_aviso"."avisos" IS 'Los avisos que se mostraron, como claves de traduccion y valores. Los arma panel/src/lib/avisosAsignacion.js. Nunca datos de la persona atendida ni tipo de ausencia.';



CREATE TABLE IF NOT EXISTS "public"."auditoria_cambio_dueno_push" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "suscripcion_id" "uuid" NOT NULL,
    "usuario_anterior" "uuid" NOT NULL,
    "usuario_nuevo" "uuid" NOT NULL,
    "rol_anterior" "text" NOT NULL,
    "rol_nuevo" "text" NOT NULL,
    "user_agent" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "prestadora_id" "uuid" DEFAULT "interno"."prestadora_actual"() NOT NULL,
    CONSTRAINT "auditoria_cambio_dueno_push_rol_anterior_check" CHECK (("rol_anterior" = ANY (ARRAY['asistente'::"text", 'cliente'::"text"]))),
    CONSTRAINT "auditoria_cambio_dueno_push_rol_nuevo_check" CHECK (("rol_nuevo" = ANY (ARRAY['asistente'::"text", 'cliente'::"text"])))
);


ALTER TABLE "public"."auditoria_cambio_dueno_push" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."auditoria_de_accesos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "admin_id" "uuid" NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "tipo_evento" "text" NOT NULL,
    "tabla_afectada" "text",
    "operacion" "text",
    "registro_id" "uuid",
    "detalle" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "auditoria_de_accesos_operacion_check" CHECK (("operacion" = ANY (ARRAY['INSERT'::"text", 'UPDATE'::"text", 'DELETE'::"text"]))),
    CONSTRAINT "auditoria_de_accesos_tipo_evento_check" CHECK (("tipo_evento" = ANY (ARRAY['login'::"text", 'logout'::"text", 'renovacion'::"text", 'mutacion'::"text"])))
);


ALTER TABLE "public"."auditoria_de_accesos" OWNER TO "postgres";


COMMENT ON TABLE "public"."auditoria_de_accesos" IS 'Todo lo que se hizo con un permiso de acceso: la entrada, la renovacion, la salida —con su motivo— y cada escritura hecha adentro de la Prestadora visitada. Nunca claves ni contenido.';



CREATE TABLE IF NOT EXISTS "public"."auditoria_reasignaciones_por_emergencia" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "turno_guardia_id" "uuid" NOT NULL,
    "usuario_id" "uuid" NOT NULL,
    "asistente_anterior_id" "uuid",
    "asistente_nuevo_id" "uuid" NOT NULL,
    "motivo" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "auditoria_reasignaciones_por_emergencia_motivo_check" CHECK ((("btrim"("motivo") <> ''::"text") AND ("char_length"("motivo") <= 500)))
);


ALTER TABLE "public"."auditoria_reasignaciones_por_emergencia" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."auditoria_respuesta_automatica_whatsapp" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "conversacion_id" "uuid",
    "mensaje_entrante_id" "uuid",
    "mensaje_saliente_id" "uuid",
    "respuesta_preparada_id" "uuid",
    "resultado" "text" NOT NULL,
    "motivo" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "el_motivo_sale_de_la_lista" CHECK (("motivo" = ANY (ARRAY['respuesta_aprobada'::"text", 'sin_respuesta_aprobada'::"text", 'tema_de_salud'::"text", 'emergencia'::"text", 'sin_telefono_de_emergencia'::"text", 'no_se_pudo_clasificar'::"text", 'envio_fallido'::"text", 'pidio_una_persona'::"text", 'la_atiende_una_persona'::"text"]))),
    CONSTRAINT "el_resultado_sale_de_la_lista" CHECK (("resultado" = ANY (ARRAY['respondida'::"text", 'derivada_a_una_persona'::"text", 'emergencia_avisada'::"text"]))),
    CONSTRAINT "lo_respondido_dice_con_que_respuesta" CHECK ((("resultado" <> 'respondida'::"text") OR ("respuesta_preparada_id" IS NOT NULL)))
);


ALTER TABLE "public"."auditoria_respuesta_automatica_whatsapp" OWNER TO "postgres";


COMMENT ON TABLE "public"."auditoria_respuesta_automatica_whatsapp" IS 'Qué contestó sola la respuesta automática de WhatsApp, en cuál conversación y con cuál respuesta aprobada. Sin contenido: sólo identificadores y un motivo de lista cerrada.';



CREATE TABLE IF NOT EXISTS "public"."ausencias" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "asistente_id" "uuid",
    "tipo" "text" NOT NULL,
    "fecha_inicio" "date" NOT NULL,
    "fecha_fin" "date" NOT NULL,
    "certificado_url" "text",
    "dias_computados" numeric(5,1),
    "turnos_guardia_afectados" "uuid"[],
    "observaciones" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "prestadora_id" "uuid" NOT NULL,
    "avisada_en" timestamp with time zone DEFAULT "now"(),
    "aviso_ausencia_at" timestamp with time zone,
    "aviso_ausencia_veces" integer DEFAULT 0 NOT NULL,
    "aviso_ausencia_clase" "text",
    "fecha_vuelta_real" "date",
    "pregunta_vuelta_at" timestamp with time zone,
    "pregunta_vuelta_veces" integer DEFAULT 0 NOT NULL,
    "usuario_id" "uuid",
    "coordinador_que_cubre_id" "uuid",
    CONSTRAINT "ausencias_de_una_sola_persona" CHECK (("num_nonnulls"("asistente_id", "usuario_id") = 1)),
    CONSTRAINT "ausencias_fin_no_antes_del_inicio" CHECK (("fecha_fin" >= "fecha_inicio")),
    CONSTRAINT "ausencias_tipo_check" CHECK (("tipo" = ANY (ARRAY['enfermedad_inculpable'::"text", 'accidente_inculpable'::"text", 'otra_licencia'::"text", 'ausencia_no_justificada'::"text"]))),
    CONSTRAINT "ausencias_vuelta_despues_del_inicio" CHECK ((("fecha_vuelta_real" IS NULL) OR ("fecha_vuelta_real" > "fecha_inicio")))
);


ALTER TABLE "public"."ausencias" OWNER TO "postgres";


COMMENT ON COLUMN "public"."ausencias"."avisada_en" IS 'Momento en que la Prestadora se entero de esta ausencia, que no es el momento en que se cargo. De aca sale si llego con tiempo o de golpe; la cuenta no se guarda.';



COMMENT ON COLUMN "public"."ausencias"."aviso_ausencia_at" IS 'Ultima vez que se aviso por esta ausencia. Lo escribe el proceso de fondo, no la pantalla.';



COMMENT ON COLUMN "public"."ausencias"."aviso_ausencia_veces" IS 'Cuantas veces se aviso por esta ausencia.';



COMMENT ON COLUMN "public"."ausencias"."aviso_ausencia_clase" IS 'Con que clase se aviso la ultima vez (con_tiempo o de_golpe). Si la clase cambia se vuelve a avisar aunque no haya pasado el intervalo: el problema dejo de ser el mismo.';



CREATE TABLE IF NOT EXISTS "public"."ausencias_cambios_de_fecha" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "ausencia_id" "uuid" NOT NULL,
    "fecha_anterior" "date" NOT NULL,
    "fecha_nueva" "date" NOT NULL,
    "cambiado_por" "uuid" DEFAULT "auth"."uid"(),
