CREATE TABLE IF NOT EXISTS "public"."cambios_de_clave_habilitados" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "usuario_id" "uuid" NOT NULL,
    "habilitado_por" "uuid" NOT NULL,
    "expira_en" timestamp with time zone NOT NULL,
    "usado_en" timestamp with time zone,
    "anulado_en" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "cambios_de_clave_habilitados_no_a_uno_mismo" CHECK (("usuario_id" <> "habilitado_por"))
);


ALTER TABLE "public"."cambios_de_clave_habilitados" OWNER TO "postgres";


COMMENT ON TABLE "public"."cambios_de_clave_habilitados" IS 'La puerta que la Prestadora le abre a alguien que llamó porque no puede entrar. Dura poco, sirve una vez, y no guarda ninguna clave ni nada con que deducirla: quien habilita nunca elige ni ve la clave de nadie.';



CREATE TABLE IF NOT EXISTS "public"."cargas_sujetas_a_aprobacion" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "paciente_id" "uuid" NOT NULL,
    "tabla" "text" NOT NULL,
    "operacion" "text" NOT NULL,
    "registro_id" "uuid",
    "datos" "jsonb" NOT NULL,
    "cargado_por" "uuid" NOT NULL,
    "cargado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "estado" "text" DEFAULT 'pendiente'::"text" NOT NULL,
    "motivo_rechazo" "text",
    "revisado_por" "uuid",
    "revisado_en" timestamp with time zone,
    CONSTRAINT "cargas_sujetas_a_aprobacion_estado_check" CHECK (("estado" = ANY (ARRAY['pendiente'::"text", 'aceptada'::"text", 'rechazada'::"text"]))),
    CONSTRAINT "cargas_sujetas_a_aprobacion_operacion_check" CHECK (("operacion" = ANY (ARRAY['alta'::"text", 'modificacion'::"text"]))),
    CONSTRAINT "cargas_sujetas_a_aprobacion_tabla_check" CHECK (("tabla" = ANY (ARRAY['informacion_de_salud_del_paciente'::"text", 'domicilios_temporales_paciente'::"text"]))),
    CONSTRAINT "el_rechazo_lleva_motivo" CHECK ((("estado" <> 'rechazada'::"text") OR (NULLIF("btrim"("motivo_rechazo"), ''::"text") IS NOT NULL))),
    CONSTRAINT "la_modificacion_de_un_domicilio_dice_cual" CHECK ((("tabla" <> 'domicilios_temporales_paciente'::"text") OR ("operacion" = 'alta'::"text") OR ("registro_id" IS NOT NULL))),
    CONSTRAINT "la_revision_dice_quien_y_cuando" CHECK ((("estado" = 'pendiente'::"text") = (("revisado_por" IS NULL) AND ("revisado_en" IS NULL))))
);


ALTER TABLE "public"."cargas_sujetas_a_aprobacion" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."catalogo_acciones_permisos" (
    "accion" "text" NOT NULL,
    "default_solo_admin" boolean NOT NULL,
    "orden" smallint NOT NULL,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."catalogo_acciones_permisos" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_acciones_permisos" IS 'Las acciones que una Prestadora puede reservar al administrador, y qué pasa cuando no configuró nada. Punto único de verdad del valor por defecto (pendiente #127).';



CREATE TABLE IF NOT EXISTS "public"."catalogo_acciones_registradas" (
    "accion" "text" NOT NULL,
    "grupo" "text" NOT NULL,
    "orden" smallint NOT NULL,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "la_hace_el_sistema" boolean DEFAULT false NOT NULL,
    CONSTRAINT "catalogo_acciones_registradas_grupo_conocido" CHECK (("grupo" = ANY (ARRAY['entrada_administrativa'::"text", 'permisos_y_membresia'::"text", 'borrado_de_datos'::"text", 'modificacion_critica'::"text", 'consecuencia_economica'::"text", 'salida_de_datos'::"text"])))
);


ALTER TABLE "public"."catalogo_acciones_registradas" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_acciones_registradas" IS 'Que acciones deja anotadas el registro de actividad. La clave es opaca: el texto visible vive en las traducciones del Panel, en los tres idiomas.';



COMMENT ON COLUMN "public"."catalogo_acciones_registradas"."grupo" IS 'A cual de los casos que pide la regla de la empresa responde esta accion.';



CREATE TABLE IF NOT EXISTS "public"."catalogo_datos_del_registro" (
    "clave" "text" NOT NULL,
    "orden" smallint NOT NULL,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."catalogo_datos_del_registro" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_datos_del_registro" IS 'Los unicos datos con nombre que el registro de actividad admite adentro de `detalle`. Lista de lo permitido, no de lo prohibido: lo que no figura acá hace fallar la escritura.';



CREATE TABLE IF NOT EXISTS "public"."catalogo_derechos_de_la_persona" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "clave" "text" NOT NULL,
    "orden" smallint NOT NULL,
    CONSTRAINT "catalogo_derechos_de_la_persona_clave_escrita" CHECK (("clave" ~ '^[a-z_]+$'::"text"))
);


ALTER TABLE "public"."catalogo_derechos_de_la_persona" OWNER TO "postgres";



COMMENT ON TABLE "public"."catalogo_derechos_de_la_persona" IS 'Los derechos que una persona puede pedir sobre sus datos. El nombre visible de cada uno es la frase derechos_de_la_persona.derecho.<clave>.';



CREATE TABLE IF NOT EXISTS "public"."catalogo_documentos_de_identidad" (
    "pais" "text" NOT NULL,
    "clase" "text" NOT NULL,
    "codigo" "text" NOT NULL,
    "sigla" "text" NOT NULL,
    "orden" integer DEFAULT 100 NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "lleva_pais" boolean DEFAULT false NOT NULL,
    "verifica_modulo_11" boolean DEFAULT false NOT NULL,
    "contiene_dni" boolean DEFAULT false NOT NULL,
    CONSTRAINT "catalogo_documentos_clase_conocida" CHECK (("clase" = ANY (ARRAY['fisica'::"text", 'juridica'::"text"])))
);


ALTER TABLE "public"."catalogo_documentos_de_identidad" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_documentos_de_identidad" IS 'Que documentos de identidad emite cada pais, y a que clase de Persona le corresponde cada uno. No es configuracion de ninguna Prestadora: es lo que emite un Estado.';



CREATE TABLE IF NOT EXISTS "public"."catalogo_funciones_intermediacion" (
    "clave" "text" NOT NULL,
    "orden" smallint NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."catalogo_funciones_intermediacion" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_funciones_intermediacion" IS 'Las funciones de la modalidad Match que tienen riesgo legal conocido. Es el catálogo de la plataforma: qué se puede encender. Si esa función tiene advertencia escrita para la jurisdicción de la Prestadora, encenderla la muestra y la deja auditada.';



COMMENT ON COLUMN "public"."catalogo_funciones_intermediacion"."clave" IS 'La misma cadena que nombra a esta función en advertencias_legales y en auditoria_advertencias_legales. Nombre guardado: no se renombra.';



COMMENT ON COLUMN "public"."catalogo_funciones_intermediacion"."orden" IS 'En qué orden se listan en pantalla. Es el orden del documento legal, para poder leerlas al lado del documento.';



CREATE TABLE IF NOT EXISTS "public"."catalogo_generos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "pais" "text" NOT NULL,
    "codigo" "text" NOT NULL,
    "orden" integer NOT NULL,
    "activo" boolean DEFAULT true NOT NULL
);


ALTER TABLE "public"."catalogo_generos" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."catalogo_identificadores_de_cuenta" (
    "pais" "text" NOT NULL,
    "codigo" "text" NOT NULL,
    "sigla" "text" NOT NULL,
    "orden" integer DEFAULT 100 NOT NULL,
    "activo" boolean DEFAULT true NOT NULL
);


ALTER TABLE "public"."catalogo_identificadores_de_cuenta" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_identificadores_de_cuenta" IS 'Con que numero se identifica una cuenta bancaria en cada pais. Un pais nuevo entra cargando filas, nunca tocando codigo.';



COMMENT ON COLUMN "public"."catalogo_identificadores_de_cuenta"."sigla" IS 'Como se llama ese identificador en su pais. No se traduce: CBU y CVU son nombres propios.';



CREATE TABLE IF NOT EXISTS "public"."catalogo_paises" (
    "codigo" "text" NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "catalogo_paises_codigo_check" CHECK (("codigo" ~ '^[A-Z]{2}$'::"text"))
);


ALTER TABLE "public"."catalogo_paises" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."catalogo_periodos_cobro" (
    "clave" "text" NOT NULL,
    "orden" smallint NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."catalogo_periodos_cobro" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."catalogo_prefijos_de_celular" (
    "pais" "text" NOT NULL,
    "prefijo" "text" NOT NULL,
    "orden" integer DEFAULT 100 NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    CONSTRAINT "el_prefijo_de_celular_es_solo_digitos" CHECK (("prefijo" ~ '^[0-9]+$'::"text"))
);


ALTER TABLE "public"."catalogo_prefijos_de_celular" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_prefijos_de_celular" IS 'Con que empieza un numero de celular en cada pais, en forma internacional y solo con digitos. Un pais nuevo entra cargando filas, nunca tocando codigo. El pais sin filas no tiene ningun numero reconocido como celular.';



COMMENT ON COLUMN "public"."catalogo_prefijos_de_celular"."prefijo" IS 'Digitos con los que empieza el numero, sin el mas y sin separadores. Incluye el codigo de pais.';



CREATE TABLE IF NOT EXISTS "public"."catalogo_proveedores_de_mensaje_de_texto" (
    "proveedor" "text" NOT NULL,
    "orden" smallint DEFAULT 100 NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."catalogo_proveedores_de_mensaje_de_texto" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_proveedores_de_mensaje_de_texto" IS 'Los proveedores de mensaje de texto que el producto conoce. Nace vacio a proposito: con este catalogo vacio la via sale en la lista de Avisos y no se puede elegir. Un proveedor entra cargando una fila, nunca tocando codigo.';



COMMENT ON COLUMN "public"."catalogo_proveedores_de_mensaje_de_texto"."proveedor" IS 'Como se llama el proveedor. Es un nombre propio y no se traduce.';



CREATE TABLE IF NOT EXISTS "public"."catalogo_software_externo" (
    "clave" "text" NOT NULL,
    "clase" "text" NOT NULL,
    "nombre" "text" NOT NULL,
    "orden" smallint DEFAULT 0 NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "catalogo_software_externo_clase_check" CHECK (("clase" = ANY (ARRAY['facturacion'::"text", 'creditos_y_cobranzas'::"text"]))),
    CONSTRAINT "catalogo_software_externo_nombre_check" CHECK (("length"("btrim"("nombre")) > 0))
);


ALTER TABLE "public"."catalogo_software_externo" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_software_externo" IS 'Con que software de afuera se puede conectar una Prestadora: los de facturacion y los de creditos y cobranzas. Ninguna de las dos tareas se hace aca; esto dice unicamente con quien se habla.';



COMMENT ON COLUMN "public"."catalogo_software_externo"."clase" IS 'Para que sirve ese software: facturacion, o creditos_y_cobranzas.';



COMMENT ON COLUMN "public"."catalogo_software_externo"."nombre" IS 'El nombre comercial del producto de ese tercero. No se traduce: es una marca.';



CREATE TABLE IF NOT EXISTS "public"."catalogo_usos_del_codigo_al_telefono" (
    "uso" "text" NOT NULL,
    "orden" smallint NOT NULL,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."catalogo_usos_del_codigo_al_telefono" OWNER TO "postgres";


COMMENT ON TABLE "public"."catalogo_usos_del_codigo_al_telefono" IS 'Para qué se manda un código al teléfono. Son tres y ninguna Prestadora las cambia: verificar el número, entrar desde un equipo nuevo y recuperar la clave.';



CREATE TABLE IF NOT EXISTS "public"."certificados" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "asistente_id" "uuid",
    "fecha_emision" "date" NOT NULL,
    "fecha_vencimiento" "date",
    "activo" boolean DEFAULT true,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "prestadora_id" "uuid" NOT NULL
);


ALTER TABLE "public"."certificados" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."cierre_servicio_asistentes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "cierre_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "avisado_verbalmente_at" timestamp with time zone,
    "avisado_verbalmente_por" "uuid",
    "aviso_automatico_enviado_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."cierre_servicio_asistentes" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."cierres_servicio_paciente" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "paciente_id" "uuid" NOT NULL,
    "motivo" "text" NOT NULL,
    "motivo_detalle" "text",
    "cerrado_por" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "servicio_id" "uuid"
);


ALTER TABLE "public"."cierres_servicio_paciente" OWNER TO "postgres";


COMMENT ON COLUMN "public"."cierres_servicio_paciente"."servicio_id" IS 'Qué Servicio se cerró. Es lo que se pactó con el Cliente, y es por donde preguntan las políticas del Coordinador.';



CREATE TABLE IF NOT EXISTS "public"."clientes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "deleted_at" timestamp with time zone,
    "prestadora_id" "uuid" NOT NULL,
    "importacion_id" "uuid",
    "pendiente_conformidad" boolean DEFAULT false NOT NULL,
    "usuario_id" "uuid" NOT NULL,
    "numero_cliente" bigint NOT NULL,
    "contratante_persona_id" "uuid" NOT NULL
);


ALTER TABLE "public"."clientes" OWNER TO "postgres";


COMMENT ON COLUMN "public"."clientes"."usuario_id" IS 'De qué cuenta cuelga esta ficha. Es la cuenta del titular; las demás personas autorizadas cuelgan de `personas_autorizadas`.';



COMMENT ON COLUMN "public"."clientes"."numero_cliente" IS 'Unico adentro de la Prestadora. Lo asigna el disparador, no se elige y no se reasigna nunca. Es lo que usan el sistema y los documentos; el nombre visible del Cliente se calcula aparte y es para la pantalla.';



CREATE TABLE IF NOT EXISTS "public"."coberturas_de_ausencia" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "ausencia_id" "uuid" NOT NULL,
    "serie_id" "uuid",
    "asistente_sustituto_id" "uuid" NOT NULL,
    "motivo" "text",
    "motivo_detalle" "text",
    "costo_adicional" numeric,
    "moneda" "text",
    "asignada_por" "uuid" DEFAULT "auth"."uid"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "objetada_at" timestamp with time zone,
    "aceptada_at" timestamp with time zone
);


ALTER TABLE "public"."coberturas_de_ausencia" OWNER TO "postgres";


COMMENT ON COLUMN "public"."coberturas_de_ausencia"."aceptada_at" IS 'Cuándo la aceptó el sustituto. Hasta entonces no cubre ningún turno de guardia.';



CREATE TABLE IF NOT EXISTS "public"."cobros_cliente" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "factura_id" "uuid" NOT NULL,
    "monto" numeric(12,2) NOT NULL,
    "moneda" "public"."moneda_iso" NOT NULL,
    "fecha_cobro" "date" NOT NULL,
    "medio" "text" NOT NULL,
    "origen" "text" DEFAULT 'panel'::"text" NOT NULL,
    "referencia_externa" "text",
    "observaciones" "text",
    "estado" "text" DEFAULT 'registrado'::"text" NOT NULL,
    "motivo_anulacion" "text",
    "anulado_por" "uuid",
    "anulado_at" timestamp with time zone,
    "registrado_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "cobros_cliente_anulado_con_fecha" CHECK ((("estado" = 'anulado'::"text") = ("anulado_at" IS NOT NULL))),
    CONSTRAINT "cobros_cliente_anulado_con_motivo" CHECK ((("estado" <> 'anulado'::"text") OR ("motivo_anulacion" IS NOT NULL))),
    CONSTRAINT "cobros_cliente_estado_check" CHECK (("estado" = ANY (ARRAY['registrado'::"text", 'anulado'::"text"]))),
    CONSTRAINT "cobros_cliente_monto_check" CHECK (("monto" > (0)::numeric)),
    CONSTRAINT "cobros_cliente_origen_check" CHECK (("origen" = ANY (ARRAY['panel'::"text", 'importacion'::"text", 'api'::"text", 'pasarela'::"text", 'migracion'::"text"])))
);


ALTER TABLE "public"."cobros_cliente" OWNER TO "postgres";


COMMENT ON TABLE "public"."cobros_cliente" IS 'Cada entrada de plata contra una factura de un Cliente. Varias filas por factura: así se representa el cobro parcial. No es un comprobante fiscal.';



COMMENT ON COLUMN "public"."cobros_cliente"."medio" IS 'Con que medio pago el Cliente. Es una opcion de la lista «medios_de_pago_del_cliente»: las que trae el producto y las que agrego esta Prestadora.';



CREATE TABLE IF NOT EXISTS "public"."cobros_intermediacion" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "acceso_id" "uuid" NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "medio" "text" NOT NULL,
    "monto" numeric(12,2) NOT NULL,
    "periodo" "date" NOT NULL,
    "estado_cobro" "text" DEFAULT 'pendiente'::"text" NOT NULL,
    "referencia_externa" "text",
    "fecha_cobro" "date" NOT NULL,
    "registrado_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "moneda" "public"."moneda_iso" NOT NULL,
    "codigo_cupon" "text",
    CONSTRAINT "cobros_intermediacion_estado_cobro_check" CHECK (("estado_cobro" = ANY (ARRAY['pendiente'::"text", 'exitoso'::"text", 'fallido'::"text"])))
);


ALTER TABLE "public"."cobros_intermediacion" OWNER TO "postgres";



COMMENT ON COLUMN "public"."cobros_intermediacion"."codigo_cupon" IS 'Código del cupón con el que el Cliente paga este período, en los rieles de cobranza en efectivo.';



CREATE TABLE IF NOT EXISTS "public"."codigos_al_telefono" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "usuario_id" "uuid" NOT NULL,
    "uso" "text" NOT NULL,
    "telefono" "text" NOT NULL,
    "codigo_verificador" "text" NOT NULL,
    "codigo_expira_en" timestamp with time zone NOT NULL,
    "codigo_intentos" smallint DEFAULT 0 NOT NULL,
    "verificado_en" timestamp with time zone,
    "anulado_en" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."codigos_al_telefono" OWNER TO "postgres";


COMMENT ON TABLE "public"."codigos_al_telefono" IS 'El código corto que se le manda al teléfono de una persona. Se guarda el identificador de verificación del código, nunca el código. Lo escribe y lo lee únicamente el backend.';



COMMENT ON COLUMN "public"."codigos_al_telefono"."telefono" IS 'El número que se está verificando, que es al que se le manda el mensaje. No viaja a ninguna pantalla ni a ningún registro.';



COMMENT ON COLUMN "public"."codigos_al_telefono"."codigo_intentos" IS 'Cuántas veces se probó un código contra este pedido. Es la cuenta del acto, no la del código: pedir uno nuevo no la vuelve a cero. Un código vencido no gasta intento.';



CREATE TABLE IF NOT EXISTS "public"."codigos_de_presencia" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "sujeto_tipo" "text" NOT NULL,
    "sujeto_id" "uuid" NOT NULL,
    "codigo_verificador" "text" NOT NULL,
    "expira_en" timestamp with time zone NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "codigos_de_presencia_sujeto_tipo_check" CHECK (("sujeto_tipo" = ANY (ARRAY['cliente'::"text", 'asistente'::"text"])))
);


ALTER TABLE "public"."codigos_de_presencia" OWNER TO "postgres";


COMMENT ON TABLE "public"."codigos_de_presencia" IS 'El código de seis dígitos que una persona muestra en la pantalla de su teléfono para que el Asistente que llega compruebe que está en la casa (pendiente #113, Plan A). Se guarda su identificador de verificación y vence solo a los segundos que configuró la Prestadora.';



COMMENT ON COLUMN "public"."codigos_de_presencia"."sujeto_tipo" IS 'Quién muestra el código: cliente (cualquiera de las personas autorizadas) o asistente (el que se va, cuando hay relevo). El Paciente no tiene cuenta en el producto y por eso no figura acá.';



COMMENT ON COLUMN "public"."codigos_de_presencia"."codigo_verificador" IS 'sha256 del código. El código en claro no se guarda en ningún lado: sólo viaja a la pantalla que lo muestra y de ahí a la que lo lee.';



CREATE TABLE IF NOT EXISTS "public"."conceptos_liquidacion" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "nombre" "text" NOT NULL,
    "signo" "text" NOT NULL,
    "unidad" "text" NOT NULL,
    "origen_valor" "text" DEFAULT 'propio'::"text" NOT NULL,
    "valor" numeric(14,4),
    "escala_tipo" "text",
    "moneda" "public"."moneda_iso",
    "activo" boolean DEFAULT true NOT NULL,
    "orden" smallint DEFAULT 100 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "conceptos_liquidacion_moneda_cuando_es_plata" CHECK (((("unidad" <> 'porcentaje'::"text") AND ("origen_valor" = 'propio'::"text")) = ("moneda" IS NOT NULL))),
    CONSTRAINT "conceptos_liquidacion_origen_valor_check" CHECK (("origen_valor" = ANY (ARRAY['propio'::"text", 'escala_legal'::"text"]))),
    CONSTRAINT "conceptos_liquidacion_signo_check" CHECK (("signo" = ANY (ARRAY['suma'::"text", 'resta'::"text"]))),
    CONSTRAINT "conceptos_liquidacion_unidad_check" CHECK (("unidad" = ANY (ARRAY['monto_fijo_mensual'::"text", 'porcentaje'::"text", 'monto_por_hora'::"text"]))),
    CONSTRAINT "conceptos_liquidacion_valor_segun_origen" CHECK (((("origen_valor" = 'propio'::"text") AND ("valor" IS NOT NULL) AND ("escala_tipo" IS NULL)) OR (("origen_valor" = 'escala_legal'::"text") AND ("escala_tipo" IS NOT NULL) AND ("valor" IS NULL))))
);


ALTER TABLE "public"."conceptos_liquidacion" OWNER TO "postgres";


COMMENT ON TABLE "public"."conceptos_liquidacion" IS 'Los conceptos de suma y resta que cada Prestadora aplica al pago de sus Asistentes. Ninguno viene cargado de fábrica.';



CREATE TABLE IF NOT EXISTS "public"."condiciones_comerciales_servicio" (
    "servicio_id" "uuid" NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "contratante_persona_id" "uuid",
    "dias_hasta_el_vencimiento" integer,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "frecuencia_de_cobro" "text",
    "medicion" "text",
    "indice_de_actualizacion" "text",
    "cobra_cancelada_por_el_cliente" boolean,
    "descuenta_lo_no_prestado" boolean,
    "cobra_turnos_guardia_adicionales" boolean,
    "cobra_horas_adicionales" boolean,
    "meses_entre_actualizaciones" integer,
    "ajuste_por_indice" "text",
    CONSTRAINT "condiciones_comerciales_frecuencia_conocida" CHECK ((("frecuencia_de_cobro" IS NULL) OR ("frecuencia_de_cobro" = ANY (ARRAY['dia'::"text", 'semana'::"text", 'quincena'::"text", 'mes'::"text"])))),
    CONSTRAINT "condiciones_comerciales_medicion_conocida" CHECK ((("medicion" IS NULL) OR ("medicion" = ANY (ARRAY['pactado_mas_excedente'::"text", 'hora'::"text", 'dia_de_guardia'::"text"])))),
    CONSTRAINT "condiciones_comerciales_plazo_razonable" CHECK ((("dias_hasta_el_vencimiento" IS NULL) OR (("dias_hasta_el_vencimiento" >= 0) AND ("dias_hasta_el_vencimiento" <= 365)))),
    CONSTRAINT "condiciones_comerciales_servi_meses_entre_actualizaciones_check" CHECK (("meses_entre_actualizaciones" = ANY (ARRAY[1, 3, 6]))),
    CONSTRAINT "condiciones_comerciales_servicio_ajuste_por_indice_check" CHECK (("ajuste_por_indice" = ANY (ARRAY['automatico'::"text", 'revision_previa'::"text"])))
);


ALTER TABLE "public"."condiciones_comerciales_servicio" OWNER TO "postgres";


COMMENT ON COLUMN "public"."condiciones_comerciales_servicio"."frecuencia_de_cobro" IS 'Cada cuánto se le factura este Servicio al Cliente: dia, semana, quincena (dos semanas) o mes. Nula: rige la de la Prestadora.';



COMMENT ON COLUMN "public"."condiciones_comerciales_servicio"."medicion" IS 'Con qué se mide lo que se cobra: pactado_mas_excedente, hora o dia_de_guardia. Nula: rige la de la Prestadora.';



CREATE TABLE IF NOT EXISTS "public"."conexiones_con_software_externo" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "clase" "text" NOT NULL,
    "software" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "conexiones_con_software_externo_clase_check" CHECK (("clase" = ANY (ARRAY['facturacion'::"text", 'creditos_y_cobranzas'::"text"])))
);


ALTER TABLE "public"."conexiones_con_software_externo" OWNER TO "postgres";


COMMENT ON TABLE "public"."conexiones_con_software_externo" IS 'Cual es el software de facturacion y cual el de creditos y cobranzas de cada Prestadora. La credencial con la que se entra vive cifrada en secretos_de_terceros. Aca no se factura ni se cobra: esto dice unicamente con quien habla.';




CREATE TABLE IF NOT EXISTS "public"."configuracion_alarmas_tomadas" (
    "prestadora_id" "uuid" NOT NULL,
    "regla" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "configuracion_alarmas_tomadas_regla_es_objeto" CHECK (("jsonb_typeof"("regla") = 'object'::"text"))
);


ALTER TABLE "public"."configuracion_alarmas_tomadas" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_alarmas_tomadas" IS 'Cuanto dura hacerse cargo de una alarma. Solo lo que esta Prestadora corrio; los valores de fabrica y los bordes viven en panel/src/lib/alarmasTomadas.js.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_alertas_ia" (
    "prestadora_id" "uuid" NOT NULL,
    "palabras_clave" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "reportes_a_analizar" integer DEFAULT 7 NOT NULL,
    "roja_avisa_cliente" boolean DEFAULT true NOT NULL,
    "amarilla_avisa_cliente" boolean DEFAULT false NOT NULL,
    "amarilla_avisa_coordinador" boolean DEFAULT true NOT NULL,
    CONSTRAINT "configuracion_alertas_ia_reportes_a_analizar_check" CHECK ((("reportes_a_analizar" >= 1) AND ("reportes_a_analizar" <= 30)))
);


ALTER TABLE "public"."configuracion_alertas_ia" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_alertas_ia" IS 'Cómo revisa esta Prestadora los reportes de sus Pacientes con inteligencia artificial: qué palabras adelantan la revisión, cuánto material mira y a quién le avisa según lo que encuentra. Sin fila, valen los valores de fábrica que están en backend/src/routes/panelConfiguracion.js.';



COMMENT ON COLUMN "public"."configuracion_alertas_ia"."palabras_clave" IS 'Palabras que, si aparecen en un reporte, disparan la revisión en el momento en vez de esperar al horario de siempre (por ejemplo: caída, sangrado, no responde). Las lee backend/src/routes/appAsistentes.js al recibir el reporte.';



COMMENT ON COLUMN "public"."configuracion_alertas_ia"."reportes_a_analizar" IS 'Cuántos de los últimos reportes de ese Paciente mira la revisión. De fábrica, 7. Cuantos más mire, más contexto tiene y más cuesta cada revisión.';



COMMENT ON COLUMN "public"."configuracion_alertas_ia"."roja_avisa_cliente" IS 'Si una alerta roja —lo urgente— también le llega al Cliente del Paciente. De fábrica, sí. Al Coordinador le llega siempre, eso no se configura.';



COMMENT ON COLUMN "public"."configuracion_alertas_ia"."amarilla_avisa_cliente" IS 'Si una alerta amarilla —lo que conviene mirar, sin urgencia— también le llega al Cliente. De fábrica, no: la amarilla es material de trabajo de la Prestadora, no una noticia para dar.';



COMMENT ON COLUMN "public"."configuracion_alertas_ia"."amarilla_avisa_coordinador" IS 'Si una alerta amarilla le llega al Coordinador. De fábrica, sí. Se puede apagar en una Prestadora que prefiera revisarlas por pantalla en vez de recibirlas de a una.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_ausencia_automatica" (
    "prestadora_id" "uuid" NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "minutos_tolerancia_checkin" integer DEFAULT 15 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "metros_tolerancia_checkin" integer DEFAULT 150 NOT NULL,
    "segundos_codigo_en_pantalla" integer DEFAULT 30 NOT NULL,
    CONSTRAINT "segundos_codigo_en_pantalla_razonable" CHECK ((("segundos_codigo_en_pantalla" >= 10) AND ("segundos_codigo_en_pantalla" <= 300)))
);


ALTER TABLE "public"."configuracion_ausencia_automatica" OWNER TO "postgres";


COMMENT ON COLUMN "public"."configuracion_ausencia_automatica"."segundos_codigo_en_pantalla" IS 'Cada cuántos segundos se renueva el código que el Cliente —o el Asistente que se va— muestra en la pantalla de su teléfono para que lo lea el Asistente que llega. Decisión de cada Prestadora.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_ausencias" (
    "prestadora_id" "uuid" NOT NULL,
    "regla" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "configuracion_ausencias_regla_es_objeto" CHECK (("jsonb_typeof"("regla") = 'object'::"text"))
);


ALTER TABLE "public"."configuracion_ausencias" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_ausencias" IS 'Con cuanta anticipacion sobre el primer turno de guardia afectado una ausencia se considera avisada con tiempo, y cada cuanto se insiste. Solo lo que esta Prestadora corrio; los valores de fabrica y los bordes viven en panel/src/lib/avisoDeAusencia.js.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_aviso_cierre_del_servicio" (
    "prestadora_id" "uuid" NOT NULL,
    "horas_plazo_aviso_verbal" smallint DEFAULT 24 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "activo" boolean DEFAULT true NOT NULL
);


ALTER TABLE "public"."configuracion_aviso_cierre_del_servicio" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."configuracion_aviso_turno_guardia_sin_cubrir" (
    "prestadora_id" "uuid" NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "horas_antes" smallint DEFAULT 48 NOT NULL,
    "horas_entre_avisos" smallint DEFAULT 12 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "configuracion_aviso_turno_guardia_sin_cubrir_horas_antes_check" CHECK ((("horas_antes" > 0) AND ("horas_antes" <= 720))),
    CONSTRAINT "config_aviso_turno_guardia_sin_cubrir_horas_entre_avisos_check" CHECK ((("horas_entre_avisos" > 0) AND ("horas_entre_avisos" <= 720)))
);


ALTER TABLE "public"."configuracion_aviso_turno_guardia_sin_cubrir" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_aviso_turno_guardia_sin_cubrir" IS 'Cuándo avisarle al Coordinador que un turno de guardia próximo sigue sin Asistente. Una fila por Prestadora; sin fila no se manda ningún aviso.';



COMMENT ON COLUMN "public"."configuracion_aviso_turno_guardia_sin_cubrir"."horas_antes" IS 'Con cuánta anticipación avisar. El aviso arranca cuando faltan estas horas para que empiece el turno de guardia.';



COMMENT ON COLUMN "public"."configuracion_aviso_turno_guardia_sin_cubrir"."horas_entre_avisos" IS 'Cada cuánto repetir el aviso mientras el hueco siga abierto. Evita que el proceso, que corre cada 5 minutos, mande el mismo correo doce veces por hora.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_calculo_candidatos" (
    "prestadora_id" "uuid" NOT NULL,
    "perfil" "text" DEFAULT 'continuidad'::"text" NOT NULL,
    "pesos" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "topes" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "configuracion_calculo_candidatos_perfil_conocido" CHECK (("perfil" = ANY (ARRAY['continuidad'::"text", 'descanso'::"text", 'cercania'::"text"]))),
    CONSTRAINT "configuracion_calculo_candidatos_pesos_es_objeto" CHECK (("jsonb_typeof"("pesos") = 'object'::"text")),
    CONSTRAINT "configuracion_calculo_candidatos_topes_es_objeto" CHECK (("jsonb_typeof"("topes") = 'object'::"text"))
);


ALTER TABLE "public"."configuracion_calculo_candidatos" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_calculo_candidatos" IS 'Como ordena cada Prestadora la lista de quienes pueden cubrir un hueco: el perfil elegido y lo que corrio respecto de el. Los valores de fabrica y las tres formas armadas viven en panel/src/lib/perfilesDeCandidatos.js.';



COMMENT ON COLUMN "public"."configuracion_calculo_candidatos"."perfil" IS 'Identificador permanente de la forma armada. Se nombra por su funcion y no se renombra.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_de_hce" (
    "prestadora_id" "uuid" NOT NULL,
    "restriccion_de_hce" boolean DEFAULT true NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "minutos_de_acceso_de_emergencia" integer DEFAULT 60 NOT NULL,
    CONSTRAINT "configuracion_de_hce_minutos_de_acceso_de_emergencia_check" CHECK ((("minutos_de_acceso_de_emergencia" >= 5) AND ("minutos_de_acceso_de_emergencia" <= 480)))
);


ALTER TABLE "public"."configuracion_de_hce" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_de_hce" IS 'Si rige la restricción de HCE: la información de salud de un paciente la ve sólo quien lo atiende. Sin renglón, rige.';



COMMENT ON COLUMN "public"."configuracion_de_hce"."minutos_de_acceso_de_emergencia" IS 'Cuantos minutos vale un acceso de emergencia a la informacion de salud desde que se abre.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_equipo_paciente" (
    "prestadora_id" "uuid" NOT NULL,
    "regla" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "configuracion_equipo_paciente_regla_es_objeto" CHECK (("jsonb_typeof"("regla") = 'object'::"text"))
);


ALTER TABLE "public"."configuracion_equipo_paciente" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_equipo_paciente" IS 'Con cuantos turnos de guardia y en que ventana de dias se entra solo al equipo de un Paciente. Solo lo que esta Prestadora corrio; los valores de fabrica y los bordes viven en panel/src/lib/equipoDelPaciente.js.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_escalada_coordinador" (
    "prestadora_id" "uuid" NOT NULL,
    "coordinador_backup_id" "uuid",
    "minutos_antes_backup" integer DEFAULT 15 NOT NULL,
    "umbrales_premura" "jsonb" DEFAULT '[{"maximo_minutos": 60, "intervalo_minutos": 10}, {"maximo_minutos": 240, "intervalo_minutos": 30}, {"maximo_minutos": null, "intervalo_minutos": 60}]'::"jsonb" NOT NULL,
    "fase_automatica_activa" boolean DEFAULT false NOT NULL,
    "minutos_antes_fase_automatica" integer DEFAULT 120 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "minutos_gracia_cierre_turno_guardia" integer DEFAULT 15 NOT NULL,
    "horas_antes_aviso_grave_sin_cerrar" integer DEFAULT 4 NOT NULL,
    "minutos_antes_todos_los_coordinadores" integer DEFAULT 45,
    "minutos_antes_administracion" integer DEFAULT 90,
    "minutos_insistencia_emergencia" integer DEFAULT 1 NOT NULL,
    CONSTRAINT "horas_antes_aviso_grave_sin_cerrar_razonable" CHECK ((("horas_antes_aviso_grave_sin_cerrar" > 0) AND ("horas_antes_aviso_grave_sin_cerrar" <= 72))),
    CONSTRAINT "minutos_gracia_cierre_turno_guardia_razonable" CHECK ((("minutos_gracia_cierre_turno_guardia" > 0) AND ("minutos_gracia_cierre_turno_guardia" <= 1440))),
    CONSTRAINT "minutos_insistencia_emergencia_razonable" CHECK ((("minutos_insistencia_emergencia" >= 1) AND ("minutos_insistencia_emergencia" <= 10)))
);


ALTER TABLE "public"."configuracion_escalada_coordinador" OWNER TO "postgres";


COMMENT ON COLUMN "public"."configuracion_escalada_coordinador"."horas_antes_aviso_grave_sin_cerrar" IS 'Cuántas horas después de vencido el plazo de cierre el aviso escala al evento turno_guardia_sin_cerrar_grave, que tiene su propia lista de destinatarios. Sale una sola vez por turno de guardia.';



COMMENT ON COLUMN "public"."configuracion_escalada_coordinador"."minutos_antes_todos_los_coordinadores" IS 'Minutos desde que empezo la alarma antes de avisarle a todos los Coordinadores. En nulo, ese escalon queda apagado.';



COMMENT ON COLUMN "public"."configuracion_escalada_coordinador"."minutos_antes_administracion" IS 'Minutos desde que empezo la alarma antes de avisarle a la administracion. En nulo, ese escalon queda apagado.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_escalada_relevo" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "nivel" integer NOT NULL,
    "minutos_demora" integer,
    "orden_prioridad" "text"[],
    "plantilla_mensaje" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."configuracion_escalada_relevo" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."configuracion_facturacion_clientes" (
    "prestadora_id" "uuid" NOT NULL,
    "regla" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "configuracion_facturacion_clientes_regla_es_objeto" CHECK (("jsonb_typeof"("regla") = 'object'::"text"))
);


ALTER TABLE "public"."configuracion_facturacion_clientes" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_facturacion_clientes" IS 'Como factura y como cobra esta Prestadora lo que no depende de un Cliente sola: el plazo de pago acordado y si el seguimiento de la cobranza es suyo o de otro software. Solo lo que corrio respecto de fabrica; los bordes viven en panel/src/lib/facturacionDeClientes.js.';




CREATE TABLE IF NOT EXISTS "public"."configuracion_funciones_intermediacion" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "funcion_clave" "text" NOT NULL,
    "activa" boolean DEFAULT false NOT NULL,
    "advertida_en" timestamp with time zone,
    "advertida_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."configuracion_funciones_intermediacion" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_funciones_intermediacion" IS 'Qué funciones de riesgo legal de Match tiene encendidas cada Prestadora. Sin fila, apagada. Nada acá bloquea nada: encender muestra el aviso de la jurisdicción, si lo hay, y lo deja auditado.';



COMMENT ON COLUMN "public"."configuracion_funciones_intermediacion"."advertida_en" IS 'Cuándo se mostró el último aviso legal al encender esta función. El historial completo, con el texto mostrado, está en auditoria_advertencias_legales.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_incidentes_turno_guardia_sin_cubrir" (
    "prestadora_id" "uuid" NOT NULL,
    "regla" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "config_incidentes_turno_guardia_sin_cubrir_regla_es_objeto" CHECK (("jsonb_typeof"("regla") = 'object'::"text"))
);


ALTER TABLE "public"."configuracion_incidentes_turno_guardia_sin_cubrir" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_incidentes_turno_guardia_sin_cubrir" IS 'A cuantas horas de empezar un turno de guardia sin nadie abre un incidente, y cada cuanto se insiste. Solo lo que esta Prestadora corrio; los valores de fabrica y los bordes viven en panel/src/lib/incidenteTurnoGuardiaSinCubrir.js.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_medicacion" (
    "prestadora_id" "uuid" NOT NULL,
    "pide_firma_del_cliente" boolean DEFAULT true NOT NULL,
    "actualizado_por" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."configuracion_medicacion" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."configuracion_mensaje_de_texto_prestadora" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "proveedor" "text",
    "remitente" "text",
    "activo" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sin_proveedor_el_mensaje_de_texto_no_se_enciende" CHECK (((NOT "activo") OR ("proveedor" IS NOT NULL)))
);


ALTER TABLE "public"."configuracion_mensaje_de_texto_prestadora" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_mensaje_de_texto_prestadora" IS 'Con que proveedor manda mensajes de texto cada Prestadora. Sin fila no hay proveedor y la via no se puede elegir. La credencial vive cifrada en secretos_de_terceros.';




COMMENT ON COLUMN "public"."configuracion_mensaje_de_texto_prestadora"."activo" IS 'Si la via esta encendida en esta Prestadora. Sin proveedor no puede estar en verdadero.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_notificaciones" (
    "evento" "text" NOT NULL,
    "descripcion" "text" NOT NULL,
    "emails" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "whatsapp_activo" boolean DEFAULT false NOT NULL,
    "notificar_cliente" boolean DEFAULT false NOT NULL,
    "plantilla_whatsapp_id" "uuid",
    "mensaje_de_texto_activo" boolean DEFAULT false NOT NULL
);


ALTER TABLE "public"."configuracion_notificaciones" OWNER TO "postgres";


COMMENT ON COLUMN "public"."configuracion_notificaciones"."descripcion" IS 'Texto histórico, en español, de cuando la lista de avisos vivía en esta tabla. El Panel ya no lo muestra: el nombre y la explicación de cada aviso salen traducidos de panel/src/i18n/translations.js, y la lista de avisos que existen es la de backend/src/utils/catalogoAvisos.js. Se conserva como respaldo por si llegara una fila de un aviso que el catálogo no conoce.';



COMMENT ON COLUMN "public"."configuracion_notificaciones"."plantilla_whatsapp_id" IS 'Con qué plantilla aprobada sale este aviso por WhatsApp. Nulo mientras la Prestadora no eligió ninguna, y entonces el aviso sale por correo.';



COMMENT ON COLUMN "public"."configuracion_notificaciones"."mensaje_de_texto_activo" IS 'Si este aviso sale tambien por mensaje de texto. Respaldo de WhatsApp: se intenta despues de WhatsApp y antes del correo. Encenderla no alcanza si la Prestadora no tiene proveedor cargado.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_pago_asistentes" (
