    "dominio" "text",
    "zona_cobertura_texto" "text",
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "telefono_emergencias" "text"
);


ALTER TABLE "public"."configuracion_prestadora" OWNER TO "postgres";


COMMENT ON COLUMN "public"."configuracion_prestadora"."dominio" IS 'La direccion por la que entra esta Prestadora. Se le asigna sola al darla de alta, es unica y no cambia nunca.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_reclutamiento" (
    "prestadora_id" "uuid" NOT NULL,
    "responsable_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."configuracion_reclutamiento" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."configuracion_referencias_laborales" (
    "prestadora_id" "uuid" NOT NULL,
    "minimo_verificadas" smallint DEFAULT 2 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "configuracion_referencias_laborales_minimo_razonable" CHECK ((("minimo_verificadas" >= 0) AND ("minimo_verificadas" <= 5)))
);


ALTER TABLE "public"."configuracion_referencias_laborales" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_referencias_laborales" IS 'Cuántas referencias laborales verificadas espera cada Prestadora antes de incorporar a un Asistente. Sin fila, no se espera ninguna y no se avisa nada.';



COMMENT ON COLUMN "public"."configuracion_referencias_laborales"."minimo_verificadas" IS 'El tope de cinco es el mismo del formulario de postulación: no se puede exigir más de lo que se puede cargar. En cero, el aviso no aparece nunca.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_respuesta_automatica_whatsapp" (
    "prestadora_id" "uuid" NOT NULL,
    "horas_sin_mensajes_para_terminar" smallint DEFAULT 24 NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "las_horas_estan_en_rango" CHECK ((("horas_sin_mensajes_para_terminar" > 0) AND ("horas_sin_mensajes_para_terminar" <= 720)))
);


ALTER TABLE "public"."configuracion_respuesta_automatica_whatsapp" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_respuesta_automatica_whatsapp" IS 'Cómo se comporta el bot de WhatsApp de cada Prestadora. Sin fila, el bot no vuelve a contestar donde ya contestó una persona.';



COMMENT ON COLUMN "public"."configuracion_respuesta_automatica_whatsapp"."horas_sin_mensajes_para_terminar" IS 'Cuántas horas sin mensajes dan por terminada una conversación que atendió una persona. Pasadas, el bot vuelve a contestar.';



CREATE TABLE IF NOT EXISTS "public"."configuracion_visibilidad_app" (
    "prestadora_id" "uuid" NOT NULL,
    "clave" "text" NOT NULL,
    "visible" boolean NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."configuracion_visibilidad_app" OWNER TO "postgres";


COMMENT ON TABLE "public"."configuracion_visibilidad_app" IS 'Qué muestran las aplicaciones del Cliente y del Asistente en cada Prestadora. Solo guarda lo que se cambió respecto del valor de fábrica; la lista de claves posibles vive en backend/src/utils/catalogoVisibilidad.js.';



COMMENT ON COLUMN "public"."configuracion_visibilidad_app"."clave" IS 'Identificador permanente de la cosa que se prende o se apaga. Nombrado por su función, nunca por la pantalla donde aparece hoy, y no se renombra jamás (CLAUDE.md §7 regla 13).';



CREATE TABLE IF NOT EXISTS "public"."configuracion_whatsapp_prestadora" (
    "prestadora_id" "uuid" NOT NULL,
    "activo" boolean DEFAULT false NOT NULL,
    "numero_telefono" "text",
    "waba_id" "text",
    "phone_number_id" "text",
    "verificado_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."configuracion_whatsapp_prestadora" OWNER TO "postgres";




CREATE TABLE IF NOT EXISTS "public"."consentimientos_asistente" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "clave" "text" NOT NULL,
    "texto_consentimiento_id" "uuid" NOT NULL,
    "version_mostrada" integer NOT NULL,
    "idioma_mostrado" "text" NOT NULL,
    "texto_mostrado" "text" NOT NULL,
    "decision" "text" NOT NULL,
    "decidido_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "retirado_at" timestamp with time zone,
    "motivo_retiro" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "consentimientos_asistente_decision_check" CHECK (("decision" = ANY (ARRAY['otorgado'::"text", 'rechazado'::"text"]))),
    CONSTRAINT "consentimientos_asistente_retiro_coherente" CHECK ((("retirado_at" IS NULL) OR ("decision" = 'otorgado'::"text")))
);


ALTER TABLE "public"."consentimientos_asistente" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."consentimientos_medicacion" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "indicacion_id" "uuid" NOT NULL,
    "documento_texto" "text" NOT NULL,
    "documento_verificador" "text" NOT NULL,
    "documento_idioma" "text" NOT NULL,
    "estado" "text" DEFAULT 'pendiente_firma'::"text" NOT NULL,
    "cerrado_como" "text",
    "cerrado_en" timestamp with time zone,
    "cerrado_desde" "text",
    "archivo_firmado_url" "text",
    "firmante_persona_id" "uuid",
    "firmante_nombre" "text",
    "cargado_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "consentimientos_medicacion_cerrado_como_check" CHECK ((("cerrado_como" IS NULL) OR ("cerrado_como" = ANY (ARRAY['documento_firmado'::"text", 'confirmado_en_la_app'::"text"])))),
    CONSTRAINT "consentimientos_medicacion_check" CHECK ((("estado" = 'cerrado'::"text") = (("cerrado_como" IS NOT NULL) AND ("cerrado_en" IS NOT NULL)))),
    CONSTRAINT "consentimientos_medicacion_check1" CHECK (((("firmante_persona_id" IS NULL) AND ("firmante_nombre" IS NULL)) OR (("firmante_persona_id" IS NOT NULL) AND ("length"("btrim"("firmante_nombre")) > 0)))),
    CONSTRAINT "consentimientos_medicacion_documento_idioma_check" CHECK (("documento_idioma" = ANY (ARRAY['es-AR'::"text", 'en'::"text", 'pt-BR'::"text"]))),
    CONSTRAINT "consentimientos_medicacion_documento_texto_check" CHECK (("length"("btrim"("documento_texto")) > 0)),
    CONSTRAINT "consentimientos_medicacion_documento_verificador_check" CHECK (("length"("btrim"("documento_verificador")) > 0)),
    CONSTRAINT "consentimientos_medicacion_estado_check" CHECK (("estado" = ANY (ARRAY['pendiente_firma'::"text", 'cerrado'::"text", 'anulado'::"text"])))
);


ALTER TABLE "public"."consentimientos_medicacion" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."consentimientos_paciente_solo" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "turno_guardia_id" "uuid" NOT NULL,
    "paciente_id" "uuid" NOT NULL,
    "quien_consintio" "text" NOT NULL,
    "cliente_id" "uuid",
    "medio" "text" NOT NULL,
    "desde_at" timestamp with time zone NOT NULL,
    "hasta_at" timestamp with time zone NOT NULL,
    "registrado_por" "uuid" NOT NULL,
    "registrado_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "nota" "text",
    CONSTRAINT "consentimientos_paciente_solo_con_nombre" CHECK (("length"("btrim"("quien_consintio")) > 0)),
    CONSTRAINT "consentimientos_paciente_solo_medio_conocido" CHECK (("medio" = ANY (ARRAY['telefono'::"text", 'en_persona'::"text", 'mensaje'::"text", 'correo'::"text"]))),
    CONSTRAINT "consentimientos_paciente_solo_termina_despues" CHECK (("hasta_at" > "desde_at"))
);


ALTER TABLE "public"."consentimientos_paciente_solo" OWNER TO "postgres";


COMMENT ON TABLE public.consentimientos_paciente_solo IS 'El Cliente supo y aceptó que la persona atendida quedara sola durante un rato. Cada permiso cierra, en la misma operación, el turno de guardia del Asistente que se fue, con su motivo.';



COMMENT ON COLUMN "public"."consentimientos_paciente_solo"."quien_consintio" IS 'Nombre de la persona del Cliente con la que se hablo. La cuenta es de todas; quien dijo que si es una.';



COMMENT ON COLUMN "public"."consentimientos_paciente_solo"."hasta_at" IS 'Hasta cuando vale. Obligatorio: un consentimiento sin fin no es un consentimiento.';



COMMENT ON COLUMN "public"."consentimientos_paciente_solo"."nota" IS 'Lo que quedo de la conversacion. Nunca datos de salud de la persona atendida.';



CREATE TABLE IF NOT EXISTS "public"."consentimientos_pagador" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "cliente_id" "uuid" NOT NULL,
    "pagador_persona_id" "uuid" NOT NULL,
    "pagador_nombre" "text" NOT NULL,
    "documento_texto" "text" NOT NULL,
    "documento_verificador" "text" NOT NULL,
    "documento_idioma" "text" NOT NULL,
    "estado" "text" DEFAULT 'pendiente_firma'::"text" NOT NULL,
    "cerrado_como" "text",
    "cerrado_en" timestamp with time zone,
    "cerrado_desde" "text",
    "archivo_firmado_url" "text",
    "cargado_por" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "firmante_persona_id" "uuid",
    "firmante_nombre" "text",
    "firmado_con_email" "text",
    "servicio_id" "uuid" NOT NULL,
    CONSTRAINT "consentimientos_pagador_cerrado_como_conocido" CHECK ((("cerrado_como" IS NULL) OR ("cerrado_como" = ANY (ARRAY['documento_firmado'::"text", 'confirmado_en_la_app'::"text", 'firmado_con_el_enlace'::"text"])))),
    CONSTRAINT "consentimientos_pagador_cierre_coherente" CHECK ((("estado" = 'cerrado'::"text") = (("cerrado_como" IS NOT NULL) AND ("cerrado_en" IS NOT NULL)))),
    CONSTRAINT "consentimientos_pagador_con_nombre" CHECK (("length"("btrim"("pagador_nombre")) > 0)),
    CONSTRAINT "consentimientos_pagador_estado_conocido" CHECK (("estado" = ANY (ARRAY['pendiente_firma'::"text", 'cerrado'::"text", 'anulado'::"text"]))),
    CONSTRAINT "consentimientos_pagador_firmante_entero" CHECK (((("firmante_persona_id" IS NULL) AND ("firmante_nombre" IS NULL)) OR (("firmante_persona_id" IS NOT NULL) AND ("length"("btrim"("firmante_nombre")) > 0))))
);


ALTER TABLE "public"."consentimientos_pagador" OWNER TO "postgres";


COMMENT ON TABLE "public"."consentimientos_pagador" IS 'Que el Pagador asumio la obligacion de pagar esta contratacion, y lo firmo. Sin una fila cerrada no hay Pagador definido.';



COMMENT ON COLUMN "public"."consentimientos_pagador"."pagador_nombre" IS 'Como se llamaba el dia que firmo. El Legajo dice con quien quedo atado; esto, que fue lo que leyo.';



COMMENT ON COLUMN "public"."consentimientos_pagador"."documento_verificador" IS 'Identificador de verificación del texto firmado. Si alguien le mueve una coma, deja de coincidir.';



COMMENT ON COLUMN "public"."consentimientos_pagador"."cerrado_desde" IS 'Con que aparato se cerro. Nunca la direccion de red ni ningun otro dato que no haga falta.';



COMMENT ON COLUMN "public"."consentimientos_pagador"."firmante_persona_id" IS 'El Apoderado que firmo por la entidad. Nulo cuando quien paga es una persona fisica y firma ella.';



COMMENT ON COLUMN "public"."consentimientos_pagador"."firmante_nombre" IS 'Cómo se llamaba el Apoderado el día que firmó. Si mañana la entidad cambia de Apoderado, el documento sigue diciendo quién lo firmó.';



CREATE TABLE IF NOT EXISTS "public"."constancias_de_revision_del_registro_de_accesos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "desde" "date" NOT NULL,
    "hasta" "date" NOT NULL,
    "revisado_por" "uuid" NOT NULL,
    "revisado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "observaciones" "text",
    CONSTRAINT "constancias_de_revision_observaciones_validas" CHECK ((("observaciones" IS NULL) OR (("btrim"("observaciones") <> ''::"text") AND ("char_length"("observaciones") <= 2000)))),
    CONSTRAINT "constancias_de_revision_periodo_valido" CHECK (("desde" <= "hasta"))
);


ALTER TABLE "public"."constancias_de_revision_del_registro_de_accesos" OWNER TO "postgres";



COMMENT ON TABLE "public"."constancias_de_revision_del_registro_de_accesos" IS 'Constancia de que la administración de la Prestadora revisó el registro de accesos a la información de salud de un período. No se edita ni se borra.';



CREATE TABLE IF NOT EXISTS "public"."consultas_de_relevo" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "incidente_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "rol" "text" NOT NULL,
    "consultado_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "respuesta" "text",
    "minutos_que_indica" integer,
    "minutos_por_gps" integer,
    "respondido_at" timestamp with time zone,
    "avisado_del_cierre_at" timestamp with time zone,
    CONSTRAINT "consultas_de_relevo_check" CHECK ((("respuesta" IS DISTINCT FROM 'disponible'::"text") OR ("minutos_que_indica" IS NOT NULL))),
    CONSTRAINT "consultas_de_relevo_check1" CHECK ((("respuesta" IS NULL) = ("respondido_at" IS NULL))),
    CONSTRAINT "consultas_de_relevo_minutos_por_gps_check" CHECK (("minutos_por_gps" >= 0)),
    CONSTRAINT "consultas_de_relevo_minutos_que_indica_check" CHECK (("minutos_que_indica" >= 0)),
    CONSTRAINT "consultas_de_relevo_respuesta_check" CHECK (("respuesta" = ANY (ARRAY['disponible'::"text", 'no_disponible'::"text"]))),
    CONSTRAINT "consultas_de_relevo_rol_check" CHECK (("rol" = ANY (ARRAY['suplente'::"text", 'franquero'::"text", 'emergencia'::"text"])))
);


ALTER TABLE "public"."consultas_de_relevo" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."contactos_vistos_intermediacion" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "cliente_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "acceso_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."contactos_vistos_intermediacion" OWNER TO "postgres";


COMMENT ON TABLE "public"."contactos_vistos_intermediacion" IS 'Qué Asistentes tiene ya abiertos un Cliente, y con qué acceso los pagó. Es lo que hace que el saldo del paquete se descuente de a un Asistente y no de a una mirada. docs/PRD_07_Modalidad_Match.md §3.3.';



CREATE TABLE IF NOT EXISTS "public"."contenidos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "titulo" "text" NOT NULL,
    "cuerpo" "text" NOT NULL,
    "enlace_url" "text",
    "orden" integer DEFAULT 0 NOT NULL,
    "publicado" boolean DEFAULT false NOT NULL,
    "creado_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "destinatarios" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    CONSTRAINT "contenidos_cuerpo_con_texto" CHECK (("btrim"("cuerpo") <> ''::"text")),
    CONSTRAINT "contenidos_destinatarios_conocidos" CHECK (("destinatarios" <@ ARRAY['clientes'::"text", 'asistentes'::"text", 'personal'::"text"])),
    CONSTRAINT "contenidos_enlace_es_https" CHECK ((("enlace_url" IS NULL) OR ("enlace_url" ~ '^https://'::"text"))),
    CONSTRAINT "contenidos_publicado_con_destinatarios" CHECK (((NOT "publicado") OR ("cardinality"("destinatarios") > 0))),
    CONSTRAINT "contenidos_titulo_con_texto" CHECK (("btrim"("titulo") <> ''::"text"))
);


ALTER TABLE "public"."contenidos" OWNER TO "postgres";


COMMENT ON TABLE "public"."contenidos" IS 'La biblioteca que cada Prestadora escribe para su gente: Clientes, Asistentes y su propio personal. Sin siembra de fábrica y sin traducción: lo escribe la Prestadora.';



COMMENT ON COLUMN "public"."contenidos"."titulo" IS 'Título tal como lo escribió la Prestadora. No se traduce.';



COMMENT ON COLUMN "public"."contenidos"."cuerpo" IS 'Texto tal como lo escribió la Prestadora. No se traduce.';



COMMENT ON COLUMN "public"."contenidos"."enlace_url" IS 'Enlace opcional a material que la Prestadora ya publica en otro lado. Siempre https://. Acá no se guardan archivos.';



COMMENT ON COLUMN "public"."contenidos"."orden" IS 'En qué orden se muestran. A igual número, manda la fecha de creación.';



COMMENT ON COLUMN "public"."contenidos"."publicado" IS 'Si la ven sus destinatarios. Sin publicar, la pieza existe solamente para quien escribe contenidos.';



COMMENT ON COLUMN "public"."contenidos"."destinatarios" IS 'Quiénes ven la pieza una vez publicada: clientes, asistentes, personal. Uno o más.';



CREATE TABLE IF NOT EXISTS "public"."contenidos_archivos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "contenido_id" "uuid" NOT NULL,
    "ruta" "text" NOT NULL,
    "nombre" "text" NOT NULL,
    "tipo" "text" NOT NULL,
    "tamano" bigint NOT NULL,
    "subido_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "contenidos_archivos_nombre_con_texto" CHECK (("btrim"("nombre") <> ''::"text")),
    CONSTRAINT "contenidos_archivos_ruta_de_su_prestadora" CHECK ((("split_part"("ruta", '/'::"text", 1) = ("prestadora_id")::"text") AND ("split_part"("ruta", '/'::"text", 2) = ("contenido_id")::"text"))),
    CONSTRAINT "contenidos_archivos_tamano_permitido" CHECK ((("tamano" > 0) AND ("tamano" <= 10485760)))
);


ALTER TABLE "public"."contenidos_archivos" OWNER TO "postgres";


COMMENT ON TABLE "public"."contenidos_archivos" IS 'Los archivos que la Prestadora sube a una pieza de Contenidos. Los ve quien ve la pieza.';



COMMENT ON COLUMN "public"."contenidos_archivos"."ruta" IS 'Dónde quedó en el depósito contenidos-archivos: <prestadora>/<contenido>/<identificador>.<extensión>.';



COMMENT ON COLUMN "public"."contenidos_archivos"."nombre" IS 'El nombre con el que se subió, para mostrarlo y para la descarga.';



CREATE TABLE IF NOT EXISTS "public"."conversaciones_intermediacion" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "cliente_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ultimo_mensaje_at" timestamp with time zone,
    "sala_videollamada" "text",
    "sala_abierta_at" timestamp with time zone
);


ALTER TABLE "public"."conversaciones_intermediacion" OWNER TO "postgres";


COMMENT ON TABLE "public"."conversaciones_intermediacion" IS 'El hilo entre un Cliente y un Asistente de Match, antes de contratarlo. Una por pareja. El chat es libre; lo que se cobra es el dato de contacto, que viaja tapado hasta que ese contacto se abre.';



CREATE TABLE IF NOT EXISTS "public"."conversaciones_whatsapp" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "telefono" "text" NOT NULL,
    "asistente_id" "uuid",
    "ultimo_mensaje_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "requiere_atencion_coordinador" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "atendida_por_una_persona_at" timestamp with time zone
);


ALTER TABLE "public"."conversaciones_whatsapp" OWNER TO "postgres";


COMMENT ON COLUMN "public"."conversaciones_whatsapp"."atendida_por_una_persona_at" IS 'Cuándo contestó una persona desde el Panel por última vez. Mientras tenga valor y la conversación no se haya dado por terminada, el bot no contesta.';



CREATE TABLE IF NOT EXISTS "public"."correcciones_factura_cliente" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "factura_id" "uuid" NOT NULL,
    "sentido" "text" NOT NULL,
    "monto" numeric(12,2) NOT NULL,
    "comprobante_tipo" "text" NOT NULL,
    "comprobante_numero" "text",
    "motivo" "text" NOT NULL,
    "fecha" "date" NOT NULL,
    "registrada_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "moneda" "public"."moneda_iso",
    CONSTRAINT "correcciones_factura_cliente_comprobante_tipo_check" CHECK (("length"("btrim"("comprobante_tipo")) > 0)),
    CONSTRAINT "correcciones_factura_cliente_monto_check" CHECK (("monto" > (0)::numeric)),
    CONSTRAINT "correcciones_factura_cliente_motivo_check" CHECK (("length"("btrim"("motivo")) > 0)),
    CONSTRAINT "correcciones_factura_cliente_sentido_check" CHECK (("sentido" = ANY (ARRAY['resta'::"text", 'suma'::"text"])))
);


ALTER TABLE "public"."correcciones_factura_cliente" OWNER TO "postgres";


COMMENT ON TABLE "public"."correcciones_factura_cliente" IS 'Los comprobantes que corrigen una factura ya emitida. El tipo es texto del software de facturacion y no se interpreta; lo unico que se usa es el sentido y el monto.';



COMMENT ON COLUMN "public"."correcciones_factura_cliente"."sentido" IS 'Que le hace al saldo: resta cuando se facturo de mas, suma cuando se facturo de menos.';



COMMENT ON COLUMN "public"."correcciones_factura_cliente"."motivo" IS 'Por que se corrigio. Obligatorio: una correccion sin explicacion no se puede revisar despues.';



CREATE TABLE IF NOT EXISTS "public"."cortes_de_consultas_a_hce" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "anio" integer NOT NULL,
    "hasta_numero" bigint NOT NULL,
    "ultimo_resumen" "bytea" NOT NULL,
    "renglones" bigint NOT NULL,
    "momento" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "cortes_de_consultas_a_hce_hasta_numero_check" CHECK (("hasta_numero" >= 1)),
    CONSTRAINT "cortes_de_consultas_a_hce_renglones_check" CHECK (("renglones" >= 0))
);


ALTER TABLE "public"."cortes_de_consultas_a_hce" OWNER TO "postgres";



CREATE TABLE IF NOT EXISTS "public"."datos_bancarios_asistente" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "pais" "text" NOT NULL,
    "identificador_clase" "text" NOT NULL,
    "identificador" "text" NOT NULL,
    "banco" "text",
    "titular" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "el_identificador_de_la_cuenta_no_esta_vacio" CHECK (("length"("btrim"("identificador")) > 0))
);


ALTER TABLE "public"."datos_bancarios_asistente" OWNER TO "postgres";


COMMENT ON TABLE "public"."datos_bancarios_asistente" IS 'Adonde se le paga a cada Asistente. Dato sensible: vive aparte de la ficha porque la proteccion por fila filtra filas y no columnas. No se registra, no viaja en ninguna direccion y no aparece en ningun mensaje de error.';



COMMENT ON COLUMN "public"."datos_bancarios_asistente"."identificador" IS 'El numero con el que se identifica la cuenta. Nunca se muestra en un registro ni en un mensaje.';



CREATE TABLE IF NOT EXISTS "public"."datos_reservados_asistente" (
    "asistente_id" "uuid" NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "motivo_exclusion_directo" "text",
    "motivo_exclusion_intermediacion" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."datos_reservados_asistente" OWNER TO "postgres";


COMMENT ON TABLE "public"."datos_reservados_asistente" IS 'Lo reservado de la ficha del Asistente: por qué se lo dio de baja, su puntaje de riesgo con los motivos que lo forman, y por qué quedó excluido de recibir trabajo. Vive separado de `asistentes` porque las reglas de acceso de la base filtran filas, no columnas: solo en una tabla propia se puede exigir el permiso `ver_datos_reservados_asistente` para leerlo.';



CREATE TABLE IF NOT EXISTS "public"."desafios_de_llave" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "desafio" "text" NOT NULL,
    "para" "text" NOT NULL,
    "rol" "text" NOT NULL,
    "prestadora_id" "uuid",
    "usuario_id" "uuid",
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "vence_en" timestamp with time zone NOT NULL,
    "usado_en" timestamp with time zone,
    CONSTRAINT "desafios_de_llave_el_alta_sabe_de_quien_es" CHECK ((("para" <> 'alta'::"text") OR (("prestadora_id" IS NOT NULL) AND ("usuario_id" IS NOT NULL)))),
    CONSTRAINT "desafios_de_llave_la_firma_sabe_de_quien_es" CHECK ((("para" <> 'firma'::"text") OR (("prestadora_id" IS NOT NULL) AND ("usuario_id" IS NOT NULL)))),
    CONSTRAINT "desafios_de_llave_para_check" CHECK (("para" = ANY (ARRAY['alta'::"text", 'entrada'::"text", 'firma'::"text"]))),
    CONSTRAINT "desafios_de_llave_rol_check" CHECK (("rol" = ANY (ARRAY['asistente'::"text", 'cliente'::"text"])))
);


ALTER TABLE "public"."desafios_de_llave" OWNER TO "postgres";


COMMENT ON TABLE "public"."desafios_de_llave" IS 'Numeros al azar de un solo uso que el telefono firma para probar que tiene la llave. Vencen a los pocos minutos y quedan marcados al usarse, para que una firma grabada no sirva dos veces.';



COMMENT ON COLUMN "public"."desafios_de_llave"."para" IS 'Si es para agregar una llave nueva -con la sesion ya abierta- o para entrar.';



COMMENT ON COLUMN "public"."desafios_de_llave"."prestadora_id" IS 'Queda nulo en los desafios de entrada: ahi todavia no se sabe quien esta entrando. En los de alta es obligatorio, porque la sesion ya lo dice.';



COMMENT ON COLUMN "public"."desafios_de_llave"."usado_en" IS 'Cuando se gasto. Un desafio usado no vuelve a servir, aunque no haya vencido.';



CREATE TABLE IF NOT EXISTS "public"."descansos_turno_guardia" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "turno_guardia_id" "uuid" NOT NULL,
    "inicio_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "fin_at" timestamp with time zone,
    "registrado_por" "uuid" NOT NULL,
    "nota" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "cliente_uuid" "uuid",
    "cliente_uuid_fin" "uuid",
    CONSTRAINT "descansos_turno_guardia_fin_despues_del_inicio" CHECK ((("fin_at" IS NULL) OR ("fin_at" > "inicio_at")))
);


ALTER TABLE "public"."descansos_turno_guardia" OWNER TO "postgres";


COMMENT ON TABLE "public"."descansos_turno_guardia" IS 'Los ratos de descanso que la Asistente toma adentro de un turno de guardia largo, sin dejar de estar disponible. No se descuenta de lo que se le paga, no interrumpe el turno de guardia y no la saca del turno de guardia: no es una ausencia.';



COMMENT ON COLUMN "public"."descansos_turno_guardia"."inicio_at" IS 'Cuando paso, no cuando se pudo enviar. Un aviso guardado en la cola sin conexion conserva el momento del telefono.';



COMMENT ON COLUMN "public"."descansos_turno_guardia"."fin_at" IS 'En blanco mientras el descanso sigue abierto.';



COMMENT ON COLUMN "public"."descansos_turno_guardia"."cliente_uuid" IS 'El identificador que pone el telefono antes del primer intento, para el que abre el descanso. Dos llegadas con el mismo identificador son el mismo hecho.';



COMMENT ON COLUMN "public"."descansos_turno_guardia"."cliente_uuid_fin" IS 'El identificador del aviso que cerro el descanso. Un reenvio del cierre se reconoce por aca y no vuelve a escribir la hora de fin.';



CREATE TABLE IF NOT EXISTS "public"."descuentos_del_servicio" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "servicio_id" "uuid" NOT NULL,
    "clase" "text" NOT NULL,
    "valor" numeric(14,2) NOT NULL,
    "moneda" "text",
    "vigente_desde" "date" NOT NULL,
    "cantidad_de_periodos" integer,
    "vigente_hasta" "date",
    "motivo" "text",
    "cargado_por" "uuid",
    "cargado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "terminado_por" "uuid",
    "terminado_en" timestamp with time zone,
    CONSTRAINT "descuentos_del_servicio_clase_conocida" CHECK (("clase" = ANY (ARRAY['porcentaje'::"text", 'monto'::"text"]))),
    CONSTRAINT "descuentos_del_servicio_fechas_en_orden" CHECK ((("vigente_hasta" IS NULL) OR ("vigente_hasta" >= "vigente_desde"))),
    CONSTRAINT "descuentos_del_servicio_moneda_del_monto" CHECK ((("clase" = 'monto'::"text") = ("moneda" IS NOT NULL))),
    CONSTRAINT "descuentos_del_servicio_moneda_escrita" CHECK ((("moneda" IS NULL) OR ("moneda" ~ '^[A-Z]{3}$'::"text"))),
    CONSTRAINT "descuentos_del_servicio_motivo_escrito" CHECK ((("motivo" IS NULL) OR (("btrim"("motivo") <> ''::"text") AND ("char_length"("motivo") <= 500)))),
    CONSTRAINT "descuentos_del_servicio_periodos_razonables" CHECK ((("cantidad_de_periodos" IS NULL) OR (("cantidad_de_periodos" >= 1) AND ("cantidad_de_periodos" <= 999)))),
    CONSTRAINT "descuentos_del_servicio_porcentaje_hasta_cien" CHECK ((("clase" <> 'porcentaje'::"text") OR ("valor" <= (100)::numeric))),
    CONSTRAINT "descuentos_del_servicio_terminacion_completa" CHECK ((("terminado_en" IS NULL) = ("terminado_por" IS NULL))),
    CONSTRAINT "descuentos_del_servicio_un_solo_fin" CHECK (("num_nonnulls"("cantidad_de_periodos", "vigente_hasta") <= 1)),
    CONSTRAINT "descuentos_del_servicio_valor_positivo" CHECK (("valor" > (0)::numeric))
);


ALTER TABLE "public"."descuentos_del_servicio" OWNER TO "postgres";


COMMENT ON TABLE "public"."descuentos_del_servicio" IS 'Descuentos a un Cliente en su Servicio: porcentaje o monto con su moneda, desde una fecha, por N períodos de facturación, hasta una fecha o sin fin. No se borran: se terminan. Los aplica descuentosDelPeriodo.js.';



CREATE TABLE IF NOT EXISTS "public"."documentos_asistente" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "tipo_documento_id" "uuid" NOT NULL,
    "fecha_vencimiento" "date",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "ruta_archivo" "text",
    "estado" "text" DEFAULT 'en_revision'::"text" NOT NULL,
    "motivo_observacion" "text",
    "revisado_por" "uuid",
    "revisado_at" timestamp with time zone,
    "cargado_por" "uuid",
    "fecha_emision" "date",
    "numero" "text",
    "organismo_id" "uuid",
    CONSTRAINT "documentos_asistente_estado_check" CHECK (("estado" = ANY (ARRAY['falta'::"text", 'en_revision'::"text", 'aprobado'::"text", 'observado'::"text"]))),
    CONSTRAINT "documentos_asistente_observado_con_motivo" CHECK ((("estado" <> 'observado'::"text") OR ("btrim"(COALESCE("motivo_observacion", ''::"text")) <> ''::"text")))
);


ALTER TABLE "public"."documentos_asistente" OWNER TO "postgres";


COMMENT ON COLUMN "public"."documentos_asistente"."ruta_archivo" IS 'Dónde está el documento dentro del depósito «documentos-asistente». Es la ruta, no un enlace: lo que hay en este depósito se abre sólo con enlace temporal.';



COMMENT ON COLUMN "public"."documentos_asistente"."estado" IS 'falta, en_revision, aprobado u observado. «Por vencer» y «Vencido» salen de la fecha de vencimiento, no se guardan.';



COMMENT ON COLUMN "public"."documentos_asistente"."motivo_observacion" IS 'Por qué la Prestadora lo observó. Se le muestra al Asistente.';



COMMENT ON COLUMN "public"."documentos_asistente"."revisado_por" IS 'Quién lo aprobó u observó.';



COMMENT ON COLUMN "public"."documentos_asistente"."cargado_por" IS 'Quién lo subió: el Asistente o alguien de la Prestadora.';



COMMENT ON COLUMN "public"."documentos_asistente"."fecha_emision" IS 'Fecha de emisión, cuando el tipo vence por plazo desde la emisión.';



COMMENT ON COLUMN "public"."documentos_asistente"."numero" IS 'Número del documento, cuando el tipo lleva número.';



COMMENT ON COLUMN "public"."documentos_asistente"."organismo_id" IS 'Quién lo otorgó. Sale de los organismos marcados para ese tipo.';



CREATE TABLE IF NOT EXISTS "public"."documentos_pagador" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "cliente_id" "uuid" NOT NULL,
    "tipo_documento_id" "uuid" NOT NULL,
    "archivo_url" "text",
    "fecha_vencimiento" "date",
    "cargado_por" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "servicio_id" "uuid" NOT NULL
);


ALTER TABLE "public"."documentos_pagador" OWNER TO "postgres";


COMMENT ON TABLE "public"."documentos_pagador" IS 'Los documentos que el Pagador exigió para esta contratación, cargados. Uno por Cliente y por tipo.';



CREATE TABLE IF NOT EXISTS "public"."tipos_documento_asistente" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "nombre" "text" NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "vencimiento" "text" DEFAULT 'fecha_del_documento'::"text" NOT NULL,
    "periodo_cantidad" integer,
    "periodo_unidad" "text",
    "lleva_numero" boolean DEFAULT false NOT NULL,
    "requisitos" "text",
    "enlace_para_obtenerlo" "text",
    "impide_trabajar" boolean DEFAULT false NOT NULL,
    "dias_de_gracia" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "tipos_documento_asistente_dias_de_gracia_check" CHECK (("dias_de_gracia" >= 0)),
    CONSTRAINT "tipos_documento_asistente_plazo_completo" CHECK (((("periodo_cantidad" IS NULL) = ("periodo_unidad" IS NULL)) AND (("periodo_cantidad" IS NULL) OR ("periodo_cantidad" > 0)) AND (("vencimiento" = 'plazo_desde_emision'::"text") = ("periodo_cantidad" IS NOT NULL)))),
    CONSTRAINT "tipos_documento_asistente_vencimiento_check" CHECK (("vencimiento" = ANY (ARRAY['no_vence'::"text", 'fecha_del_documento'::"text", 'plazo_desde_emision'::"text"])))
);


ALTER TABLE "public"."tipos_documento_asistente" OWNER TO "postgres";


COMMENT ON COLUMN "public"."tipos_documento_asistente"."vencimiento" IS 'Cómo vence: no_vence; fecha_del_documento (la carga quien sube el documento); plazo_desde_emision (la calcula la base desde la fecha de emisión).';



COMMENT ON COLUMN "public"."tipos_documento_asistente"."periodo_cantidad" IS 'Con plazo desde la emisión, cuántas unidades dura el documento.';



COMMENT ON COLUMN "public"."tipos_documento_asistente"."periodo_unidad" IS 'Con plazo desde la emisión, la unidad de tiempo. Sale del mismo catálogo que las formas de cobro.';



COMMENT ON COLUMN "public"."tipos_documento_asistente"."lleva_numero" IS 'Si quien lo carga tiene que escribir el número del documento.';



COMMENT ON COLUMN "public"."tipos_documento_asistente"."requisitos" IS 'Lo que se mira a ojo al revisar el documento. Se le muestra al Asistente al cargarlo.';



COMMENT ON COLUMN "public"."tipos_documento_asistente"."enlace_para_obtenerlo" IS 'Dónde se tramita el documento. Se le muestra al Asistente al cargarlo.';



COMMENT ON COLUMN "public"."tipos_documento_asistente"."impide_trabajar" IS 'Si falta o no vale, el Asistente no recibe turnos de guardia, salvo los días de gracia y la excepción de a un turno de guardia.';



COMMENT ON COLUMN "public"."tipos_documento_asistente"."dias_de_gracia" IS 'Días desde que el documento deja de valer en que el Asistente sigue con los Pacientes que ya atendía.';



CREATE TABLE IF NOT EXISTS "public"."tipos_documento_por_tipo_asistente" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "tipo_documento_id" "uuid" NOT NULL,
    "tipo_asistente_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."tipos_documento_por_tipo_asistente" OWNER TO "postgres";


COMMENT ON TABLE "public"."tipos_documento_por_tipo_asistente" IS 'A qué tipos de Asistente se pide cada documento («Se pide a»).';



CREATE OR REPLACE VIEW "public"."documentos_pedidos_al_asistente" WITH ("security_invoker"='true') AS
 SELECT "a"."id" AS "asistente_id",
    "a"."prestadora_id",
    "t"."id" AS "tipo_documento_id",
    "t"."nombre",
    "t"."impide_trabajar",
    "u"."id" AS "documento_id",
    COALESCE("u"."estado", 'falta'::"text") AS "estado",
    "u"."fecha_vencimiento",
    "u"."motivo_observacion",
    "interno"."gracia_hasta"("a"."id", "t"."id", "interno"."hoy_de_la_prestadora"("a"."prestadora_id")) AS "gracia_hasta"
   FROM ((("public"."asistentes" "a"
     JOIN "public"."tipos_documento_por_tipo_asistente" "r" ON ((("r"."tipo_asistente_id" = "a"."tipo_asistente_id") AND ("r"."prestadora_id" = "a"."prestadora_id"))))
     JOIN "public"."tipos_documento_asistente" "t" ON ((("t"."id" = "r"."tipo_documento_id") AND "t"."activo")))
     LEFT JOIN LATERAL ( SELECT "d"."id",
            "d"."estado",
            "d"."fecha_vencimiento",
            "d"."motivo_observacion"
           FROM "public"."documentos_asistente" "d"
          WHERE (("d"."asistente_id" = "a"."id") AND ("d"."tipo_documento_id" = "t"."id"))
          ORDER BY "d"."created_at" DESC
         LIMIT 1) "u" ON (true))
  WHERE ("a"."deleted_at" IS NULL);


ALTER VIEW "public"."documentos_pedidos_al_asistente" OWNER TO "postgres";


COMMENT ON VIEW "public"."documentos_pedidos_al_asistente" IS 'Cada documento que se le pide a cada Asistente, con el último cargado. gracia_hasta viene vacía si el documento vale o nunca tuvo uno aprobado.';



