);


ALTER TABLE "public"."etapas_incorporacion_asistente" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."excepciones_familiar_relevo" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "incidente_id" "uuid",
    "registrado_por" "uuid" NOT NULL,
    "motivo" "text",
    "desde_at" timestamp with time zone NOT NULL,
    "hasta_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "turno_guardia_id" "uuid" NOT NULL,
    "origen" "text" NOT NULL,
    "familiar_persona_id" "uuid",
    CONSTRAINT "excepciones_familiar_relevo_origen_conocido" CHECK (("origen" = ANY (ARRAY['relevo'::"text", 'turno_guardia_sin_cubrir'::"text", 'extension'::"text"]))),
    CONSTRAINT "excepciones_familiar_relevo_termina_despues" CHECK ((("hasta_at" IS NULL) OR ("hasta_at" >= "desde_at")))
);


ALTER TABLE "public"."excepciones_familiar_relevo" OWNER TO "postgres";


COMMENT ON TABLE "public"."excepciones_familiar_relevo" IS 'Un familiar termino cuidando porque la Prestadora no mando a nadie. Es un defecto grave del servicio que no se pudo solucionar, nunca un turno de guardia cubierto: no cierra el turno de guardia ni lo cuenta como prestado.';



COMMENT ON COLUMN "public"."excepciones_familiar_relevo"."registrado_por" IS 'Quien de la Prestadora dejo escrito el hecho. No lo autorizo: a un familiar no se le pide que se quede.';



COMMENT ON COLUMN "public"."excepciones_familiar_relevo"."hasta_at" IS 'Cuando volvio a haber personal en esa casa. Vacio mientras siga sin haberlo.';



COMMENT ON COLUMN "public"."excepciones_familiar_relevo"."origen" IS 'Por cual de los tres caminos el turno de guardia quedo sin nadie: relevo, turno_guardia_sin_cubrir o extension.';



COMMENT ON COLUMN "public"."excepciones_familiar_relevo"."familiar_persona_id" IS 'Cual Legajo del Padron es el familiar que se quedo cubriendo. Es siempre una Persona fisica. Admite vacio solo por las filas que ya estaban cargadas: en el alta lo exige el disparador.';



CREATE TABLE IF NOT EXISTS "public"."excepciones_por_documentos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "turno_guardia_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "usuario_id" "uuid" NOT NULL,
    "motivo" "text" NOT NULL,
    "documentos" "text"[] NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "excepciones_por_documentos_motivo_check" CHECK (("btrim"("motivo") <> ''::"text"))
);


ALTER TABLE "public"."excepciones_por_documentos" OWNER TO "postgres";


COMMENT ON TABLE "public"."excepciones_por_documentos" IS 'Turnos de guardia asignados con documentos pendientes: quién, a quién, por qué y qué documentos faltaban. Vale sólo para ese turno de guardia y ese Asistente. No se borra.';



CREATE TABLE IF NOT EXISTS "public"."extensiones_de_turno_guardia" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "turno_guardia_id" "uuid" NOT NULL,
    "relevo_turno_guardia_id" "uuid",
    "desde_at" timestamp with time zone NOT NULL,
    "hasta_at" timestamp with time zone,
    "ultima_notificacion_at" timestamp with time zone,
    "veces_notificado" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "extensiones_de_turno_guardia_termina_despues" CHECK ((("hasta_at" IS NULL) OR ("hasta_at" >= "desde_at")))
);


ALTER TABLE "public"."extensiones_de_turno_guardia" OWNER TO "postgres";


COMMENT ON TABLE "public"."extensiones_de_turno_guardia" IS 'El rato que una Asistente se queda adentro despues de que termino su turno de guardia porque el relevo no llego. Se abre sola y se cierra cuando llega el relevo o cuando ella cierra el turno de guardia. De aca salen las horas de mas.';



COMMENT ON COLUMN "public"."extensiones_de_turno_guardia"."desde_at" IS 'La hora de fin de su propio turno de guardia, no cuando el sistema se dio cuenta.';



CREATE TABLE IF NOT EXISTS "public"."facturas_cliente" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "cliente_id" "uuid" NOT NULL,
    "periodo" "date" NOT NULL,
    "monto_total" numeric(12,2) DEFAULT 0 NOT NULL,
    "estado" "text" DEFAULT 'pendiente'::"text" NOT NULL,
    "fecha_emision" "date" NOT NULL,
    "fecha_vencimiento" "date",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "moneda" "public"."moneda_iso" NOT NULL,
    "monto_facturado" numeric(12,2),
    "comprobante_tipo" "text",
    "comprobante_numero" "text",
    "facturado_at" timestamp with time zone,
    "comprobante_archivo" "text",
    "comprobante_subido_at" timestamp with time zone,
    "servicio_id" "uuid" NOT NULL,
    "periodo_hasta" "date" NOT NULL,
    CONSTRAINT "facturas_cliente_estado_check" CHECK (("estado" = ANY (ARRAY['pendiente'::"text", 'pagada'::"text", 'vencida'::"text"]))),
    CONSTRAINT "facturas_cliente_monto_facturado_check" CHECK ((("monto_facturado" IS NULL) OR ("monto_facturado" >= (0)::numeric))),
    CONSTRAINT "facturas_cliente_periodo_en_orden" CHECK (("periodo_hasta" >= "periodo"))
);


ALTER TABLE "public"."facturas_cliente" OWNER TO "postgres";


COMMENT ON COLUMN "public"."facturas_cliente"."periodo" IS 'Primer día del período que cubre la factura, incluido.';



COMMENT ON COLUMN "public"."facturas_cliente"."monto_total" IS 'Lo que el sistema calculo sumando los renglones: lo que se manda a facturar. No incluye impuestos.';



COMMENT ON COLUMN "public"."facturas_cliente"."monto_facturado" IS 'Lo que el software de facturacion informo que emitio, con impuestos adentro. Vacio mientras no se haya facturado. Es contra este monto que se mide la cobranza.';



COMMENT ON COLUMN "public"."facturas_cliente"."comprobante_tipo" IS 'Como llama el software de facturacion al comprobante que emitio. Texto que se guarda y no se interpreta: cada pais tiene los suyos y el sistema no conoce ninguno.';



COMMENT ON COLUMN "public"."facturas_cliente"."comprobante_numero" IS 'El numero del comprobante emitido, tal como lo devolvio el software de facturacion.';



COMMENT ON COLUMN "public"."facturas_cliente"."facturado_at" IS 'Cuando se anoto lo que emitio el software de facturacion. Vacio mientras no se haya facturado.';



COMMENT ON COLUMN "public"."facturas_cliente"."periodo_hasta" IS 'Último día del período que cubre la factura, incluido. Sale de la frecuencia de cobro del Servicio.';



CREATE TABLE IF NOT EXISTS "public"."facturas_cliente_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "factura_id" "uuid" NOT NULL,
    "paciente_id" "uuid",
    "descripcion" "text" NOT NULL,
    "monto" numeric(12,2) NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "servicio_id" "uuid",
    "moneda" "public"."moneda_iso" NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "cantidad" numeric(12,2),
    "unidad" "text",
    "precio_unitario" numeric(12,2),
    "descuento_id" "uuid",
    "concepto" "text",
    CONSTRAINT "facturas_cliente_items_cantidad_no_negativa" CHECK ((("cantidad" IS NULL) OR ("cantidad" >= (0)::numeric))),
    CONSTRAINT "facturas_cliente_items_concepto_conocido" CHECK ((("concepto" IS NULL) OR ("concepto" = ANY (ARRAY['pactado'::"text", 'medido'::"text", 'adicional'::"text", 'no_prestado'::"text", 'cancelado_por_el_cliente'::"text", 'descuento'::"text"])))),
    CONSTRAINT "facturas_cliente_items_unidad_conocida" CHECK ((("unidad" IS NULL) OR ("unidad" = ANY (ARRAY['periodo'::"text", 'turno_guardia'::"text", 'hora'::"text", 'hora_extra'::"text", 'dia_de_guardia'::"text"]))))
);


ALTER TABLE "public"."facturas_cliente_items" OWNER TO "postgres";


COMMENT ON COLUMN "public"."facturas_cliente_items"."prestadora_id" IS 'La Prestadora dueña del renglón. Sale de la factura y no puede diferir de ella.';



CREATE TABLE IF NOT EXISTS "public"."feriados_por_pais" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "pais" "text" NOT NULL,
    "fecha" "date" NOT NULL,
    CONSTRAINT "feriados_por_pais_pais_escrito" CHECK (("pais" ~ '^[A-Z]{2}$'::"text"))
);


ALTER TABLE "public"."feriados_por_pais" OWNER TO "postgres";



COMMENT ON TABLE "public"."feriados_por_pais" IS 'Los feriados de cada país. Es catálogo del producto: lo carga una migración, y lo leen todos.';



CREATE TABLE IF NOT EXISTS "public"."finales_turno_guardia_sin_cubrir" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "clave" "text",
    "nombre" "text",
    "es_defecto_grave" boolean DEFAULT false NOT NULL,
    "pide_detalle" boolean DEFAULT false NOT NULL,
    "lo_escribe_el_sistema" boolean DEFAULT false NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "orden" integer DEFAULT 100 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "finales_turno_guardia_sin_cubrir_los_del_sistema_no_se_apagan" CHECK (((NOT "lo_escribe_el_sistema") OR "activo")),
    CONSTRAINT "finales_turno_guardia_sin_cubrir_del_sistema_son_del_producto" CHECK (((NOT "lo_escribe_el_sistema") OR ("clave" IS NOT NULL))),
    CONSTRAINT "finales_turno_guardia_sin_cubrir_nombre_segun_nivel" CHECK (((("clave" IS NOT NULL) AND ("nombre" IS NULL)) OR (("clave" IS NULL) AND ("nombre" IS NOT NULL))))
);


ALTER TABLE "public"."finales_turno_guardia_sin_cubrir" OWNER TO "postgres";


COMMENT ON TABLE "public"."finales_turno_guardia_sin_cubrir" IS 'Como puede terminar el expediente de un turno de guardia que quedo sin nadie. Cada Prestadora arma su lista: nace con los que trae el producto y a partir de ahi agrega y saca los que quiera.';



COMMENT ON COLUMN "public"."finales_turno_guardia_sin_cubrir"."clave" IS 'Final que trajo el producto. El texto visible sale de las traducciones, buscandolo por esta clave; es tambien lo que se guarda en el expediente.';



COMMENT ON COLUMN "public"."finales_turno_guardia_sin_cubrir"."nombre" IS 'Final que escribio la Prestadora. Se muestra tal cual, sin traducir, y es lo que se guarda en el expediente.';



COMMENT ON COLUMN "public"."finales_turno_guardia_sin_cubrir"."es_defecto_grave" IS 'Terminar asi deja escrito que el servicio fallo y no se pudo arreglar. Lo decide la Prestadora, porque solo ella sabe que es una falla en su forma de trabajar.';



COMMENT ON COLUMN "public"."finales_turno_guardia_sin_cubrir"."pide_detalle" IS 'Cerrar con este final obliga a escribir que se hizo.';



COMMENT ON COLUMN "public"."finales_turno_guardia_sin_cubrir"."lo_escribe_el_sistema" IS 'El final no se elige: lo escribe el motor cuando la base ya dice que el turno de guardia termino asi. No se ofrece para elegir y no se puede apagar.';



CREATE TABLE IF NOT EXISTS "public"."formas_de_cobro_intermediacion" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "nombre" "text" NOT NULL,
    "importe" numeric(12,2) NOT NULL,
    "moneda" "public"."moneda_iso" NOT NULL,
    "periodo_cantidad" integer,
    "periodo_unidad" "text",
    "dias_gratis" integer,
    "contactos_incluidos" integer,
    "renueva_sola" boolean DEFAULT false NOT NULL,
    "ofrecida" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "formas_cobro_intermediacion_contactos_positivos" CHECK ((("contactos_incluidos" IS NULL) OR ("contactos_incluidos" > 0))),
    CONSTRAINT "formas_cobro_intermediacion_dias_gratis_no_negativos" CHECK ((("dias_gratis" IS NULL) OR ("dias_gratis" >= 0))),
    CONSTRAINT "formas_cobro_intermediacion_importe_no_negativo" CHECK (("importe" >= (0)::numeric)),
    CONSTRAINT "formas_cobro_intermediacion_periodo_entero" CHECK ((("periodo_cantidad" IS NULL) = ("periodo_unidad" IS NULL))),
    CONSTRAINT "formas_cobro_intermediacion_periodo_positivo" CHECK ((("periodo_cantidad" IS NULL) OR ("periodo_cantidad" > 0))),
    CONSTRAINT "formas_cobro_intermediacion_renueva_con_periodo" CHECK ((("renueva_sola" = false) OR ("periodo_cantidad" IS NOT NULL)))
);


ALTER TABLE "public"."formas_de_cobro_intermediacion" OWNER TO "postgres";


COMMENT ON TABLE "public"."formas_de_cobro_intermediacion" IS 'Cómo cobra cada Prestadora el acceso a los datos de contacto. Las piezas, no los tipos: la forma sale de cómo se combinen. docs/PRD_07_Modalidad_Match.md §3.';



CREATE TABLE IF NOT EXISTS "public"."formulario_campos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "seccion_id" "uuid" NOT NULL,
    "prestadora_id" "uuid",
    "clave" "text" NOT NULL,
    "tipo" "text" NOT NULL,
    "etiqueta" "jsonb" NOT NULL,
    "obligatorio" boolean DEFAULT false NOT NULL,
    "obligatorio_si" "text",
    "no_obligatorio_si" "text",
    "maximo" integer,
    "formatos" "text"[],
    "lista_de_opciones" "text",
    "vigencia" boolean DEFAULT false NOT NULL,
    "orden" integer DEFAULT 100 NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "formulario_campos_etiqueta_completa" CHECK ("interno"."texto_en_los_tres_idiomas"("etiqueta")),
    CONSTRAINT "formulario_campos_formatos_solo_en_archivo" CHECK (((("tipo" = 'archivo'::"text") AND ("formatos" IS NOT NULL) AND ("array_length"("formatos", 1) > 0)) OR (("tipo" <> 'archivo'::"text") AND ("formatos" IS NULL)))),
    CONSTRAINT "formulario_campos_lista_de_opciones_solo_en_lista" CHECK (((("tipo" = ANY (ARRAY['lista'::"text", 'lista_multiple'::"text"])) AND ("lista_de_opciones" IS NOT NULL)) OR (("tipo" <> ALL (ARRAY['lista'::"text", 'lista_multiple'::"text"])) AND ("lista_de_opciones" IS NULL)))),
    CONSTRAINT "formulario_campos_maximo_positivo" CHECK ((("maximo" IS NULL) OR ("maximo" > 0))),
    CONSTRAINT "formulario_campos_tipo_check" CHECK (("tipo" = ANY (ARRAY['texto'::"text", 'texto_largo'::"text", 'fecha'::"text", 'anio'::"text", 'mes_anio'::"text", 'casilla'::"text", 'archivo'::"text", 'telefono'::"text", 'lista'::"text", 'lista_multiple'::"text"]))),
    CONSTRAINT "formulario_campos_una_sola_condicion" CHECK ((("obligatorio_si" IS NULL) OR ("no_obligatorio_si" IS NULL)))
);


ALTER TABLE "public"."formulario_campos" OWNER TO "postgres";


COMMENT ON TABLE "public"."formulario_campos" IS 'Los casilleros de cada sección. No hay columna de ayuda: un casillero lleva su etiqueta y nada más.';



COMMENT ON COLUMN "public"."formulario_campos"."formatos" IS 'Qué formatos de archivo acepta el casillero. Lo que acepta el depósito manda igual: esto no lo amplía.';



COMMENT ON COLUMN "public"."formulario_campos"."lista_de_opciones" IS 'De que lista de opciones elige este casillero. Es la clave de una fila de listas_de_opciones; las opciones salen de la base y nunca escritas adentro de la pantalla.';



CREATE TABLE IF NOT EXISTS "public"."formulario_secciones" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "formulario_id" "uuid" NOT NULL,
    "prestadora_id" "uuid",
    "clave" "text" NOT NULL,
    "titulo" "jsonb" NOT NULL,
    "repetible" boolean DEFAULT false NOT NULL,
    "maximo_repeticiones" integer,
    "obligatoria_cuando" "text",
    "orden" integer DEFAULT 100 NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "formulario_secciones_titulo_completo" CHECK ("interno"."texto_en_los_tres_idiomas"("titulo")),
    CONSTRAINT "formulario_secciones_tope_solo_si_repite" CHECK ((("maximo_repeticiones" IS NULL) OR (("repetible" = true) AND ("maximo_repeticiones" > 0))))
);


ALTER TABLE "public"."formulario_secciones" OWNER TO "postgres";


COMMENT ON COLUMN "public"."formulario_secciones"."obligatoria_cuando" IS 'Vacío: la sección es obligatoria desde que se abre el formulario. Con dato: es la condición que la vuelve obligatoria, escrita como la lee el motor.';



CREATE TABLE IF NOT EXISTS "public"."formularios_declarados" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid",
    "clave" "text" NOT NULL,
    "ambito" "text" NOT NULL,
    "titulo" "jsonb" NOT NULL,
    "orden" integer DEFAULT 100 NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "formularios_declarados_ambito_check" CHECK (("ambito" = ANY (ARRAY['asistente'::"text", 'paciente'::"text", 'cliente'::"text", 'servicio'::"text"]))),
    CONSTRAINT "formularios_declarados_titulo_completo" CHECK ("interno"."texto_en_los_tres_idiomas"("titulo"))
);


ALTER TABLE "public"."formularios_declarados" OWNER TO "postgres";


COMMENT ON TABLE "public"."formularios_declarados" IS 'Qué formularios existen. La pantalla no escribe casilleros a mano: lee de acá y dibuja.';



COMMENT ON COLUMN "public"."formularios_declarados"."prestadora_id" IS 'NULL = formulario que trae el producto, lo ven todas las Prestadoras y ninguna lo puede tocar. Con dato = lo agregó esa Prestadora y sólo lo ve ella.';



COMMENT ON COLUMN "public"."formularios_declarados"."titulo" IS 'El título visible en los tres idiomas: es-AR, en y pt-BR. Una restricción rechaza la fila a la que le falte uno.';




CREATE TABLE IF NOT EXISTS "public"."turno_guardia_comprobaciones" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "turno_guardia_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "momento" "text" NOT NULL,
    "estado" "text" NOT NULL,
    "medio" "text",
    "sujeto_tipo" "text",
    "sujeto_id" "uuid",
    "lat" double precision,
    "lng" double precision,
    "comprobada_en" timestamp with time zone,
    "pedido_en" timestamp with time zone,
    "motivo_sin_comprobar" "text",
    "motivo_detalle" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "autorizada_por" "uuid",
    "motivo_del_pedido" "text",
    "detalle_del_pedido" "text",
    CONSTRAINT "turno_guardia_comprobaciones_autorizacion_check" CHECK ((("medio" = 'autorizacion_prestadora'::"text") = ("autorizada_por" IS NOT NULL))),
    CONSTRAINT "turno_guardia_comprobaciones_coherencia_check" CHECK (((("estado" = 'comprobada'::"text") AND ("medio" IS NOT NULL) AND ("comprobada_en" IS NOT NULL) AND ("motivo_sin_comprobar" IS NULL)) OR (("estado" = 'sin_comprobar'::"text") AND ("motivo_sin_comprobar" IS NOT NULL) AND ("medio" IS NULL)) OR (("estado" = 'pendiente_de_autorizacion'::"text") AND ("medio" IS NULL) AND ("motivo_sin_comprobar" IS NULL) AND ("pedido_en" IS NOT NULL)))),
    CONSTRAINT "turno_guardia_comprobaciones_estado_check" CHECK (("estado" = ANY (ARRAY['pendiente_de_autorizacion'::"text", 'comprobada'::"text", 'sin_comprobar'::"text"]))),
    CONSTRAINT "turno_guardia_comprobaciones_medio_check" CHECK ((("medio" IS NULL) OR ("medio" = ANY (ARRAY['codigo_cliente'::"text", 'codigo_asistente_saliente'::"text", 'autorizacion_prestadora'::"text"])))),
    CONSTRAINT "turno_guardia_comprobaciones_momento_check" CHECK (("momento" = ANY (ARRAY['checkin'::"text", 'checkout'::"text"]))),
    CONSTRAINT "turno_guardia_comprobaciones_motivo_check" CHECK ((("motivo_sin_comprobar" IS NULL) OR ("motivo_sin_comprobar" = ANY (ARRAY['nadie_para_mostrar'::"text", 'prestadora_no_responde'::"text", 'sin_camara'::"text", 'sin_conexion'::"text", 'otro'::"text"])))),
    CONSTRAINT "turno_guardia_comprobaciones_motivo_del_pedido_check" CHECK ((("motivo_del_pedido" IS NULL) OR ("motivo_del_pedido" = ANY (ARRAY['nadie_para_mostrar'::"text", 'sin_camara'::"text", 'otro'::"text"])))),
    CONSTRAINT "turno_guardia_comprobaciones_salida_comprobada_check" CHECK ((NOT (("momento" = 'checkout'::"text") AND ("estado" = 'sin_comprobar'::"text")))),
    CONSTRAINT "turno_guardia_comprobaciones_sujeto_coherencia_check" CHECK (((("medio" = ANY (ARRAY['codigo_cliente'::"text", 'codigo_asistente_saliente'::"text"])) AND ("sujeto_tipo" IS NOT NULL) AND ("sujeto_id" IS NOT NULL)) OR (("medio" = 'autorizacion_prestadora'::"text") AND ("sujeto_tipo" IS NULL) AND ("sujeto_id" IS NULL)) OR ("medio" IS NULL))),
    CONSTRAINT "turno_guardia_comprobaciones_sujeto_tipo_check" CHECK ((("sujeto_tipo" IS NULL) OR ("sujeto_tipo" = ANY (ARRAY['cliente'::"text", 'asistente'::"text"]))))
);


ALTER TABLE "public"."turno_guardia_comprobaciones" OWNER TO "postgres";


COMMENT ON TABLE "public"."turno_guardia_comprobaciones" IS 'Cómo se comprobó que el Asistente estaba realmente en el domicilio al llegar y al irse (pendiente #113). Una fila por acto: cuando hay relevo, el turno de guardia que termina y el que empieza tienen cada uno el suyo.';



COMMENT ON COLUMN "public"."turno_guardia_comprobaciones"."estado" IS 'comprobada (alguien mostró el código, o lo soltó la Prestadora), pendiente_de_codigo (el Asistente avisó que no hay quién se lo muestre y espera), sin_comprobar (se entró igual, con un motivo, y el Coordinador lo tiene que cerrar).';



COMMENT ON COLUMN "public"."turno_guardia_comprobaciones"."medio" IS 'Con qué se comprobó: el código del Cliente, el del Asistente que se iba, o el que soltó la Prestadora. Es lo que decide si al Cliente se le avisa: se le avisa cuando él no participó de la comprobación.';



COMMENT ON COLUMN "public"."turno_guardia_comprobaciones"."motivo_sin_comprobar" IS 'Por qué se entró sin comprobar. El turno de guardia nunca se traba: si en la Prestadora no atiende nadie, el Asistente elige un motivo, entra a trabajar, y esto queda en la lista del Coordinador.';



CREATE TABLE IF NOT EXISTS "public"."turno_guardia_pacientes" (
    "turno_guardia_id" "uuid" NOT NULL,
    "paciente_id" "uuid" NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."turno_guardia_pacientes" OWNER TO "postgres";


COMMENT ON TABLE "public"."turno_guardia_pacientes" IS 'A quiénes atiende un turno de guardia. Una fila por Paciente. Un turno de guardia puede tener varias: un matrimonio en su casa, o todo un piso de un asilo.';



CREATE TABLE IF NOT EXISTS "public"."turnos_guardia" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "asistente_id" "uuid",
    "paciente_id" "uuid" NOT NULL,
    "serie_id" "uuid",
    "coordinador_id" "uuid",
    "fecha" "date" NOT NULL,
    "hora_inicio" time without time zone NOT NULL,
    "hora_fin" time without time zone NOT NULL,
    "modalidad" "text" NOT NULL,
    "estado" "text" DEFAULT 'programada'::"text" NOT NULL,
    "cancelacion_origen" "text",
    "cancelacion_alcance" "text",
    "salida_checkin_at" timestamp with time zone,
    "salida_lat" double precision,
    "salida_lng" double precision,
    "medio_transporte" "text",
    "checkin_at" timestamp with time zone,
    "checkin_lat" double precision,
    "checkin_lng" double precision,
    "checkout_at" timestamp with time zone,
    "checkout_lat" double precision,
    "checkout_lng" double precision,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "push_asignacion_enviado_at" timestamp with time zone,
    "push_recordatorio_enviado_at" timestamp with time zone,
    "ubicacion_actual_lat" double precision,
    "ubicacion_actual_lng" double precision,
    "ubicacion_actual_at" timestamp with time zone,
    "push_llegada_enviado_at" timestamp with time zone,
    "push_reporte_enviado_at" timestamp with time zone,
    "servicio_id" "uuid" NOT NULL,
    "canal_modalidad" "text" DEFAULT 'directa'::"text" NOT NULL,
    "aviso_sin_cubrir_at" timestamp with time zone,
    "aviso_sin_cubrir_veces" smallint DEFAULT 0 NOT NULL,
    "cerrada_at" timestamp with time zone,
    "cerrada_por" "uuid",
    "cerrada_origen" "text",
    "cerrada_motivo" "text",
    "aviso_sin_cerrar_at" timestamp with time zone,
    "aviso_sin_cerrar_veces" smallint,
    "aviso_sin_cerrar_backup_at" timestamp with time zone,
    "aviso_sin_cerrar_grave_at" timestamp with time zone,
    "dias_hasta_el_fin" smallint DEFAULT 0 NOT NULL,
    "horas_extra" numeric(5,2) DEFAULT 0 NOT NULL,
    "horas_extra_motivo" "text",
    "llegada_tarde" boolean DEFAULT false NOT NULL,
    "interrupcion_id" "uuid",
    "push_recordatorio_reporte_enviado_at" timestamp with time zone,
    "salio_sin_reporte" boolean DEFAULT false NOT NULL,
    "reporte_llego_at" timestamp with time zone,
    "factura_espera_el_reporte" boolean DEFAULT false NOT NULL,
    "push_reporte_pendiente_enviado_at" timestamp with time zone,
    "cerrada_motivo_id" "uuid",
    CONSTRAINT "turnos_guardia_canal_modalidad_check" CHECK (("canal_modalidad" = ANY (ARRAY['directa'::"text", 'intermediacion'::"text"]))),
    CONSTRAINT "turnos_guardia_cancelacion_alcance_check" CHECK (("cancelacion_alcance" = ANY (ARRAY['servicio'::"text", 'prestacion'::"text", 'turno_guardia_recurrente'::"text", 'turno_guardia'::"text"]))),
    CONSTRAINT "turnos_guardia_cancelacion_check" CHECK ((("estado" = 'cancelada'::"text") OR (("cancelacion_origen" IS NULL) AND ("cancelacion_alcance" IS NULL)))),
    CONSTRAINT "turnos_guardia_cancelacion_origen_check" CHECK (("cancelacion_origen" = ANY (ARRAY['cliente'::"text", 'prestadora'::"text"]))),
    CONSTRAINT "turnos_guardia_cerrado_origen_check" CHECK (("cerrada_origen" = ANY (ARRAY['asistente'::"text", 'panel'::"text"]))),
    CONSTRAINT "turnos_guardia_cierre_por_el_asistente_sin_motivo" CHECK ((("cerrada_origen" IS DISTINCT FROM 'asistente'::"text") OR ("cerrada_motivo" IS NULL))),
    CONSTRAINT "turnos_guardia_cierre_por_el_panel_exige_persona_y_motivo" CHECK ((("cerrada_origen" IS DISTINCT FROM 'panel'::"text") OR (("cerrada_por" IS NOT NULL) AND ("cerrada_motivo" IS NOT NULL) AND ("btrim"("cerrada_motivo") <> ''::"text")))),
    CONSTRAINT "turnos_guardia_cierre_rastro_completo" CHECK (((("cerrada_at" IS NULL) AND ("cerrada_origen" IS NULL) AND ("cerrada_por" IS NULL) AND ("cerrada_motivo" IS NULL)) OR (("cerrada_at" IS NOT NULL) AND ("cerrada_origen" IS NOT NULL)))),
    CONSTRAINT "turnos_guardia_dios_hasta_el_fin_valido" CHECK (("dias_hasta_el_fin" >= 0)),
    CONSTRAINT "turnos_guardia_dura_algo" CHECK ((("dias_hasta_el_fin" > 0) OR ("hora_fin" > "hora_inicio"))),
    CONSTRAINT "turnos_guardia_factura_espera_el_reporte_check" CHECK (((NOT "factura_espera_el_reporte") OR "salio_sin_reporte")),
    CONSTRAINT "turnos_guardia_estado_check" CHECK (("estado" = ANY (ARRAY['programada'::"text", 'activa'::"text", 'completada'::"text", 'cancelada'::"text", 'ausente'::"text", 'pausada'::"text", 'suspendida'::"text", 'salida_sin_reporte'::"text"]))),
    CONSTRAINT "turnos_guardia_reporte_llego_check" CHECK ((("reporte_llego_at" IS NULL) OR "salio_sin_reporte")),
    CONSTRAINT "turnos_guardia_salida_sin_reporte_check" CHECK ((("estado" <> 'salida_sin_reporte'::"text") OR ("salio_sin_reporte" AND ("reporte_llego_at" IS NULL) AND ("checkout_at" IS NOT NULL)))),
    CONSTRAINT "turnos_guardia_interrupcion_check" CHECK ((("interrupcion_id" IS NULL) OR ("estado" = ANY (ARRAY['pausada'::"text", 'suspendida'::"text"])))),
    CONSTRAINT "turnos_guardia_horos_extra_con_motivo" CHECK ((("horas_extra" = (0)::numeric) OR (("horas_extra_motivo" IS NOT NULL) AND ("btrim"("horas_extra_motivo") <> ''::"text")))),
    CONSTRAINT "turnos_guardia_horos_extra_no_negativas" CHECK (("horas_extra" >= (0)::numeric)),
    CONSTRAINT "turnos_guardia_sin_cubrir_estado_check" CHECK ((("asistente_id" IS NOT NULL) OR ("estado" = ANY (ARRAY['programada'::"text", 'cancelada'::"text", 'pausada'::"text", 'suspendida'::"text"])))),
    CONSTRAINT "turnos_guardia_sin_cubrir_sin_marcas_check" CHECK ((("asistente_id" IS NOT NULL) OR (("checkin_at" IS NULL) AND ("checkout_at" IS NULL) AND ("salida_checkin_at" IS NULL))))
);


ALTER TABLE "public"."turnos_guardia" OWNER TO "postgres";


COMMENT ON COLUMN "public"."turnos_guardia"."asistente_id" IS 'NULL = turno de guardia sin cubrir. Es un estado normal y esperado, no un dato faltante.';



COMMENT ON COLUMN "public"."turnos_guardia"."paciente_id" IS 'EN RETIRO. Guarda a uno solo de los Pacientes del turno de guardia, el primero. La lista completa vive en turno_guardia_pacientes. Sigue acá únicamente para que las pantallas todavía sin actualizar no se rompan; se elimina cuando ninguna la lea.';



COMMENT ON COLUMN "public"."turnos_guardia"."aviso_sin_cubrir_at" IS 'Última vez que se le avisó al Coordinador que este turno de guardia sigue sin cubrir. NULL = nunca se avisó.';



COMMENT ON COLUMN "public"."turnos_guardia"."aviso_sin_cubrir_veces" IS 'Cuántas veces se avisó. Sirve para que el aviso repetido diga que ya es la tercera vez, no para decidir si mandarlo.';



COMMENT ON COLUMN "public"."turnos_guardia"."cerrada_at" IS 'Cuándo se dio por terminado el turno de guardia. Es distinto de checkout_at: esa es la hora en que el Asistente marcó que se iba de la casa, y esta es la hora en que alguien confirmó que el turno de guardia quedó cerrado.';



COMMENT ON COLUMN "public"."turnos_guardia"."cerrada_por" IS 'Quién la cerró. Si la cerró el Asistente, es él mismo (todo Asistente es también una fila de usuarios). Si la cerró alguien desde el Panel, es el Coordinador o el Admin de la Prestadora que apretó el botón.';



COMMENT ON COLUMN "public"."turnos_guardia"."cerrada_origen" IS 'Desde dónde se cerró: asistente (marcó la salida en su teléfono) o panel (lo cerró una persona de la Prestadora porque quedó sin cerrar). Cuando dice panel, el turno de guardia NO tiene hora ni lugar de salida, y el informe a la Obra Social tiene que leerlo así.';



COMMENT ON COLUMN "public"."turnos_guardia"."cerrada_motivo" IS 'Por qué se cerró desde el Panel, escrito por la persona que la cerró. Solo se llena cuando el origen es panel: el Asistente que marca su salida no explica nada.';



COMMENT ON COLUMN public.turnos_guardia.cerrada_motivo_id IS 'El motivo de la lista con el que se cerró desde el Panel. El texto que quedó escrito en ese momento está en cerrada_motivo.';



COMMENT ON COLUMN "public"."turnos_guardia"."aviso_sin_cerrar_grave_at" IS 'Cuándo se avisó por el evento turno_guardia_sin_cerrar_grave. Nulo mientras no se haya escalado.';



COMMENT ON COLUMN "public"."turnos_guardia"."dias_hasta_el_fin" IS 'Cuantos dias despues de fecha termina el turno de guardia: 0 el mismo dia, 1 al siguiente, 2 dos dias despues, y asi sin tope. Con 0 la hora de fin va despues de la de comienzo.';



COMMENT ON COLUMN "public"."turnos_guardia"."horas_extra" IS 'Horas de mas autorizadas en este turno de guardia, anotadas cuando pasaron. No se deducen de la diferencia entre la marca de salida y la hora de fin planificada: irse tarde no es una hora extra autorizada.';



COMMENT ON COLUMN "public"."turnos_guardia"."push_recordatorio_reporte_enviado_at" IS 'Cuándo se le recordó al Asistente que presente el Reporte Diario de este turno de guardia. Vacío si todavía no se le recordó.';



COMMENT ON COLUMN "public"."turnos_guardia"."salio_sin_reporte" IS 'Verdadero si el Asistente salió del turno de guardia sin haber presentado el Reporte Diario. Queda verdadero aunque el reporte llegue después.';



COMMENT ON COLUMN "public"."turnos_guardia"."reporte_llego_at" IS 'Cuándo llegó el Reporte Diario de un turno de guardia del que el Asistente salió sin presentarlo. Vacío mientras sigue pendiente.';



COMMENT ON COLUMN "public"."turnos_guardia"."factura_espera_el_reporte" IS 'Verdadero si el Asistente salió sin Reporte Diario y la Prestadora había elegido no facturar esos turnos de guardia: se factura cuando llega el reporte, en la factura del período en que llegó si la de su fecha ya estaba hecha.';



COMMENT ON COLUMN "public"."turnos_guardia"."push_reporte_pendiente_enviado_at" IS 'Cuándo se le avisó por última vez al Asistente que falta su Reporte Diario de este turno de guardia. Vacío si todavía no se le avisó.';



CREATE TABLE IF NOT EXISTS "public"."turnos_guardia_cobertura" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "turno_guardia_original_id" "uuid",
    "ausencia_id" "uuid",
    "asistente_sustituto_id" "uuid" NOT NULL,
    "costo_adicional" numeric(12,2),
    "created_at" timestamp with time zone DEFAULT "now"(),
    "prestadora_id" "uuid" NOT NULL,
    "moneda" "public"."moneda_iso" NOT NULL,
    "asistente_titular_id" "uuid",
    "motivo" "text",
    "motivo_detalle" "text",
    "cobertura_de_ausencia_id" "uuid",
    CONSTRAINT "turnos_guardia_cobertura_titular_distinto_del_sustituto" CHECK ((("asistente_titular_id" IS NULL) OR ("asistente_titular_id" <> "asistente_sustituto_id")))
);


ALTER TABLE "public"."turnos_guardia_cobertura" OWNER TO "postgres";


COMMENT ON COLUMN "public"."turnos_guardia_cobertura"."costo_adicional" IS 'Lo que la sustitución le cuesta de más a la Prestadora, aparte de lo que se le paga al sustituto por el turno de guardia. La remuneración del sustituto no se escribe acá: el turno de guardia quedó a su nombre, así que se liquida con su propio valor, como la de cualquiera.';



COMMENT ON COLUMN "public"."turnos_guardia_cobertura"."asistente_titular_id" IS 'A quién le tocaba ese turno de guardia antes de la sustitución. El turno de guardia en sí pasa a nombre de quien lo hace, que es el sustituto; que el titular haya faltado se ve en su ausencia, no acá. Vacío en las coberturas anotadas antes de que existiera esta columna.';



COMMENT ON COLUMN "public"."turnos_guardia_cobertura"."motivo" IS 'Causa de la sustitución: la clave o el nombre de una fila de motivos_sustitucion_turno_guardia. Vacío en las coberturas anotadas antes de que existiera el catálogo.';



CREATE TABLE IF NOT EXISTS "public"."turnos_guardia_tracking_gps" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "turno_guardia_id" "uuid" NOT NULL,
    "lat" double precision NOT NULL,
    "lng" double precision NOT NULL,
    "registrado_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."turnos_guardia_tracking_gps" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."hospitalizaciones_paciente" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "paciente_id" "uuid" NOT NULL,
    "institucion" "text" NOT NULL,
    "motivo" "text",
    "fecha_inicio" "date" NOT NULL,
    "fecha_fin" "date",
    "registrado_por" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "forma" "text" NOT NULL,
    CONSTRAINT "hospitalizaciones_paciente_forma_check" CHECK (("forma" = ANY (ARRAY['suspende'::"text", 'muda'::"text", 'sigue'::"text"])))
);


ALTER TABLE "public"."hospitalizaciones_paciente" OWNER TO "postgres";


COMMENT ON COLUMN "public"."hospitalizaciones_paciente"."forma" IS 'Qué pasa con el Servicio mientras dura la internación: suspende (el Servicio se suspende), muda (el Servicio se muda al domicilio temporal en la institución) o sigue (el Servicio sigue en el domicilio habitual).';


CREATE TABLE IF NOT EXISTS "public"."importaciones_prestadora" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "usuario_id" "uuid" NOT NULL,
    "tipo" "text" NOT NULL,
    "archivo_nombre" "text",
    "filas_totales" integer DEFAULT 0 NOT NULL,
    "filas_creadas" integer DEFAULT 0 NOT NULL,
    "filas_error" integer DEFAULT 0 NOT NULL,
    "errores" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "estado_conformidad" "text" DEFAULT 'pendiente'::"text" NOT NULL,
    "revisada_en" timestamp with time zone,
    "revisada_por" "uuid",
    CONSTRAINT "importaciones_prestadora_estado_conformidad_check" CHECK (("estado_conformidad" = ANY (ARRAY['pendiente'::"text", 'confirmada'::"text", 'rechazada'::"text"]))),
    CONSTRAINT "importaciones_prestadora_tipo_check" CHECK (("tipo" = ANY (ARRAY['asistente'::"text", 'cliente'::"text", 'lista_precios'::"text"])))
);


ALTER TABLE "public"."importaciones_prestadora" OWNER TO "postgres";



CREATE TABLE IF NOT EXISTS "public"."incidentes_de_seguridad" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "ocurrido_at" timestamp with time zone NOT NULL,
    "conocido_at" timestamp with time zone NOT NULL,
    "descripcion" "text" NOT NULL,
    "cargado_por" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "autoridad_notificada_at" timestamp with time zone,
    "titulares_notificados_at" timestamp with time zone,
    "responsable_notificado_at" timestamp with time zone,
    "factor_naturaleza_y_alcance" "text",
    "factor_quien_recibio" "text",
    "factor_adquiridos_o_vistos" "text",
    "factor_mitigacion" "text",
    "conclusion" "text",
    "evaluado_por" "uuid",
    "evaluado_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "incidentes_de_seguridad_conclusion_conocida" CHECK ((("conclusion" IS NULL) OR ("conclusion" = ANY (ARRAY['baja_probabilidad_de_compromiso'::"text", 'se_presume_brecha'::"text"])))),
    CONSTRAINT "incidentes_de_seguridad_conclusion_de_los_cuatro_factores" CHECK ((("conclusion" IS NULL) OR (("btrim"(COALESCE("factor_naturaleza_y_alcance", ''::"text")) <> ''::"text") AND ("btrim"(COALESCE("factor_quien_recibio", ''::"text")) <> ''::"text") AND ("btrim"(COALESCE("factor_adquiridos_o_vistos", ''::"text")) <> ''::"text") AND ("btrim"(COALESCE("factor_mitigacion", ''::"text")) <> ''::"text")))),
    CONSTRAINT "incidentes_de_seguridad_la_descripcion_no_va_vacia" CHECK (("btrim"("descripcion") <> ''::"text")),
    CONSTRAINT "incidentes_de_seguridad_no_se_supo_antes_de_ocurrir" CHECK (("conocido_at" >= "ocurrido_at"))
);


ALTER TABLE "public"."incidentes_de_seguridad" OWNER TO "postgres";



COMMENT ON TABLE "public"."incidentes_de_seguridad" IS 'Cada incidente de seguridad sobre datos de pacientes de una Prestadora: cuándo ocurrió, cuándo se supo, la evaluación de los cuatro factores del riesgo, la conclusión y a quién se avisó. Todo incidente queda anotado, se haya avisado o no, y no se borra.';


CREATE TABLE IF NOT EXISTS "public"."incidentes_relevo" (
