    "push_enviado_at" timestamp with time zone
);


ALTER TABLE "public"."mensajes_asistente" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."mensajes_del_sistema" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid",
    "clave" "text" NOT NULL,
    "i18n" "jsonb" NOT NULL,
