    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "plantillas_whatsapp_estado_check" CHECK (("estado" = ANY (ARRAY['borrador'::"text", 'enviada_meta'::"text", 'aprobada'::"text", 'rechazada'::"text"])))
);


ALTER TABLE "public"."plantillas_whatsapp" OWNER TO "postgres";



CREATE TABLE IF NOT EXISTS "public"."plazos_de_notificacion_de_brechas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "jurisdiccion" "text" NOT NULL,
    "destinatario" "text" NOT NULL,
    "organismo" "text",
    "cantidad" integer NOT NULL,
    "unidad" "text" NOT NULL,
    "cuenta_desde" "text" NOT NULL,
    "fuente" "text" NOT NULL,
    "vigencia_desde" "date" NOT NULL,
    "vigencia_hasta" "date",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "plazos_de_brechas_la_vigencia_no_termina_antes_de_empezar" CHECK ((("vigencia_hasta" IS NULL) OR ("vigencia_hasta" >= "vigencia_desde"))),
    CONSTRAINT "plazos_de_notificacion_de_brechas_cita_su_norma" CHECK (("btrim"("fuente") <> ''::"text")),
    CONSTRAINT "plazos_de_notificacion_de_brechas_destinatario_conocido" CHECK (("destinatario" = ANY (ARRAY['autoridad'::"text", 'titular'::"text", 'responsable'::"text"]))),
    CONSTRAINT "plazos_de_notificacion_de_brechas_jurisdiccion_es_un_pais" CHECK (("jurisdiccion" ~ '^[A-Z]{2}$'::"text")),
    CONSTRAINT "plazos_de_notificacion_de_brechas_la_cantidad_es_positiva" CHECK (("cantidad" > 0)),
    CONSTRAINT "plazos_de_notificacion_de_brechas_momento_conocido" CHECK (("cuenta_desde" = ANY (ARRAY['ocurrido'::"text", 'conocido'::"text"]))),
    CONSTRAINT "plazos_de_notificacion_de_brechas_unidad_conocida" CHECK (("unidad" = ANY (ARRAY['horas'::"text", 'dias_corridos'::"text", 'dias_habiles'::"text"])))
);


ALTER TABLE "public"."plazos_de_notificacion_de_brechas" OWNER TO "postgres";



COMMENT ON TABLE "public"."plazos_de_notificacion_de_brechas" IS 'Plazo legal para avisar de un incidente de seguridad, por país y destinatario. Se cargan sólo los plazos que el documento legal del país escribe con número, unidad, momento de inicio y artículo. Se cargan con migraciones y ningún plazo vive en el código.';



CREATE TABLE IF NOT EXISTS "public"."plazos_de_respuesta_de_derechos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "pais" "text" NOT NULL,
    "tipo" "text" NOT NULL,
    "cantidad" integer NOT NULL,
    "unidad" "text" NOT NULL,
    "fuente" "text" NOT NULL,
    "vigente_desde" "date" NOT NULL,
    "vigente_hasta" "date",
    "dias_de_aviso" integer NOT NULL,
    CONSTRAINT "plazos_de_respuesta_aviso_razonable" CHECK ((("dias_de_aviso" >= 0) AND ("dias_de_aviso" <= 365))),
    CONSTRAINT "plazos_de_respuesta_cantidad_positiva" CHECK ((("cantidad" >= 1) AND ("cantidad" <= 3650))),
    CONSTRAINT "plazos_de_respuesta_fechas_en_orden" CHECK ((("vigente_hasta" IS NULL) OR ("vigente_hasta" >= "vigente_desde"))),
    CONSTRAINT "plazos_de_respuesta_fuente_escrita" CHECK (("btrim"("fuente") <> ''::"text")),
    CONSTRAINT "plazos_de_respuesta_pais_escrito" CHECK (("pais" ~ '^[A-Z]{2}$'::"text")),
    CONSTRAINT "plazos_de_respuesta_unidad_conocida" CHECK (("unidad" = ANY (ARRAY['horas'::"text", 'dias_corridos'::"text", 'dias_habiles'::"text"])))
);


ALTER TABLE "public"."plazos_de_respuesta_de_derechos" OWNER TO "postgres";



COMMENT ON TABLE "public"."plazos_de_respuesta_de_derechos" IS 'Plazo de respuesta de cada derecho en cada país, con la norma y su artículo en fuente. Rige el vigente el día en que se recibió la solicitud. Sólo se cargan plazos escritos con su artículo en el documento legal del país.';


CREATE TABLE IF NOT EXISTS "public"."plazos_de_ubicacion_avisados" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "control_en_el_turno_guardia_desde" timestamp with time zone NOT NULL,
    "avisado_en" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."plazos_de_ubicacion_avisados" OWNER TO "postgres";


COMMENT ON TABLE "public"."plazos_de_ubicacion_avisados" IS 'Asistentes cuyo plazo para aceptar la ubicación durante el turno de guardia venció y ya se le avisó a la Prestadora.';



CREATE TABLE IF NOT EXISTS "public"."postulaciones" (
    "id" bigint NOT NULL,
    "nombre" character varying(100) NOT NULL,
    "telefono" character varying(30) NOT NULL,
    "email" character varying(100) NOT NULL,
    "especialidades" "text" NOT NULL,
    "zonas" "text" NOT NULL,
    "disponibilidad" "text" NOT NULL,
    "anios_experiencia" character varying(20),
    "situacion_fiscal" character varying(50) NOT NULL,
    "como_conocio" character varying(100),
    "mensaje" "text",
    "estado" character varying(30) DEFAULT 'pendiente'::character varying,
    "canal" character varying(50) DEFAULT 'web'::character varying,
    "creado_en" timestamp with time zone DEFAULT "now"(),
    "nota_interna" "text",
    "asistente_id" "uuid",
    "dni" "text",
    "idioma" "text" DEFAULT 'es-AR'::"text" NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "fecha_nacimiento" "date",
    "domicilio" "text",
    "lat" double precision,
    "lng" double precision,
    "localidad" "text",
    "nacionalidad" "text",
    "cuil" "text",
    "genero" "text",
    "foto_perfil_url" "text",
    "tipo_registro_afip" "text",
    "obra_social" "text",
    "estudios" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "experiencia_laboral" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "referencias_laborales" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "experiencia_clinica" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "distancia_maxima_km" numeric(6,2),
    "disponible_urgencias" boolean DEFAULT false NOT NULL,
    "disponible_con_retiro" boolean DEFAULT false NOT NULL,
    "disponible_sin_retiro" boolean DEFAULT false NOT NULL,
    "honorario_pretendido" numeric(12,2),
    "moneda" "public"."moneda_iso" NOT NULL,
    CONSTRAINT "postulaciones_distancia_positiva" CHECK ((("distancia_maxima_km" IS NULL) OR ("distancia_maxima_km" > (0)::numeric))),
    CONSTRAINT "postulaciones_honorario_positivo" CHECK ((("honorario_pretendido" IS NULL) OR ("honorario_pretendido" > (0)::numeric))),
    CONSTRAINT "postulaciones_listas_son_listas" CHECK ((("jsonb_typeof"("estudios") = 'array'::"text") AND ("jsonb_typeof"("experiencia_laboral") = 'array'::"text") AND ("jsonb_typeof"("referencias_laborales") = 'array'::"text")))
);


ALTER TABLE "public"."postulaciones" OWNER TO "postgres";


COMMENT ON COLUMN "public"."postulaciones"."especialidades" IS 'Claves de opciones_postulacion del grupo especialidad, separadas por coma. Nunca la etiqueta traducida: una postulación en cualquier idioma guarda siempre el mismo valor.';



COMMENT ON COLUMN "public"."postulaciones"."fecha_nacimiento" IS 'Fecha de nacimiento que declara quien se postula.';



COMMENT ON COLUMN "public"."postulaciones"."experiencia_clinica" IS 'Claves de opciones_postulacion cuyo grupo empieza con experiencia_clinica_.';



COMMENT ON COLUMN "public"."postulaciones"."honorario_pretendido" IS 'Lo que la persona pretende cobrar por hora. Opcional: no decirlo no traba la postulación.';



ALTER TABLE "public"."postulaciones" ALTER COLUMN "id" ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME "public"."postulaciones_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);



CREATE TABLE IF NOT EXISTS "public"."prestaciones" (
    "id" bigint NOT NULL,
    "paciente_id" "uuid" NOT NULL,
    "tipo_servicio" "text" NOT NULL,
    "configuracion" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "precio_lista_id" bigint,
    "precio_lista_snapshot" numeric(12,2),
    "tipo_descuento" "text",
    "valor_descuento" numeric(12,2),
    "precio_final" numeric(12,2),
    "nota" "text",
    "estado" "text" DEFAULT 'vigente'::"text" NOT NULL,
    "requiere_revision" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "prestadora_id" "uuid" NOT NULL,
    "servicio_id" "uuid",
    "moneda" "public"."moneda_iso" NOT NULL,
    "vigente_desde" "date" NOT NULL,
    "vigente_hasta" "date",
    "forma_de_precio" "text" DEFAULT 'directo'::"text",
    "sentido_del_ajuste" "text",
    "prestacion_anterior_id" bigint,
    "precio_turno_guardia_adicional" numeric(12,2),
    "precio_hora_adicional" numeric(12,2),
    CONSTRAINT "prestaciones_adicionales_no_negativos" CHECK (((("precio_turno_guardia_adicional" IS NULL) OR ("precio_turno_guardia_adicional" >= (0)::numeric)) AND (("precio_hora_adicional" IS NULL) OR ("precio_hora_adicional" >= (0)::numeric)))),
    CONSTRAINT "prestaciones_ajuste_completo" CHECK (((("tipo_descuento" IS NULL) AND ("valor_descuento" IS NULL) AND ("sentido_del_ajuste" IS NULL)) OR (("tipo_descuento" IS NOT NULL) AND ("valor_descuento" IS NOT NULL) AND ("sentido_del_ajuste" IS NOT NULL)))),
    CONSTRAINT "prestaciones_ajuste_no_negativo" CHECK ((("valor_descuento" IS NULL) OR ("valor_descuento" >= (0)::numeric))),
    CONSTRAINT "prestaciones_estado_check" CHECK (("estado" = ANY (ARRAY['vigente'::"text", 'de_baja'::"text"]))),
    CONSTRAINT "prestaciones_forma_de_precio_valida" CHECK (("forma_de_precio" = ANY (ARRAY['lista'::"text", 'directo'::"text"]))),
    CONSTRAINT "prestaciones_no_se_reemplaza_a_si_misma" CHECK ((("prestacion_anterior_id" IS NULL) OR ("prestacion_anterior_id" <> "id"))),
    CONSTRAINT "prestaciones_precio_coherente_con_su_forma" CHECK (((("forma_de_precio" IS NULL) AND ("precio_lista_id" IS NULL) AND ("precio_lista_snapshot" IS NULL) AND ("tipo_descuento" IS NULL) AND ("valor_descuento" IS NULL) AND ("sentido_del_ajuste" IS NULL) AND ("precio_final" IS NULL) AND ("precio_turno_guardia_adicional" IS NULL) AND ("precio_hora_adicional" IS NULL) AND (NOT "requiere_revision")) OR (("forma_de_precio" = 'lista'::"text") AND ("precio_lista_id" IS NOT NULL) AND ("precio_lista_snapshot" IS NOT NULL) AND ("precio_final" IS NOT NULL)) OR (("forma_de_precio" = 'directo'::"text") AND ("precio_lista_id" IS NULL) AND ("tipo_descuento" IS NULL) AND ("precio_final" IS NOT NULL)))),
    CONSTRAINT "prestaciones_precio_final_no_negativo" CHECK (("precio_final" >= (0)::numeric)),
    CONSTRAINT "prestaciones_sentido_del_ajuste_valido" CHECK ((("sentido_del_ajuste" IS NULL) OR ("sentido_del_ajuste" = ANY (ARRAY['descuento'::"text", 'recargo'::"text"])))),
    CONSTRAINT "prestaciones_tipo_descuento_check" CHECK (("tipo_descuento" = ANY (ARRAY['porcentaje'::"text", 'monto_fijo'::"text"]))),
    CONSTRAINT "prestaciones_vigencia_coherente" CHECK ((("vigente_hasta" IS NULL) OR ("vigente_hasta" >= "vigente_desde")))
);


ALTER TABLE "public"."prestaciones" OWNER TO "postgres";


COMMENT ON COLUMN "public"."prestaciones"."tipo_descuento" IS 'Cómo se mide el ajuste sobre el precio de la lista: porcentaje o monto_fijo. El nombre es de antes, y vale para el descuento y para el recargo.';



COMMENT ON COLUMN "public"."prestaciones"."valor_descuento" IS 'Cuánto es el ajuste sobre el precio de la lista, siempre positivo: el sentido lo dice sentido_del_ajuste.';



COMMENT ON COLUMN "public"."prestaciones"."vigente_desde" IS 'Primer dia en que corre lo pactado. Puede ser posterior al alta: un acuerdo se firma antes de arrancar.';



COMMENT ON COLUMN "public"."prestaciones"."vigente_hasta" IS 'Ultimo dia en que corre lo pactado, incluido. Vacio quiere decir que sigue abierta.';



COMMENT ON COLUMN "public"."prestaciones"."forma_de_precio" IS 'Cómo se llegó al precio: de la lista o escrito. Vacía quiere decir que la prestación todavía no tiene precio.';



COMMENT ON COLUMN "public"."prestaciones"."sentido_del_ajuste" IS 'Si el ajuste sobre el precio de la lista lo baja (descuento) o lo sube (recargo). Va con tipo_descuento y valor_descuento.';



COMMENT ON COLUMN "public"."prestaciones"."prestacion_anterior_id" IS 'La Prestación cuyo precio ésta reemplaza desde su vigente_desde. Al guardarla, la base cierra la anterior el día antes.';



COMMENT ON COLUMN "public"."prestaciones"."precio_turno_guardia_adicional" IS 'Precio pactado de cada turno de guardia adicional, en la moneda de la prestación. Vacío: la factura la valúa en proporción al precio pactado. Cambia con el precio cuando se ajusta.';



COMMENT ON COLUMN "public"."prestaciones"."precio_hora_adicional" IS 'Precio pactado de cada hora adicional, en la moneda de la prestación. Vacío: la factura la valúa en proporción al precio pactado. Cambia con el precio cuando se ajusta.';



ALTER TABLE "public"."prestaciones" ALTER COLUMN "id" ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME "public"."prestaciones_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);



CREATE OR REPLACE VIEW "public"."prestaciones_sin_importes" WITH ("security_barrier"='true') AS
 SELECT "id",
    "prestadora_id",
    "servicio_id",
    "paciente_id",
    "tipo_servicio",
    "configuracion",
    "nota",
    "estado",
    "vigente_desde",
    "vigente_hasta",
    "prestacion_anterior_id",
    "created_at",
    ("forma_de_precio" IS NOT NULL) AS "tiene_precio"
   FROM "public"."prestaciones" "p"
  WHERE (("prestadora_id" = "interno"."prestadora_actual"()) AND "interno"."ve_la_prestacion"("paciente_id"));


ALTER VIEW "public"."prestaciones_sin_importes" OWNER TO "postgres";


COMMENT ON VIEW "public"."prestaciones_sin_importes" IS 'Las prestaciones de los Pacientes que ve quien inició sesión, sin el precio. Es lo que lee la Coordinadora; la tabla con el precio la leen la administración y quien gestiona la facturación.';



CREATE TABLE IF NOT EXISTS "public"."prestadora_modalidades" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
