    "desactivada_por" "uuid",
    "desactivada_en" timestamp with time zone,
    CONSTRAINT "prestadora_modalidades_modalidad_check" CHECK (("modalidad" = ANY (ARRAY['directa'::"text", 'intermediacion'::"text"])))
);


ALTER TABLE "public"."prestadora_modalidades" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."prestadoras" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "razon_social" "text" NOT NULL,
    "nombre_fantasia" "text" NOT NULL,
    "identificacion_fiscal" "text",
    "pais" "text" DEFAULT 'AR'::"text" NOT NULL,
    "estado" "public"."estado_prestadora" DEFAULT 'prospecto'::"public"."estado_prestadora" NOT NULL,
    "zonas_operacion" "text"[],
    "fecha_alta" "date",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "dias_aviso_vencimiento_documentos" smallint DEFAULT 30 NOT NULL,
    "dias_generacion_series_turno_guardia" smallint DEFAULT 90 NOT NULL,
    "politica_verificacion_alta_manual" "text" DEFAULT 'omitir'::"text" NOT NULL,
    "logo_url" "text",
    "minutos_aviso_previo_turno_guardia" integer DEFAULT 60 NOT NULL,
    "moneda" "public"."moneda_iso" NOT NULL,
    "videollamada_base_url" "text",
    "casilla_envio" "text",
    "regla_reenvio" "text",
    "cierre_por_inactividad_activo" boolean DEFAULT true NOT NULL,
    "cierre_por_inactividad_minutos" integer DEFAULT 15 NOT NULL,
    "control_de_ubicacion_en_el_turno_guardia" boolean DEFAULT true NOT NULL,
    "minutos_entre_controles_de_ubicacion" integer DEFAULT 5 NOT NULL,
    "dias_para_aceptar_la_ubicacion" integer DEFAULT 30 NOT NULL,
    "control_de_ubicacion_en_el_turno_guardia_desde" timestamp with time zone,
    "logo_impresion_ruta" "text",
    "referencia_celtatech" "text",
    "zona_horaria" "text" DEFAULT 'America/Argentina/Buenos_Aires'::"text" NOT NULL,
    "registro_de_accesos_hora_de_inicio" time without time zone DEFAULT '07:00:00'::time without time zone NOT NULL,
    "registro_de_accesos_hora_de_fin" time without time zone DEFAULT '20:00:00'::time without time zone NOT NULL,
    "registro_de_accesos_pacientes_por_dia" integer DEFAULT 20 NOT NULL,
    "registro_de_accesos_horas_alrededor_del_turno_guardia" integer DEFAULT 12 NOT NULL,
    "turnos_guardia_solo_con_firma_del_pagador" boolean DEFAULT false NOT NULL,
    "minutos_recordatorio_reporte" integer DEFAULT 30 NOT NULL,
    "factura_turnos_sin_reporte" boolean DEFAULT true NOT NULL,
    "horas_entre_avisos_reporte_pendiente" integer DEFAULT 2 NOT NULL,
    CONSTRAINT "prestadoras_cierre_por_inactividad_minutos_check" CHECK ((("cierre_por_inactividad_minutos" >= 5) AND ("cierre_por_inactividad_minutos" <= 120))),
    CONSTRAINT "prestadoras_dias_para_aceptar_la_ubicacion_check" CHECK ((("dias_para_aceptar_la_ubicacion" >= 1) AND ("dias_para_aceptar_la_ubicacion" <= 365))),
    CONSTRAINT "prestadoras_horas_entre_avisos_reporte_pendiente_check" CHECK ((("horas_entre_avisos_reporte_pendiente" >= 1) AND ("horas_entre_avisos_reporte_pendiente" <= 24))),
    CONSTRAINT "prestadoras_minutos_aviso_previo_turno_guardia_check" CHECK ((("minutos_aviso_previo_turno_guardia" >= 5) AND ("minutos_aviso_previo_turno_guardia" <= 1440))),
    CONSTRAINT "prestadoras_minutos_entre_controles_de_ubicacion_check" CHECK ((("minutos_entre_controles_de_ubicacion" >= 1) AND ("minutos_entre_controles_de_ubicacion" <= 60))),
    CONSTRAINT "prestadoras_minutos_recordatorio_reporte_check" CHECK ((("minutos_recordatorio_reporte" >= 5) AND ("minutos_recordatorio_reporte" <= 1440))),
    CONSTRAINT "prestadoras_politica_verificacion_alta_manual_check" CHECK (("politica_verificacion_alta_manual" = ANY (ARRAY['omitir'::"text", 'pendiente'::"text", 'aprobado'::"text"]))),
    CONSTRAINT "prestadoras_registro_de_accesos_horario_valido" CHECK (("registro_de_accesos_hora_de_inicio" <> "registro_de_accesos_hora_de_fin")),
    CONSTRAINT "prestadoras_registro_de_accesos_horas_alrededor_valido" CHECK ((("registro_de_accesos_horas_alrededor_del_turno_guardia" >= 0) AND ("registro_de_accesos_horas_alrededor_del_turno_guardia" <= 72))),
    CONSTRAINT "prestadoras_registro_de_accesos_pacientes_por_dia_valido" CHECK (("registro_de_accesos_pacientes_por_dia" > 0)),
    CONSTRAINT "prestadoras_zona_horaria_conocida" CHECK ((('2000-01-01 00:00:00+00'::timestamp with time zone AT TIME ZONE "zona_horaria") IS NOT NULL))
);


ALTER TABLE "public"."prestadoras" OWNER TO "postgres";


COMMENT ON COLUMN "public"."prestadoras"."logo_url" IS 'Dirección del logo de la Prestadora, la marca que ven el Cliente y el Asistente. Vacío significa que todavía no lo subió: en ese caso las pantallas muestran nombre_fantasia escrito. Los archivos viven en el depósito marca-prestadoras, en la carpeta de esa Prestadora.';



COMMENT ON COLUMN "public"."prestadoras"."logo_impresion_ruta" IS 'Ruta del logo para impresión adentro del depósito logos-para-impresion: el que va en los documentos que se imprimen. Vacío significa que no lo cargó: en ese caso el documento usa el logo de internet si es PNG o JPG, y si no sale sin logo.';



COMMENT ON COLUMN "public"."prestadoras"."referencia_celtatech" IS 'Con qué identifica CeltaTech el alta de esta Prestadora. Llega con el alta, no se interpreta y no cambia. Con ella un alta repetida devuelve la misma Prestadora.';



COMMENT ON COLUMN "public"."prestadoras"."zona_horaria" IS 'Zona horaria de la Prestadora, con el nombre de la base internacional de zonas horarias.';



COMMENT ON COLUMN "public"."prestadoras"."registro_de_accesos_hora_de_inicio" IS 'Hora de inicio del horario de trabajo. Un acceso a información de salud fuera del horario sale de lo normal.';



COMMENT ON COLUMN "public"."prestadoras"."registro_de_accesos_hora_de_fin" IS 'Hora de fin del horario de trabajo. Si es menor que la de inicio, el horario cruza la medianoche.';



COMMENT ON COLUMN "public"."prestadoras"."registro_de_accesos_pacientes_por_dia" IS 'Pacientes distintos por día que una persona lee sin que llame la atención.';



COMMENT ON COLUMN "public"."prestadoras"."registro_de_accesos_horas_alrededor_del_turno_guardia" IS 'Horas antes y después de un turno de guardia en las que el Asistente todavía atiende a ese Paciente.';



COMMENT ON COLUMN "public"."prestadoras"."minutos_aviso_previo_turno_guardia" IS 'Cuántos minutos antes de que empiece el turno de guardia se le manda el recordatorio al Asistente. De fábrica, 60. El tope es un día entero; menos de cinco minutos no llegaría a tiempo de servir para nada.';



COMMENT ON COLUMN "public"."prestadoras"."moneda" IS 'Moneda en la que esta Prestadora carga sus precios y cobra. Nace del país configurado y se cambia desde Configuración.';



COMMENT ON COLUMN "public"."prestadoras"."videollamada_base_url" IS 'Direccion base de las salas de videollamada de esta Prestadora, sin barra final. El producto le agrega el nombre de sala. Vacia: esta Prestadora no ofrece videollamada y el boton no aparece. No lleva ninguna credencial.';



COMMENT ON COLUMN "public"."prestadoras"."casilla_envio" IS 'Nombre de la casilla desde la que esta Prestadora manda sus avisos, sin el dominio. Se fija al darla de alta y no cambia: es la dirección que la gente ya tiene en su buzón. El dominio lo pone el motor.';



COMMENT ON COLUMN "public"."prestadoras"."regla_reenvio" IS 'Identificador del reenvío de las respuestas de esta Prestadora, tal como lo da el servicio de correo. Se abre al darla de alta y se corta cuando se va. Vacío: no hay reenvío y las respuestas se pierden.';



COMMENT ON COLUMN "public"."prestadoras"."turnos_guardia_solo_con_firma_del_pagador" IS 'Verdadero: un Servicio programa turnos de guardia sólo con la firma vigente del Responsable de pagos. De fábrica, falso.';



COMMENT ON COLUMN "public"."prestadoras"."control_de_ubicacion_en_el_turno_guardia" IS 'Verdadero: viaje y turno de guardia. Falso: sólo viaje. De fábrica, viaje y turno de guardia.';



COMMENT ON COLUMN "public"."prestadoras"."minutos_entre_controles_de_ubicacion" IS 'Cada cuántos minutos se controla la ubicación durante el turno de guardia, cuando la Prestadora eligió viaje y turno de guardia. De fábrica, 5.';



COMMENT ON COLUMN "public"."prestadoras"."dias_para_aceptar_la_ubicacion" IS 'Días que tiene el Asistente para aceptar el registro de su ubicación durante el turno de guardia, desde que la Prestadora eligió viaje y turno de guardia. De fábrica, 30.';



COMMENT ON COLUMN "public"."prestadoras"."control_de_ubicacion_en_el_turno_guardia_desde" IS 'Desde cuándo la Prestadora tiene viaje y turno de guardia. Vacía con sólo viaje. La pone la base.';



COMMENT ON COLUMN "public"."prestadoras"."minutos_recordatorio_reporte" IS 'Cuántos minutos antes del fin del turno de guardia se le recuerda al Asistente que presente el Reporte Diario. Entre 5 y 1440.';



COMMENT ON COLUMN "public"."prestadoras"."factura_turnos_sin_reporte" IS 'Si se le factura al Cliente el turno de guardia en el que el Asistente salió sin presentar el Reporte Diario. Verdadero: se factura igual. Falso: se factura cuando llega el reporte.';



COMMENT ON COLUMN "public"."prestadoras"."horas_entre_avisos_reporte_pendiente" IS 'Cada cuántas horas se le repite al Asistente el aviso de que falta su Reporte Diario, mientras no lo presente. Entre 1 y 24.';



CREATE TABLE IF NOT EXISTS "public"."propuestas_de_ajuste_por_indice" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "prestacion_id" bigint NOT NULL,
    "servicio_id" "uuid" NOT NULL,
    "indice" "text" NOT NULL,
    "periodo_base" "date" NOT NULL,
    "periodo_nuevo" "date" NOT NULL,
    "precio_actual" numeric NOT NULL,
    "precio_propuesto" numeric NOT NULL,
    "moneda" "text" NOT NULL,
    "rige_desde" "date" NOT NULL,
    "estado" "text" DEFAULT 'pendiente'::"text" NOT NULL,
    "prestacion_nueva_id" bigint,
    "revisada_por" "uuid",
    "revisada_en" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "propuestas_de_ajuste_periodos_en_orden" CHECK (("periodo_nuevo" > "periodo_base")),
    CONSTRAINT "propuestas_de_ajuste_por_indice_estado_check" CHECK (("estado" = ANY (ARRAY['pendiente'::"text", 'aceptada'::"text", 'rechazada'::"text", 'aplicada'::"text", 'sin_efecto'::"text"]))),
    CONSTRAINT "propuestas_de_ajuste_por_indice_precio_actual_check" CHECK (("precio_actual" > (0)::numeric)),
    CONSTRAINT "propuestas_de_ajuste_por_indice_precio_propuesto_check" CHECK (("precio_propuesto" >= (0)::numeric)),
    CONSTRAINT "propuestas_de_ajuste_por_indice_rige_desde_check" CHECK (("rige_desde" = ("date_trunc"('month'::"text", ("rige_desde")::timestamp with time zone))::"date")),
    CONSTRAINT "propuestas_de_ajuste_revision_completa" CHECK ((("estado" = ANY (ARRAY['aceptada'::"text", 'rechazada'::"text"])) = ("revisada_en" IS NOT NULL))),
    CONSTRAINT "propuestas_de_ajuste_version_nueva" CHECK ((("estado" = ANY (ARRAY['aceptada'::"text", 'aplicada'::"text"])) = ("prestacion_nueva_id" IS NOT NULL)))
);


ALTER TABLE "public"."propuestas_de_ajuste_por_indice" OWNER TO "postgres";


