CREATE POLICY "coordinacion_corrige_el_equipo_del_servicio" ON "public"."equipo_servicio" TO "authenticated" USING ((("prestadora_id" = "interno"."prestadora_actual"()) AND ("interno"."es_admin_prestadora"() OR ("interno"."coordina_el_servicio"("servicio_id") AND "interno"."tiene_permiso"('modificar_asistentes_del_servicio'::"text"))))) WITH CHECK ((("prestadora_id" = "interno"."prestadora_actual"()) AND (EXISTS ( SELECT 1
   FROM "public"."servicios" "s"
  WHERE (("s"."id" = "equipo_servicio"."servicio_id") AND ("s"."prestadora_id" = "interno"."prestadora_actual"())))) AND ("interno"."es_admin_prestadora"() OR ("interno"."coordina_el_servicio"("servicio_id") AND "interno"."tiene_permiso"('modificar_asistentes_del_servicio'::"text")))));



CREATE POLICY "coordinador_agrega_informacion_de_salud" ON "public"."informacion_de_salud_del_paciente" FOR INSERT TO "authenticated" WITH CHECK ((("prestadora_id" = "interno"."prestadora_actual"()) AND "interno"."coordinador_ve_al_paciente"("paciente_id") AND "interno"."tiene_permiso"('editar_datos_paciente'::"text")));



CREATE POLICY "coordinador_agrega_pacientes" ON "public"."pacientes" FOR INSERT TO "authenticated" WITH CHECK ((("prestadora_id" = "interno"."prestadora_actual"()) AND "interno"."es_coordinador"() AND "interno"."coordina_un_servicio_del_cliente"("cliente_id") AND "interno"."tiene_permiso"('editar_datos_paciente'::"text")));



