-- Si el lugar que eligió una persona cubre el lugar de un domicilio: es el mismo lugar, es el lugar
-- que lo contiene, o los dos están en una misma zona de cobertura activa de la Prestadora. Es el
-- único lugar donde vive esa comparación: la usan los Coordinadores sugeridos y los criterios de
-- las candidatas.
CREATE OR REPLACE FUNCTION "interno"."el_lugar_esta_cubierto"("p_prestadora" "uuid", "p_lugar" "uuid", "p_elegido" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT p_elegido = p_lugar
      OR EXISTS (SELECT 1 FROM public.lugares l
                  WHERE l.id = p_lugar
                    AND l.prestadora_id = p_prestadora
                    AND l.parte_de = p_elegido)
      OR EXISTS (SELECT 1
                   FROM public.zona_lugares zp
                   JOIN public.zona_lugares zc
                     ON zc.zona_id = zp.zona_id AND zc.prestadora_id = p_prestadora
                   JOIN public.zonas_cobertura z
                     ON z.id = zp.zona_id AND z.prestadora_id = p_prestadora AND z.activa
                  WHERE zp.lugar_id = p_lugar
                    AND zp.prestadora_id = p_prestadora
                    AND zc.lugar_id = p_elegido);
$$;

ALTER FUNCTION "interno"."el_lugar_esta_cubierto"("p_prestadora" "uuid", "p_lugar" "uuid", "p_elegido" "uuid") OWNER TO "postgres";

