-- Los criterios para sugerir y asignar Asistentes: lugar, tareas, Especialidad, antecedentes y
-- acuerdo económico.
-- =============================================================================================

-- La Especialidad que pide una tarea del catálogo de un tipo de Asistente. Es opcional: una tarea
-- sin renglón acá no pide ninguna. La Especialidad es del mismo tipo de Asistente que la tarea.
CREATE TABLE IF NOT EXISTS "public"."especialidad_que_pide_la_tarea" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "tarea_id" "uuid" NOT NULL,
    "especialidad_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "especialidad_que_pide_la_tarea_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "especialidad_que_pide_la_tarea_una_por_tarea" UNIQUE ("prestadora_id", "tarea_id"),
    CONSTRAINT "especialidad_que_pide_la_tarea_prestadora_id_fkey" FOREIGN KEY ("prestadora_id") REFERENCES "public"."prestadoras"("id") ON DELETE CASCADE,
    CONSTRAINT "especialidad_que_pide_la_tarea_tarea_id_fkey" FOREIGN KEY ("tarea_id") REFERENCES "public"."tareas_tipo_asistente"("id") ON DELETE CASCADE,
    CONSTRAINT "especialidad_que_pide_la_tarea_especialidad_fkey" FOREIGN KEY ("especialidad_id", "prestadora_id") REFERENCES "public"."especialidades"("id", "prestadora_id") ON DELETE CASCADE
);

