GRANT ALL ON TABLE "public"."especialidad_que_pide_la_tarea" TO "service_role";


-- La tarea es de la Prestadora o del producto para su país, no es una prohibición, y la
-- Especialidad es del mismo tipo de Asistente que la tarea.
CREATE OR REPLACE FUNCTION "interno"."la_especialidad_pedida_es_de_la_tarea"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_pais   text;
  v_tarea  public.tareas_tipo_asistente;
  v_tipo   uuid;
BEGIN
  SELECT p.pais INTO v_pais FROM public.prestadoras p WHERE p.id = NEW.prestadora_id;

  SELECT * INTO v_tarea FROM public.tareas_tipo_asistente t WHERE t.id = NEW.tarea_id;
  IF NOT FOUND
     OR (v_tarea.prestadora_id IS NULL AND v_tarea.pais IS DISTINCT FROM v_pais)
     OR (v_tarea.prestadora_id IS NOT NULL AND v_tarea.prestadora_id <> NEW.prestadora_id) THEN
    RAISE EXCEPTION 'tarea_ajena:' USING ERRCODE = '23514';
  END IF;
  IF v_tarea.clase = 'prohibida' THEN
    RAISE EXCEPTION 'tarea_prohibida:' USING ERRCODE = '23514';
  END IF;

  SELECT e.tipo_asistente_id INTO v_tipo
    FROM public.especialidades e
   WHERE e.id = NEW.especialidad_id AND e.prestadora_id = NEW.prestadora_id;
  IF v_tipo IS DISTINCT FROM v_tarea.tipo_asistente_id THEN
    RAISE EXCEPTION 'especialidad_de_otro_tipo:' USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;

ALTER FUNCTION "interno"."la_especialidad_pedida_es_de_la_tarea"() OWNER TO "postgres";

REVOKE ALL ON FUNCTION "interno"."la_especialidad_pedida_es_de_la_tarea"() FROM PUBLIC, "anon";

CREATE OR REPLACE TRIGGER "la_especialidad_pedida_es_de_la_tarea" BEFORE INSERT OR UPDATE ON "public"."especialidad_que_pide_la_tarea" FOR EACH ROW EXECUTE FUNCTION "interno"."la_especialidad_pedida_es_de_la_tarea"();


-- Los valores anteriores del Legajo de cada Asistente: cada uno con desde cuándo rigió y hasta
-- cuándo. El valor vigente es el de la tabla de remuneraciones.
CREATE TABLE IF NOT EXISTS "public"."remuneraciones_asistente_anteriores" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "valor_hora" numeric(12,2),
    "valor_turno_guardia" numeric(12,2),
    "valor_semana" numeric(12,2),
    "valor_mes" numeric(12,2),
    "valor_hora_extra" numeric(12,2),
    "moneda" "public"."moneda_iso" NOT NULL,
    "unidad_medicion" "text" NOT NULL,
    "rige_desde" "date" NOT NULL,
    "rige_hasta" "date" NOT NULL,
    "reemplazado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "reemplazado_por" "uuid",
    CONSTRAINT "remuneraciones_asistente_anteriores_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "remuneraciones_asistente_anteriores_en_orden" CHECK (("rige_hasta" > "rige_desde")),
    CONSTRAINT "remuneraciones_asistente_anteriores_asistente_fkey" FOREIGN KEY ("asistente_id", "prestadora_id") REFERENCES "public"."asistentes"("id", "prestadora_id") ON DELETE CASCADE,
    CONSTRAINT "remuneraciones_asistente_anteriores_reemplazado_por_fkey" FOREIGN KEY ("reemplazado_por") REFERENCES "public"."usuarios"("id") ON DELETE SET NULL
);

