GRANT ALL ON FUNCTION "interno"."usuario_registrado_de_la_sesion"() TO "trabajo_sin_persona";


-- Un valor nuevo del Legajo rige desde hoy, en el día de la Prestadora, salvo que traiga su fecha.
CREATE OR REPLACE FUNCTION "interno"."el_valor_del_legajo_rige_desde_hoy"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NEW.rige_desde IS NULL THEN
    NEW.rige_desde := interno.hoy_de_la_prestadora(NEW.prestadora_id);
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION "interno"."el_valor_del_legajo_rige_desde_hoy"() OWNER TO "postgres";

REVOKE ALL ON FUNCTION "interno"."el_valor_del_legajo_rige_desde_hoy"() FROM PUBLIC, "anon";

CREATE OR REPLACE TRIGGER "el_valor_del_legajo_rige_desde_hoy" BEFORE INSERT ON "public"."remuneraciones_asistente" FOR EACH ROW EXECUTE FUNCTION "interno"."el_valor_del_legajo_rige_desde_hoy"();


-- Al cambiar el valor del Legajo, el anterior pasa a los valores anteriores con hasta cuándo
-- rigió. Si el cambio no trae su fecha, rige desde hoy. Con la misma fecha del valor que reemplaza
-- es una corrección y no deja historia. Una fecha anterior a la del valor vigente no se acepta.
CREATE OR REPLACE FUNCTION "interno"."guardar_el_valor_anterior_del_legajo"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF (NEW.valor_hora, NEW.valor_turno_guardia, NEW.valor_semana, NEW.valor_mes, NEW.valor_hora_extra, NEW.moneda, NEW.unidad_medicion)
     IS NOT DISTINCT FROM
     (OLD.valor_hora, OLD.valor_turno_guardia, OLD.valor_semana, OLD.valor_mes, OLD.valor_hora_extra, OLD.moneda, OLD.unidad_medicion) THEN
    IF NEW.rige_desde IS NULL OR NEW.rige_desde < OLD.rige_desde THEN
      NEW.rige_desde := OLD.rige_desde;
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.rige_desde IS NULL OR NEW.rige_desde = OLD.rige_desde THEN
    NEW.rige_desde := greatest(OLD.rige_desde, interno.hoy_de_la_prestadora(NEW.prestadora_id));
  END IF;

  IF NEW.rige_desde < OLD.rige_desde THEN
    RAISE EXCEPTION 'rige_desde_anterior:' USING ERRCODE = '23514';
  END IF;

  IF NEW.rige_desde > OLD.rige_desde THEN
    INSERT INTO public.remuneraciones_asistente_anteriores (
      prestadora_id, asistente_id, valor_hora, valor_turno_guardia, valor_semana, valor_mes, valor_hora_extra,
      moneda, unidad_medicion, rige_desde, rige_hasta, reemplazado_por)
    VALUES (OLD.prestadora_id, OLD.asistente_id, OLD.valor_hora, OLD.valor_turno_guardia, OLD.valor_semana, OLD.valor_mes,
            OLD.valor_hora_extra, OLD.moneda, OLD.unidad_medicion, OLD.rige_desde, NEW.rige_desde,
            interno.usuario_registrado_de_la_sesion());
  END IF;

  RETURN NEW;
END;
$$;

ALTER FUNCTION "interno"."guardar_el_valor_anterior_del_legajo"() OWNER TO "postgres";

REVOKE ALL ON FUNCTION "interno"."guardar_el_valor_anterior_del_legajo"() FROM PUBLIC, "anon";

CREATE OR REPLACE TRIGGER "guardar_el_valor_anterior_del_legajo" BEFORE UPDATE ON "public"."remuneraciones_asistente" FOR EACH ROW EXECUTE FUNCTION "interno"."guardar_el_valor_anterior_del_legajo"();


-- El valor del Legajo de un Asistente que regía en una fecha: el de fecha más reciente que no sea
-- posterior. Si la fecha es anterior al primer valor cargado, el primero. Corre con los permisos
-- de quien llama: la protección por fila decide si lo puede ver.
CREATE OR REPLACE FUNCTION "public"."valor_del_legajo_en"("p_asistente" "uuid", "p_fecha" "date") RETURNS TABLE("valor_hora" numeric, "valor_turno_guardia" numeric, "valor_semana" numeric, "valor_mes" numeric, "valor_hora_extra" numeric, "moneda" "text", "unidad_medicion" "text", "rige_desde" "date")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT x.valor_hora, x.valor_turno_guardia, x.valor_semana, x.valor_mes, x.valor_hora_extra,
         x.moneda, x.unidad_medicion, x.rige_desde
    FROM (
      SELECT r.valor_hora, r.valor_turno_guardia, r.valor_semana, r.valor_mes, r.valor_hora_extra,
             r.moneda::text AS moneda, r.unidad_medicion, r.rige_desde
        FROM public.remuneraciones_asistente r
       WHERE r.asistente_id = p_asistente
      UNION ALL
      SELECT h.valor_hora, h.valor_turno_guardia, h.valor_semana, h.valor_mes, h.valor_hora_extra,
             h.moneda::text, h.unidad_medicion, h.rige_desde
        FROM public.remuneraciones_asistente_anteriores h
       WHERE h.asistente_id = p_asistente
    ) x
   ORDER BY (x.rige_desde <= p_fecha) DESC,
            CASE WHEN x.rige_desde <= p_fecha THEN x.rige_desde END DESC NULLS LAST,
            x.rige_desde
   LIMIT 1;
$$;

ALTER FUNCTION "public"."valor_del_legajo_en"("p_asistente" "uuid", "p_fecha" "date") OWNER TO "postgres";

REVOKE ALL ON FUNCTION "public"."valor_del_legajo_en"("p_asistente" "uuid", "p_fecha" "date") FROM PUBLIC, "anon";
GRANT ALL ON FUNCTION "public"."valor_del_legajo_en"("p_asistente" "uuid", "p_fecha" "date") TO "authenticated";
GRANT ALL ON FUNCTION "public"."valor_del_legajo_en"("p_asistente" "uuid", "p_fecha" "date") TO "service_role";
GRANT ALL ON FUNCTION "public"."valor_del_legajo_en"("p_asistente" "uuid", "p_fecha" "date") TO "trabajo_sin_persona";


-- Las propuestas de ajuste por índice del valor del Legajo. Igual que las de las prestaciones: la
-- tarea programada las calcula; con ajuste automático quedan aplicadas, con revisión previa las
-- acepta o rechaza la administración.
CREATE TABLE IF NOT EXISTS "public"."propuestas_de_ajuste_del_legajo" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "indice" "text" NOT NULL,
    "periodo_base" "date" NOT NULL,
    "periodo_nuevo" "date" NOT NULL,
    "factor" numeric NOT NULL,
    "valor_rige_desde" "date" NOT NULL,
    "rige_desde" "date" NOT NULL,
    "moneda" "text" NOT NULL,
    "unidad_medicion" "text" NOT NULL,
    "valor_hora_actual" numeric(12,2),
    "valor_hora_propuesto" numeric(12,2),
    "valor_turno_guardia_actual" numeric(12,2),
    "valor_turno_guardia_propuesto" numeric(12,2),
    "valor_semana_actual" numeric(12,2),
    "valor_semana_propuesto" numeric(12,2),
    "valor_mes_actual" numeric(12,2),
    "valor_mes_propuesto" numeric(12,2),
    "valor_hora_extra_actual" numeric(12,2),
    "valor_hora_extra_propuesto" numeric(12,2),
    "estado" "text" DEFAULT 'pendiente'::"text" NOT NULL,
    "revisada_por" "uuid",
    "revisada_en" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "propuestas_de_ajuste_del_legajo_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "propuestas_de_ajuste_del_legajo_estado_check" CHECK (("estado" = ANY (ARRAY['pendiente'::"text", 'aceptada'::"text", 'rechazada'::"text", 'aplicada'::"text", 'sin_efecto'::"text"]))),
    CONSTRAINT "propuestas_de_ajuste_del_legajo_periodos_en_orden" CHECK (("periodo_nuevo" > "periodo_base")),
    CONSTRAINT "propuestas_de_ajuste_del_legajo_rige_desde_check" CHECK (("rige_desde" = ("date_trunc"('month'::"text", ("rige_desde")::timestamp with time zone))::"date")),
    CONSTRAINT "propuestas_de_ajuste_del_legajo_rige_despues" CHECK (("rige_desde" > "valor_rige_desde")),
    CONSTRAINT "propuestas_de_ajuste_del_legajo_revision_completa" CHECK ((("estado" = ANY (ARRAY['aceptada'::"text", 'rechazada'::"text"])) = ("revisada_en" IS NOT NULL))),
    CONSTRAINT "propuestas_de_ajuste_del_legajo_asistente_fkey" FOREIGN KEY ("asistente_id", "prestadora_id") REFERENCES "public"."asistentes"("id", "prestadora_id") ON DELETE CASCADE,
    CONSTRAINT "propuestas_de_ajuste_del_legajo_prestadora_id_fkey" FOREIGN KEY ("prestadora_id") REFERENCES "public"."prestadoras"("id"),
    CONSTRAINT "propuestas_de_ajuste_del_legajo_revisada_por_fkey" FOREIGN KEY ("revisada_por") REFERENCES "public"."usuarios"("id")
);

ALTER TABLE "public"."propuestas_de_ajuste_del_legajo" OWNER TO "postgres";

COMMENT ON COLUMN "public"."propuestas_de_ajuste_del_legajo"."valor_mes_actual" IS 'El importe por mes del Legajo cuando se armó la propuesta.';

COMMENT ON COLUMN "public"."propuestas_de_ajuste_del_legajo"."valor_mes_propuesto" IS 'El importe por mes ajustado por el índice.';

CREATE INDEX "propuestas_de_ajuste_del_legajo_por_prestadora" ON "public"."propuestas_de_ajuste_del_legajo" USING "btree" ("prestadora_id", "estado");

CREATE UNIQUE INDEX "propuestas_de_ajuste_del_legajo_una_pendiente" ON "public"."propuestas_de_ajuste_del_legajo" USING "btree" ("asistente_id") WHERE ("estado" = 'pendiente'::"text");

CREATE UNIQUE INDEX "propuestas_de_ajuste_del_legajo_una_por_mes" ON "public"."propuestas_de_ajuste_del_legajo" USING "btree" ("asistente_id", "valor_rige_desde", "rige_desde") WHERE ("estado" <> 'sin_efecto'::"text");

ALTER TABLE "public"."propuestas_de_ajuste_del_legajo" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "la_administracion_lee_las_propuestas_del_legajo" ON "public"."propuestas_de_ajuste_del_legajo" FOR SELECT TO "authenticated" USING ((("prestadora_id" = "interno"."prestadora_actual"()) AND "interno"."es_la_administracion_de_la_prestadora"("prestadora_id") AND "interno"."tiene_permiso"('ver_pagos_asistente'::"text")));

GRANT SELECT ON TABLE "public"."propuestas_de_ajuste_del_legajo" TO "authenticated";
GRANT ALL ON TABLE "public"."propuestas_de_ajuste_del_legajo" TO "service_role";


-- Calcula el ajuste por índice del valor del Legajo de cada Asistente de la Prestadora, con el
-- índice, la frecuencia y la forma de ajuste de la configuración del pago a los Asistentes. Con
-- ajuste automático cambia el valor y deja la propuesta aplicada; con revisión previa deja la
-- propuesta pendiente. Sólo la corre la tarea programada, dentro de una Prestadora.
CREATE OR REPLACE FUNCTION "public"."ajustar_valores_del_legajo_por_indice"() RETURNS TABLE("aplicados" integer, "propuestos" integer, "sin_efecto" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_prest      uuid := interno.prestadora_actual();
  v_regla      jsonb;
  v_indice     text;
  v_meses      integer;
  v_ajuste     text;
  v_hoy        date;
  v            record;
  v_ancla      date;
  v_rige       date;
  v_base       date;
  v_nuevo      date;
  v_factor     numeric;
  v_hora       numeric;
  v_turno      numeric;
  v_semana     numeric;
  v_mes        numeric;
  v_extra      numeric;
  v_propuesta  uuid;
BEGIN
  IF v_prest IS NULL OR coalesce(auth.jwt() ->> 'role', '') <> 'trabajo_sin_persona' THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;

  -- Dos corridas a la vez para la misma Prestadora harían el mismo ajuste dos veces.
  PERFORM pg_advisory_xact_lock(hashtextextended('ajuste_del_legajo:' || v_prest::text, 0));

  aplicados := 0;
  propuestos := 0;
  sin_efecto := 0;
  v_hoy := interno.hoy_de_la_prestadora(v_prest);

  SELECT c.regla INTO v_regla FROM public.configuracion_pago_asistentes c
   WHERE c.prestadora_id = v_prest;

  SELECT x.indice, x.meses, x.ajuste INTO v_indice, v_meses, v_ajuste
    FROM interno.condiciones_del_ajuste_por_indice(coalesce(v_regla, '{}'::jsonb), NULL, NULL, NULL) x;

  -- Las pendientes que ya no corresponden: cambió el valor del Legajo o el índice.
  WITH vencidas AS (
    UPDATE public.propuestas_de_ajuste_del_legajo pr
       SET estado = 'sin_efecto'
     WHERE pr.prestadora_id = v_prest
       AND pr.estado = 'pendiente'
       AND (pr.indice IS DISTINCT FROM v_indice
            OR NOT EXISTS (
              SELECT 1 FROM public.remuneraciones_asistente r
               WHERE r.asistente_id = pr.asistente_id
                 AND r.prestadora_id = v_prest
                 AND r.rige_desde = pr.valor_rige_desde
                 AND r.moneda::text = pr.moneda
                 AND r.unidad_medicion = pr.unidad_medicion
                 AND r.valor_hora IS NOT DISTINCT FROM pr.valor_hora_actual
                 AND r.valor_turno_guardia IS NOT DISTINCT FROM pr.valor_turno_guardia_actual
                 AND r.valor_semana IS NOT DISTINCT FROM pr.valor_semana_actual
                 AND r.valor_mes IS NOT DISTINCT FROM pr.valor_mes_actual
                 AND r.valor_hora_extra IS NOT DISTINCT FROM pr.valor_hora_extra_actual))
    RETURNING pr.id
  )
  SELECT count(*) INTO sin_efecto FROM vencidas;

  IF v_indice IS NULL THEN
    RETURN NEXT;
    RETURN;
  END IF;

  FOR v IN
    SELECT r.asistente_id, r.valor_hora, r.valor_turno_guardia, r.valor_semana, r.valor_mes, r.valor_hora_extra,
           r.moneda::text AS moneda, r.unidad_medicion, r.rige_desde
      FROM public.remuneraciones_asistente r
      JOIN public.asistentes a ON a.id = r.asistente_id AND a.prestadora_id = r.prestadora_id
     WHERE r.prestadora_id = v_prest
       AND a.estado <> 'cesado'
       AND r.rige_desde <= v_hoy
       AND greatest(coalesce(r.valor_hora, 0), coalesce(r.valor_turno_guardia, 0),
                    coalesce(r.valor_semana, 0), coalesce(r.valor_mes, 0), coalesce(r.valor_hora_extra, 0)) > 0
       AND NOT EXISTS (SELECT 1 FROM public.propuestas_de_ajuste_del_legajo pr
                        WHERE pr.asistente_id = r.asistente_id AND pr.estado = 'pendiente')
     ORDER BY r.asistente_id
  LOOP
    SELECT greatest(date_trunc('month', v.rige_desde)::date, max(pr.rige_desde))
      INTO v_ancla
      FROM public.propuestas_de_ajuste_del_legajo pr
     WHERE pr.asistente_id = v.asistente_id
       AND pr.valor_rige_desde = v.rige_desde
       AND pr.estado = 'rechazada';

    v_rige := (v_ancla + make_interval(months => v_meses))::date;
    CONTINUE WHEN v_hoy < v_rige;

    v_base := (date_trunc('month', v.rige_desde) - interval '1 month')::date;
    v_nuevo := (v_rige - interval '1 month')::date;

    v_factor := interno.valor_del_indice_de_la_prestadora(v_prest, v_indice, v_nuevo)
              / NULLIF(interno.valor_del_indice_de_la_prestadora(v_prest, v_indice, v_base), 0);
    CONTINUE WHEN v_factor IS NULL;

    v_hora := round(v.valor_hora * v_factor, 2);
    v_turno := round(v.valor_turno_guardia * v_factor, 2);
    v_semana := round(v.valor_semana * v_factor, 2);
    v_mes := round(v.valor_mes * v_factor, 2);
    v_extra := round(v.valor_hora_extra * v_factor, 2);
    CONTINUE WHEN (v_hora, v_turno, v_semana, v_mes, v_extra) IS NOT DISTINCT FROM
                  (v.valor_hora, v.valor_turno_guardia, v.valor_semana, v.valor_mes, v.valor_hora_extra);

    -- Ya hubo un ajuste para ese mes sobre este valor (rechazado, por ejemplo): no se vuelve a proponer.
    CONTINUE WHEN EXISTS (SELECT 1 FROM public.propuestas_de_ajuste_del_legajo pr
                           WHERE pr.asistente_id = v.asistente_id
                             AND pr.valor_rige_desde = v.rige_desde
                             AND pr.rige_desde = v_rige
                             AND pr.estado <> 'sin_efecto');

    INSERT INTO public.propuestas_de_ajuste_del_legajo (
      prestadora_id, asistente_id, indice, periodo_base, periodo_nuevo, factor, valor_rige_desde,
      rige_desde, moneda, unidad_medicion,
      valor_hora_actual, valor_hora_propuesto, valor_turno_guardia_actual, valor_turno_guardia_propuesto,
      valor_semana_actual, valor_semana_propuesto, valor_mes_actual, valor_mes_propuesto, valor_hora_extra_actual, valor_hora_extra_propuesto,
      estado)
    VALUES (v_prest, v.asistente_id, v_indice, v_base, v_nuevo, v_factor, v.rige_desde,
            v_rige, v.moneda, v.unidad_medicion,
            v.valor_hora, v_hora, v.valor_turno_guardia, v_turno,
            v.valor_semana, v_semana, v.valor_mes, v_mes, v.valor_hora_extra, v_extra,
            CASE WHEN v_ajuste = 'automatico' THEN 'aplicada' ELSE 'pendiente' END)
    RETURNING id INTO v_propuesta;

    IF v_ajuste = 'automatico' THEN
      UPDATE public.remuneraciones_asistente
         SET valor_hora = v_hora, valor_turno_guardia = v_turno, valor_semana = v_semana, valor_mes = v_mes,
             valor_hora_extra = v_extra, rige_desde = v_rige, updated_at = now()
       WHERE asistente_id = v.asistente_id AND prestadora_id = v_prest;

      INSERT INTO public.registro_actividad (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, detalle)
      VALUES (v_prest, NULL, 'ajuste_del_legajo_aplicado', 'propuestas_de_ajuste_del_legajo', v_propuesta,
              jsonb_build_object('asistente_id', v.asistente_id, 'indice', v_indice, 'rige_desde', v_rige));
      aplicados := aplicados + 1;
    ELSE
      propuestos := propuestos + 1;
    END IF;
  END LOOP;

  RETURN NEXT;
END;
$$;

ALTER FUNCTION "public"."ajustar_valores_del_legajo_por_indice"() OWNER TO "postgres";

REVOKE ALL ON FUNCTION "public"."ajustar_valores_del_legajo_por_indice"() FROM PUBLIC, "anon";
GRANT ALL ON FUNCTION "public"."ajustar_valores_del_legajo_por_indice"() TO "service_role";
GRANT ALL ON FUNCTION "public"."ajustar_valores_del_legajo_por_indice"() TO "trabajo_sin_persona";


-- La administración acepta o rechaza una propuesta pendiente de ajuste del valor del Legajo. Al
-- aceptarla, el valor nuevo rige desde el mes de la propuesta. Si el valor del Legajo cambió
-- después de calcularla, la propuesta ya no vale.
CREATE OR REPLACE FUNCTION "public"."revisar_propuesta_de_ajuste_del_legajo"("p_propuesta" "uuid", "p_aceptar" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_prest  uuid := interno.prestadora_actual();
  v_quien  uuid := interno.usuario_de_la_sesion();
  pr       public.propuestas_de_ajuste_del_legajo;
  r        public.remuneraciones_asistente;
BEGIN
  IF v_prest IS NULL OR v_quien IS NULL
     OR NOT interno.es_la_administracion_de_la_prestadora(v_prest)
     OR NOT interno.tiene_permiso('ver_pagos_asistente') THEN
    RAISE EXCEPTION 'sin_permiso' USING ERRCODE = '42501';
  END IF;
  IF p_aceptar IS NULL THEN
    RAISE EXCEPTION 'dato_invalido' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO pr FROM public.propuestas_de_ajuste_del_legajo
   WHERE id = p_propuesta AND prestadora_id = v_prest
   FOR UPDATE;
  IF NOT FOUND OR pr.estado <> 'pendiente' THEN
    RAISE EXCEPTION 'no_encontrado' USING ERRCODE = 'P0002';
  END IF;

  IF NOT p_aceptar THEN
    UPDATE public.propuestas_de_ajuste_del_legajo
       SET estado = 'rechazada', revisada_por = v_quien, revisada_en = now()
     WHERE id = pr.id;

    INSERT INTO public.registro_actividad (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, detalle)
    VALUES (v_prest, v_quien, 'ajuste_del_legajo_rechazado', 'propuestas_de_ajuste_del_legajo', pr.id,
            jsonb_build_object('asistente_id', pr.asistente_id, 'indice', pr.indice, 'rige_desde', pr.rige_desde));
    RETURN;
  END IF;

  SELECT * INTO r FROM public.remuneraciones_asistente
   WHERE asistente_id = pr.asistente_id AND prestadora_id = v_prest
   FOR UPDATE;
  IF NOT FOUND
     OR r.rige_desde <> pr.valor_rige_desde
     OR r.moneda::text <> pr.moneda
     OR r.unidad_medicion <> pr.unidad_medicion
     OR (r.valor_hora, r.valor_turno_guardia, r.valor_semana, r.valor_mes, r.valor_hora_extra) IS DISTINCT FROM
        (pr.valor_hora_actual, pr.valor_turno_guardia_actual, pr.valor_semana_actual, pr.valor_mes_actual, pr.valor_hora_extra_actual) THEN
    RAISE EXCEPTION 'ya_reemplazado' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.remuneraciones_asistente
     SET valor_hora = pr.valor_hora_propuesto, valor_turno_guardia = pr.valor_turno_guardia_propuesto,
         valor_semana = pr.valor_semana_propuesto, valor_mes = pr.valor_mes_propuesto,
         valor_hora_extra = pr.valor_hora_extra_propuesto,
         rige_desde = pr.rige_desde, updated_at = now()
   WHERE asistente_id = pr.asistente_id AND prestadora_id = v_prest;

  UPDATE public.propuestas_de_ajuste_del_legajo
     SET estado = 'aceptada', revisada_por = v_quien, revisada_en = now()
   WHERE id = pr.id;

  INSERT INTO public.registro_actividad (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, detalle)
  VALUES (v_prest, v_quien, 'ajuste_del_legajo_aceptado', 'propuestas_de_ajuste_del_legajo', pr.id,
          jsonb_build_object('asistente_id', pr.asistente_id, 'indice', pr.indice, 'rige_desde', pr.rige_desde));
END;
$$;

ALTER FUNCTION "public"."revisar_propuesta_de_ajuste_del_legajo"("p_propuesta" "uuid", "p_aceptar" boolean) OWNER TO "postgres";

REVOKE ALL ON FUNCTION "public"."revisar_propuesta_de_ajuste_del_legajo"("p_propuesta" "uuid", "p_aceptar" boolean) FROM PUBLIC, "anon";
GRANT ALL ON FUNCTION "public"."revisar_propuesta_de_ajuste_del_legajo"("p_propuesta" "uuid", "p_aceptar" boolean) TO "authenticated";
GRANT ALL ON FUNCTION "public"."revisar_propuesta_de_ajuste_del_legajo"("p_propuesta" "uuid", "p_aceptar" boolean) TO "service_role";


-- El valor final que se negoció con un Asistente para un Servicio, con su unidad, su moneda y
-- desde cuándo rige. Vive aparte del Legajo, que guarda el valor pretendido.
CREATE TABLE IF NOT EXISTS "public"."valores_acordados_del_servicio" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prestadora_id" "uuid" NOT NULL,
    "servicio_id" "uuid" NOT NULL,
    "asistente_id" "uuid" NOT NULL,
    "rige_desde" "date" NOT NULL,
    "unidad_medicion" "text" NOT NULL,
    "valor" numeric(12,2) NOT NULL,
    "moneda" "public"."moneda_iso" NOT NULL,
    "decidido_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "valores_acordados_del_servicio_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "valores_acordados_del_servicio_uno_por_fecha" UNIQUE ("servicio_id", "asistente_id", "rige_desde"),
    CONSTRAINT "valores_acordados_del_servicio_unidad_conocida" CHECK (("unidad_medicion" = ANY (ARRAY['hora'::"text", 'turno_guardia'::"text", 'semana'::"text", 'mes'::"text"]))),
    CONSTRAINT "valores_acordados_del_servicio_valor_positivo" CHECK (("valor" > (0)::numeric)),
    CONSTRAINT "valores_acordados_del_servicio_servicio_fkey" FOREIGN KEY ("servicio_id", "prestadora_id") REFERENCES "public"."servicios"("id", "prestadora_id") ON DELETE CASCADE,
    CONSTRAINT "valores_acordados_del_servicio_asistente_fkey" FOREIGN KEY ("asistente_id", "prestadora_id") REFERENCES "public"."asistentes"("id", "prestadora_id") ON DELETE CASCADE,
    CONSTRAINT "valores_acordados_del_servicio_decidido_por_fkey" FOREIGN KEY ("decidido_por") REFERENCES "public"."usuarios"("id") ON DELETE SET NULL
);

ALTER TABLE "public"."valores_acordados_del_servicio" OWNER TO "postgres";

CREATE INDEX "valores_acordados_del_servicio_por_asistente" ON "public"."valores_acordados_del_servicio" USING "btree" ("asistente_id", "prestadora_id");

