    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  NEW.decidido_por := interno.usuario_registrado_de_la_sesion();
  RETURN NEW;
END;
$$;

ALTER FUNCTION "interno"."anotar_quien_decidio_el_valor_acordado"() OWNER TO "postgres";

